-- ── 3. functions ────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.add_contact(p_athlete_id text, p_display_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_whatsapp text DEFAULT NULL::text, p_source text DEFAULT 'proof'::text, p_tier text DEFAULT 'free'::text)
 RETURNS TABLE(aid text, akey text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_athlete_id is null or btrim(p_athlete_id) = '' then
    raise exception 'athlete id required';
  end if;

  insert into public.hab_contacts (athlete_id, email, whatsapp, display_name, source, tier)
  values (p_athlete_id, nullif(btrim(coalesce(p_email, '')), ''),
                        nullif(btrim(coalesce(p_whatsapp, '')), ''),
                        nullif(btrim(coalesce(p_display_name, '')), ''),
                        coalesce(p_source, 'proof'), coalesce(p_tier, 'free'))
  on conflict (athlete_id) do update
    set email        = coalesce(excluded.email, hab_contacts.email),
        whatsapp     = coalesce(excluded.whatsapp, hab_contacts.whatsapp),
        display_name = coalesce(excluded.display_name, hab_contacts.display_name),
        source       = excluded.source,
        tier         = excluded.tier,
        updated_at   = now();

  return query select p_athlete_id, null::text;
end; $function$;

CREATE OR REPLACE FUNCTION public.assess_member()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select exists (select 1 from public.assess_accounts a where a.user_id = auth.uid() and a.revoked_at is null) $function$;

CREATE OR REPLACE FUNCTION public.assess_publish(p_token text, p_key text, p_body jsonb, p_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_token is null or length(p_token) < 40 or not exists (
       select 1 from public.assess_publish_keys k
       where k.key_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex')) then
    raise exception 'not allowed';
  end if;
  insert into public.assess_content (key, body, version, updated_at)
  values (p_key, p_body, p_version, now())
  on conflict (key) do update set body = excluded.body, version = excluded.version, updated_at = now();
end $function$;

CREATE OR REPLACE FUNCTION public.assess_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin new.updated_at := now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.career_achievement_eval(p_athlete text, p_id text, p_body jsonb, p_m jsonb, p_ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_test text := public.career_achievement_test(p_body); v_k text; v_need numeric; s jsonb; g jsonb; v_day date; v_ev jsonb;
  v_facts jsonb := '[]'::jsonb; v_n integer := 0; v_num integer; v_ref text; v_kind text;
  v_best integer := 0; v_run integer := 0; v_away integer := 0; v_armed boolean := false; v_old integer := 0; v_aw integer;
  v_bests integer; v_rets integer;
  c_none constant jsonb := '{"crossed": []}'::jsonb;
begin
  if v_test is null then return c_none; end if;

  if v_test = 'first' then
    select f.day, f.kind, f.ref into v_day, v_kind, v_ref from public.career_facts f
     where f.athlete_id = p_athlete and f.kind = p_body ->> 'reads' and f.void_at is null
     order by f.day, f.ref limit 1;
    v_ev := jsonb_build_object('via', 'first', 'n', 1, 'facts', jsonb_build_array(jsonb_build_object('kind', v_kind, 'ref', v_ref)));

  elsif v_test in ('proof', 'best_value', 'total', 'best_run') then
    -- stage79: total and best_run read the measure their entry key names (career_entry_keys()), the first step that reaches `at`
    v_k := case when v_test = 'proof' then public.career_proof_key(p_body ->> 'proof_measure')
                when v_test = 'best_value' then public.career_maxpct_key(p_body)
                else (public.career_entry_keys('achievement', p_body, p_ctx))[1] end;
    v_need := public.career_num(case when v_test = 'proof' then p_body -> 'proof_need' else p_body -> 'at' end);
    select x.s into s from jsonb_array_elements(coalesce(p_m -> v_k -> 'steps', '[]'::jsonb)) with ordinality x(s, o)
     where public.career_num(x.s -> 1) >= v_need order by x.o limit 1;
    if s is not null then
      v_day := (s ->> 0)::date;
      v_ev := jsonb_build_object('via', v_k, 'n', s -> 1,
                                 'facts', case when s ->> 3 is not null then jsonb_build_array(jsonb_build_object('kind', s ->> 2, 'ref', s ->> 3))
                                               else '[]'::jsonb end);
    end if;

  elsif v_test = 'goals' then
    -- every goal met; the day the last of them was
    if jsonb_typeof(p_body -> 'goals') is distinct from 'array' or jsonb_array_length(p_body -> 'goals') = 0 then return c_none; end if;
    for g in select e from jsonb_array_elements(p_body -> 'goals') e loop
      v_k := public.career_proof_key(g ->> 'kind');
      v_need := public.career_num(g -> 'need');
      if g ->> 'kind' is null or v_k is null or v_need is null then return c_none; end if;
      s := null;
      select x.s into s from jsonb_array_elements(coalesce(p_m -> v_k -> 'steps', '[]'::jsonb)) with ordinality x(s, o)
       where public.career_num(x.s -> 1) >= v_need order by x.o limit 1;
      if s is null then return c_none; end if;
      v_day := greatest(v_day, (s ->> 0)::date);
      v_n := v_n + 1;
      if s ->> 3 is not null and jsonb_array_length(v_facts) < 5 then
        v_facts := v_facts || jsonb_build_array(jsonb_build_object('kind', s ->> 2, 'ref', s ->> 3));
      end if;
    end loop;
    v_ev := jsonb_build_object('via', 'goals', 'n', v_n, 'facts', v_facts);

  elsif v_test in ('cycle_all_held', 'cycle_by_the_book', 'cycle_with_broken') then
    -- a finished cycle judged by the week facts of that cycle (refs c<n>|w<k>, so two cycles' weeks never mix); a week before the first
    -- session, or one Amir paused, has no fact and does not count (D9)
    select c.day, c.ref into v_day, v_ref from public.career_facts c
     where c.athlete_id = p_athlete and c.kind = 'cycle_finished' and c.void_at is null
       and case when v_test = 'cycle_with_broken' then
                  exists (select 1 from public.career_facts w where w.athlete_id = p_athlete and w.kind = 'week_broken' and w.void_at is null
                             and w.value ->> 'cycle' = c.value ->> 'cycle')
                else
                  exists (select 1 from public.career_facts w where w.athlete_id = p_athlete and w.kind = 'week_held' and w.void_at is null
                             and w.value ->> 'cycle' = c.value ->> 'cycle')
                  and not exists (select 1 from public.career_facts w where w.athlete_id = p_athlete and w.kind = 'week_broken' and w.void_at is null
                                     and w.value ->> 'cycle' = c.value ->> 'cycle')
                  and (v_test = 'cycle_all_held'
                       or not exists (select 1 from public.career_facts w
                                       where w.athlete_id = p_athlete and w.kind = 'week_held' and w.void_at is null
                                         and w.value ->> 'cycle' = c.value ->> 'cycle'
                                         and not exists (select 1 from public.career_facts b
                                                          where b.athlete_id = p_athlete and b.kind = 'week_by_the_book' and b.void_at is null
                                                            and b.ref = w.ref)))
           end
     order by c.day, c.ref limit 1;
    v_ev := jsonb_build_object('via', v_test, 'n', 1, 'facts', jsonb_build_array(jsonb_build_object('kind', 'cycle_finished', 'ref', v_ref)));

  elsif v_test = 'runs_together' then
    -- the first day every listed habit's run reaches `run` at once
    v_need := public.career_num(p_body -> 'run');
    with hs as (select distinct x as h from jsonb_array_elements_text(case when jsonb_typeof(p_body -> 'habits') = 'array' then p_body -> 'habits' else '[]'::jsonb end) x),
    tg as (select hs.h, coalesce(public.career_num(p_ctx -> 'targets' -> hs.h),
                                 case when coalesce(p_ctx -> 'custom', '[]'::jsonb) ? hs.h then 1 end) as tgt from hs),
    dn as (
      select tg.h, f.day as d from public.career_facts f join tg on substr(f.ref, 12) = tg.h
       where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null
         and jsonb_typeof(f.value -> 'v') = 'number' and (f.value ->> 'v')::numeric >= tg.tgt
    ),
    isl as (select dn.h, dn.d, dn.d - (row_number() over (partition by dn.h order by dn.d))::int as grp from dn),
    rl as (select isl.h, isl.d, (row_number() over (partition by isl.h, isl.grp order by isl.d))::int as run from isl)
    select min(z.d) into v_day from (
      select rl.d from rl where rl.run >= v_need group by rl.d
      having count(distinct rl.h) = (select count(*) from hs)
    ) z
    where (select count(*) from hs) > 0 and (select count(*) from tg where tg.tgt is not null) = (select count(*) from hs);
    v_ev := jsonb_build_object('via', 'runs_together', 'n', v_need, 'facts', '[]'::jsonb);

  elsif v_test = 'patterns_in_cycle' then
    -- a personal best in every group of movement patterns within one cycle; a lift is placed by the Spine (an approved entry whose name or
    -- alias it is, compared as career_norm() compares lifts); one the Spine cannot place counts for nothing
    with cyc as (select (e ->> 'num')::int as num, (e ->> 'cstart')::date as cs, (e ->> 'cend')::date as ce
                   from jsonb_array_elements(coalesce(p_ctx -> 'cycles', '[]'::jsonb)) e),
    grp as (select g2.key as gname, pv.value #>> '{}' as pat
              from jsonb_each(case when jsonb_typeof(p_body -> 'groups') = 'object' then p_body -> 'groups' else '{}'::jsonb end) g2,
                   jsonb_array_elements(case when jsonb_typeof(g2.value) = 'array' then g2.value else '[]'::jsonb end) pv),
    ng as (select count(distinct grp.gname) as n from grp),
    sp as (select public.career_norm(e.name) as nm, e.pattern from public.exercises e where e.status = 'approved' and e.pattern is not null
           union
           select public.career_norm(a.x), e.pattern from public.exercises e cross join unnest(e.aliases) a(x)
            where e.status = 'approved' and e.pattern is not null),
    pb as (select f.day, f.ref, public.career_norm(f.value ->> 'lift') as lift from public.career_facts f
            where f.athlete_id = p_athlete and f.kind = 'personal_best' and f.void_at is null),
    hit as (select c.num, gr.gname, min(pb.day) as d
              from cyc c join pb on pb.day between c.cs and c.ce join sp on sp.nm = pb.lift join grp gr on gr.pat = sp.pattern
             group by c.num, gr.gname),
    got as (select hit.num, max(hit.d) as d from hit group by hit.num
             having count(*) = (select ng.n from ng) and (select ng.n from ng) > 0)
    select got.d, got.num into v_day, v_num from got order by got.d, got.num limit 1;
    if v_day is not null then
      select coalesce(jsonb_agg(jsonb_build_object('kind', 'personal_best', 'ref', z.ref)), '[]'::jsonb) into v_facts
        from (select f.ref from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'personal_best' and f.void_at is null
                 and f.day = v_day order by f.ref limit 5) z;
      v_ev := jsonb_build_object('via', 'patterns_in_cycle', 'n', v_num, 'facts', v_facts);
    end if;

  elsif v_test = 'cycle_proving' then
    -- one cycle with `bests` personal bests in its dates, `retests` retests beaten, at least one week held and none broken
    v_bests := greatest(coalesce(public.career_num(p_body -> 'bests'), 1), 1)::int;
    v_rets := greatest(coalesce(public.career_num(p_body -> 'retests'), 0), 0)::int;
    with cyc as (select (e ->> 'num')::int as num, (e ->> 'cstart')::date as cs, (e ->> 'cend')::date as ce
                   from jsonb_array_elements(coalesce(p_ctx -> 'cycles', '[]'::jsonb)) e),
    x as (
      select c.num,
             (select f.day from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'personal_best' and f.void_at is null
                 and f.day between c.cs and c.ce order by f.day, f.ref offset v_bests - 1 limit 1) as b_day,
             case when v_rets > 0 then
               (select f.day from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'retest_beaten' and f.void_at is null
                   and f.value ->> 'cycle' = c.num::text order by f.day, f.ref offset v_rets - 1 limit 1) end as r_day,
             (select min(f.day) from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'week_held' and f.void_at is null
                 and f.value ->> 'cycle' = c.num::text) as h_day,
             exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'week_broken' and f.void_at is null
                        and f.value ->> 'cycle' = c.num::text) as broken
        from cyc c
    )
    select greatest(x.b_day, x.r_day, x.h_day), x.num into v_day, v_num from x
     where x.b_day is not null and x.h_day is not null and not x.broken and (v_rets = 0 or x.r_day is not null)
     order by greatest(x.b_day, x.r_day, x.h_day), x.num limit 1;
    v_ev := jsonb_build_object('via', 'cycle_proving', 'n', v_num, 'facts', '[]'::jsonb);

  elsif v_test = 'run_regained' then
    -- after `away_weeks` or more broken weeks in a row with no session at all, the held-weeks run reaches the best run before the gap
    v_aw := greatest(coalesce(public.career_num(p_body -> 'away_weeks'), 4), 1)::int;
    for s in select e from jsonb_array_elements(coalesce(p_m -> 'weeks' -> 'walk', '[]'::jsonb)) e loop
      if s ->> 1 = 'h' then
        v_run := v_run + 1; v_away := 0;
        if v_armed and v_run >= v_old then
          v_day := (s ->> 0)::date;
          v_ev := jsonb_build_object('via', 'run_regained', 'n', v_run,
                                     'facts', jsonb_build_array(jsonb_build_object('kind', 'week_held', 'ref', s ->> 3)));
          exit;
        end if;
        v_best := greatest(v_best, v_run);
      else
        v_run := 0;
        if coalesce(public.career_num(s -> 2), 0) = 0 then v_away := v_away + 1; else v_away := 0; end if;
        if not v_armed and v_away >= v_aw and v_best > 0 then v_armed := true; v_old := v_best; end if;
      end if;
    end loop;

  elsif v_test = 'month_held' then
    -- stage79: Full Month, the month's honour made personal, by Courtside's own rule (stage75): every training week that ENDS in a calendar
    -- month (a plan week of a cycle, career_weeks()) has a week_held fact, and there are at least `weeks` of them. Decided once the month is
    -- over, so a cycle published later can never add a week to a month already awarded. The day is the month's last day.
    v_need := greatest(coalesce(public.career_num(p_body -> 'weeks'), 4), 1);
    with wk as (
      select date_trunc('month', w.wto)::date as m0,
             exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'week_held' and f.void_at is null
                       and f.ref = 'c' || w.cycle_num || '|w' || w.week) as held
        from public.career_weeks(p_athlete) w
       where w.wto is not null and coalesce(array_length(w.plan, 1), 0) > 0),
    ms as (select wk.m0, count(*)::int as weeks, count(*) filter (where wk.held)::int as held from wk group by wk.m0)
    select ((ms.m0 + interval '1 month')::date - 1), ms.weeks into v_day, v_num from ms
     where ms.weeks >= v_need and ms.held = ms.weeks and (ms.m0 + interval '1 month')::date <= current_date
     order by ms.m0 limit 1;
    v_ev := jsonb_build_object('via', 'month_held', 'n', v_num, 'facts', '[]'::jsonb);

  elsif v_test = 'on_dates' then
    -- stage99: the first finished plan session (a full or an early finish, not voided) whose own date falls in one of the windows
    select f.day, f.kind, f.ref into v_day, v_kind, v_ref from public.career_facts f
     where f.athlete_id = p_athlete and f.kind in ('session_finished', 'session_finished_early') and f.void_at is null
       and public.career_in_windows(f.day, p_body -> 'windows')
     order by f.day, f.ref, f.kind limit 1;
    v_ev := jsonb_build_object('via', 'on_dates', 'n', 1,
                               'facts', case when v_ref is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('kind', v_kind, 'ref', v_ref)) end);

  elsif v_test = 'slam_year' then
    -- stage99: a session in each window of the on_dates entries named in `of`, in one calendar year (career_slam_year())
    s := public.career_slam_year(p_athlete, p_body -> 'of');
    v_day := (s ->> 'day')::date;
    v_ev := jsonb_build_object('via', 'slam_year', 'n', s -> 'need', 'facts', '[]'::jsonb);

  elsif v_test = 'clock' then
    -- stage99: the first finished plan session whose local finish time (the phone's `fin`, kept on the session fact) is before / from the time asked.
    -- A session saved before stage99, or by a phone that did not say, has no `fin` and counts for nothing.
    select f.day, f.kind, f.ref into v_day, v_kind, v_ref from public.career_facts f
     where f.athlete_id = p_athlete and f.kind in ('session_finished', 'session_finished_early') and f.void_at is null
       and case when (f.value ->> 'fin') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'      -- a CASE, so the cast below never meets a value that is not a time
                then (((p_body ->> 'finish_before') is not null and (f.value ->> 'fin')::time < (p_body ->> 'finish_before')::time)
                   or ((p_body ->> 'finish_from') is not null and (f.value ->> 'fin')::time >= (p_body ->> 'finish_from')::time))
                else false end
     order by f.day, f.ref, f.kind limit 1;
    v_ev := jsonb_build_object('via', 'clock', 'n', 1,
                               'facts', case when v_ref is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('kind', v_kind, 'ref', v_ref)) end);
  end if;

  if v_day is null then return c_none; end if;
  return jsonb_build_object('crossed', jsonb_build_array(jsonb_build_object('day', v_day, 'evidence', coalesce(v_ev, '{}'::jsonb))));
end $function$;

CREATE OR REPLACE FUNCTION public.career_achievement_test(p_body jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_body ->> 'test', case when p_body ? 'proof_measure' then 'proof' end)
$function$;

CREATE OR REPLACE FUNCTION public.career_award_id(p_kind text, p_item text, p_tier integer DEFAULT NULL::integer, p_subject text DEFAULT ''::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select p_kind || ':' || p_item
         || case when p_tier is not null then ':' || p_tier::text else '' end
         || case when coalesce(p_subject, '') <> '' then ':' || p_subject else '' end
$function$;

CREATE OR REPLACE FUNCTION public.career_award_pays(p_athlete text, p_body jsonb, p_tier_body jsonb, p_day date, p_ctx jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_S date := (p_ctx ->> 'S')::date;
begin
  if not (coalesce(p_body, '{}'::jsonb) ? 'starts_at') or v_S is null or p_day > v_S then
    return true;
  end if;
  if p_body ? 'history_twin_counts' then
    return (select count(*) from public.career_facts f
             where f.athlete_id = p_athlete and f.kind = p_body ->> 'history_twin_counts' and f.void_at is null and f.day <= v_S)
           < coalesce(public.career_num(p_tier_body -> 'at'), 0);
  end if;
  return false;
end $function$;

CREATE OR REPLACE FUNCTION public.career_award_spec(p_kind text, p_item text, p_tier integer, p_day date, p_evidence jsonb, p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_n numeric := round(public.career_num(p_evidence -> 'n')); v_cap text := p_body ->> 'caption';
begin
  if v_cap is not null and v_n is not null then v_cap := replace(v_cap, '{n}', v_n::text); end if;
  if p_kind = 'badge' then
    return jsonb_build_object('kind', 'badge', 'name', coalesce(p_body ->> 'name', p_item), 'meaning', p_body ->> 'meaning',
                              'metal', p_body -> 'tiers' -> (p_tier - 1) ->> 'metal', 'tier', p_tier, 'n', v_n, 'caption', v_cap,
                              'date', to_char(p_day, 'YYYY-MM-DD'));
  elsif p_kind = 'achievement' then
    return jsonb_build_object('kind', 'achievement', 'name', coalesce(p_body ->> 'name', p_item), 'meaning', p_body ->> 'meaning',
                              'caption', v_cap, 'date', to_char(p_day, 'YYYY-MM-DD'));
  end if;
  return jsonb_build_object('kind', 'title', 'name', coalesce(p_body ->> 'name', p_item), 'meaning', p_body ->> 'meaning',
                            'metal', p_body ->> 'metal', 'from', p_body ->> 'from', 'date', to_char(p_day, 'YYYY-MM-DD'));
end $function$;

CREATE OR REPLACE FUNCTION public.career_award_xp(p_kind text, p_tier integer, p_subject text, p_body jsonb, p_hr jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_tb jsonb; v_mult numeric;
begin
  if p_kind = 'title' then return 0; end if;
  if p_body is null then return null; end if;
  if p_kind = 'badge' then
    if p_tier is null or jsonb_typeof(p_body -> 'tiers') is distinct from 'array' or p_tier > jsonb_array_length(p_body -> 'tiers') then
      return null;
    end if;
    v_tb := p_body -> 'tiers' -> (p_tier - 1);
    if p_body ->> 'kind' = 'per_habit_best_run' then
      v_mult := public.career_num(v_tb -> 'mult');
      if v_mult is null then return null; end if;
      return greatest(10, round(coalesce(public.career_num(p_hr -> 'weights' -> p_subject), public.career_num(p_hr -> 'customXp'), 25)
                                * coalesce(public.career_num(p_hr -> 'completionBonus'), 1.2) * v_mult / 10) * 10)::int;
    end if;
    return round(public.career_num(v_tb -> 'xp'))::int;
  end if;
  return round(public.career_num(p_body -> 'xp'))::int;
end $function$;

CREATE OR REPLACE FUNCTION public.career_backfill(p_athlete text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text; v_n integer := 0;
begin
  if public.career_rules_now() is null then
    raise exception 'Career Mode has no rulebook yet: run the seed first (python scripts/career_seed.py)';
  end if;
  for v_id in
    select distinct z.id from (
      select a.athlete_id as id from public.athlete_progress a
      union select s.athlete_id from public.session_history s
      union select l.athlete_id from public.library_sessions l
      union select p.athlete_id from public.programs p
      union select f.athlete_id from public.career_facts f) z
     where p_athlete is null or z.id = p_athlete
     order by 1
  loop
    perform public.career_observe_proof(v_id);
    perform public.career_observe_session(v_id);
    perform public.career_observe_library(v_id);
    perform public.career_derive(v_id);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('athletes', v_n,
           'facts', coalesce((select jsonb_object_agg(x.kind, x.n) from (
                               select f.kind, count(*) as n from public.career_facts f
                                where f.void_at is null and (p_athlete is null or f.athlete_id = p_athlete)
                                group by f.kind order by f.kind) x), '{}'::jsonb),
           'void', (select count(*) from public.career_facts f where f.void_at is not null and (p_athlete is null or f.athlete_id = p_athlete)));
end $function$;

CREATE OR REPLACE FUNCTION public.career_badge_eval(p_id text, p_body jsonb, p_m jsonb, p_ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_k text; v_meas jsonb; v_have numeric := 0; v_now numeric; v_cross jsonb := '[]'::jsonb; t record; s jsonb; v_subject text;
  v_aid text; v_per boolean := p_body ->> 'kind' = 'per_habit_best_run';
begin
  if jsonb_typeof(p_body -> 'tiers') is distinct from 'array' then
    return jsonb_build_object('have', 0, 'now', null, 'crossed', '[]'::jsonb);
  end if;
  foreach v_k in array coalesce(public.career_entry_keys('badge', p_body, p_ctx), '{}'::text[]) loop
    v_meas := coalesce(p_m -> v_k, '{"have": 0, "now": null, "steps": []}'::jsonb);
    v_have := greatest(v_have, coalesce(public.career_num(v_meas -> 'have'), 0));
    if jsonb_typeof(v_meas -> 'now') = 'number' then v_now := greatest(coalesce(v_now, 0), public.career_num(v_meas -> 'now')); end if;
    v_subject := case when v_per then substr(v_k, 5) else '' end;
    if v_per and v_subject !~ '^[A-Za-z0-9_.-]+$' then continue; end if;
    for t in select e.ord::int as tier, e.val from jsonb_array_elements(p_body -> 'tiers') with ordinality e(val, ord) loop
      v_aid := public.career_award_id('badge', p_id, t.tier, v_subject);
      if coalesce(p_ctx -> 'owned', '{}'::jsonb) ? v_aid then continue; end if;
      s := null;
      select x.s into s from jsonb_array_elements(coalesce(v_meas -> 'steps', '[]'::jsonb)) with ordinality x(s, o)
       where public.career_num(x.s -> 1) >= public.career_num(t.val -> 'at')
       order by x.o limit 1;
      if s is null then continue; end if;
      v_cross := v_cross || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'tier', t.tier, 'subject', nullif(v_subject, ''), 'day', s ->> 0,
        'evidence', jsonb_build_object('via', v_k, 'n', s -> 1,
                                       'facts', case when s ->> 3 is not null
                                                     then jsonb_build_array(jsonb_build_object('kind', s ->> 2, 'ref', s ->> 3))
                                                     else '[]'::jsonb end))));
    end loop;
  end loop;
  return jsonb_build_object('have', v_have, 'now', v_now, 'crossed', v_cross);
end $function$;

CREATE OR REPLACE FUNCTION public.career_badge_run(p_body jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_body ->> 'run',
                  case when p_body ->> 'counts' = 'week_held' then 'plan_weeks'
                       when p_body ->> 'counts' = 'habit_done' and p_body ? 'habit' then 'days'
                       else 'iso_weeks' end)
$function$;

CREATE OR REPLACE FUNCTION public.career_bonus_rules(p_habit_rules jsonb, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when p_habit_rules is null or public.career_switch_day(p_rules, 'catalogue') is null then p_habit_rules
              else p_habit_rules || '{"tiers": [], "milestones": []}'::jsonb end
$function$;

CREATE OR REPLACE FUNCTION public.career_canon(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when jsonb_typeof(p) = 'array'
              then coalesce((select jsonb_agg(e.v order by e.v::text) from jsonb_array_elements(p) as e(v)), '[]'::jsonb)
              else p end
$function$;

CREATE OR REPLACE FUNCTION public.career_catalogue_before(p_offset integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id text; v_ids jsonb := '[]'::jsonb;
begin
  if public.career_catalogue_on() then
    raise exception 'career_catalogue_before: the catalogue switch is already on; the scores before it are the ones kept in backup.career_catalogue_before';
  end if;
  for v_id in select x from public.career_rewards_athletes(p_offset, p_limit) x loop
    insert into backup.career_catalogue_before (athlete_id, score, at) values (v_id, public.career_compute(v_id), now())
    on conflict (athlete_id) do update set score = excluded.score, at = now();
    v_ids := v_ids || to_jsonb(v_id);
  end loop;
  return jsonb_build_object('n', jsonb_array_length(v_ids), 'ids', v_ids);
end $function$;

CREATE OR REPLACE FUNCTION public.career_catalogue_on()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select public.career_switch_day(public.career_rules_now(), 'catalogue') is not null
$function$;

CREATE OR REPLACE FUNCTION public.career_catalogue_preview(p_rules jsonb, p_offset integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old jsonb := public.career_rules_now(); v_ver integer; v_newest integer; v_src text; v_id text; v_before jsonb; v_line jsonb;
        v_lines jsonb := '[]'::jsonb;
begin
  if v_old is null then raise exception 'career_catalogue_preview: no rulebook loaded yet'; end if;
  if public.career_catalogue_on() then raise exception 'career_catalogue_preview: the catalogue switch is already on'; end if;
  select r.version, r.source into v_newest, v_src from public.career_rules r order by r.version desc limit 1;
  v_ver := public.career_num(p_rules -> 'version')::int;
  if jsonb_typeof(p_rules) is distinct from 'object' or v_ver is null or v_ver < v_newest then
    raise exception 'career_catalogue_preview: p_rules must be a rulebook of version % or later', v_newest;
  end if;
  if ((p_rules - 'version') #- '{switch,catalogue}') is distinct from ((v_old - 'version') #- '{switch,catalogue}') then
    raise exception 'career_catalogue_preview: p_rules may differ from the newest rulebook only in [switch] catalogue (and its version)';
  end if;
  if public.career_switch_day(p_rules, 'catalogue') is null then
    raise exception 'career_catalogue_preview: p_rules has no catalogue switch day (today or before)';
  end if;
  for v_id in select x from public.career_rewards_athletes(p_offset, p_limit) x loop
    v_before := public.career_compute(v_id);
    v_line := null;
    begin
      insert into public.career_rules (version, rules, source, loaded_at) values (v_ver, p_rules, v_src, clock_timestamp())
      on conflict (version) do update set rules = excluded.rules, loaded_at = excluded.loaded_at;
      perform public.career_evaluate(v_id, null, 'baseline');
      v_line := public.career_rewards_line(v_id, v_before, public.career_compute(v_id));
      raise exception using errcode = 'P0001', message = 'career dry run';
    exception when sqlstate 'P0001' then
      if sqlerrm <> 'career dry run' then raise; end if;
    end;
    v_lines := v_lines || jsonb_build_array(v_line);
  end loop;
  return jsonb_build_object('n', jsonb_array_length(v_lines), 'dry_run', true, 'lines', v_lines);
end $function$;

CREATE OR REPLACE FUNCTION public.career_cfg(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with d as (
    select f.day, f.value -> 'live' as ids, lag(f.value -> 'live') over (order by f.day) as prev
      from public.career_facts f
     where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null
  )
  select jsonb_build_object(
    'roster', coalesce((select jsonb_agg(jsonb_build_object('from', d.day::text, 'ids', d.ids) order by d.day)
                          from d where d.prev is distinct from d.ids), '[]'::jsonb),
    'custom', coalesce((select jsonb_agg(jsonb_build_object('id', c.value))
                          from (select f.value -> 'custom' as cl from public.career_facts f
                                 where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null
                                 order by f.day desc limit 1) z,
                               jsonb_array_elements_text(coalesce(z.cl, '[]'::jsonb)) c), '[]'::jsonb))
$function$;

CREATE OR REPLACE FUNCTION public.career_changed_kinds()
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select array_agg(distinct k order by k)
    from unnest(string_to_array(nullif(current_setting('career.changed', true), ''), ',')) k
   where k <> ''
$function$;

CREATE OR REPLACE FUNCTION public.career_compare(p_season date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_x jsonb; v_r jsonb; v_xp jsonb; v_rp jsonb; v_xb jsonb; v_rb jsonb; v_now jsonb := public.career_rules_now(); v_settle date; v_cat date;
  v_s date; v_t date := current_date; v_wk date; a record;
  v_log jsonb; v_cfg jsonb; v_cl jsonb; v_cc jsonb; v_rows jsonb := '[]'::jsonb; v_bad integer := 0; v_n integer := 0; v_settled integer := 0;
  p_season_xp bigint; c_season_xp bigint; p_week bigint; c_week bigint; p_all bigint; c_all bigint; p_aw bigint; c_aw bigint;
  v_probe jsonb; v_facts jsonb; v_row_ok boolean; v_diff jsonb; v_closed integer; v_out jsonb;
begin
  select x.rules into v_x from public.xp_rules x where x.id = 1;
  v_r := public.career_habit_rules();
  if v_x is null or v_r is null then
    raise exception 'nothing to compare: xp_rules or the Career Mode rulebook is missing';
  end if;
  v_cat := public.career_switch_day(v_now, 'catalogue');
  v_xp := public.career_paid_rules(v_x, v_now);
  v_rp := public.career_paid_rules(v_r, v_now);
  v_xb := public.career_bonus_rules(v_x, v_now);
  v_rb := public.career_bonus_rules(v_r, v_now);
  v_settle := public.career_settled_before(v_now);
  v_s := coalesce(p_season, (select s.starts_on from public.current_season() s), '1970-01-01'::date);
  v_wk := greatest(v_t - 6, v_s);
  select coalesce(jsonb_agg(k.key order by k.key), '[]'::jsonb) into v_diff
    from jsonb_object_keys(v_r) as k(key)
   where k.key <> 'questRuns'
     and (v_cat is null or k.key not in ('tiers', 'milestones'))
     and public.career_canon(public.career_scoring(k.key, v_r -> k.key)) is distinct from public.career_canon(public.career_scoring(k.key, v_x -> k.key));
  for a in
    select ap.athlete_id, ap.data from public.athlete_progress ap
     where ap.data ? (ap.athlete_id || '_hab_log') order by ap.athlete_id
  loop
    v_n := v_n + 1;
    v_log := public.hab_log_of(a.data, a.athlete_id);
    v_cfg := public.hab_cfg_of(a.data, a.athlete_id);
    v_cl := public.career_log(a.athlete_id);
    v_cc := public.career_cfg(a.athlete_id);
    p_season_xp := public.hab_xp(v_log, v_s, v_t, v_xp) + public.hab_bonus_xp(v_log, v_cfg, v_s, v_s, v_t, v_xb);
    c_season_xp := public.hab_xp(v_cl, v_s, v_t, v_rp) + public.hab_bonus_xp(v_cl, v_cc, v_s, v_s, v_t, v_rb);
    p_week := public.hab_xp(v_log, v_wk, v_t, v_xp) + public.hab_bonus_xp(v_log, v_cfg, v_s, v_wk, v_t, v_xb);
    c_week := public.hab_xp(v_cl, v_wk, v_t, v_rp) + public.hab_bonus_xp(v_cl, v_cc, v_s, v_wk, v_t, v_rb);
    p_all := public.hab_xp(v_log, '1970-01-01', v_t, v_xp) + public.hab_bonus_xp(v_log, v_cfg, '1970-01-01', '1970-01-01', v_t, v_xb);
    c_all := public.hab_xp(v_cl, '1970-01-01', v_t, v_rp) + public.hab_bonus_xp(v_cl, v_cc, '1970-01-01', '1970-01-01', v_t, v_rb);
    v_probe := public.career_probe(v_log, v_cfg, v_s, v_t, v_x);
    select jsonb_build_object(
             'perfect', count(*) filter (where f.kind = 'perfect_day' and f.day between v_s and v_t),
             'on_target', count(*) filter (where f.kind = 'day_on_target' and f.day between v_s and v_t),
             'comebacks', count(*) filter (where f.kind = 'comeback' and f.day between v_s and v_t
                                             and public.career_day(f.value ->> 'prev') >= v_s))
      into v_facts
      from public.career_facts f where f.athlete_id = a.athlete_id and f.void_at is null;
    -- the closed days whose log and facts differ (only once the XP switch is on: before it, nothing settles)
    v_closed := case when v_settle is null then 0 else
      (select count(*)::int from (
         select coalesce(pl.key, cl.key) as k
           from (select e.key, e.value from jsonb_each(coalesce(v_log, '{}'::jsonb)) e
                  where e.key ~ '^\d{4}-\d{2}-\d{2}$' and jsonb_typeof(e.value) = 'object' and e.key < v_settle::text) pl
           full join (select e.key, e.value from jsonb_each(coalesce(v_cl, '{}'::jsonb)) e where e.key < v_settle::text) cl
             on cl.key = pl.key
          where pl.value is distinct from cl.value) z) end;
    v_row_ok := p_season_xp = c_season_xp and p_week = c_week and p_all = c_all and v_probe = v_facts;
    if v_cat is not null then
      -- the tiers and milestones Proof paid up to the switch, against what the awards carried over (spec §5.3)
      p_aw := public.hab_bonus_xp(v_log, v_cfg, null, null, v_cat, v_x || '{"quests": [], "questRuns": [], "comebackXp": 0}'::jsonb);
      select coalesce(sum(case when not aw.pays then 0
                               else aw.xp /* stage76: minted XP */ end), 0)::bigint
        into c_aw
        from public.career_awards aw join public.career_catalogue c on c.kind = aw.kind and c.id = aw.item
       where aw.athlete_id = a.athlete_id and aw.day <= v_cat and c.body ->> 'origin' = 'proof';
      c_aw := c_aw + (select coalesce(sum(public.career_num(k.value -> 'xp')), 0)::bigint from public.career_facts k
                       where k.athlete_id = a.athlete_id and k.kind = 'award_kept' and k.void_at is null
                         and k.day <= v_cat and k.value ->> 'proof' = 'true');   -- stage78: the Proof awards that left with the cut
      v_row_ok := v_row_ok and p_aw = c_aw;
    end if;
    if not v_row_ok and v_closed > 0 then
      v_settled := v_settled + 1;
    elsif not v_row_ok then
      v_bad := v_bad + 1;
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'athlete_id', a.athlete_id, 'ok', v_row_ok,
      'settled', case when not v_row_ok and v_closed > 0 then true end, 'closed', nullif(v_closed, 0),
      'season', jsonb_build_object('proof', p_season_xp, 'career', c_season_xp),
      'week', jsonb_build_object('proof', p_week, 'career', c_week),
      'all', jsonb_build_object('proof', p_all, 'career', c_all),
      'probe', jsonb_build_object('proof', v_probe, 'facts', v_facts),
      'awards', case when v_cat is not null then jsonb_build_object('proof', p_aw, 'career', c_aw) end)));
  end loop;
  v_out := jsonb_build_object('ok', v_bad = 0 and jsonb_array_length(v_diff) = 0, 'season_start', v_s, 'today', v_t,
                              'xp_switch', public.career_switch_day(v_now, 'xp'), 'settled_before', v_settle,
                              'athletes', v_n, 'matched', v_n - v_bad - v_settled, 'settled', v_settled,
                              'rules_equal', jsonb_array_length(v_diff) = 0, 'rules_differ_on', v_diff, 'rows', v_rows);
  if v_cat is not null then v_out := v_out || jsonb_build_object('catalogue_switch', v_cat); end if;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.career_compute(p_athlete text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now(); v_hr jsonb; v_hb jsonb; v_paid jsonb; v_log jsonb; v_cfg jsonb;
  v_name text; v_start date; v_s date; v_wfrom date; v_today date := current_date;
  c_d bigint; c_b bigint; s_d bigint; s_b bigint; w_d bigint; w_b bigint;
  c_f jsonb; c_r numeric; s_f jsonb; s_r numeric; w_r numeric; v_cxp bigint; v_sxp bigint;
begin
  if v_rules is null or p_athlete is null then return null; end if;
  v_hr := public.career_habit_rules();
  v_hb := public.career_bonus_rules(v_hr, v_rules);
  v_paid := public.career_paid_rules(v_hr, v_rules);
  v_log := public.career_log(p_athlete);
  v_cfg := public.career_cfg(p_athlete);
  select s.name, s.starts_on into v_name, v_start from public.current_season() s;
  v_s := coalesce(v_start, '1970-01-01'::date);
  v_wfrom := greatest(v_today - 6, v_s);
  c_d := public.hab_xp(v_log, null, v_today, v_paid);
  c_b := public.hab_bonus_xp(v_log, v_cfg, null, null, v_today, v_hb);
  s_d := public.hab_xp(v_log, v_s, v_today, v_paid);
  s_b := public.hab_bonus_xp(v_log, v_cfg, v_s, v_s, v_today, v_hb);
  w_d := public.hab_xp(v_log, v_wfrom, v_today, v_paid);
  w_b := public.hab_bonus_xp(v_log, v_cfg, v_s, v_wfrom, v_today, v_hb);
  with p as (select x.* from public.career_facts_paid(p_athlete) x where x.day <= v_today)
  select coalesce((select jsonb_object_agg(z.kind, jsonb_build_object('n', z.n, 'xp', z.xp))
                     from (select p.kind, count(*) as n, sum(p.xp) as xp from p group by p.kind) z), '{}'::jsonb),
         coalesce((select sum(p.xp) from p), 0),
         coalesce((select jsonb_object_agg(z.kind, jsonb_build_object('n', z.n, 'xp', z.xp))
                     from (select p.kind, count(*) as n, sum(p.xp) as xp from p where p.day >= v_s and not p.career_only group by p.kind) z),
                  '{}'::jsonb),
         coalesce((select sum(p.xp) from p where p.day >= v_s and not p.career_only), 0),
         coalesce((select sum(p.xp) from p where p.day >= v_wfrom and not p.career_only), 0)
    into c_f, c_r, s_f, s_r, w_r;
  v_cxp := (c_d + c_b + round(c_r))::bigint;
  v_sxp := (s_d + s_b + round(s_r))::bigint;
  return jsonb_build_object(
    'career', jsonb_build_object('habits', jsonb_build_object('daily', c_d, 'bonus', c_b, 'xp', c_d + c_b),
                                 'facts', c_f, 'facts_xp', round(c_r)::bigint, 'xp', v_cxp)
              || (public.career_level(v_cxp, v_rules) - 'rank'),   -- stage78: the level, no rank name
    'season', jsonb_build_object('name', v_name, 'starts_on', v_start, 'points', v_sxp,
                                 'parts', jsonb_build_object('habits', jsonb_build_object('daily', s_d, 'bonus', s_b, 'xp', s_d + s_b),
                                                             'facts', s_f, 'facts_xp', round(s_r)::bigint, 'xp', v_sxp)),
    'week', jsonb_build_object('from', v_wfrom, 'points', (w_d + w_b + round(w_r))::bigint));
end $function$;

CREATE OR REPLACE FUNCTION public.career_cycle_wins(p_athlete text, p_from date, p_to date, p_plan text[], p_rules jsonb)
 RETURNS TABLE(lift text, name text, gain numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_min numeric := coalesce(public.career_num(p_rules #> '{fact,effort_win,min_gain}'), 0.02);
  v_limit integer := coalesce(public.career_num(p_rules #> '{fact,effort_win,limit}')::int, 3);
  x record; v_cur text := null; v_out jsonb := '[]'::jsonb; v_g numeric;
  a_name text; a_w numeric; a_n numeric; a_ng boolean; a_idx numeric; a_first integer;
  has_b boolean := false; b_w numeric; b_n numeric; b_ng boolean; b_r numeric; b_idx numeric;
begin
  for x in
    select es.*, dense_rank() over (order by es.f_d, es.f_pd, es.f_o, es.lift) as met
      from (select e0.*, first_value(e0.d) over w0 as f_d, first_value(e0.plan_day) over w0 as f_pd, first_value(e0.ord) over w0 as f_o
              from public.career_entry_sets(p_athlete, p_from, p_to, p_plan) e0
             where e0.lift <> ''
            window w0 as (partition by e0.lift order by e0.d, e0.plan_day, e0.ord)) es
     order by es.lift, es.d, es.plan_day, es.ord
  loop
    if v_cur is distinct from x.lift then
      if v_cur is not null and has_b then
        v_g := public.career_win_gain(a_w, a_n, a_ng, a_idx, b_w, b_n, b_ng, b_idx, v_min);
        if v_g is not null then
          v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'g', v_g, 'met', a_first));
        end if;
      end if;
      v_cur := x.lift; a_name := x.name; a_w := x.b_w; a_n := x.b_n; a_ng := x.b_n_given; a_idx := x.b_idx; a_first := x.met;
      has_b := false;
    elsif not has_b then
      has_b := true; b_w := x.b_w; b_n := x.b_n; b_ng := x.b_n_given; b_r := x.b_r; b_idx := x.b_idx;
    elsif (x.b_idx is not null and (b_idx is null or x.b_idx > b_idx))
       or (x.b_idx is null and b_idx is null and x.b_r is not null and (b_r is null or x.b_r < b_r)) then
      b_w := x.b_w; b_n := x.b_n; b_ng := x.b_n_given; b_r := x.b_r; b_idx := x.b_idx;
    end if;
  end loop;
  if v_cur is not null and has_b then
    v_g := public.career_win_gain(a_w, a_n, a_ng, a_idx, b_w, b_n, b_ng, b_idx, v_min);
    if v_g is not null then
      v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'g', v_g, 'met', a_first));
    end if;
  end if;
  return query
    select y.l, y.nm, y.g from jsonb_to_recordset(v_out) as y(l text, nm text, g numeric, met integer)
     order by y.g desc, y.met
     limit v_limit;
end $function$;

CREATE OR REPLACE FUNCTION public.career_d20_check(p_version integer, p_rules jsonb, p_catalogue jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_newest integer; v_old jsonb; v_starts text := p_rules ->> 'starts_on'; v_cat jsonb; k text;
  c_by_day constant text[] := array['when', 'cap', 'source', 'pays_for', 'meaning', 'xp', 'xp_from', 'career_only', 'limit', 'limit_per'];
begin
  select max(r.version) into v_newest from public.career_rules r;
  if v_newest is null then return; end if;                                  -- the first seed (a fresh database): nothing to protect yet
  select r.rules into v_old from public.career_rules r where r.version = v_newest;
  if p_version = v_newest then
    if public.career_d20_prices(v_old) is distinct from public.career_d20_prices(p_rules) then
      raise exception 'D20: rulebook version % is loaded, and a seed of the same version may change only names and captions. A change of XP, a cap, the habits, the level curve or how a fact is worked out is a NEW version with starts_on = today (rulebook.toml → version and starts_on). Nothing was changed', p_version;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('kind', c.kind, 'id', c.id, 'body', c.body)), '[]'::jsonb) into v_cat from public.career_catalogue c;
    if public.career_d20_core(v_cat) is distinct from public.career_d20_core(p_catalogue) then
      raise exception 'D20: the catalogue changed more than its names and captions (what earns a reward, its tiers or its XP). That is a NEW rulebook version with starts_on = today; awards already minted keep theirs. Nothing was changed';
    end if;
    return;
  end if;
  -- a new version
  if v_starts is null or v_starts !~ '^\d{4}-\d{2}-\d{2}$' or v_starts::date not between current_date - 1 and current_date then
    raise exception 'D20: a new rulebook version (%) needs starts_on = today (or yesterday, for a time zone) in rulebook.toml, found %. Nothing was changed', p_version, coalesce(v_starts, 'none');
  end if;
  foreach k in array array['habits', 'level', 'season', 'week', 'share'] loop
    if (v_old -> k) is distinct from (p_rules -> k) then
      raise exception 'D20: [%] cannot change forward only (it would re-work every past day). That is Amir''s decision as a bug fix, backwards or forwards, not a seed. Nothing was changed', k;
    end if;
  end loop;
  for k in select jsonb_object_keys(case when jsonb_typeof(v_old -> 'fact') = 'object' then v_old -> 'fact' else '{}'::jsonb end) loop
    if p_rules -> 'fact' ? k and ((v_old -> 'fact' -> k) - c_by_day) is distinct from ((p_rules -> 'fact' -> k) - c_by_day) then
      raise exception 'D20: how the fact % is worked out changed (%). Only its xp, career_only and cap can change forward only; this is Amir''s decision as a bug fix. Nothing was changed',
        k, (select string_agg(x, ', ') from jsonb_object_keys(((v_old -> 'fact' -> k) - c_by_day) || ((p_rules -> 'fact' -> k) - c_by_day)) x
             where (v_old -> 'fact' -> k -> x) is distinct from (p_rules -> 'fact' -> k -> x));
    end if;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.career_d20_core(p_catalogue jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select md5(coalesce(string_agg(x.kind || '|' || x.id || '|' ||
           (case when jsonb_typeof(x.body -> 'tiers') = 'array'
                 then (x.body - array['name', 'caption', 'from', 'rule', 'note', 'notes', 'origin', 'tiers'])
                      || jsonb_build_object('tiers', (select jsonb_agg(t.v - 'tier_name' order by t.o) from jsonb_array_elements(x.body -> 'tiers') with ordinality t(v, o)))
                 else x.body - array['name', 'caption', 'from', 'rule', 'note', 'notes', 'origin'] end)::text, ',' order by x.kind, x.id), ''))
    from jsonb_to_recordset(case when jsonb_typeof(p_catalogue) = 'array' then p_catalogue else '[]'::jsonb end) as x(kind text, id text, body jsonb)
   where x.kind in ('badge', 'achievement', 'title', 'mission', 'quest', 'skin')
$function$;

CREATE OR REPLACE FUNCTION public.career_d20_prices(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('habits', p -> 'habits', 'level', p -> 'level', 'season', p -> 'season', 'week', p -> 'week', 'share', p -> 'share',
           'fact', coalesce((select jsonb_object_agg(e.key, e.value - array['when', 'cap', 'source', 'pays_for', 'meaning'])
                               from jsonb_each(case when jsonb_typeof(p -> 'fact') = 'object' then p -> 'fact' else '{}'::jsonb end) e), '{}'::jsonb))
$function$;

CREATE OR REPLACE FUNCTION public.career_day(p text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p is null or p !~ '^\d{4}-\d{2}-\d{2}' then return null; end if;
  return left(p, 10)::date;
exception when others then
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_derive(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now();
  v_close integer; v_share numeric; v_away integer; v_window integer;
  v_paused date; v_want jsonb := '[]'::jsonb; w record; c record; x record;
  v_ref text; v_closed boolean; v_run integer := 0; v_armed boolean := false; v_prev_broken boolean := false; v_prev_to date;
  v_done integer; v_planned integer; v_recs jsonb; v_raw text; v_first date; v_status text;
begin
  if v_rules is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  v_close := coalesce(public.career_num(v_rules #> '{week,close_after_days}')::int, 1);
  v_share := coalesce(public.career_num(v_rules #> '{fact,cycle_finished,min_share}'), 0.8);
  v_away := coalesce(public.career_num(v_rules #> '{fact,training_return,weeks_away}')::int, 2);
  v_window := coalesce(public.career_num(v_rules #> '{fact,retest_done,window_days}')::int, 7);
  select s.since, s.status into v_paused, v_status from public.athlete_status s where s.athlete_id = p_athlete;
  select min(sh.completed_on) into v_first from public.session_history sh where sh.athlete_id = p_athlete and sh.hidden_at is null;

  -- ── weeks, in the order they happened, from the week of the athlete's first session ──
  for w in
    with wk as (select * from public.career_weeks(p_athlete)),
    s as (select sh.day::text as pday, sh.completed_on as d, 'd' || sh.day || '|' || sh.completed_on::text as ref
            from public.session_history sh where sh.athlete_id = p_athlete and sh.hidden_at is null)
    select wk.*,
           (select count(*) from s where s.d between wk.wfrom and wk.wto and s.pday = any (wk.plan))::int as nsess,
           (select bool_and(exists (select 1 from s where s.d between wk.wfrom and wk.wto and s.pday = pd)) from unnest(wk.plan) pd) as held,
           (select max(z.fd) from (select min(s.d) as fd from s where s.d between wk.wfrom and wk.wto and s.pday = any (wk.plan)
                                    group by s.pday) z) as held_on,
           (select bool_and(exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'full_log'
                                       and f.ref = s.ref and f.void_at is null)
                            and exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'checkin_done'
                                           and f.ref = s.ref and f.void_at is null))
              from s where s.d between wk.wfrom and wk.wto and s.pday = any (wk.plan)) as by_book
      from wk
     order by wk.wfrom, wk.cycle_index
  loop
    if v_first is null or w.wto < v_first then
      continue;              -- before their first session: a week they never started is neither held nor broken
    end if;
    v_ref := 'c' || w.cycle_num || '|w' || w.week;
    v_closed := current_date > w.wto + v_close;
    if w.held then
      if v_armed then
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'training_return', 'ref', v_ref, 'day', w.held_on,
                    'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week)));
        v_armed := false;
      end if;
      if v_prev_broken and w.wfrom - v_prev_to <= 8 then
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'bounce_back', 'ref', v_ref, 'day', w.held_on,
                    'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week)));
      end if;
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'week_held', 'ref', v_ref, 'day', w.held_on,
                  'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week, 'sessions', w.nsess, 'plan', cardinality(w.plan))));
      if w.by_book then         -- every session that week fully logged and checked in first
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'week_by_the_book', 'ref', v_ref, 'day', w.held_on,
                    'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week)));
      end if;
      v_run := 0; v_prev_broken := false; v_prev_to := w.wto;
    elsif v_closed then
      if v_paused is not null and w.wto >= v_paused then
        continue;            -- a week Amir paused the athlete for (or one after they left) is neither broken nor away (P2)
      end if;
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'week_broken', 'ref', v_ref, 'day', w.wto,
                  'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week, 'sessions', w.nsess, 'plan', cardinality(w.plan))));
      if w.nsess = 0 then
        v_run := v_run + 1;
        if v_run >= v_away then v_armed := true; end if;
      else
        v_run := 0;
      end if;
      v_prev_broken := true; v_prev_to := w.wto;
    end if;
    -- a week still running and not yet held: nothing yet
  end loop;

  -- ── cycles that have ended: finished, the roadmap, the effort wins ──
  for c in
    select distinct on (cw.cycle_index) cw.cycle_index, cw.cycle_num, cw.weeks, cw.cstart, cw.cend, cw.plan, cw.is_last
      from public.career_weeks(p_athlete) cw
     order by cw.cycle_index
  loop
    if current_date <= c.cend + v_close then continue; end if;
    select count(*) into v_done from public.session_history s
     where s.athlete_id = p_athlete and s.hidden_at is null and s.completed_on between c.cstart and c.cend and s.day::text = any (c.plan);
    v_planned := cardinality(c.plan) * c.weeks;
    if v_planned > 0 and v_done::numeric / v_planned >= v_share then
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'cycle_finished', 'ref', 'c' || c.cycle_num, 'day', c.cend + 1,
                  'value', jsonb_build_object('cycle', c.cycle_num, 'done', v_done, 'planned', v_planned)));
      if c.is_last then
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'roadmap_finished', 'ref', 'roadmap', 'day', c.cend + 1,
                    'value', jsonb_build_object('cycle', c.cycle_num)));
      end if;
    end if;
    for x in select * from public.career_cycle_wins(p_athlete, c.cstart, c.cend, c.plan, v_rules) loop
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'effort_win', 'ref', 'c' || c.cycle_num || '|' || x.lift,
                  'day', c.cend + 1, 'value', jsonb_build_object('cycle', c.cycle_num, 'lift', x.name, 'gain', round(x.gain, 4))));
    end loop;
  end loop;

  -- ── every whole month since the first session (month_with_amir); none while a former athlete ──
  if v_first is not null then
    for x in
      select g as n, (v_first + make_interval(months => g))::date as on_day
        from generate_series(1, 1200) g
       where (v_first + make_interval(months => g))::date <= case when v_status = 'former' then least(current_date, v_paused) else current_date end
    loop
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'month_with_amir', 'ref', x.n::text, 'day', x.on_day,
                  'value', jsonb_build_object('month', x.n)));
    end loop;
  end if;

  -- ── each lift's best gain over its first session (lift_gain) ──
  for x in select * from public.career_lift_gains(p_athlete) loop
    v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'lift_gain', 'ref', x.lift, 'day', x.d,
                'value', jsonb_build_object('lift', x.name, 'pct', x.pct)));
  end loop;

  -- ── the Personal Records: a new best (personal_best), a retest (retest_done, retest_beaten) ──
  select a.data -> (p_athlete || '_1rm') into v_recs from public.athlete_progress a where a.athlete_id = p_athlete;
  if jsonb_typeof(v_recs) = 'string' then
    v_raw := v_recs #>> '{}';
    begin
      v_recs := v_raw::jsonb;
    exception when others then
      v_recs := '[]'::jsonb;
    end;
  end if;
  if jsonb_typeof(v_recs) is distinct from 'array' then v_recs := '[]'::jsonb; end if;

  -- A Personal Records entry says its measure in `u` ('lb' or 'plates'; absent = kg), and its `kg` is the estimate in THAT measure (program.html:
  -- saveCeilingEntry(), fillRecords()). A lift's records are kept per measure, never compared across: one entry speaks for each day of a lift
  -- IN A MEASURE, and a lift's first number in a measure is not a best (the bar to beat is that measure's own).
  with rec as (
    select r0.e ->> 'lift' as lift, public.career_rec_unit(r0.e) as u, public.career_day(r0.e ->> 'd') as d, r0.e, r0.ord,
           coalesce(public.career_js_num(r0.e -> 't'), 0) as t
      from jsonb_array_elements(v_recs) with ordinality r0(e, ord)
     where jsonb_typeof(r0.e) = 'object' and public.career_truthy(r0.e -> 'lift') and public.career_truthy(r0.e -> 'd')
  ),
  eff as (     -- one entry speaks for each day of a lift and measure: the newest write (ceilingLifts(), fillRecords())
    select distinct on (rec.lift, rec.d, rec.u) rec.* from rec where rec.d is not null order by rec.lift, rec.d, rec.u, rec.t desc, rec.ord
  ),
  kept as (select eff.* from eff where not public.career_truthy(eff.e -> 'del') and coalesce(public.career_num(eff.e -> 'kg'), 0) > 0)
  select v_want || coalesce(jsonb_agg(jsonb_build_object('kind', 'personal_best',
                                                         'ref', k.lift || '|' || k.d::text || case when k.u = 'kg' then '' else '|' || k.u end, 'day', k.d,
                                                         'value', jsonb_build_object('lift', k.lift, 'kg', public.career_num(k.e -> 'kg'))
                                                                  || case when k.u = 'kg' then '{}'::jsonb else jsonb_build_object('u', k.u) end)), '[]'::jsonb)
    into v_want
    from kept k
   where public.career_truthy(k.e -> 'auto')
     and exists (select 1 from kept k2 where k2.lift = k.lift and k2.u = k.u and k2.d < k.d);   -- a lift's first number in a measure is not a best: nothing to beat

  -- retests: a test-flagged lift (exTestSpec(): true, or "<n>RM" up to 10) logged in its cycle's test week, the last [fact.retest_done]
  -- window_days of the cycle (inRetestWindow()) and after its end while it is still the current cycle, judged on its best estimate that
  -- week; beaten when that tops the lift's previous test, or its best earlier record when there was none. All of it per lift AND measure
  -- (kg, lb, plates): a retest in pounds is judged against pounds only, and the first one in a measure beats nothing.
  for x in
    with cyc as (select distinct on (cw.cycle_index) cw.* from public.career_weeks(p_athlete) cw order by cw.cycle_index),
    src as (
      select cyc.cycle_index, cyc.cycle_num, cyc.cend, cyc.is_current, cyc.plan,
             case when cyc.is_current then (select pr.data from public.programs pr where pr.athlete_id = p_athlete)
                  else (select v.data from public.program_versions v
                         where v.athlete_id = p_athlete and jsonb_typeof(v.data -> 'currentCycleIndex') = 'number'
                           and public.career_num(v.data -> 'currentCycleIndex') = cyc.cycle_index
                         order by v.saved_at desc limit 1) end as data
        from cyc
    ),
    flagged as (
      select distinct src.cycle_index, src.cycle_num, src.cend, src.is_current, ex.v ->> 'name' as name,
             public.career_norm(ex.v ->> 'name') as lift
        from src,
             jsonb_array_elements(case when jsonb_typeof(src.data -> 'workouts' -> 'days') = 'array'
                                       then src.data -> 'workouts' -> 'days' else '[]'::jsonb end) as dd(v),
             jsonb_array_elements(case when jsonb_typeof(dd.v -> 'blocks') = 'array' then dd.v -> 'blocks' else '[]'::jsonb end) as bb(v),
             jsonb_array_elements(case when jsonb_typeof(bb.v -> 'exercises') = 'array' then bb.v -> 'exercises' else '[]'::jsonb end) as ex(v)
       where ex.v ->> 'type' = 'standard' and public.career_truthy(ex.v -> 'name')
         and (ex.v -> 'test' = 'true'::jsonb
              or ((ex.v ->> 'test') ~* '^\d+\s*rm$' and (substring(ex.v ->> 'test' from '^(\d+)'))::int between 1 and 10))
    ),
    evidence as (
      select f.cycle_index, f.cycle_num, f.name, es.lift, public.career_lift_unit(es.lift) as u, es.d, es.best_est as est
        from flagged f
        join lateral public.career_entry_sets(p_athlete, f.cend - v_window, case when f.is_current then current_date else f.cend end, null) es
          on public.career_lift_base(es.lift) = f.lift
      union all
      select f.cycle_index, f.cycle_num, f.name, public.career_lift_key(r.e ->> 'lift', public.career_rec_unit(r.e)), public.career_rec_unit(r.e),
             public.career_day(r.e ->> 'd'), public.career_num(r.e -> 'kg')
        from flagged f, jsonb_array_elements(v_recs) r(e)
       where jsonb_typeof(r.e) = 'object' and public.career_truthy(r.e -> 'test') and not public.career_truthy(r.e -> 'del')
         and public.career_norm(r.e ->> 'lift') = f.lift
         and public.career_day(r.e ->> 'd') between f.cend - v_window and case when f.is_current then current_date else f.cend end
    )
    select distinct on (ev.lift, ev.cycle_index) ev.*
      from evidence ev
     order by ev.lift, ev.cycle_index, ev.est desc nulls last, ev.d
  loop
    v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'retest_done', 'ref', x.lift || '|c' || x.cycle_num, 'day', x.d,
                'value', jsonb_strip_nulls(jsonb_build_object('lift', x.name, 'cycle', x.cycle_num, 'est', x.est)
                                           || case when x.u = 'kg' then '{}'::jsonb else jsonb_build_object('u', x.u) end)));
  end loop;
  -- beaten: against this lift's previous retest, else its best record before the retest day
  with t as (
    select (e.v ->> 'ref') as ref, (e.v ->> 'day')::date as d, e.v -> 'value' as v,
           public.career_lift_key(e.v #>> '{value,lift}', e.v #>> '{value,u}') as lift,
           (e.v #>> '{value,cycle}')::int as cyc, public.career_num(e.v #> '{value,est}') as est
      from jsonb_array_elements(v_want) as e(v) where e.v ->> 'kind' = 'retest_done'
  ),
  recs as (
    select public.career_lift_key(r1.e ->> 'lift', public.career_rec_unit(r1.e)) as lift, public.career_day(r1.e ->> 'd') as d,
           public.career_num(r1.e -> 'kg') as kg
      from jsonb_array_elements(v_recs) r1(e)
     where jsonb_typeof(r1.e) = 'object' and not public.career_truthy(r1.e -> 'del') and coalesce(public.career_num(r1.e -> 'kg'), 0) > 0
  ),
  judged as (
    select t.*,
           (select t2.est from t t2 where t2.lift = t.lift and t2.cyc < t.cyc and t2.est is not null order by t2.cyc desc limit 1) as prev_test,
           (select max(r.kg) from recs r where r.lift = t.lift and r.d < t.d) as prev_best
      from t
  )
  select v_want || coalesce(jsonb_agg(jsonb_build_object('kind', 'retest_beaten', 'ref', j.ref, 'day', j.d,
                                                         'value', j.v || jsonb_build_object('beat', coalesce(j.prev_test, j.prev_best)))), '[]'::jsonb)
    into v_want
    from judged j
   where j.est is not null and coalesce(j.prev_test, j.prev_best) is not null and j.est > coalesce(j.prev_test, j.prev_best);

  perform public.career_sync(p_athlete, array['week_held', 'week_broken', 'bounce_back', 'training_return', 'week_by_the_book',
                                              'cycle_finished', 'roadmap_finished', 'effort_win', 'month_with_amir', 'lift_gain',
                                              'personal_best', 'retest_beaten'], v_want, 'server');
  perform public.career_sync(p_athlete, array['retest_done'], v_want, 'training');
end $function$;

CREATE OR REPLACE FUNCTION public.career_derive_days(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb := public.career_rules_now(); v_want jsonb; v_lapse integer; v_stick integer; v_settle date;
begin
  if v_rules is null or p_athlete is null then return; end if;
  v_lapse := coalesce((v_rules #>> '{habits,lapse_days}')::int, 3);
  v_stick := coalesce((v_rules #>> '{habits,comeback_stick}')::int, 7);
  v_settle := public.career_settled_before(v_rules);
  with hd as (select * from public.career_habit_days(p_athlete)),
  q as (select hd.d, lag(hd.d) over (order by hd.d) as prev from hd where hd.on_target),
  isl as (select hd.d, hd.d - (row_number() over (order by hd.d))::int as grp from hd where hd.on_target),
  runs as (select min(isl.d) as s, count(*)::int as len from isl group by isl.grp)
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_want from (
    select jsonb_build_object('kind', 'day_on_target', 'ref', hd.d::text, 'day', hd.d,
                              'value', jsonb_build_object('done', hd.ndone, 'of', hd.nlive)) as x
      from hd where hd.on_target
    union all
    select jsonb_build_object('kind', 'perfect_day', 'ref', hd.d::text, 'day', hd.d, 'value', jsonb_build_object('of', hd.nlive))
      from hd where hd.perfect
    union all
    select jsonb_build_object('kind', 'comeback', 'ref', q.d::text, 'day', q.d,
                              'value', jsonb_build_object('prev', q.prev, 'gone', q.d - q.prev - 1))
      from q where v_lapse > 0 and q.prev is not null and q.d - q.prev - 1 >= v_lapse
    union all
    select jsonb_build_object('kind', 'comeback_stuck', 'ref', q.d::text, 'day', q.d + v_stick - 1,
                              'value', jsonb_build_object('held', r.len))
      from q join runs r on r.s = q.d
     where v_lapse > 0 and v_stick > 0 and q.prev is not null and q.d - q.prev - 1 >= v_lapse and r.len >= v_stick
  ) s;
  perform public.career_sync(p_athlete, array['day_on_target', 'perfect_day'], v_want, 'proof', null, v_settle);
  perform public.career_sync(p_athlete, array['comeback', 'comeback_stuck'], v_want, 'server', null, v_settle);
end $function$;

CREATE OR REPLACE FUNCTION public.career_digits(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select translate(coalesce(p, ''),
                   U&'\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\066B\060C',
                   '01234567890123456789..')
$function$;

CREATE OR REPLACE FUNCTION public.career_earned_days(p_athlete text)
 RETURNS TABLE(award_id text, earned date)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now(); v_S date; v_hr jsonb; v_ctx jsonb; v_commended boolean; v_cycles boolean := false;
  c record; t record; x jsonb; r jsonb; v_woken jsonb := '[]'::jsonb; v_keys text[] := '{}'::text[]; v_m jsonb;
begin
  if p_athlete is null or v_rules is null or not public.career_catalogue_on() then return; end if;
  v_S := public.career_switch_day(v_rules, 'catalogue');
  v_hr := public.career_habit_rules();
  v_ctx := jsonb_build_object(
    'S', v_S, 'hr', v_hr, 'targets', coalesce(v_hr -> 'targets', '{}'::jsonb),
    'custom', coalesce((select f.value -> 'custom' from public.career_facts f
                         where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null and jsonb_typeof(f.value -> 'custom') = 'array'
                         order by f.day desc limit 1), '[]'::jsonb),
    'weights', v_hr -> 'weights', 'cb', v_hr -> 'completionBonus', 'cx', v_hr -> 'customXp',
    'version', (select max(rr.version) from public.career_rules rr), 'owned', '{}'::jsonb);
  v_commended := exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'commendation' and f.void_at is null);
  for c in select cc.kind, cc.id, cc.body from public.career_catalogue cc where cc.kind in ('badge', 'achievement')
            order by (cc.kind = 'badge') desc, cc.id loop
    if c.body ->> 'meaning' = 'chosen' and not v_commended then continue; end if;
    if c.body ? 'retire_at' then continue; end if;
    if c.kind = 'achievement' and public.career_achievement_test(c.body) in ('patterns_in_cycle', 'cycle_proving') then v_cycles := true; end if;
    v_woken := v_woken || jsonb_build_array(jsonb_build_object('kind', c.kind, 'id', c.id, 'body', c.body));
    v_keys := v_keys || public.career_entry_keys(c.kind, c.body, v_ctx);
  end loop;
  if v_cycles then
    v_ctx := v_ctx || jsonb_build_object('cycles', coalesce((
      select jsonb_agg(jsonb_build_object('num', z.cycle_num, 'cstart', z.cstart, 'cend', z.cend) order by z.cycle_index)
        from (select distinct on (w.cycle_index) w.cycle_index, w.cycle_num, w.cstart, w.cend
                from public.career_weeks(p_athlete) w order by w.cycle_index) z), '[]'::jsonb));
  end if;
  v_m := public.career_measures(p_athlete, v_ctx, v_keys);
  for x in select e from jsonb_array_elements(v_woken) e loop
    if x ->> 'kind' = 'badge' then
      r := public.career_badge_eval(x ->> 'id', x -> 'body', v_m, v_ctx);
    else
      r := public.career_achievement_eval(p_athlete, x ->> 'id', x -> 'body', v_m, v_ctx);
    end if;
    for t in select e from jsonb_array_elements(coalesce(r -> 'crossed', '[]'::jsonb)) e loop
      award_id := public.career_award_id(x ->> 'kind', x ->> 'id', (t.e ->> 'tier')::int, coalesce(t.e ->> 'subject', ''));
      earned := (t.e ->> 'day')::date;
      return next;
    end loop;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.career_entry_keys(p_kind text, p_body jsonb, p_ctx jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_counts text[]; v_t text; v_out text[] := '{}'::text[];
begin
  v_counts := case jsonb_typeof(p_body -> 'counts')
                when 'array' then array(select x from jsonb_array_elements_text(p_body -> 'counts') x order by x)
                when 'string' then array[p_body ->> 'counts']
                else '{}'::text[] end;
  if p_kind = 'badge' then
    case p_body ->> 'kind'
      when 'best_run' then
        return case public.career_badge_run(p_body)
                 when 'plan_weeks' then array['weeks']
                 when 'days' then array['run:' || coalesce(p_body ->> 'habit', '')]
                 else array['iso:' || coalesce(v_counts[1], '')] end;
      when 'total' then return array['count:' || array_to_string(v_counts, ',')];
      when 'best_value' then return array[public.career_maxpct_key(p_body)];
      when 'per_habit_best_run' then
        return array(select 'run:' || t.key from jsonb_each(coalesce(p_ctx -> 'targets', '{}'::jsonb)) t
                     union
                     select 'run:' || c.value from jsonb_array_elements_text(coalesce(p_ctx -> 'custom', '[]'::jsonb)) c);
      when 'proof' then return array[public.career_proof_key(p_body ->> 'proof_measure')];
      else return '{}'::text[];
    end case;
  end if;
  v_t := public.career_achievement_test(p_body);
  if v_t = 'proof' then
    return array[public.career_proof_key(p_body ->> 'proof_measure')];
  elsif v_t = 'goals' then
    select coalesce(array_agg(distinct public.career_proof_key(g ->> 'kind')), '{}'::text[]) into v_out
      from jsonb_array_elements(case when jsonb_typeof(p_body -> 'goals') = 'array' then p_body -> 'goals' else '[]'::jsonb end) g
     where public.career_proof_key(g ->> 'kind') is not null and g ->> 'kind' is not null;
    return v_out;
  elsif v_t = 'best_value' then
    return array[public.career_maxpct_key(p_body)];
  elsif v_t = 'run_regained' then
    return array['weeks'];
  elsif v_t = 'total' then      -- stage79: the at-th fact of its kind, counted as a badge of kind total counts it (a capped kind only as paid)
    return array['count:' || array_to_string(public.career_reads_kinds(p_body), ',')];   /* stage99: reads may be a list */
  elsif v_t = 'best_run' then   -- stage79: training weeks held in a row, the run the held_weeks mark walks
    return array['weeks'];
  end if;
  return '{}'::text[];
end $function$;

CREATE OR REPLACE FUNCTION public.career_entry_kinds(p_kind text, p_body jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_counts text[]; v_m text; v_t text;
begin
  v_counts := case jsonb_typeof(p_body -> 'counts')
                when 'array' then array(select jsonb_array_elements_text(p_body -> 'counts'))
                when 'string' then array[p_body ->> 'counts']
                else '{}'::text[] end;
  if p_kind = 'badge' then
    case p_body ->> 'kind'
      when 'best_run' then
        return case public.career_badge_run(p_body)
                 when 'plan_weeks' then array['week_held', 'week_broken']
                 when 'days' then array['habit_done']
                 else v_counts end;
      when 'total' then return v_counts;
      when 'best_value' then return array['lift_gain'];
      when 'per_habit_best_run' then return array['habit_done'];
      when 'proof' then v_m := p_body ->> 'proof_measure';
      else return v_counts;
    end case;
  else
    v_t := public.career_achievement_test(p_body);
    case v_t
      when 'first' then return array[p_body ->> 'reads'];
      when 'proof' then v_m := p_body ->> 'proof_measure';
      when 'goals' then return array['habit_done', 'habit_day', 'day_on_target', 'perfect_day', 'comeback', 'comeback_stuck'];
      when 'cycle_all_held', 'cycle_by_the_book', 'cycle_with_broken' then
        return array['cycle_finished', 'week_held', 'week_by_the_book', 'week_broken'];
      when 'runs_together' then return array['habit_done'];
      when 'patterns_in_cycle' then return array['personal_best'];
      when 'best_value' then return array['lift_gain'];
      when 'cycle_proving' then return array['personal_best', 'retest_beaten', 'week_held', 'week_broken'];
      when 'run_regained' then return array['week_held', 'week_broken'];
      when 'total' then return public.career_reads_kinds(p_body) /* stage99: reads may be a list */;
      when 'on_dates', 'slam_year', 'clock' then return array['session_finished', 'session_finished_early'];   /* stage99 */
      when 'best_run', 'month_held' then return array['week_held', 'week_broken'];
      else return '{}'::text[];
    end case;
  end if;
  return case when v_m is null then array['day_on_target']
              when v_m like 'streak:%' or v_m like 'daysHit:%' or v_m like 'total:%' then array['habit_done']
              when v_m = 'daysWith3' then array['habit_done', 'habit_day']
              when v_m in ('perfectDays', 'perfect') then array['perfect_day']
              when v_m = 'dayStreak' then array['day_on_target']
              when v_m = 'qualify' then array['day_on_target']
              when v_m = 'comebackRun' then array['comeback', 'day_on_target']
              when v_m = 'comebacksStuck' then array['comeback_stuck']
              else '{}'::text[] end;
end $function$;

CREATE OR REPLACE FUNCTION public.career_entry_sets(p_athlete text, p_from date, p_to date, p_plan text[])
 RETURNS TABLE(d date, plan_day integer, ord integer, name text, lift text, b_w numeric, b_n numeric, b_n_given boolean, b_r numeric, b_idx numeric, best_est numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  s record; e jsonb; eo integer; st jsonb;
  w numeric; n numeric; n_given boolean; r numeric; rir numeric; idx numeric; rpe numeric; eff numeric; est numeric;
  has_best boolean; bw numeric; bn numeric; bng boolean; br numeric; bidx numeric; best numeric;
  sets jsonb; wu text; v_m text; v_step numeric; wr record;
begin
  for s in
    select sh.completed_on, sh.day, sh.log from public.session_history sh
     where sh.athlete_id = p_athlete and sh.hidden_at is null and jsonb_typeof(sh.log) = 'array'
       and sh.completed_on between coalesce(p_from, '-infinity'::date) and coalesce(p_to, 'infinity'::date)
       and (p_plan is null or sh.day::text = any (p_plan))
     order by sh.completed_on, sh.day
  loop
    eo := 0;
    for e in select x.value from jsonb_array_elements(s.log) x loop
      eo := eo + 1;
      if jsonb_typeof(e) <> 'object' or public.career_truthy(e -> 'circuit') or not public.career_truthy(e -> 'ex') then continue; end if;
      has_best := false; bw := null; bn := null; bng := false; br := null; bidx := null; best := null;
      sets := case when jsonb_typeof(e -> 'sets') = 'array' then e -> 'sets' else '[]'::jsonb end;
      -- setsMeasure(): the measure of an exercise is the unit of the first logged set that holds a weight, else kilograms
      v_m := 'kg';
      for st in select y.value from jsonb_array_elements(sets) y loop
        if jsonb_typeof(st) = 'object'
           and (public.career_truthy(st -> 'w') or public.career_truthy(st -> 'r') or public.career_truthy(st -> 'd')) then
          wr := public.career_w(st -> 'w');
          if wr.n is not null then v_m := wr.u; exit; end if;
        end if;
      end loop;
      v_step := case v_m when 'lb' then 5 when 'plates' then 0.5 else 2.5 end;      -- ONE_RM_ROUND
      for st in select y.value from jsonb_array_elements(sets) y loop
        -- histSetLogged(): a weight, an RPE or a tick
        if jsonb_typeof(st) <> 'object'
           or not (public.career_truthy(st -> 'w') or public.career_truthy(st -> 'r') or public.career_truthy(st -> 'd')) then
          continue;
        end if;
        wr := public.career_w(st -> 'w'); w := wr.n; wu := wr.u;          -- the number as typed, in its own measure
        if w is not null and wu <> v_m then continue; end if;          -- a set in another measure is left out (cycleBestSet(), histBestSet())
        if st ? 'n' and jsonb_typeof(st -> 'n') <> 'null' and not (jsonb_typeof(st -> 'n') = 'string' and st ->> 'n' = '') then
          n_given := true; n := public.career_js_num(st -> 'n');
        elsif public.career_truthy(e -> 'reps') then
          n_given := true; n := public.career_js_num(e -> 'reps');
        else
          n_given := false; n := null;
        end if;
        r := case when public.career_truthy(st -> 'r') then public.career_js_num(st -> 'r') end;
        rir := case when r >= 6 and r <= 10 then 10 - r else 0 end;
        idx := case when n is not null and n <> 0 then case when w is not null then w * (1 + (n + rir) / 30) else n + rir end end;
        if not has_best
           or (idx is not null and (bidx is null or idx > bidx))
           or (idx is null and bidx is null and r is not null and (br is null or r < br)) then
          has_best := true; bw := w; bn := n; bng := n_given; br := r; bidx := idx;
        end if;
        rpe := public.career_js_num(st -> 'r');
        est := null;
        if w is not null and n is not null and n > 0 and rpe > 0 then
          eff := n + greatest(0, 10 - rpe);
          if eff <= 10 then
            if v_m = 'kg' then
              est := round((case when eff <= 1 then w else w * (1 + eff / 30) end) / v_step) * v_step;        -- exact numbers, as stage66 had it
            else
              -- pounds and plates in DOUBLES, operation for operation as estimateOneRM() computes them: an estimate that lands exactly on
              -- half a step (225 lb x 5 @8 is 277.5) is rounded up there, and exact numbers (1/30 cut at 20 digits) would round it down
              est := (floor((case when eff <= 1 then w::float8 else w::float8 * (1 + eff::float8 / 30) end) / v_step::float8 + 0.5) * v_step::float8)::numeric;
            end if;
          end if;
        end if;
        if est is not null and (best is null or est > best) then best := est; end if;
      end loop;
      if has_best then
        d := s.completed_on; plan_day := s.day; ord := eo; name := e ->> 'ex'; lift := public.career_lift_key(e ->> 'ex', v_m);
        b_w := bw; b_n := bn; b_n_given := bng; b_r := br; b_idx := bidx; best_est := best;
        return next;
      end if;
    end loop;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.career_evaluate(p_athlete text, p_kinds text[] DEFAULT NULL::text[], p_how text DEFAULT 'live'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb; v_S date; v_old jsonb; v_found boolean; v_kinds text[] := p_kinds; v_stamp text; v_hr jsonb; v_ctx jsonb;
  v_backfill integer; v_commended boolean; v_cycles boolean := false; v_test text;
  c record; t record; x jsonb; r jsonb; v_woken jsonb := '[]'::jsonb; v_keys text[] := '{}'::text[]; v_m jsonb;
  v_have jsonb := '{}'::jsonb; v_now jsonb := '{}'::jsonb; v_minted text[] := '{}'::text[]; v_title boolean := false;
  v_tb jsonb; v_slam jsonb; v_rw jsonb; v_day date;
begin
  if p_athlete is null or not public.career_catalogue_on() then return null; end if;
  if p_how is null or p_how not in ('live', 'silent', 'baseline') then
    raise exception 'career_evaluate: p_how is live, silent or baseline, not %', p_how;
  end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  v_rules := public.career_rules_now();
  v_S := public.career_switch_day(v_rules, 'catalogue');
  select s.rewards into v_old from public.career_scores s where s.athlete_id = p_athlete;
  v_found := found;
  if not v_found then       -- no score row yet: what an earlier call in this transaction worked out (career_scored() stores it with the row)
    v_old := nullif(current_setting('career.rw_' || md5(p_athlete), true), '')::jsonb;
  end if;
  if v_old ->> 'base' is distinct from v_S::text then v_kinds := null; end if;
  v_stamp := public.career_rewards_stamp(p_athlete);
  if v_kinds is null and v_old ->> 'stamp' = v_stamp then
    return v_old || '{"skipped": true}'::jsonb;
  end if;

  v_hr := public.career_habit_rules();
  v_backfill := coalesce(public.career_num(v_rules #> '{habits,backfill_days}'), 3)::int;
  v_ctx := jsonb_build_object(
    'S', v_S, 'hr', v_hr, 'targets', coalesce(v_hr -> 'targets', '{}'::jsonb),
    'custom', coalesce((select f.value -> 'custom' from public.career_facts f
                         where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null and jsonb_typeof(f.value -> 'custom') = 'array'
                         order by f.day desc limit 1), '[]'::jsonb),
    'weights', v_hr -> 'weights', 'cb', v_hr -> 'completionBonus', 'cx', v_hr -> 'customXp',
    'version', (select max(rr.version) from public.career_rules rr),
    'owned', coalesce((select jsonb_object_agg(a.award_id, a.day) from public.career_awards a where a.athlete_id = p_athlete), '{}'::jsonb));
  v_commended := exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'commendation' and f.void_at is null);

  -- which entries wake, and the measures they need
  for c in select cc.kind, cc.id, cc.body from public.career_catalogue cc where cc.kind in ('badge', 'achievement')
            order by (cc.kind = 'badge') desc, cc.id loop
    if c.body ->> 'meaning' = 'chosen' and not v_commended then continue; end if;                       -- phase 4
    if v_kinds is not null and not (public.career_entry_kinds(c.kind, c.body) && v_kinds) then continue; end if;
    if c.body ? 'retire_at' and p_how <> 'baseline' and current_date > v_S + v_backfill + 1 then continue; end if;
    if c.kind = 'achievement' then
      if (v_ctx -> 'owned') ? ('achievement:' || c.id) then continue; end if;                          -- owned: nothing left to cross
      v_test := public.career_achievement_test(c.body);
      if v_test in ('patterns_in_cycle', 'cycle_proving') then v_cycles := true; end if;
    end if;
    v_woken := v_woken || jsonb_build_array(jsonb_build_object('kind', c.kind, 'id', c.id, 'body', c.body));
    v_keys := v_keys || public.career_entry_keys(c.kind, c.body, v_ctx);
  end loop;
  if v_cycles then
    v_ctx := v_ctx || jsonb_build_object('cycles', coalesce((
      select jsonb_agg(jsonb_build_object('num', z.cycle_num, 'cstart', z.cstart, 'cend', z.cend) order by z.cycle_index)
        from (select distinct on (w.cycle_index) w.cycle_index, w.cycle_num, w.cstart, w.cend
                from public.career_weeks(p_athlete) w order by w.cycle_index) z), '[]'::jsonb));
  end if;
  v_m := public.career_measures(p_athlete, v_ctx, v_keys);

  -- every woken entry against the measures; what is new is minted
  for x in select e from jsonb_array_elements(v_woken) e loop
    if x ->> 'kind' = 'badge' then
      r := public.career_badge_eval(x ->> 'id', x -> 'body', v_m, v_ctx);
      v_have := v_have || jsonb_build_object(x ->> 'id', r -> 'have');
      if jsonb_typeof(r -> 'now') = 'number' then v_now := v_now || jsonb_build_object(x ->> 'id', r -> 'now'); end if;
    else
      r := public.career_achievement_eval(p_athlete, x ->> 'id', x -> 'body', v_m, v_ctx);
    end if;
    for t in select e from jsonb_array_elements(coalesce(r -> 'crossed', '[]'::jsonb)) e loop
      if public.career_mint(p_athlete, x ->> 'kind', x ->> 'id', (t.e ->> 'tier')::int, coalesce(t.e ->> 'subject', ''), (t.e ->> 'day')::date,
                            x -> 'body', case when t.e ? 'tier' then x -> 'body' -> 'tiers' -> ((t.e ->> 'tier')::int - 1) end,
                            t.e -> 'evidence', p_how, v_ctx) then
        v_minted := v_minted || public.career_award_id(x ->> 'kind', x ->> 'id', (t.e ->> 'tier')::int, coalesce(t.e ->> 'subject', ''));
      end if;
    end loop;
  end loop;

  -- titles: every owned tier or achievement whose CURRENT entry carries a title (a full call looks at all of them, so a title a re-seed
  -- added to a tier already owned, or one an earlier call missed, is minted too; a partial call only at what it just minted)
  for t in
    select a.award_id, a.day, a.size, a.how,
           case when a.kind = 'badge' then k0.body -> 'tiers' -> (a.tier - 1) ->> 'title' else k0.body ->> 'title' end as title
      from public.career_awards a join public.career_catalogue k0 on k0.kind = a.kind and k0.id = a.item
     where a.athlete_id = p_athlete and a.kind in ('badge', 'achievement')
       and (v_kinds is null or a.award_id = any (v_minted))
     order by a.day, a.award_id
  loop
    if t.title is null or exists (select 1 from public.career_awards z where z.athlete_id = p_athlete and z.award_id = 'title:' || t.title) then
      continue;
    end if;
    select k0.body into v_tb from public.career_catalogue k0 where k0.kind = 'title' and k0.id = t.title;
    if v_tb is null then continue; end if;
    if public.career_mint(p_athlete, 'title', t.title, null, '', t.day, v_tb, jsonb_build_object('size', t.size),
                          jsonb_build_object('from', t.award_id), case when t.how = 'live' then p_how else t.how end, v_ctx) then
      v_minted := v_minted || ('title:' || t.title);
      v_title := true;
    end if;
  end loop;

  -- the Grand Slam: a title of each of the four meanings
  if v_title or v_kinds is null then
    v_slam := public.career_slam(p_athlete);
    if v_slam -> 'consistency' <> 'null'::jsonb and v_slam -> 'commitment' <> 'null'::jsonb
       and v_slam -> 'progress' <> 'null'::jsonb and v_slam -> 'resilience' <> 'null'::jsonb
       and v_slam -> 'grand' = 'null'::jsonb then
      select k0.body into v_tb from public.career_catalogue k0 where k0.kind = 'title' and k0.id = 'grand_slam';
      if v_tb is not null then
        v_day := greatest((v_slam #>> '{consistency,day}')::date, (v_slam #>> '{commitment,day}')::date,
                          (v_slam #>> '{progress,day}')::date, (v_slam #>> '{resilience,day}')::date);
        if public.career_mint(p_athlete, 'title', 'grand_slam', null, '', v_day, v_tb, jsonb_build_object('size', coalesce(v_tb ->> 'size', 'legend')),
                              jsonb_build_object('titles', jsonb_build_array(v_slam #> '{consistency,id}', v_slam #> '{commitment,id}',
                                                                             v_slam #> '{progress,id}', v_slam #> '{resilience,id}')),
                              p_how, v_ctx) then
          v_minted := v_minted || 'title:grand_slam'::text;
        end if;
      end if;
    end if;
  end if;

  -- the cache: a partial call merges and keeps the stamp it found
  v_rw := jsonb_build_object(
    'have', coalesce(v_old -> 'have', '{}'::jsonb) || v_have,
    'now', coalesce(v_old -> 'now', '{}'::jsonb) || v_now,
    'at', clock_timestamp(), 'base', v_S::text,
    'stamp', case when v_kinds is null then to_jsonb(public.career_rewards_stamp(p_athlete)) else coalesce(v_old -> 'stamp', 'null'::jsonb) end);
  if v_found then
    update public.career_scores s set rewards = v_rw where s.athlete_id = p_athlete;
  else
    -- never a scoreless row (the board would serve it): kept for this transaction, and career_scored() stores it with the row it writes
    perform set_config('career.rw_' || md5(p_athlete), v_rw::text, true);
  end if;
  return v_rw || jsonb_build_object('minted', to_jsonb(v_minted));
end $function$;

CREATE OR REPLACE FUNCTION public.career_facts_paid(p_athlete text)
 RETURNS TABLE(kind text, ref text, day date, xp numeric, career_only boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with v as (select r.version, r.starts_on, r.rules as j from public.career_rules r),
  f as (
    select f.kind, f.ref, f.day, f.value from public.career_facts f
     where f.athlete_id = p_athlete and f.void_at is null
       and f.kind not in ('habit_done', 'habit_day', 'workout_tick', 'comeback', 'award_kept')
  ),
  priced as (
    select f.*,
           case when r.j -> 'fact' -> f.kind ->> 'xp_from' = 'value' then coalesce(public.career_num(f.value -> 'xp'), 0)
                else coalesce(public.career_num(r.j -> 'fact' -> f.kind -> 'xp'), 0) end as xp,
           coalesce(r.j -> 'fact' -> f.kind -> 'career_only' = 'true'::jsonb, false) as conly,
           r.j -> 'fact' -> f.kind ->> 'limit_per' as per,
           coalesce(public.career_num(r.j -> 'fact' -> f.kind -> 'limit'), 0) as lim
      from f cross join lateral (select v.j from v where v.starts_on is null or v.starts_on <= f.day order by v.version desc limit 1) r
  ),
  weeks as (select * from public.career_weeks(p_athlete)),
  keyed as (
    select p.*,
           case p.per
             when 'plan_day_week' then
               coalesce((select 'c' || w.cycle_num || '|w' || w.week from weeks w
                          where p.day between w.wfrom and w.wto and (p.value ->> 'plan_day') = any (w.plan)
                          order by w.cstart desc limit 1),
                        'iso:' || to_char(p.day, 'IYYY-IW')) || '|d' || coalesce(p.value ->> 'plan_day', '')
             when 'week' then 'iso:' || to_char(p.day, 'IYYY-IW')
             when 'cycle' then split_part(p.ref, '|', 1)
           end as grp
      from priced p
  ),
  ranked as (
    select k.*, row_number() over (partition by case when k.per = 'plan_day_week' then 'session' else k.kind end, k.grp
                                   order by k.xp desc, k.day, k.ref) as rn
      from keyed k
  )
  select ranked.kind, ranked.ref, ranked.day, ranked.xp, ranked.conly
    from ranked
   where ranked.grp is null or ranked.rn <= ranked.lim
  union all
  select 'award'::text, a.award_id, a.day, (case when not a.pays then 0 else a.xp end)::numeric,
         coalesce(a.earned_on < public.season_start_of(a.day), false)
    from public.career_awards a
   where a.athlete_id = p_athlete and public.career_catalogue_on()
  union all
  select 'award_kept'::text, k.ref, k.day, coalesce(public.career_num(k.value -> 'xp'), 0), false
    from public.career_facts k
   where k.athlete_id = p_athlete and k.kind = 'award_kept' and k.void_at is null and public.career_catalogue_on()
$function$;

CREATE OR REPLACE FUNCTION public.career_facts_xp(p_athlete text, p_from date, p_to date)
 RETURNS TABLE(kind text, n bigint, xp numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select p.kind, count(*), sum(p.xp)
    from public.career_facts_paid(p_athlete) p
   where p.day between coalesce(p_from, '-infinity'::date) and coalesce(p_to, 'infinity'::date)
     and not (p.career_only and p_from is not null)
   group by p.kind
$function$;

CREATE OR REPLACE FUNCTION public.career_habit_days(p_athlete text)
 RETURNS TABLE(d date, ndone integer, nlive integer, on_target boolean, perfect boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
with
  rr as (select public.career_habit_rules() as p_rules),
  bonusmult as (
    select coalesce((rr.p_rules ->> 'customXp')::numeric, 25) as cx,
           coalesce((rr.p_rules ->> 'streakQualifyPct')::numeric, 80) as qpct,
           coalesce((rr.p_rules ->> 'gateV2')::boolean, false) as gate2
      from rr
  ),
  hday as (
    select f.day, f.value from public.career_facts f
     where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null
  ),
  dl as (
    select h.day as d,
           coalesce((select jsonb_object_agg(substr(x.ref, 12), x.value -> 'v') from public.career_facts x
                      where x.athlete_id = p_athlete and x.kind = 'habit_done' and x.void_at is null and x.day = h.day),
                    '{}'::jsonb) as vals,
           h.value -> 'live' as ids
      from hday h
  ),
  lastday as (select h.value from hday h order by h.day desc limit 1),
  habits as (
    select t.key as hid, t.value::numeric as tgt, b.cx as fallback
      from rr, jsonb_each_text(coalesce(rr.p_rules -> 'targets', '{}'::jsonb)) t, bonusmult b
    union all
    select c.value, 1::numeric, b.cx
      from lastday, jsonb_array_elements_text(coalesce(lastday.value -> 'custom', '[]'::jsonb)) c, bonusmult b
  ),
  weighted as (
    select h.hid, h.tgt, coalesce((rr.p_rules -> 'weights' ->> h.hid)::numeric, h.fallback) as w
      from habits h, rr
  ),
  daylive as (
    select dl.d, w.hid, w.tgt, w.w,
           jsonb_exists(coalesce(rr.p_rules -> 'unearnable', '[]'::jsonb), w.hid) as lockd
      from dl cross join weighted w cross join rr
     where jsonb_exists(dl.ids, w.hid)
  ),
  perday as (
    select dl.d, dl.vals,
           count(dv.hid) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt)::int as ndone,
           count(dv.hid)::int as nlive,
           coalesce(sum(dv.w) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt), 0) as wdone,
           coalesce(sum(dv.w) filter (
             where (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                    and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
                or not dv.lockd), 0) as glive,
           coalesce(sum(
             case when jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt
                  then dv.w
                  when dv.lockd then 0
                  when dv.tgt > 0 and jsonb_typeof(dl.vals -> dv.hid) = 'number'
                       and (dl.vals ->> dv.hid)::numeric > 0
                  then dv.w * least((dl.vals ->> dv.hid)::numeric / dv.tgt, 1)
                  else 0 end), 0) as gpart,
           count(dv.hid) filter (
             where not (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
               and not dv.lockd)::int as gmiss
    from dl left join daylive dv on dv.d = dl.d
    group by dl.d, dl.vals
  ),
  qualday as (
    select p.d
    from perday p, bonusmult b
    where case when b.gate2
               then (p.glive > 0 and round(p.gpart / p.glive * 100) >= b.qpct)
                     or (p.gmiss <= 1 and p.gpart > 0)
               else p.glive > 0 and round(p.wdone / p.glive * 100) >= b.qpct
          end
  )
select p.d, p.ndone, p.nlive, (q.d is not null), (p.nlive > 0 and p.ndone >= p.nlive)
  from perday p left join qualday q on q.d = p.d
$function$;

CREATE OR REPLACE FUNCTION public.career_habit_rules()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with r as (select public.career_rules_now() as j),
  b as (select c.body from public.career_catalogue c where c.kind = 'badge' and c.body ->> 'origin' = 'proof'),
  a as (select c.body from public.career_catalogue c where c.kind = 'achievement' and c.body ->> 'origin' = 'proof'),
  m as (select c.body from public.career_catalogue c where c.kind = 'mission' and c.body ->> 'origin' = 'proof')
  select case when r.j is null then null else jsonb_build_object(
    'completionBonus',  r.j #> '{habits,completion_bonus}',
    'customXp',         r.j #> '{habits,weights,custom}',
    'maxCustom',        r.j #> '{habits,max_custom}',
    'weights',          coalesce(r.j #> '{habits,weights}', '{}'::jsonb) - 'custom',
    'targets',          coalesce(r.j #> '{habits,targets}', '{}'::jsonb),
    'streakQualifyPct', r.j #> '{habits,qualify_pct}',
    'gateV2',           r.j #> '{habits,one_miss_door}',
    'unearnable',       coalesce(r.j #> '{habits,locked}', '[]'::jsonb),
    'lapseDays',        r.j #> '{habits,lapse_days}',
    'comebackXp',       r.j #> '{fact,comeback,xp}',
    'comebackStick',    r.j #> '{habits,comeback_stick}',
    'tiers', coalesce((select jsonb_agg(jsonb_build_object('days', t.value -> 'at', 'mult', t.value -> 'mult') order by t.ord)
                         from b, jsonb_array_elements(b.body -> 'tiers') with ordinality t(value, ord)
                        where b.body ->> 'kind' = 'per_habit_best_run'), '[]'::jsonb),
    'milestones', coalesce((select jsonb_agg(x.ms) from (
                     select jsonb_build_object('code', b.body -> 'proof_codes' -> (t.ord - 1)::int, 'need', t.value -> 'at',
                                               'xp', t.value -> 'xp', 'measure', b.body -> 'proof_measure') as ms
                       from b, jsonb_array_elements(b.body -> 'tiers') with ordinality t(value, ord)
                      where b.body ? 'proof_measure'
                     union all
                     select jsonb_build_object('code', a.body -> 'proof_code', 'need', a.body -> 'proof_need',
                                               'xp', a.body -> 'xp', 'measure', a.body -> 'proof_measure')
                       from a where a.body ? 'proof_measure') x), '[]'::jsonb),
    'quests', coalesce((select jsonb_agg(jsonb_build_object('id', m.body -> 'proof_id', 'kind', m.body -> 'proof_kind',
                                                            'need', m.body -> 'proof_need', 'xp', m.body -> 'proof_xp'))
                          from m where m.body ? 'proof_kind'), '[]'::jsonb),
    'questRuns', coalesce((select x.rules -> 'questRuns' from public.xp_rules x where x.id = 1), '[]'::jsonb)
  ) end
  from r
$function$;

CREATE OR REPLACE FUNCTION public.career_honour_figure(p_month date, p_honour text, p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  m1 date := (date_trunc('month', p_month) + interval '1 month')::date - 1;
  v_rules jsonb := jsonb_set(public.career_rules_now(), '{fact,effort_win,limit}', '1000'::jsonb, true);
  v_n int; v_w record;
begin
  if p_honour = 'sessions' then
    select count(*)::int into v_n from public.career_facts_paid(p_athlete_id) x
     where x.kind in ('session_finished', 'session_finished_early') and x.day between m0 and m1;
    if v_n >= 1 then return jsonb_build_object('n', v_n); end if;
  elsif p_honour = 'improved' then
    select w.name, round(w.gain * 100, 1) as pct into v_w
      from public.career_cycle_wins(p_athlete_id, m0, m1, null, v_rules) w
     where public.career_norm(w.name) in (select nm from public.career_main_lift_names() nm)
     order by round(w.gain * 100, 1) desc, w.name limit 1;
    if v_w.name is not null and v_w.pct > 0 then return jsonb_build_object('lift', v_w.name, 'pct', v_w.pct); end if;
  elsif p_honour = 'full_month' then
    select count(*)::int into v_n from public.career_weeks(p_athlete_id) w where w.wto between m0 and m1 and coalesce(array_length(w.plan, 1), 0) > 0;
    if v_n >= 1 then return jsonb_build_object('weeks', v_n); end if;
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_honours_live(p_month date, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  m1 date := (date_trunc('month', p_month) + interval '1 month')::date - 1;
  v_rules jsonb := jsonb_set(public.career_rules_now(), '{fact,effort_win,limit}', '1000'::jsonb, true);   -- every win, not the top three
  v_out jsonb;
begin
  with
  _cs_people as (
    select p.athlete_id from public.programs p
     where public.career_is_client(p.athlete_id, p_not_clients)
       and exists (select 1 from public.career_facts f where f.athlete_id = p.athlete_id and f.void_at is null and f.day between m0 and m1)),
  paid as (
    select pp.athlete_id, count(*)::int as n
      from _cs_people pp cross join lateral public.career_facts_paid(pp.athlete_id) x
     where x.kind in ('session_finished', 'session_finished_early') and x.day between m0 and m1
     group by pp.athlete_id),
  mains as (select nm from public.career_main_lift_names() nm),
  wins as (
    select pp.athlete_id, w.name, round(w.gain * 100, 1) as pct
      from _cs_people pp cross join lateral public.career_cycle_wins(pp.athlete_id, m0, m1, null, v_rules) w
     where public.career_norm(w.name) in (select nm from mains)),
  best_win as (
    select distinct on (athlete_id) athlete_id, name, pct from wins order by athlete_id, pct desc, name),
  wk as (
    select pp.athlete_id, w.cycle_num, w.week,
           exists (select 1 from public.career_facts f where f.athlete_id = pp.athlete_id and f.kind = 'week_held' and f.void_at is null
                     and f.ref = 'c' || w.cycle_num || '|w' || w.week) as held
      from _cs_people pp cross join lateral public.career_weeks(pp.athlete_id) w
     where w.wto between m0 and m1 and coalesce(array_length(w.plan, 1), 0) > 0),
  wk_sum as (select athlete_id, count(*)::int as weeks, count(*) filter (where held)::int as held from wk group by athlete_id),
  held_in as (
    select f.athlete_id, count(*)::int as n from public.career_facts f join _cs_people pp using (athlete_id)
     where f.kind = 'week_held' and f.void_at is null and f.day between m0 and m1 group by f.athlete_id),
  back_in as (
    select f.athlete_id, count(*)::int as n, max(public.career_num(f.value -> 'gone')) as gone
      from public.career_facts f join _cs_people pp using (athlete_id)
     where f.kind in ('training_return', 'bounce_back', 'comeback') and f.void_at is null and f.day between m0 and m1
     group by f.athlete_id),
  top_paid as (select max(n) as n from paid),
  top_win as (select max(pct) as pct from best_win),
  s1 as (select athlete_id, n from held_in order by n desc, athlete_id limit 1),
  s2 as (select athlete_id, name, pct from best_win where athlete_id not in (select athlete_id from s1) order by pct desc, athlete_id limit 1),
  s3 as (select athlete_id, n, gone from back_in
          where athlete_id not in (select athlete_id from s1) and athlete_id not in (select athlete_id from s2)
          order by n desc, gone desc nulls last, athlete_id limit 1)
  select jsonb_build_object(
    'month', m0,
    'sessions', jsonb_build_object('n', (select n from top_paid),
                  'who', coalesce((select jsonb_agg(p.athlete_id order by p.athlete_id) from paid p, top_paid t where p.n = t.n and t.n >= 1), '[]'::jsonb)),
    'improved', jsonb_build_object('pct', (select pct from top_win),
                  'who', coalesce((select jsonb_agg(jsonb_build_object('athlete_id', b.athlete_id, 'lift', b.name, 'pct', b.pct) order by b.athlete_id)
                                     from best_win b, top_win t where b.pct = t.pct and t.pct > 0), '[]'::jsonb)),
    'full_month', jsonb_build_object(
                  'who', coalesce((select jsonb_agg(jsonb_build_object('athlete_id', w.athlete_id, 'weeks', w.weeks) order by w.athlete_id)
                                     from wk_sum w where w.weeks >= 4 and w.held = w.weeks), '[]'::jsonb),
                  'near', coalesce((select jsonb_agg(jsonb_build_object('athlete_id', w.athlete_id, 'held', w.held, 'weeks', w.weeks) order by w.athlete_id)
                                      from wk_sum w where w.weeks >= 4 and w.held = w.weeks - 1), '[]'::jsonb)),
    'shortlist', coalesce((select jsonb_agg(x.o order by x.k) from (
                    select 1 as k, jsonb_build_object('slot', 'weeks_held', 'athlete_id', athlete_id, 'n', n) as o from s1 where n > 0
                    union all select 2, jsonb_build_object('slot', 'gain', 'athlete_id', athlete_id, 'lift', name, 'pct', pct) from s2 where pct > 0
                    union all select 3, jsonb_build_object('slot', 'comeback', 'athlete_id', athlete_id, 'n', n, 'gone', gone) from s3 where n > 0) x), '[]'::jsonb))
  into v_out;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.career_honours_open(p_month date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select current_date >= ((date_trunc('month', p_month) + interval '1 month')::date - 1)
$function$;

CREATE OR REPLACE FUNCTION public.career_in_windows(p_day date, p_windows jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(bool_or(to_char(p_day, 'MM-DD') between (w.v ->> 'from') and (w.v ->> 'to')), false)
    from jsonb_array_elements(case when jsonb_typeof(p_windows) = 'array' then p_windows else '[]'::jsonb end) w(v)
$function$;

CREATE OR REPLACE FUNCTION public.career_is_client(p_athlete text, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_athlete, '') not in ('', 'demo')
     and not (p_athlete = any (coalesce(p_not_clients, '{}'::text[])))
     and not exists (select 1 from public.athlete_status s where s.athlete_id = p_athlete and s.status = 'former')
$function$;

CREATE OR REPLACE FUNCTION public.career_js_num(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text;
begin
  if p is null then return null; end if;
  case jsonb_typeof(p)
    when 'number' then return (p #>> '{}')::numeric;
    when 'boolean' then return case when p = 'true'::jsonb then 1 else 0 end;
    when 'null' then return 0;
    when 'string' then
      t := btrim(p #>> '{}');
      if t = '' then return 0; end if;
      if t ~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$' then return t::numeric; end if;
      return null;
    else return null;
  end case;
end $function$;

CREATE OR REPLACE FUNCTION public.career_keep_levels(p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now(); a record; v_rows jsonb := '[]'::jsonb;
  v_record integer; v_now integer; v_best integer; v_xp bigint; v_raw bigint; v_lv integer; v_kept bigint; v_had jsonb;
begin
  if v_rules is null or public.career_switch_day(v_rules, 'xp') is null then
    raise exception 'career_keep_levels: the XP switch is not on (rulebook.toml → [switch] xp)';
  end if;
  for a in
    select z.id,
           coalesce(nullif(btrim(concat_ws(' ', p.data #>> '{athlete,firstName}', p.data #>> '{athlete,lastName}')), ''), o.display_name) as name,
           exists (select 1 from public.athlete_progress ap where ap.athlete_id = z.id and ap.data ? (z.id || '_hab_log')) as has_log
      from (select ap.athlete_id as id from public.athlete_progress ap where ap.data ? (ap.athlete_id || '_hab_log')
            union select r.athlete_id from public.hab_season_results r
            union select f.athlete_id from public.career_facts f where f.void_at is null) z
      left join public.programs p on p.athlete_id = z.id
      left join public.leaderboard_optin o on o.athlete_id = z.id
     order by z.id
  loop
    v_record := (select max(r.level) from public.hab_season_results r where r.athlete_id = a.id);
    v_now := case when a.has_log then public.hab_proof_level(a.id) end;
    v_best := greatest(coalesce(v_record, 0), coalesce(v_now, 0));
    select f.value into v_had from public.career_facts f
     where f.athlete_id = a.id and f.kind = 'level_kept' and f.ref = 'xp-switch' and f.void_at is null;
    v_xp := coalesce((public.career_score(a.id, null, null, current_date) ->> 'xp')::bigint, 0);
    v_raw := v_xp - coalesce(public.career_num(v_had -> 'xp'), 0)::bigint;          -- the career without the level kept
    v_lv := (public.career_level(v_raw, v_rules) ->> 'level')::int;
    v_kept := coalesce(public.career_num(v_had -> 'xp'), 0)::bigint;
    if v_had is null and v_best > v_lv then
      v_kept := public.career_level_floor(v_best, v_rules) - v_raw;
      insert into public.career_facts (athlete_id, kind, ref, day, value, source, updated_at)
      values (a.id, 'level_kept', 'xp-switch', p_day,
              jsonb_strip_nulls(jsonb_build_object('xp', v_kept, 'level', v_best, 'was', v_lv,
                                                   'proof_record', v_record, 'proof_now', v_now)), 'server', clock_timestamp())
      on conflict (athlete_id, kind, ref) do update
         set day = excluded.day, value = excluded.value, source = excluded.source, void_at = null, updated_at = clock_timestamp();
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'athlete_id', a.id, 'name', a.name, 'proof_now', v_now, 'proof_record', v_record,
      'career_xp', v_raw, 'career_level', v_lv, 'kept_xp', nullif(v_kept, 0),
      'level', (public.career_level(v_raw + v_kept, v_rules) ->> 'level')::int)));
  end loop;
  return v_rows;
end $function$;

CREATE OR REPLACE FUNCTION public.career_kg(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text; m text[]; n numeric;
begin
  if p is null or jsonb_typeof(p) not in ('string', 'number') then return null; end if;
  if not public.career_truthy(p) then return null; end if;        -- String(v || ''): 0 and '' read as nothing
  t := regexp_replace(public.career_digits(p #>> '{}'), ',', '.');  -- the first comma only, as String.replace does
  m := regexp_match(t, '^\s*([1-4])\s*[×xX*]\s*([0-9]+(?:\.[0-9]+)?)');
  if m is not null then
    n := m[2]::numeric;
  else
    m := regexp_match(t, '[0-9]+(?:\.[0-9]+)?');
    if m is null then return null; end if;
    n := m[1]::numeric;
  end if;
  if not (n > 0) then return null; end if;
  -- the unit, as weightOf() reads it: pounds first, then plates, else kilograms
  if t ~* '[0-9]\s*(lbs?|pounds?)([^a-z]|$)' then return round(n * 0.45359237, 2); end if;
  if t ~* '[0-9]\s*plates?([^a-z]|$)' then return null; end if;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.career_level(p_xp bigint, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_base numeric := coalesce(public.career_num(p_rules #> '{level,base}'), 300);
  v_growth numeric := coalesce(public.career_num(p_rules #> '{level,growth}'), 0.55);
  v_per integer := greatest(1, coalesce(public.career_num(p_rules #> '{level,levels_per_rank}')::int, 5));
  v_prestige integer := greatest(1, coalesce(public.career_num(p_rules #> '{level,prestige_after}')::int, 50));
  v_ranks jsonb := coalesce(p_rules #> '{level,ranks}', '[]'::jsonb);
  v_xp numeric := greatest(coalesce(p_xp, 0), 0);
  lv integer := 1; spent numeric := 0; cost numeric; i integer; star integer; within integer; nm text;
begin
  cost := greatest(10, round(v_base * power(1, v_growth) / 10) * 10);
  while lv < 100000 and v_xp - spent >= cost loop
    spent := spent + cost;
    lv := lv + 1;
    cost := greatest(10, round(v_base * power(lv, v_growth) / 10) * 10);
  end loop;
  i := lv - 1; star := i / v_prestige; within := i % v_prestige;
  nm := coalesce(v_ranks ->> least(within / v_per, greatest(jsonb_array_length(v_ranks) - 1, 0)), '');
  return jsonb_build_object('level', lv,
                            'rank', case when star > 0 then '★' || star || ' ' else '' end || nm || ' ' || (within % v_per + 1),
                            'xp_in_level', (v_xp - spent)::bigint, 'level_cost', cost::bigint, 'to_next', (cost - (v_xp - spent))::bigint);
end $function$;

CREATE OR REPLACE FUNCTION public.career_level_floor(p_level integer, p_rules jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_base numeric := coalesce(public.career_num(p_rules #> '{level,base}'), 300);
  v_growth numeric := coalesce(public.career_num(p_rules #> '{level,growth}'), 0.55);
  lv integer := 1; total numeric := 0;
begin
  while lv < least(coalesce(p_level, 1), 100000) loop
    total := total + greatest(10, round(v_base * power(lv, v_growth) / 10) * 10);
    lv := lv + 1;
  end loop;
  return total::bigint;
end $function$;

CREATE OR REPLACE FUNCTION public.career_lift_base(p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ select regexp_replace(p_key, '\|(lb|plates)$', '') $function$;

CREATE OR REPLACE FUNCTION public.career_lift_gains(p_athlete text)
 RETURNS TABLE(lift text, name text, pct numeric, d date)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  x record; v_cur text := null; v_out jsonb := '[]'::jsonb;
  a_name text; a_w numeric; a_n numeric; a_ng boolean; a_idx numeric; best_idx numeric; best_d date;
begin
  for x in
    select es.* from public.career_entry_sets(p_athlete, null, null, null) es
     where es.lift <> '' order by es.lift, es.d, es.plan_day, es.ord
  loop
    if v_cur is distinct from x.lift then
      if v_cur is not null and best_idx is not null then
        v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'p', round((best_idx / a_idx - 1) * 100, 1), 'dd', best_d));
      end if;
      v_cur := x.lift; a_name := x.name; a_w := x.b_w; a_n := x.b_n; a_ng := x.b_n_given; a_idx := x.b_idx;
      best_idx := null; best_d := null;
    elsif a_ng and x.b_n_given and coalesce(a_idx, 0) > 0 and coalesce(x.b_idx, 0) > a_idx and x.b_idx > coalesce(best_idx, 0)
          and ((a_w is null) = (x.b_w is null))
          and ((a_w is not null and round((x.b_w - a_w) * 2) / 2 > 0) or coalesce(x.b_n, 0) > coalesce(a_n, 0)) then
      best_idx := x.b_idx; best_d := x.d;
    end if;
  end loop;
  if v_cur is not null and best_idx is not null then
    v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'p', round((best_idx / a_idx - 1) * 100, 1), 'dd', best_d));
  end if;
  return query select y.l, y.nm, y.p, y.dd from jsonb_to_recordset(v_out) as y(l text, nm text, p numeric, dd date);
end $function$;

CREATE OR REPLACE FUNCTION public.career_lift_key(p_name text, p_unit text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select public.career_norm(p_name) || case when p_unit in ('lb', 'plates') then '|' || p_unit else '' end
$function$;

CREATE OR REPLACE FUNCTION public.career_lift_unit(p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when p_key ~ '\|lb$' then 'lb' when p_key ~ '\|plates$' then 'plates' else 'kg' end
$function$;

CREATE OR REPLACE FUNCTION public.career_log(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(x.day::text, x.vals), '{}'::jsonb)
    from (select d.day,
                 coalesce((select jsonb_object_agg(substr(f.ref, 12), f.value -> 'v') from public.career_facts f
                            where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null and f.day = d.day),
                          '{}'::jsonb) as vals
            from (select distinct f.day from public.career_facts f
                   where f.athlete_id = p_athlete and f.kind in ('habit_day', 'habit_done') and f.void_at is null) d) x
$function$;

CREATE OR REPLACE FUNCTION public.career_main_lift_names()
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_k text; v_pats text[]; v_qs text[]; v_xs text[];
begin
  select public.career_maxpct_key(c.body) into v_k from public.career_catalogue c where c.kind = 'achievement' and c.id = 'double_up';
  if v_k is null or v_k not like 'maxpct:%' then return; end if;
  v_pats := string_to_array(substr(split_part(v_k, '|', 1), 8), ',');
  v_qs := (select string_to_array(substr(p.x, 3), ',') from unnest((string_to_array(v_k, '|'))[2:]) p(x) where p.x like 'q:%' limit 1);
  v_xs := (select string_to_array(substr(p.x, 3), ',') from unnest((string_to_array(v_k, '|'))[2:]) p(x) where p.x like 'x:%' limit 1);
  if v_xs is not null and exists (select 1 from unnest(v_xs) i(id) where not exists (select 1 from public.exercises e where e.id = i.id)) then
    return;
  end if;
  return query
    select distinct public.career_norm(n.x)
      from public.exercises e cross join unnest(array[e.name] || coalesce(e.aliases, '{}'::text[])) n(x)
     where e.status = 'approved' and e.pattern = any (v_pats)
       and (v_qs is null or e.qualities && v_qs) and (v_xs is null or e.id <> all (v_xs));
end $function$;

CREATE OR REPLACE FUNCTION public.career_maxpct_key(p_body jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case jsonb_typeof(p_body -> 'patterns')
           when 'array' then 'maxpct:' || coalesce((select string_agg(distinct x, ',' order by x)
                                                     from jsonb_array_elements_text(p_body -> 'patterns') x where x <> ''), '')
           when 'string' then 'maxpct:' || (p_body ->> 'patterns')
           else 'maxpct' end
      || case jsonb_typeof(p_body -> 'qualities')
           when 'array' then '|q:' || coalesce((select string_agg(distinct x, ',' order by x)
                                                  from jsonb_array_elements_text(p_body -> 'qualities') x where x <> ''), '')
           when 'string' then '|q:' || (p_body ->> 'qualities')
           else '' end
      || case jsonb_typeof(p_body -> 'exclude')
           when 'array' then '|x:' || coalesce((select string_agg(distinct x, ',' order by x)
                                                  from jsonb_array_elements_text(p_body -> 'exclude') x where x <> ''), '')
           when 'string' then '|x:' || (p_body ->> 'exclude')
           else '' end
$function$;

CREATE OR REPLACE FUNCTION public.career_measures(p_athlete text, p_ctx jsonb, p_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_out jsonb := '{}'::jsonb; v_k text; v_h text; v_t numeric; v_v jsonb; v_kinds text[]; r record;
  v_best integer; v_run integer; v_steps jsonb; v_walk jsonb; v_custom text[]; v_capped text[]; v_pats text[];
  c_empty constant jsonb := '{"have": 0, "now": null, "steps": []}'::jsonb;
begin
  v_custom := array(select jsonb_array_elements_text(coalesce(p_ctx -> 'custom', '[]'::jsonb)));
  for v_k in select distinct x from unnest(coalesce(p_keys, '{}'::text[])) x where x is not null order by 1 loop
    v_v := null;
    if v_k like 'run:%' or v_k like 'hits:%' or v_k like 'sum:%' then
      v_h := substr(v_k, strpos(v_k, ':') + 1);
      v_t := coalesce(public.career_num(p_ctx -> 'targets' -> v_h), case when v_h = any (v_custom) then 1 end);
      if v_k = 'run:custom' then
        with dn as (
          select substr(f.ref, 12) as hid, f.day as d from public.career_facts f
           where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null
             and substr(f.ref, 12) = any (v_custom)
             and jsonb_typeof(f.value -> 'v') = 'number' and (f.value ->> 'v')::numeric >= 1
        ),
        isl as (select dn.hid, dn.d, dn.d - (row_number() over (partition by dn.hid order by dn.d))::int as grp from dn),
        rl as (select isl.hid, isl.d, (row_number() over (partition by isl.hid, isl.grp order by isl.d))::int as run from isl),
        lastd as (select distinct on (rl.hid) rl.hid, rl.d, rl.run from rl order by rl.hid, rl.d desc),
        perday as (select rl.d, max(rl.run) as run, (array_agg(rl.hid order by rl.run desc, rl.hid))[1] as hid from rl group by rl.d),
        mx as (select p.d, p.run, p.hid,
                      coalesce(max(p.run) over (order by p.d rows between unbounded preceding and 1 preceding), 0) as prev from perday p)
        select jsonb_build_object(
                 'have', coalesce((select max(perday.run) from perday), 0),
                 'now', coalesce((select max(l.run) from lastd l where l.d >= current_date - 1), 0),
                 'steps', coalesce((select jsonb_agg(jsonb_build_array(mx.d, mx.run, 'habit_done', mx.d::text || '|' || mx.hid) order by mx.d)
                                      from mx where mx.run > mx.prev), '[]'::jsonb))
          into v_v;
      elsif v_t is null then
        v_v := c_empty;
      elsif v_k like 'run:%' then
        with dn as (
          select f.day as d from public.career_facts f
           where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null and substr(f.ref, 12) = v_h
             and jsonb_typeof(f.value -> 'v') = 'number' and (f.value ->> 'v')::numeric >= v_t
        ),
        isl as (select dn.d, dn.d - (row_number() over (order by dn.d))::int as grp from dn),
        rl as (select isl.d, (row_number() over (partition by isl.grp order by isl.d))::int as run from isl),
        mx as (select rl.d, rl.run, coalesce(max(rl.run) over (order by rl.d rows between unbounded preceding and 1 preceding), 0) as prev from rl)
        select jsonb_build_object(
                 'have', coalesce((select max(rl.run) from rl), 0),
                 'now', coalesce((select rl.run from rl where rl.d >= current_date - 1 order by rl.d desc limit 1), 0),
                 'steps', coalesce((select jsonb_agg(jsonb_build_array(mx.d, mx.run, 'habit_done', mx.d::text || '|' || v_h) order by mx.d)
                                      from mx where mx.run > mx.prev), '[]'::jsonb))
          into v_v;
      elsif v_k like 'hits:%' then
        with dn as (
          select f.day as d, f.ref from public.career_facts f
           where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null and substr(f.ref, 12) = v_h
             and jsonb_typeof(f.value -> 'v') = 'number' and (f.value ->> 'v')::numeric >= v_t
        ),
        hn as (select dn.d, dn.ref, (row_number() over (order by dn.d))::int as n from dn)
        select jsonb_build_object('have', (select count(*) from dn), 'now', null,
                 'steps', coalesce((select jsonb_agg(jsonb_build_array(hn.d, hn.n, 'habit_done', hn.ref) order by hn.d) from hn), '[]'::jsonb))
          into v_v;
      else      -- sum: every number logged for the habit, as hab_bonus_xp()'s quest totals add them
        with x as (
          select f.day as d, f.ref, (f.value ->> 'v')::numeric as val from public.career_facts f
           where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null and substr(f.ref, 12) = v_h
             and jsonb_typeof(f.value -> 'v') = 'number'
        ),
        acc as (select x.d, x.ref, x.val, sum(x.val) over (order by x.d) as tot from x)
        select jsonb_build_object('have', coalesce((select sum(x.val) from x), 0), 'now', null,
                 'steps', coalesce((select jsonb_agg(jsonb_build_array(acc.d, acc.tot, 'habit_done', acc.ref) order by acc.d)
                                      from acc where acc.val > 0), '[]'::jsonb))
          into v_v;
      end if;
    elsif v_k = 'with3' then
      with w3 as (select hd.d, (row_number() over (order by hd.d))::int as n from public.career_habit_days(p_athlete) hd where hd.ndone >= 3)
      select jsonb_build_object('have', (select count(*) from w3), 'now', null,
               'steps', coalesce((select jsonb_agg(jsonb_build_array(w3.d, w3.n, 'habit_day', w3.d::text) order by w3.d) from w3), '[]'::jsonb))
        into v_v;
    elsif v_k in ('perfect', 'qualify', 'stuck') or v_k like 'count:%' then
      v_kinds := case v_k when 'perfect' then array['perfect_day'] when 'qualify' then array['day_on_target']
                          when 'stuck' then array['comeback_stuck'] else string_to_array(substr(v_k, 7), ',') end;
      -- D19 (career/CAREER_MODE.md, round 4): a count over a kind the rulebook caps (limit_per: a session, one per plan day per training
      -- week; a Library session, two a week; an effort win, three a cycle) counts only the facts career_facts_paid() pays, the cap GAME-4
      -- puts on XP, so a plan day repeated in its week never moves Century. Every other kind is counted as it was. A finished and an early
      -- session share one cap, which pays the higher XP: count them together, as Century does. The early kind counted alone would lose
      -- one when a full finish of the same plan day in the same week replaces it; the finished kind alone holds while it out-earns an early one.
      v_capped := case when v_k like 'count:%'
                       then array(select k from unnest(v_kinds) k
                                   where public.career_rules_now() -> 'fact' -> k ->> 'limit_per' is not null)
                       else '{}'::text[] end;
      if cardinality(v_capped) = 0 then
      with x as (
        select f.day as d, f.kind, f.ref, (row_number() over (order by f.day, f.ref, f.kind))::int as n from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = any (v_kinds) and f.void_at is null
      )
      select jsonb_build_object('have', (select count(*) from x), 'now', null,
               'steps', coalesce((select jsonb_agg(jsonb_build_array(x.d, x.n, x.kind, x.ref) order by x.n) from x), '[]'::jsonb))
        into v_v;
      else
      with y as (
        select f.day as d, f.kind, f.ref from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = any (v_kinds) and not (f.kind = any (v_capped)) and f.void_at is null
        union all
        select p.day, p.kind, p.ref from public.career_facts_paid(p_athlete) p where p.kind = any (v_capped)
      ),
      x as (select y.d, y.kind, y.ref, (row_number() over (order by y.d, y.ref, y.kind))::int as n from y)
      select jsonb_build_object('have', (select count(*) from x), 'now', null,
               'steps', coalesce((select jsonb_agg(jsonb_build_array(x.d, x.n, x.kind, x.ref) order by x.n) from x), '[]'::jsonb))
        into v_v;
      end if;
    elsif v_k in ('daystreak', 'cbrun') then
      with q as (
        select f.day as d from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = 'day_on_target' and f.void_at is null
      ),
      isl as (select q.d, q.d - (row_number() over (order by q.d))::int as grp from q),
      rl as (select isl.d, isl.grp, (row_number() over (partition by isl.grp order by isl.d))::int as run from isl),
      st as (select isl.grp, min(isl.d) as s from isl group by isl.grp),
      cb as (
        select f.day as c, f.ref from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = 'comeback' and f.void_at is null
      ),
      pts as (    -- the day streak: every on-target day with its run; after a comeback: the days of the run that starts on it
        select rl.d, rl.run, 'day_on_target'::text as kind, rl.d::text as ref from rl where v_k = 'daystreak'
        union all
        select i.d, (i.d - cb.c + 1)::int, 'comeback', cb.ref from cb join st on st.s = cb.c join isl i on i.grp = st.grp where v_k = 'cbrun'
      ),
      mx as (select pts.*, coalesce(max(pts.run) over (order by pts.d rows between unbounded preceding and 1 preceding), 0) as prev from pts)
      select jsonb_build_object(
               'have', coalesce((select max(pts.run) from pts), 0),
               'now', case when v_k = 'daystreak'
                           then coalesce((select rl.run from rl where rl.d >= current_date - 1 order by rl.d desc limit 1), 0) end,
               'steps', coalesce((select jsonb_agg(jsonb_build_array(mx.d, mx.run, mx.kind, mx.ref) order by mx.d) from mx where mx.run > mx.prev),
                                 '[]'::jsonb))
        into v_v;
    elsif v_k = 'weeks' then
      -- held weeks in a row, walked as get_profile() walks them: a held week adds one, a broken week ends the run (a week between
      -- cycles, or one Amir paused, has no fact and is no week at all). The walk is kept for All the Way Back.
      v_best := 0; v_run := 0; v_steps := '[]'::jsonb; v_walk := '[]'::jsonb;
      for r in select f.kind, f.day, f.ref, public.career_num(f.value -> 'sessions') as sess from public.career_facts f
                where f.athlete_id = p_athlete and f.void_at is null and f.kind in ('week_held', 'week_broken')
                order by f.day, f.ref loop
        if r.kind = 'week_held' then
          v_run := v_run + 1;
          if v_run > v_best then
            v_best := v_run;
            v_steps := v_steps || jsonb_build_array(jsonb_build_array(r.day, v_run, r.kind, r.ref));
          end if;
        else
          v_run := 0;
        end if;
        v_walk := v_walk || jsonb_build_array(jsonb_build_array(r.day, case when r.kind = 'week_held' then 'h' else 'b' end, r.sess, r.ref));
      end loop;
      v_v := jsonb_build_object('have', v_best, 'now', v_run, 'steps', v_steps, 'walk', v_walk);
    elsif v_k like 'iso:%' then
      v_h := substr(v_k, 5);
      with x as (
        select f.day, f.ref from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = v_h and f.void_at is null
      ),
      w as (select date_trunc('week', x.day)::date as wk, min(x.day) as fd, (array_agg(x.ref order by x.day, x.ref))[1] as ref from x group by 1),
      isl as (select w.wk, w.fd, w.ref, w.wk - (7 * row_number() over (order by w.wk))::int as grp from w),
      rl as (select isl.wk, isl.fd, isl.ref, (row_number() over (partition by isl.grp order by isl.wk))::int as run from isl),
      mx as (select rl.*, coalesce(max(rl.run) over (order by rl.wk rows between unbounded preceding and 1 preceding), 0) as prev from rl)
      select jsonb_build_object(
               'have', coalesce((select max(rl.run) from rl), 0),
               'now', coalesce((select rl.run from rl where rl.wk >= date_trunc('week', current_date)::date - 7 order by rl.wk desc limit 1), 0),
               'steps', coalesce((select jsonb_agg(jsonb_build_array(mx.fd, mx.run, v_h, mx.ref) order by mx.wk) from mx where mx.run > mx.prev),
                                 '[]'::jsonb))
        into v_v;
    elsif v_k = 'maxpct' then
      -- a lift_gain keeps only its latest high, so earlier history is lost (accepted, spec §3.3)
      with x as (
        select f.day as d, f.ref, public.career_num(f.value -> 'pct') as pct from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = 'lift_gain' and f.void_at is null and public.career_num(f.value -> 'pct') is not null
      ),
      mx as (select x.*, max(x.pct) over (order by x.d, x.ref rows between unbounded preceding and 1 preceding) as prev from x)
      select jsonb_build_object('have', coalesce((select max(x.pct) from x), 0), 'now', null,
               'steps', coalesce((select jsonb_agg(jsonb_build_array(mx.d, mx.pct, 'lift_gain', mx.ref) order by mx.d, mx.ref)
                                    from mx where mx.prev is null or mx.pct > mx.prev), '[]'::jsonb))
        into v_v;
    elsif v_k like 'maxpct:%' or v_k like 'maxpct|%' then
      -- maxpct over the lifts the entry names (GAME-10; D18 as amended 2026-10-18; the key is career_maxpct_key()'s). A lift_gain counts when
      -- an approved Spine entry whose name or alias it is (compared as career_norm() compares lifts; the All-Court test's placing) is on one of
      -- the patterns (maxpct:<patterns>; a key without them takes any pattern), carries one of the qualities (|q:, when the key has it) and is
      -- not one of the ids left out (|x:, when the key has it). An empty list of patterns or qualities matches no lift. A lift the Spine cannot
      -- place counts for nothing. For The Upgrade and Double Up: the seven main patterns, the strength quality, and the four accessories Amir
      -- left out (45° Back Extension, Cable Face Pull, Machine Reverse Fly, Cable Straight-Arm Pulldown).
      -- A lift is placed by value.lift, the exercise name as logged. Under stage72 that name carries no measure (|lb or |plates is on the ref,
      -- the series key), so a main lift logged in pounds or plates is placed as one in kilograms is. Each measure is its own series with its
      -- own lift_gain; the best is the number. Nothing here calls a function the weight units add or change, so their ways back leave this
      -- working.
      -- Fail closed: while any |x: id names no row of public.exercises (a typo in the list, the entry given a new id, or deleted), the key
      -- counts no lift at all (ks is empty), and says so in the database log (the warning below), until the list or the Spine is put right.
      -- Otherwise the list would silently exclude nothing, the entry it names could count again under its new id, and a mint is never taken
      -- back (GAME-1); a crossing held back is minted, on its own day, at the first full evaluate after the fix. A draft is no reason to stop:
      -- a draft places no lift (sp reads approved entries only), and its id is still on the list when it is approved again.
      v_pats := case when v_k like 'maxpct:%' then string_to_array(substr(split_part(v_k, '|', 1), 8), ',') end;
      with kp as (select (select string_to_array(substr(p.x, 3), ',') from unnest((string_to_array(v_k, '|'))[2:]) p(x) where p.x like 'q:%' limit 1) as qs,
                         (select string_to_array(substr(p.x, 3), ',') from unnest((string_to_array(v_k, '|'))[2:]) p(x) where p.x like 'x:%' limit 1) as xs),
      ks as (select kp.qs, kp.xs from kp
              where kp.xs is null or not exists (select 1 from unnest(kp.xs) i(id)
                                                  where not exists (select 1 from public.exercises e where e.id = i.id))),
      sp as (select public.career_norm(n.x) as nm
               from public.exercises e cross join ks cross join unnest(array[e.name] || e.aliases) n(x)
              where e.status = 'approved' and (v_pats is null or e.pattern = any (v_pats))
                and (ks.qs is null or e.qualities && ks.qs) and (ks.xs is null or e.id <> all (ks.xs))),
      x as (
        select f.day as d, f.ref, public.career_num(f.value -> 'pct') as pct from public.career_facts f
         where f.athlete_id = p_athlete and f.kind = 'lift_gain' and f.void_at is null and public.career_num(f.value -> 'pct') is not null
           and public.career_norm(f.value ->> 'lift') in (select sp.nm from sp)
      ),
      mx as (select x.*, max(x.pct) over (order by x.d, x.ref rows between unbounded preceding and 1 preceding) as prev from x)
      select jsonb_build_object('have', coalesce((select max(x.pct) from x), 0), 'now', null,
               'steps', coalesce((select jsonb_agg(jsonb_build_array(mx.d, mx.pct, 'lift_gain', mx.ref) order by mx.d, mx.ref)
                                    from mx where mx.prev is null or mx.pct > mx.prev), '[]'::jsonb))
        into v_v;
      -- Failing closed is silent otherwise (the rewards just stop moving): a warning in the database log names the key and every |x: id that
      -- has no row in public.exercises. A warning never stops a save. Keys without |x: skip the look-up.
      if v_k like '%|x:%' then
        declare
          v_gone text;
        begin
          select string_agg(i.id, ', ' order by i.id) into v_gone
            from unnest((select string_to_array(substr(p.x, 3), ',') from unnest((string_to_array(v_k, '|'))[2:]) p(x) where p.x like 'x:%' limit 1)) i(id)
           where not exists (select 1 from public.exercises e where e.id = i.id);
          if v_gone is not null then
            raise warning 'Career Mode: % counts no lift while % in its exclude list is not in the Spine (no row in public.exercises; fail closed). Put the list (career/*.toml, then a re-seed) or the Spine right.', v_k, v_gone;
          end if;
        end;
      end if;
    end if;
    v_out := v_out || jsonb_build_object(v_k, coalesce(v_v, c_empty));
  end loop;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.career_mint(p_athlete text, p_kind text, p_item text, p_tier integer, p_subject text, p_day date, p_body jsonb, p_tier_body jsonb, p_evidence jsonb, p_how text, p_ctx jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_S date := (p_ctx ->> 'S')::date; v_hist boolean; v_pays boolean; v_xp integer; v_how text; v_size text; v_id text; v_n integer;
  v_earned date := p_day;
begin
  if p_athlete is null or p_day is null or v_S is null then return false; end if;
  if (select r.starts_on from public.career_rules r order by r.version desc limit 1) > p_day then p_day := (select r.starts_on from public.career_rules r order by r.version desc limit 1); end if;
  v_hist := p_day <= v_S;
  if coalesce(p_body, '{}'::jsonb) ? 'retire_at' and not v_hist then return false; end if;
  v_id := public.career_award_id(p_kind, p_item, p_tier, coalesce(p_subject, ''));
  v_pays := p_kind <> 'title' and public.career_award_pays(p_athlete, p_body, p_tier_body, p_day, p_ctx);
  v_xp := case when v_pays then greatest(coalesce(public.career_award_xp(p_kind, p_tier, coalesce(p_subject, ''), p_body, p_ctx -> 'hr'), 0), 0) else 0 end;
  if v_xp > 0 and coalesce(p_body, '{}'::jsonb) ? 'paid_from' and v_earned < public.career_day(p_body ->> 'paid_from') then v_xp := 0; end if;   /* stage99: D21 */
  v_how := case when v_hist then 'baseline' else p_how end;
  v_size := coalesce(p_tier_body ->> 'size', p_body ->> 'size', 'win');
  if v_size not in ('tick', 'win', 'highlight', 'milestone', 'legend') then v_size := 'win'; end if;
  insert into public.career_awards (athlete_id, award_id, kind, item, tier, subject, day, pays, xp, size, meaning, evidence, how, rules_version, earned_on)
  values (p_athlete, v_id, p_kind, p_item, p_tier, coalesce(p_subject, ''), p_day, v_pays, v_xp, v_size,
          coalesce(p_body ->> 'meaning', ''), coalesce(p_evidence, '{}'::jsonb), v_how, coalesce((p_ctx ->> 'version')::int, 0), least(v_earned, p_day))
  on conflict (athlete_id, award_id) do nothing;
  get diagnostics v_n = row_count;
  if v_n = 0 then return false; end if;
  if v_how = 'live' and v_size <> 'tick' and (p_kind <> 'title' or p_item = 'grand_slam') then
    insert into public.career_recognition (athlete_id, award_id, audience, size) values (p_athlete, v_id, 'athlete', v_size)
    on conflict (athlete_id, award_id, audience) do nothing;
  end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.career_norm(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select btrim(regexp_replace(lower(coalesce(p, '')), '\s+', ' ', 'g'))
$function$;

CREATE OR REPLACE FUNCTION public.career_num(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text;
begin
  if p is null then return null; end if;
  if jsonb_typeof(p) = 'number' then return (p #>> '{}')::numeric; end if;
  if jsonb_typeof(p) = 'string' then
    t := btrim(p #>> '{}');
    if t ~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' then return t::numeric; end if;
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_observe_library(p_athlete text, p_slug text DEFAULT NULL::text, p_on date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_want jsonb;
begin
  if public.career_rules_now() is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  select coalesce(jsonb_agg(jsonb_build_object('kind', 'library_session', 'ref', ls.slug || '|' || ls.completed_on::text,
                                               'day', ls.completed_on,
                                               'value', jsonb_strip_nulls(jsonb_build_object('slug', ls.slug, 'counts_as', ls.counts_as,
                                                                                             'minutes', ls.duration_min)))), '[]'::jsonb)
    into v_want
    from public.library_sessions ls
   where ls.athlete_id = p_athlete and (p_slug is null or (ls.slug = p_slug and ls.completed_on = p_on));
  perform public.career_sync(p_athlete, array['library_session'], v_want, 'training',
                             case when p_slug is null then null else array[p_slug || '|' || p_on::text] end);
end $function$;

CREATE OR REPLACE FUNCTION public.career_observe_proof(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now();
  v_data jsonb; v_log jsonb; v_cfg jsonb; v_want jsonb;
begin
  if v_rules is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  select a.data into v_data from public.athlete_progress a where a.athlete_id = p_athlete;
  v_log := public.hab_log_of(v_data, p_athlete);
  if jsonb_typeof(v_log) is distinct from 'object' then v_log := '{}'::jsonb; end if;
  v_cfg := public.hab_cfg_of(v_data, p_athlete);
  if jsonb_typeof(v_cfg) is distinct from 'object' then v_cfg := '{}'::jsonb; end if;

  with dl as (
    select public.career_day(e.key) as d, e.value as vals
      from jsonb_each(v_log) e
     where e.key ~ '^\d{4}-\d{2}-\d{2}$' and jsonb_typeof(e.value) = 'object' and public.career_day(e.key) is not null
  ),
  hv as (select dl.d, h.key as hid, h.value as v from dl, jsonb_each(dl.vals) h),
  weighted as (
    select t.key as hid from jsonb_each(coalesce(v_rules #> '{habits,targets}', '{}'::jsonb)) t
    union all
    select c.value ->> 'id'
      from jsonb_array_elements(case when jsonb_typeof(v_cfg -> 'custom') = 'array' then v_cfg -> 'custom' else '[]'::jsonb end) c
     where c.value ->> 'id' is not null
  ),
  roster as (
    select r.value
      from jsonb_array_elements(case when jsonb_typeof(v_cfg -> 'roster') = 'array' then v_cfg -> 'roster' else '[]'::jsonb end) r(value)
  ),
  dayroster as (
    select dl.d,
           (select r.value -> 'ids' from roster r
             where public.career_day(r.value ->> 'from') <= dl.d
             order by public.career_day(r.value ->> 'from') desc limit 1) as ids
      from dl
  ),
  custom as (
    select coalesce(jsonb_agg(c.value ->> 'id'), '[]'::jsonb) as ids
      from jsonb_array_elements(case when jsonb_typeof(v_cfg -> 'custom') = 'array' then v_cfg -> 'custom' else '[]'::jsonb end) c
     where c.value ->> 'id' is not null
  ),
  onlist as (
    select coalesce(jsonb_agg(w.hid), '[]'::jsonb) as ids from weighted w where coalesce(v_cfg -> 'on' ->> w.hid, 'true') <> 'false'
  )
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_want from (
    select jsonb_build_object('kind', 'habit_done', 'ref', hv.d::text || '|' || hv.hid, 'day', hv.d,
                              'value', jsonb_build_object('v', hv.v)) as x
      from hv
    union all
    select jsonb_build_object('kind', 'habit_day', 'ref', dr.d::text, 'day', dr.d,
                              'value', jsonb_build_object('live', case when dr.ids is not null then dr.ids else o.ids end,
                                                          'custom', c.ids))
      from dayroster dr, onlist o, custom c
    union all
    select jsonb_build_object('kind', 'workout_tick', 'ref', hv.d::text, 'day', hv.d, 'value', jsonb_build_object('habit', hv.hid))
      from hv
     where jsonb_typeof(hv.v) = 'number'
       and jsonb_exists(coalesce(v_rules #> '{habits,locked}', '[]'::jsonb), hv.hid)
       and (hv.v #>> '{}')::numeric >= coalesce(public.career_num(v_rules #> array['habits', 'targets', hv.hid]), 1)
  ) s;
  perform public.career_sync(p_athlete, array['habit_done', 'habit_day', 'workout_tick'], v_want, 'proof', null,
                             public.career_settled_before(v_rules));
  perform public.career_derive_days(p_athlete);
end $function$;

CREATE OR REPLACE FUNCTION public.career_observe_session(p_athlete text, p_day integer DEFAULT NULL::integer, p_on date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if public.career_rules_now() is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  perform public.career_sync(p_athlete, array['session_finished', 'session_finished_early', 'full_log', 'checkin_done'],
                             public.career_session_want(p_athlete, p_day, p_on), 'training',
                             case when p_day is null then null else array['d' || p_day || '|' || p_on::text] end);
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_library()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if tg_op in ('UPDATE', 'DELETE') then
      perform public.career_observe_library(old.athlete_id, old.slug, old.completed_on);
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      perform public.career_observe_library(new.athlete_id, new.slug, new.completed_on);
    end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not read a Library session of %: % (%). The save itself went through.',
                  coalesce(new.athlete_id, old.athlete_id), sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_programme()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_changed text[];
begin
  perform set_config('career.changed', '', true);
  begin
    perform public.career_derive(new.athlete_id);
  exception when others then
    raise warning 'Career Mode (shadow) could not read the programme of %: % (%). The save itself went through.',
                  new.athlete_id, sqlerrm, sqlstate;
  end;
  begin
    if public.career_catalogue_on() then
      v_changed := public.career_changed_kinds();
      if v_changed is not null then perform public.career_evaluate(new.athlete_id, v_changed, 'live'); end if;
    end if;
  exception when others then
    raise warning 'Career Mode could not work out the awards of %: % (%). The save itself went through.', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text := coalesce(new.athlete_id, old.athlete_id); v_habits boolean := true; v_records boolean := true; v_changed text[];
begin
  if tg_op = 'UPDATE' and new.athlete_id = old.athlete_id then
    v_habits := (new.data -> (v_id || '_hab_log')) is distinct from (old.data -> (v_id || '_hab_log'))
             or (new.data -> (v_id || '_hab_cfg')) is distinct from (old.data -> (v_id || '_hab_cfg'));
    v_records := (new.data -> (v_id || '_1rm')) is distinct from (old.data -> (v_id || '_1rm'));
    if not v_habits and not v_records then return null; end if;
  end if;
  perform set_config('career.changed', '', true);
  begin
    if tg_op = 'UPDATE' and new.athlete_id is distinct from old.athlete_id then
      perform public.career_observe_proof(old.athlete_id);
    end if;
    if v_habits then perform public.career_observe_proof(v_id); end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not read the Proof log of %: % (%). The save itself went through.', v_id, sqlerrm, sqlstate;
  end;
  begin
    if tg_op = 'UPDATE' and new.athlete_id is distinct from old.athlete_id then
      perform public.career_derive(old.athlete_id);
    end if;
    if v_records then perform public.career_derive(v_id); end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not work out the training facts of %: % (%). The save itself went through.', v_id, sqlerrm, sqlstate;
  end;
  begin
    if tg_op <> 'DELETE' and public.career_catalogue_on() then
      v_changed := public.career_changed_kinds();
      if v_changed is not null then perform public.career_evaluate(new.athlete_id, v_changed, 'live'); end if;
    end if;
  exception when others then
    raise warning 'Career Mode could not work out the awards of %: % (%). The save itself went through.', v_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_changed text[];
begin
  perform set_config('career.changed', '', true);
  begin
    if tg_op in ('UPDATE', 'DELETE') then
      perform public.career_observe_session(old.athlete_id, old.day, old.completed_on);
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      perform public.career_observe_session(new.athlete_id, new.day, new.completed_on);
    end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not read a session of %: % (%). The save itself went through.',
                  coalesce(new.athlete_id, old.athlete_id), sqlerrm, sqlstate;
  end;
  begin
    if tg_op in ('INSERT', 'UPDATE') then
      perform public.career_derive(new.athlete_id);
    end if;
    if tg_op = 'DELETE' or (tg_op = 'UPDATE' and new.athlete_id is distinct from old.athlete_id) then
      perform public.career_derive(old.athlete_id);
    end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not work out the training facts of %: % (%). The save itself went through.',
                  coalesce(new.athlete_id, old.athlete_id), sqlerrm, sqlstate;
  end;
  begin
    if tg_op <> 'DELETE' and public.career_catalogue_on() then     -- a hidden session is an update: still evaluated (nothing is taken back)
      v_changed := public.career_changed_kinds();
      if v_changed is not null then perform public.career_evaluate(new.athlete_id, v_changed, 'live'); end if;
    end if;
  exception when others then
    raise warning 'Career Mode could not work out the awards of %: % (%). The save itself went through.', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_paid_rules(p_habit_rules jsonb, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when p_habit_rules is null or public.career_switch_day(p_rules, 'xp') is null then p_habit_rules
              else jsonb_set(p_habit_rules, '{weights}',
                             coalesce(p_habit_rules -> 'weights', '{}'::jsonb)
                             || coalesce((select jsonb_object_agg(l.value, 0)
                                            from jsonb_array_elements_text(case when jsonb_typeof(p_habit_rules -> 'unearnable') = 'array'
                                                                                then p_habit_rules -> 'unearnable' else '[]'::jsonb end) l),
                                         '{}'::jsonb)) end
$function$;

CREATE OR REPLACE FUNCTION public.career_probe(p_log jsonb, p_cfg jsonb, p_season date, p_to date, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_base jsonb; v_days integer := greatest(p_to - p_season + 1, 0); v_perfect bigint; v_on bigint; v_back bigint;
begin
  v_base := p_rules || jsonb_build_object('tiers', '[]'::jsonb, 'milestones', '[]'::jsonb, 'quests', '[]'::jsonb,
                                          'questRuns', '[]'::jsonb, 'comebackXp', 0);
  v_perfect := public.hab_bonus_xp(p_log, p_cfg, p_season, p_season, p_to,
                 v_base || jsonb_build_object('milestones', (select coalesce(jsonb_agg(jsonb_build_object('code', 'zzp' || g, 'need', g,
                                                             'xp', 1, 'measure', 'perfectDays')), '[]'::jsonb)
                                                               from generate_series(1, v_days) g)));
  v_on := public.hab_bonus_xp(p_log, p_cfg, p_season, p_season, p_to,
            v_base || jsonb_build_object(
              'quests', (select jsonb_agg(jsonb_build_object('id', 'zzq' || g, 'kind', 'qualify', 'need', g, 'xp', 1)) from generate_series(1, 7) g),
              'questRuns', (select coalesce(jsonb_agg(jsonb_build_object('start', (p_season + 7 * k)::text,
                                                                         'ids', (select jsonb_agg('zzq' || g) from generate_series(1, 7) g))), '[]'::jsonb)
                              from generate_series(0, v_days / 7) k)));
  v_back := public.hab_bonus_xp(p_log, p_cfg, p_season, p_season, p_to, v_base || jsonb_build_object('comebackXp', 1));
  return jsonb_build_object('perfect', v_perfect, 'on_target', v_on, 'comebacks', v_back);
end $function$;

CREATE OR REPLACE FUNCTION public.career_proof_key(p_measure text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when p_measure is null then 'daystreak'
              when p_measure = 'dayStreak' then 'daystreak'   -- stage93: days in a row that counted, by name
              when p_measure like 'streak:%' then 'run:' || substr(p_measure, 8)
              when p_measure like 'daysHit:%' then 'hits:' || substr(p_measure, 9)
              when p_measure like 'total:%' then 'sum:' || substr(p_measure, 7)
              when p_measure = 'daysWith3' then 'with3'
              when p_measure in ('perfectDays', 'perfect') then 'perfect'
              when p_measure = 'qualify' then 'qualify'
              when p_measure = 'comebackRun' then 'cbrun'
              when p_measure = 'comebacksStuck' then 'stuck'
         end
$function$;

CREATE OR REPLACE FUNCTION public.career_proof_sum(p_athlete text, p_to date)
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select public.hab_bonus_xp(public.hab_log_of(ap.data, p_athlete), public.hab_cfg_of(ap.data, p_athlete), null, null, p_to,
                             x.rules || '{"quests": [], "questRuns": [], "comebackXp": 0}'::jsonb)
    from public.athlete_progress ap, public.xp_rules x
   where ap.athlete_id = p_athlete and x.id = 1 and ap.data ? (p_athlete || '_hab_log')
$function$;

CREATE OR REPLACE FUNCTION public.career_reads_kinds(p_body jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case jsonb_typeof(p_body -> 'reads')
           when 'array' then array(select x from jsonb_array_elements_text(p_body -> 'reads') x order by x)
           when 'string' then array[p_body ->> 'reads']
           else '{}'::text[] end
$function$;

CREATE OR REPLACE FUNCTION public.career_rec_unit(p jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when jsonb_typeof(p -> 'u') = 'string' and (p ->> 'u') in ('lb', 'plates') then p ->> 'u' else 'kg' end
$function$;

CREATE OR REPLACE FUNCTION public.career_rewards_athletes(p_offset integer, p_limit integer)
 RETURNS SETOF text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select z.id from (select ap.athlete_id as id from public.athlete_progress ap where ap.data ? (ap.athlete_id || '_hab_log')
                    union select r.athlete_id from public.hab_season_results r
                    union select f.athlete_id from public.career_facts f where f.void_at is null) z
   order by z.id
  offset greatest(coalesce(p_offset, 0), 0) limit greatest(coalesce(p_limit, 5), 0)
$function$;

CREATE OR REPLACE FUNCTION public.career_rewards_batch(p_offset integer, p_limit integer, p_how text DEFAULT 'baseline'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id text; v_lines jsonb := '[]'::jsonb; v_before jsonb; v_after jsonb; v_line jsonb; v_ok boolean := true;
begin
  if not public.career_catalogue_on() then
    raise exception 'career_rewards_batch: the catalogue switch is off (rulebook.toml → [switch] catalogue)';
  end if;
  if p_how is null or p_how not in ('baseline', 'silent') then
    raise exception 'career_rewards_batch: p_how is baseline or silent, not %', p_how;
  end if;
  for v_id in select x from public.career_rewards_athletes(p_offset, p_limit) x loop
    begin
      perform public.career_evaluate(v_id, null, p_how);
      v_after := public.career_scored(v_id);
      v_before := null;      -- stage79: the go-day's copy only while it exists (it is dropped on 2026-11-01)
      if to_regclass('backup.career_catalogue_before') is not null then
        execute 'select b.score from backup.career_catalogue_before b where b.athlete_id = $1' into v_before using v_id;
      end if;
      v_line := public.career_rewards_line(v_id, coalesce(v_before, v_after), v_after);
    exception when others then
      v_line := jsonb_build_object('athlete_id', v_id, 'ok', false, 'error', sqlerrm);
    end;
    v_ok := v_ok and coalesce((v_line ->> 'ok')::boolean, false);
    v_lines := v_lines || jsonb_build_array(v_line);
  end loop;
  return jsonb_build_object('n', jsonb_array_length(v_lines), 'ok', v_ok, 'lines', v_lines);
end $function$;

CREATE OR REPLACE FUNCTION public.career_rewards_line(p_athlete text, p_before jsonb, p_after jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with s as (select public.career_switch_day(public.career_rules_now(), 'catalogue') as d, public.career_habit_rules() as hr),
  aw as (
    select a.*, c.body,
           case when not a.pays then 0 else a.xp /* stage76: minted XP */ end as px
      from public.career_awards a left join public.career_catalogue c on c.kind = a.kind and c.id = a.item cross join s
     where a.athlete_id = p_athlete
  )
  select jsonb_build_object(
    'athlete_id', p_athlete,
    'name', (select coalesce(nullif(btrim(concat_ws(' ', p.data #>> '{athlete,firstName}', p.data #>> '{athlete,lastName}')), ''),
                             (select o.display_name from public.leaderboard_optin o where o.athlete_id = p_athlete))
               from (select 1) one left join public.programs p on p.athlete_id = p_athlete),
    'awards', (select count(*) from aw where aw.kind <> 'title'),
    'by_meaning', coalesce((select jsonb_object_agg(z.meaning, z.n) from (select aw.meaning, count(*) as n from aw where aw.kind <> 'title'
                                                                           group by aw.meaning) z), '{}'::jsonb),
    'titles', coalesce((select jsonb_agg(aw.item order by aw.day, aw.item) from aw where aw.kind = 'title'), '[]'::jsonb),
    'grand_slam', exists (select 1 from aw where aw.award_id = 'title:grand_slam'),
    'xp_before', p_before #> '{career,xp}', 'xp_after', p_after #> '{career,xp}',
    'level_before', p_before #> '{career,level}', 'level_after', p_after #> '{career,level}',
    'season_before', p_before #> '{season,points}', 'season_after', p_after #> '{season,points}',
    'proof_carried', (select coalesce(sum(aw.px), 0) from aw, s where aw.body ->> 'origin' = 'proof' and aw.day <= s.d),
    'proof_sum', (select public.career_proof_sum(p_athlete, s.d) from s),
    'back_pay', (select coalesce(sum(aw.px), 0) from aw, s where coalesce(aw.body ->> 'origin', 'new') <> 'proof' and aw.day <= s.d),
    'ok', coalesce((p_after #>> '{career,level}')::int >= (p_before #>> '{career,level}')::int, true))
$function$;

CREATE OR REPLACE FUNCTION public.career_rewards_profile(p_athlete text, p_rw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now(); v_S date; v_rw jsonb := p_rw; v_stale boolean := false; v_hr jsonb;
  v_ms jsonb; v_keep integer; v_max integer; v_full jsonb; v_free boolean; f record; v_now integer := 0; v_best integer := 0;
  v_dnow integer; v_dbest integer; v_four jsonb; v_ladder jsonb; v_near jsonb; v_out jsonb; v_moments jsonb; v_sess integer;
  c_rank constant jsonb := '{"tick": 0, "win": 1, "highlight": 2, "milestone": 3, "legend": 4}'::jsonb;
  c_session constant jsonb := '["session_finished", "session_finished_early", "full_log", "checkin_done"]'::jsonb;
  c_week constant jsonb := '["week_held", "week_by_the_book", "bounce_back", "training_return", "cycle_finished", "roadmap_finished", "effort_win"]'::jsonb;
begin
  v_S := public.career_switch_day(v_rules, 'catalogue');
  if v_S is null then
    return '{"badges": [], "achievements": [], "moments": []}'::jsonb;
  end if;
  if v_rw is null then
    select s.rewards into v_rw from public.career_scores s where s.athlete_id = p_athlete;
    v_rw := coalesce(v_rw, '{}'::jsonb);
    v_stale := true;
  end if;
  v_hr := public.career_habit_rules();
  select c.body into v_ms from public.career_catalogue c where c.kind = 'setting' and c.id = 'moments';
  v_keep := coalesce(public.career_num(v_ms -> 'keep_days'), 14)::int;
  v_max := coalesce(public.career_num(v_ms -> 'max'), 8)::int;
  v_full := coalesce(case when jsonb_typeof(v_ms -> 'full_screen') = 'array' then v_ms -> 'full_screen' end, '["milestone", "legend"]'::jsonb);
  v_free := coalesce((select p.data #>> '{athlete,tier}' = 'free' from public.programs p where p.athlete_id = p_athlete), false);

  -- the four numbers (D3, D4)
  for f in select cf.kind from public.career_facts cf
            where cf.athlete_id = p_athlete and cf.void_at is null and cf.kind in ('week_held', 'week_broken')
            order by cf.day, cf.ref loop
    if f.kind = 'week_held' then v_now := v_now + 1; v_best := greatest(v_best, v_now); else v_now := 0; end if;
  end loop;
  with q as (select cf.day as d from public.career_facts cf where cf.athlete_id = p_athlete and cf.kind = 'day_on_target' and cf.void_at is null),
  isl as (select q.d, q.d - (row_number() over (order by q.d))::int as grp from q),
  rl as (select isl.d, (row_number() over (partition by isl.grp order by isl.d))::int as run from isl)
  select coalesce((select rl.run from rl where rl.d >= current_date - 1 order by rl.d desc limit 1), 0), coalesce((select max(rl.run) from rl), 0)
    into v_dnow, v_dbest;
  -- commitment, coached (D19, CAREER_MODE.md): the sessions Century counts, the ones career_facts_paid() pays (a plan day done again in
  -- its training week counts once), so the Home row's "N sessions" and Century's ladder never disagree. Read from evaluate's cache, the
  -- `have` of a live badge whose one measure is that count: no second pass over the paid facts. Worked out here only when no such badge
  -- holds one; when that fails as well, every session fact is counted (the number before stage73). A stale cache gives the ladder's own
  -- number. get_profile()'s older numbers.sessions_with_amir stays every session fact.
  if not v_free then
    select public.career_num(v_rw -> 'have' -> c.id)::int into v_sess
      from public.career_catalogue c
     where c.kind = 'badge' and c.body ->> 'kind' = 'total' and not (c.body ? 'retire_at') and coalesce(c.body ->> 'meaning', '') <> 'chosen'
       and jsonb_typeof(v_rw -> 'have' -> c.id) = 'number'
       and public.career_entry_keys('badge', c.body, '{}'::jsonb) = array['count:session_finished,session_finished_early']
     order by c.id limit 1;
    if v_sess is null then
      begin
        v_sess := public.career_num(public.career_measures(p_athlete, '{}'::jsonb, array['count:session_finished,session_finished_early'])
                                      -> 'count:session_finished,session_finished_early' -> 'have')::int;
      exception when others then
        raise warning 'Career Mode could not count the paid sessions of %: % (%). Every session fact is counted.', p_athlete, sqlerrm, sqlstate;
        v_sess := null;
      end;
    end if;
  end if;
  select jsonb_build_object(
           'consistency', case when v_free then jsonb_build_object('key', 'day_streak', 'value', v_dnow, 'best', v_dbest)
                               else jsonb_build_object('key', 'weeks_held', 'value', v_now, 'best', v_best) end,
           'commitment', case when v_free then jsonb_build_object('key', 'perfect_days', 'value', count(*) filter (where cf.kind = 'perfect_day'))
                              else jsonb_build_object('key', 'sessions_with_amir',
                                                      'value', coalesce(v_sess, count(*) filter (where cf.kind in ('session_finished', 'session_finished_early')))) end,
           'progress', case when v_free then jsonb_build_object('key', 'habit_steps', 'locked', true,
                              'value', coalesce((select sum(z.t) from (select max(a.tier) as t from public.career_awards a
                                                                         join public.career_catalogue c on c.kind = 'badge' and c.id = a.item
                                                                        where a.athlete_id = p_athlete and a.kind = 'badge'
                                                                          and c.body ->> 'kind' = 'best_run' and c.body ? 'habit'
                                                                        group by a.item) z), 0))
                            else jsonb_build_object('key', 'personal_bests', 'value', count(*) filter (where cf.kind = 'personal_best')) end,
           'resilience', jsonb_build_object('key', 'comebacks', 'value', count(*) filter (where cf.kind in ('comeback', 'training_return'))))
    into v_four
    from public.career_facts cf where cf.athlete_id = p_athlete and cf.void_at is null;

  -- the ladder: every live badge (not retired, not chosen), where it stands and its next tier. The size budget (spec §6): a key whose
  -- value is null is left out (phone on a server-only badge, the next-tier keys on a top tier: both apps read absent as null), a `have`
  -- or `tier` of 0 is left out (both apps and the rehearsal read Number(x) || 0), and `counts` and `now` go only with a `phone` (the
  -- finish card, careerMoves(), reads them for those alone); so does `size_next`, once the near list below has been ordered by it.
  -- `next_tier` is always tier + 1 beside a `next`: it goes with a `phone` (the training app's award id for a tier its finish card
  -- crossed, rwCountingBands()) and past tier 5 only, because AA Proof's one other read of it, catalogueTotal() without its catalogue
  -- copy, counts max(5, next_tier) steps for a ladder not yet at its top: absent and 1 to 5 are the same 5 there.
  select coalesce(jsonb_object_agg(c.id, jsonb_strip_nulls(jsonb_build_object(
           'name', c.body ->> 'name', 'meaning', c.body ->> 'meaning', 'counts', case when z.phone is not null then z.counts end,
           'have', nullif(coalesce(public.career_num(v_rw -> 'have' -> c.id), 0), 0),
           'now', case when z.phone is not null then v_rw -> 'now' -> c.id end,
           'tier', nullif(t.tier, 0), 'next', public.career_num(t.nt -> 'at'),
           'next_tier', case when t.nt is not null and (z.phone is not null or t.tier + 1 > 5) then t.tier + 1 end,
           'metal_next', t.nt ->> 'metal', 'size_next', t.nt ->> 'size',
           'phone', z.phone))), '{}'::jsonb)
    into v_ladder
    from public.career_catalogue c
    cross join lateral (select y.counts, case when jsonb_array_length(y.counts) = 0 then null
                                              when y.counts <@ c_session then 'session' when y.counts <@ c_week then 'week' end as phone
                          from (select case jsonb_typeof(c.body -> 'counts') when 'array' then c.body -> 'counts'
                                            when 'string' then jsonb_build_array(c.body -> 'counts') else '[]'::jsonb end as counts) y) z
    cross join lateral (select y.tier, c.body -> 'tiers' -> y.tier as nt
                          from (select coalesce(max(a.tier), 0) as tier from public.career_awards a
                                 where a.athlete_id = p_athlete and a.kind = 'badge' and a.item = c.id and a.subject = '') y) t
   where c.kind = 'badge' and not (c.body ? 'retire_at') and coalesce(c.body ->> 'meaning', '') <> 'chosen'
     and coalesce(c.body ->> 'kind', '') <> 'per_habit_best_run';

  -- near: the nearest goals, an index into the ladder (its name, have, next, meaning, next_tier and metal_next are the ladder entry's,
  -- under the same id). The size budget: the first row carries id, name, have, next and pct (the training app's Home row prints near[0]
  -- alone, careerNearText()); every other row is its id only (AA Proof reads the ids and draws the rest from the ladder, catalogueShelf()).
  select coalesce(jsonb_agg(case when n.rn = 1 then n.j else jsonb_build_object('id', n.id) end order by n.rn), '[]'::jsonb) into v_near
    from (select e.key as id,
                 jsonb_build_object('id', e.key, 'name', e.value ->> 'name', 'have', e.value -> 'have', 'next', e.value -> 'next',
                                    'pct', floor(public.career_num(e.value -> 'have') * 100 / public.career_num(e.value -> 'next'))::int) as j,
                 row_number() over (order by (public.career_num(e.value -> 'next') - public.career_num(e.value -> 'have'))
                                               / public.career_num(e.value -> 'next'),
                                             coalesce(public.career_num(c_rank -> (e.value ->> 'size_next')), 0) desc, e.key) as rn
            from jsonb_each(v_ladder) e
           where public.career_num(e.value -> 'have') > 0 and public.career_num(e.value -> 'next') > 0) n
   where n.rn <= 6;

  -- size_next stays only beside a `phone`: the training app reads it for a ladder its finish card moved (rwCountingBands()), AA Proof
  -- never (the near order above has used it already). The size budget.
  select coalesce(jsonb_object_agg(e.key, case when e.value ? 'phone' then e.value else e.value - 'size_next' end), '{}'::jsonb)
    into v_ladder from jsonb_each(v_ladder) e;

  -- the moments waiting to be told: `also` (the title the award minted) only when there is one (the size budget)
  select coalesce(jsonb_agg(m.j order by m.rk desc, m.day desc, m.award_id), '[]'::jsonb) into v_moments
    from (select r.award_id, a.day, coalesce(public.career_num(c_rank -> r.size), 0) as rk,
                 jsonb_build_object(
                   'award_id', r.award_id, 'kind', a.kind, 'item', a.item, 'tier', a.tier, 'size', r.size, 'day', a.day,
                   'full', (v_full ? r.size) and r.due_at >= now() - make_interval(days => v_keep),
                   'xp', case when not a.pays then 0 else a.xp /* stage76: minted XP */ end,
                   'spec', public.career_award_spec(a.kind, a.item, a.tier, a.day, a.evidence, c.body))
                 || coalesce((select jsonb_build_object('also', jsonb_agg(public.career_award_spec('title', ta.item, null, ta.day, ta.evidence, tc.body)
                                                                          order by ta.item))
                                from public.career_awards ta left join public.career_catalogue tc on tc.kind = 'title' and tc.id = ta.item
                               where ta.athlete_id = p_athlete and ta.kind = 'title' and ta.evidence ->> 'from' = r.award_id
                              having count(*) > 0), '{}'::jsonb) as j
            from public.career_recognition r
            join public.career_awards a on a.athlete_id = r.athlete_id and a.award_id = r.award_id
            left join public.career_catalogue c on c.kind = a.kind and c.id = a.item
           where r.athlete_id = p_athlete and r.audience = 'athlete' and r.told_at is null
           order by 3 desc, a.day desc, r.award_id limit greatest(v_max, 0)) m;

  v_out := jsonb_build_object(
    'catalogue_version', (select r.version::text || '@' || extract(epoch from r.loaded_at)::bigint::text
                            from public.career_rules r order by r.version desc limit 1),
    'numbers', jsonb_build_object('free', v_free, 'four', v_four),
    -- owned: every award id the athlete holds, sorted byte by byte (the phones' dedupe and the shelf's held mark; a set: no day here,
    -- get_awards() has each day). About 25 bytes an award: the one part of the core that grows with a career.
    'owned', coalesce((select jsonb_agg(a.award_id order by a.award_id collate "C") from public.career_awards a where a.athlete_id = p_athlete),
                      '[]'::jsonb),
    'title_worn', (select o.title from public.leaderboard_optin o where o.athlete_id = p_athlete),
    'slam', public.career_slam(p_athlete),
    'ladder', v_ladder,
    'near', v_near,
    'moments', v_moments);
  if v_stale then v_out := v_out || '{"rewards_stale": true}'::jsonb; end if;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.career_rewards_stamp(p_athlete text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select md5(concat_ws('|',
    public.career_stamp(p_athlete),
    (select count(*)::text || '@' || coalesce(max(a.created_at)::text, '-') from public.career_awards a where a.athlete_id = p_athlete),
    (select count(*)::text || '@' || coalesce(max(t.created_at)::text, '-') from public.hab_titles t where t.athlete_id = p_athlete),
    (select max(e.updated_at)::text from public.exercises e where e.status = 'approved')))
$function$;

CREATE OR REPLACE FUNCTION public.career_rules_now()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select r.rules from public.career_rules r order by r.version desc limit 1
$function$;

CREATE OR REPLACE FUNCTION public.career_rules_on(p_day date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select r.rules from public.career_rules r where r.starts_on is null or r.starts_on <= p_day order by r.version desc limit 1
$function$;

CREATE OR REPLACE FUNCTION public.career_score(p_athlete text, p_season date, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb := public.career_habit_rules(); v_paid jsonb; v_log jsonb; v_cfg jsonb; v_daily bigint := 0; v_bonus bigint := 0;
        v_facts jsonb; v_rest numeric;
begin
  if v_rules is null then return null; end if;
  v_paid := public.career_paid_rules(v_rules, public.career_rules_now());
  v_log := public.career_log(p_athlete);
  v_cfg := public.career_cfg(p_athlete);
  v_daily := public.hab_xp(v_log, p_from, p_to, v_paid);
  v_bonus := public.hab_bonus_xp(v_log, v_cfg, p_season, p_from, p_to, public.career_bonus_rules(v_rules, public.career_rules_now()));
  select coalesce(jsonb_object_agg(x.kind, jsonb_build_object('n', x.n, 'xp', x.xp)), '{}'::jsonb), coalesce(sum(x.xp), 0)
    into v_facts, v_rest
    from public.career_facts_xp(p_athlete, p_from, p_to) x;
  return jsonb_build_object('habits', jsonb_build_object('daily', v_daily, 'bonus', v_bonus, 'xp', v_daily + v_bonus),
                            'facts', v_facts, 'facts_xp', round(v_rest)::bigint,
                            'xp', (v_daily + v_bonus + round(v_rest))::bigint);
end $function$;

CREATE OR REPLACE FUNCTION public.career_scored(p_athlete text, p_recompute boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare v_stamp text; v_old text; v_score jsonb; v_rw jsonb; v_S date;
begin
  if p_athlete is null or public.career_rules_now() is null then return null; end if;
  v_S := public.career_switch_day(public.career_rules_now(), 'catalogue');
  if v_S is not null and (select c.rewards ->> 'base' from public.career_scores c where c.athlete_id = p_athlete) is distinct from v_S::text then
    begin
      perform public.career_evaluate(p_athlete, null, 'silent');
    exception when others then
      raise warning 'Career Mode could not work out the awards of %: % (%). The stored score is served.', p_athlete, sqlerrm, sqlstate;
      select c.score into v_score from public.career_scores c where c.athlete_id = p_athlete;
      if v_score is not null then return v_score || '{"stale": true}'::jsonb; end if;
    end;
  end if;
  v_stamp := public.career_stamp(p_athlete);
  select c.stamp, c.score into v_old, v_score from public.career_scores c where c.athlete_id = p_athlete;
  if v_old = v_stamp then return v_score; end if;
  if v_old is not null and not p_recompute then return v_score || '{"stale": true}'::jsonb; end if;
  v_score := public.career_compute(p_athlete);
  if v_score is null then return null; end if;
  v_rw := nullif(current_setting('career.rw_' || md5(p_athlete), true), '')::jsonb;
  insert into public.career_scores as c (athlete_id, stamp, score, updated_at, rewards) values (p_athlete, v_stamp, v_score, now(), v_rw)
  on conflict on constraint career_scores_pkey do update
     set stamp = excluded.stamp, score = excluded.score, updated_at = now(), rewards = coalesce(c.rewards, excluded.rewards);
  return v_score;
end $function$;

CREATE OR REPLACE FUNCTION public.career_scores_for(p_ids text[], p_budget interval DEFAULT '00:00:02.5'::interval)
 RETURNS TABLE(athlete_id text, score jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare v_t0 timestamptz := clock_timestamp(); v_id text; v_stamp text; v_old text; v_cached jsonb; v_score jsonb; v_S date; v_base text;
        v_failed boolean;
begin
  if public.career_rules_now() is null then return; end if;
  v_S := public.career_switch_day(public.career_rules_now(), 'catalogue');
  for v_id in select distinct x.id from unnest(coalesce(p_ids, '{}'::text[])) as x(id) where x.id is not null order by 1 loop
    v_old := null; v_cached := null; v_base := null; v_failed := false;
    select c.stamp, c.score, c.rewards ->> 'base' into v_old, v_cached, v_base from public.career_scores c where c.athlete_id = v_id;
    if v_S is not null and v_base is distinct from v_S::text and not (v_old is not null and clock_timestamp() - v_t0 > p_budget) then
      begin
        perform public.career_evaluate(v_id, null, 'silent');
      exception when others then
        raise warning 'Career Mode could not work out the awards of %: % (%). The stored score is served.', v_id, sqlerrm, sqlstate;
        v_failed := true;
      end;
    end if;
    v_stamp := public.career_stamp(v_id);
    if v_old is not null and (v_old = v_stamp or v_failed or clock_timestamp() - v_t0 > p_budget) then
      athlete_id := v_id; score := v_cached; return next;
      continue;
    end if;
    v_score := public.career_compute(v_id);
    if v_score is null then continue; end if;
    insert into public.career_scores as c (athlete_id, stamp, score, updated_at, rewards)
    values (v_id, v_stamp, v_score, now(), nullif(current_setting('career.rw_' || md5(v_id), true), '')::jsonb)
    on conflict on constraint career_scores_pkey do update
       set stamp = excluded.stamp, score = excluded.score, updated_at = now(), rewards = coalesce(c.rewards, excluded.rewards);
    athlete_id := v_id; score := v_score; return next;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.career_scoring(p_key text, p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when jsonb_typeof(p) = 'array' and p_key = 'milestones' then
      (select coalesce(jsonb_agg(jsonb_build_object('code', e.v -> 'code', 'need', e.v -> 'need', 'xp', e.v -> 'xp', 'measure', e.v -> 'measure')), '[]'::jsonb)
         from jsonb_array_elements(p) as e(v))
    when jsonb_typeof(p) = 'array' and p_key = 'quests' then
      (select coalesce(jsonb_agg(jsonb_build_object('id', e.v -> 'id', 'kind', e.v -> 'kind', 'need', e.v -> 'need', 'xp', e.v -> 'xp')), '[]'::jsonb)
         from jsonb_array_elements(p) as e(v))
    when jsonb_typeof(p) = 'array' and p_key = 'tiers' then
      (select coalesce(jsonb_agg(jsonb_build_object('days', e.v -> 'days', 'mult', e.v -> 'mult')), '[]'::jsonb)
         from jsonb_array_elements(p) as e(v))
    else p end
$function$;

CREATE OR REPLACE FUNCTION public.career_seed(p_version integer, p_rules jsonb, p_catalogue jsonb, p_source text, p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_newest integer; v_n integer; v_old jsonb := public.career_rules_now(); v_which text; v_was date; v_will text;
  v_xp_on date; v_turn_on boolean; v_same boolean; v_backfill jsonb; v_levels jsonb; v_out jsonb; v_cat date; v_turn_cat boolean;
begin
  if p_version is null or p_version < 1 then
    raise exception 'the rulebook version must be a whole number from 1';
  end if;
  if jsonb_typeof(p_rules) is distinct from 'object' or public.career_num(p_rules -> 'version') is distinct from p_version then
    raise exception 'the rulebook must be an object whose version is %', p_version;
  end if;
  if jsonb_typeof(p_catalogue) is distinct from 'array' then
    raise exception 'the catalogue must be a JSON array of {kind, id, body}';
  end if;
  select max(r.version) into v_newest from public.career_rules r;
  if v_newest is not null and p_version < v_newest then
    raise exception 'rulebook version % is older than the one loaded (%): nothing was changed', p_version, v_newest;
  end if;
  perform public.career_d20_check(p_version, p_rules, p_catalogue);   -- stage76 (D20): forward only
  foreach v_which in array array['xp', 'catalogue'] loop
    v_will := p_rules #>> array['switch', v_which];
    v_was := public.career_switch_day(v_old, v_which);
    if v_will is not null and v_will <> 'off' and v_will !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'rulebook.toml → [switch] % must be "off" or a day (YYYY-MM-DD), found %: nothing was changed', v_which, v_will;
    end if;
    if v_will ~ '^\d{4}-\d{2}-\d{2}$' and v_will::date > current_date then
      raise exception 'rulebook.toml → [switch] % is %, a day still to come: turn a switch on on the day it happens. Nothing was changed', v_which, v_will;
    end if;
    if v_was is not null and coalesce(v_will, 'off') = 'off' then
      raise exception 'the % switch is on (since %) and is never turned back off: it would take every athlete''s level back. Nothing was changed (the way back is scripts/career/rollback_stage69.sql for xp, rollback_stage70.sql for the catalogue, on Amir''s word)', v_which, v_was;
    end if;
  end loop;
  if public.career_switch_day(p_rules, 'catalogue') is not null and public.career_switch_day(p_rules, 'xp') is null then
    raise exception 'the catalogue switch (phase 3) needs the XP switch (phase 2) on first: nothing was changed';
  end if;
  v_xp_on := public.career_switch_day(p_rules, 'xp');
  v_turn_on := v_xp_on is not null and public.career_switch_day(v_old, 'xp') is null;
  v_same := v_old is not null
        and (v_old - 'version' - 'switch' - 'shadow') = (p_rules - 'version' - 'switch' - 'shadow')
        and (select md5(coalesce(string_agg(c.kind || '|' || c.id || '|' || c.body::text, ',' order by c.kind, c.id), ''))
               from public.career_catalogue c)
          = (select md5(coalesce(string_agg(x.kind || '|' || x.id || '|' || x.body::text, ',' order by x.kind, x.id), ''))
               from jsonb_to_recordset(p_catalogue) as x(kind text, id text, body jsonb));
  v_cat := public.career_switch_day(p_rules, 'catalogue');
  v_turn_cat := v_cat is not null and public.career_switch_day(v_old, 'catalogue') is null;
  if v_turn_cat and v_turn_on then
    raise exception 'turn the XP switch and the catalogue switch on in two seeds, days apart: nothing was changed';
  end if;
  if v_turn_cat and not v_same then
    raise exception 'turn the catalogue switch on with no other change (seed the catalogue first, then the switch alone): nothing was changed';
  end if;
  if v_turn_cat and v_cat < current_date - 1 then
    raise exception 'the catalogue switch day must be today (or yesterday, for a time zone), not %: nothing was changed', v_cat;
  end if;

  begin
    insert into public.career_rules (version, rules, source, loaded_at, starts_on) values (p_version, p_rules, p_source, now(), case when v_newest is not null and p_version > v_newest then (p_rules ->> 'starts_on')::date end)   /* stage76 */
    on conflict (version) do update set rules = excluded.rules, source = excluded.source, loaded_at = now();
    delete from public.career_catalogue;
    insert into public.career_catalogue (kind, id, body, version, loaded_at)
    select x.kind, x.id, x.body, p_version, now()
      from jsonb_to_recordset(p_catalogue) as x(kind text, id text, body jsonb);
    get diagnostics v_n = row_count;
    v_backfill := case when v_same then jsonb_build_object('skipped', 'only a switch changed: no fact depends on it')
                       else public.career_backfill(null) end;
    if v_turn_on then
      v_levels := public.career_keep_levels(v_xp_on);
    end if;
    v_out := jsonb_strip_nulls(jsonb_build_object(
      'version', p_version, 'catalogue', v_n, 'backfill', v_backfill,
      'switch', jsonb_build_object('xp', coalesce(v_xp_on::text, 'off'),
                                   'catalogue', coalesce(v_cat::text, 'off')),
      'turned_on', case when v_turn_on then 'xp' when v_turn_cat then 'catalogue' end,
      'levels', v_levels,
      'next', case when v_turn_cat then 'run the career_rewards_batch() statements from scripts/career_seed.py --catalogue-steps'
                   when v_cat is not null and not v_same then 'the catalogue changed with the switch on: run career_rewards_batch(o, 5, ''silent'') from offset 0 until it answers n = 0'
              end));
    if p_dry_run then
      raise exception using errcode = 'P0001', message = 'career_seed: dry run';
    end if;
  exception when sqlstate 'P0001' then
    if sqlerrm <> 'career_seed: dry run' then
      raise;
    end if;
    v_out := v_out || jsonb_build_object('dry_run', true, 'note', 'a dry run: everything above was worked out, then undone');
  end;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.career_session_want(p_athlete text, p_day integer DEFAULT NULL::integer, p_on date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with s as (
    select sh.day, sh.completed_on, sh.duration_min, sh.readiness, sh.log, sh.fin,
           'd' || sh.day || '|' || sh.completed_on::text as ref,
           regexp_match(coalesce(sh.status, ''), '^\s*partial\s*\(\s*(\d+)\s+of\s+(\d+)', 'i') as part,
           coalesce(sh.status, '') ~* '^\s*partial' as early
      from public.session_history sh
     where sh.athlete_id = p_athlete and sh.hidden_at is null
       and (p_day is null or (sh.day = p_day and sh.completed_on = p_on))
  ),
  ent as (      -- every set of every exercise of a structured log (a circuit logs rounds, not sets)
    select s.ref, e.o, st.v as st
      from s, jsonb_array_elements(case when jsonb_typeof(s.log) = 'array' then s.log else '[]'::jsonb end) with ordinality as e(v, o),
           jsonb_array_elements(case when jsonb_typeof(e.v) = 'object' and jsonb_typeof(e.v -> 'sets') = 'array'
                                     then e.v -> 'sets' else '[]'::jsonb end) as st(v)
  ),
  asks as (     -- the exercises whose card asks an RPE: the log does not carry the target, so one rated on any set asks it on all
    select ent.ref, ent.o from ent group by ent.ref, ent.o having bool_or(public.career_truthy(ent.st -> 'r'))
  ),
  logged as (
    select s.ref,
           jsonb_typeof(s.log) = 'array' and not s.early
           and exists (select 1 from ent where ent.ref = s.ref)
           and not exists (select 1 from ent where ent.ref = s.ref and not public.career_truthy(ent.st -> 'd'))
           and not exists (select 1 from ent join asks on asks.ref = ent.ref and asks.o = ent.o
                            where ent.ref = s.ref and not public.career_truthy(ent.st -> 'r')) as ok
      from s
  ),
  checkin as (
    select s.ref,
           jsonb_typeof(s.readiness) = 'object'
           and not public.career_truthy(s.readiness -> 'skipped')
           and exists (select 1 from unnest(array['composite', 'score', 'sleep', 'energy', 'soreness', 'stress', 'overall']) as k(key)
                        where jsonb_typeof(s.readiness -> k.key) = 'number') as ok
      from s
  )
  select coalesce(jsonb_agg(x), '[]'::jsonb) from (
    select jsonb_build_object('kind', case when s.early then 'session_finished_early' else 'session_finished' end,
                              'ref', s.ref, 'day', s.completed_on,
                              'value', jsonb_strip_nulls(jsonb_build_object('plan_day', s.day::text, 'minutes', s.duration_min, 'fin', s.fin /* stage99 */,
                                                                            'done', (s.part)[1]::int, 'of', (s.part)[2]::int))) as x
      from s
    union all
    select jsonb_build_object('kind', 'full_log', 'ref', s.ref, 'day', s.completed_on, 'value', jsonb_build_object('plan_day', s.day::text))
      from s join logged l on l.ref = s.ref where l.ok
    union all
    select jsonb_build_object('kind', 'checkin_done', 'ref', s.ref, 'day', s.completed_on, 'value', jsonb_build_object('plan_day', s.day::text))
      from s join checkin c on c.ref = s.ref where c.ok
  ) z
$function$;

CREATE OR REPLACE FUNCTION public.career_settled_before(p_rules jsonb)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when public.career_switch_day(p_rules, 'xp') is null then null
              else current_date - (coalesce((p_rules #>> '{habits,backfill_days}')::int, 3) + 1) end
$function$;

CREATE OR REPLACE FUNCTION public.career_slam(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with owned as (
    select c.id as cid, t.earned_on as day
      from public.hab_titles t
      join lateral (select c0.id from public.career_catalogue c0
                     where c0.kind = 'title' and (c0.body ->> 'proof_id' = t.title or c0.id = t.title)
                     order by (c0.body ->> 'proof_id' = t.title) desc nulls last, c0.id limit 1) c on true
     where t.athlete_id = p_athlete
    union all
    select a.item, a.day from public.career_awards a where a.athlete_id = p_athlete and a.kind = 'title'
  ),
  m as (
    select o.cid, o.day, c.body ->> 'meaning' as meaning, c.body ->> 'name' as name
      from owned o join public.career_catalogue c on c.kind = 'title' and c.id = o.cid
  ),
  pick as (
    select distinct on (m.meaning) m.meaning, jsonb_build_object('id', m.cid, 'name', m.name, 'day', m.day) as j
      from m where m.meaning in ('consistency', 'commitment', 'progress', 'resilience')
     order by m.meaning, m.day, m.cid
  )
  select jsonb_build_object(
    'consistency', (select pick.j from pick where pick.meaning = 'consistency'),
    'commitment',  (select pick.j from pick where pick.meaning = 'commitment'),
    'progress',    (select pick.j from pick where pick.meaning = 'progress'),
    'resilience',  (select pick.j from pick where pick.meaning = 'resilience'),
    'grand', (select jsonb_build_object('day', a.day) from public.career_awards a where a.athlete_id = p_athlete and a.award_id = 'title:grand_slam'))
$function$;

CREATE OR REPLACE FUNCTION public.career_slam_year(p_athlete text, p_of jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with win as (
    select (row_number() over (order by c.id, w.o))::int as wi, (w.v ->> 'from') as lo, (w.v ->> 'to') as hi
      from public.career_catalogue c
           cross join lateral jsonb_array_elements(case when jsonb_typeof(c.body -> 'windows') = 'array' then c.body -> 'windows' else '[]'::jsonb end)
                      with ordinality w(v, o)
     where c.kind = 'achievement'
       and c.id in (select x from jsonb_array_elements_text(case when jsonb_typeof(p_of) = 'array' then p_of else '[]'::jsonb end) x)
  ),
  hit as (
    select extract(year from f.day)::int as y, win.wi, min(f.day) as d
      from public.career_facts f join win on to_char(f.day, 'MM-DD') between win.lo and win.hi
     where f.athlete_id = p_athlete and f.kind in ('session_finished', 'session_finished_early') and f.void_at is null
     group by 1, 2
  ),
  yr as (select hit.y, count(*)::int as n, max(hit.d) as d from hit group by hit.y)
  select jsonb_build_object(
           'need', (select count(*) from win),
           'have', coalesce((select max(yr.n) from yr), 0),
           'day', (select min(yr.d) from yr where yr.n = (select count(*) from win) and (select count(*) from win) > 0))
$function$;

CREATE OR REPLACE FUNCTION public.career_stamp(p_athlete text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select md5(concat_ws('|',
    (select r.version::text || '@' || r.loaded_at::text from public.career_rules r order by r.version desc limit 1),
    (select md5(coalesce(x.rules -> 'questRuns', '[]'::jsonb)::text) from public.xp_rules x where x.id = 1),
    (select s.starts_on::text from public.current_season() s),
    current_date::text,
    (select count(*)::text || '@' || coalesce(max(f.updated_at)::text, '-') from public.career_facts f where f.athlete_id = p_athlete),
    (select p.updated_at::text from public.programs p where p.athlete_id = p_athlete),
    (select count(*)::text || '@' || coalesce(max(v.saved_at)::text, '-') from public.program_versions v where v.athlete_id = p_athlete),
    (select count(*)::text || '@' || coalesce(max(a.created_at)::text, '-') from public.career_awards a where a.athlete_id = p_athlete)))
$function$;

CREATE OR REPLACE FUNCTION public.career_switch_day(p_rules jsonb, p_which text)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v text := p_rules #>> array['switch', p_which]; d date;
begin
  if v is null or v !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  begin
    d := v::date;
  exception when others then
    return null;
  end;
  return case when d <= current_date then d end;
end $function$;

CREATE OR REPLACE FUNCTION public.career_sync(p_athlete text, p_kinds text[], p_want jsonb, p_source text, p_refs text[] DEFAULT NULL::text[], p_settled_before date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_up integer; v_gone integer; v_k1 text[]; v_k2 text[];
begin
  with w as (
    select distinct on (x.kind, x.ref) x.kind, x.ref, x.day, coalesce(x.value, '{}'::jsonb) as value
      from jsonb_to_recordset(coalesce(p_want, '[]'::jsonb)) as x(kind text, ref text, day date, value jsonb)
     where x.kind = any (p_kinds) and x.ref is not null and x.day is not null
     order by x.kind, x.ref
  ), up as (
    insert into public.career_facts as f (athlete_id, kind, ref, day, value, source, updated_at)
    select p_athlete, w.kind, w.ref, w.day, w.value, p_source, clock_timestamp() from w
    on conflict (athlete_id, kind, ref) do update
       set day = excluded.day, value = excluded.value, source = excluded.source, void_at = null, updated_at = clock_timestamp()
     where (f.day is distinct from excluded.day or f.value is distinct from excluded.value
            or f.source is distinct from excluded.source or f.void_at is not null)
       and (p_settled_before is null or f.day >= p_settled_before)
    returning f.kind
  )
  select count(*), array_agg(distinct up.kind) into v_up, v_k1 from up;

  with w as (
    select x.kind, x.ref
      from jsonb_to_recordset(coalesce(p_want, '[]'::jsonb)) as x(kind text, ref text, day date, value jsonb)
     where x.kind = any (p_kinds)
  ), gone as (
    update public.career_facts f set void_at = clock_timestamp(), updated_at = clock_timestamp()
     where f.athlete_id = p_athlete and f.kind = any (p_kinds) and f.void_at is null
       and (p_refs is null or f.ref = any (p_refs))
       and (p_settled_before is null or f.day >= p_settled_before)
       and not exists (select 1 from w where w.kind = f.kind and w.ref = f.ref)
    returning f.kind
  )
  select count(*), array_agg(distinct gone.kind) into v_gone, v_k2 from gone;
  if v_up + v_gone > 0 then
    perform set_config('career.changed',
                       concat_ws(',', nullif(current_setting('career.changed', true), ''), array_to_string(coalesce(v_k1, '{}') || coalesce(v_k2, '{}'), ',')),
                       true);
  end if;
  return v_up + v_gone;
end $function$;

CREATE OR REPLACE FUNCTION public.career_truthy(p jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case jsonb_typeof(p)
           when 'boolean' then p = 'true'::jsonb
           when 'number' then (p #>> '{}')::numeric <> 0
           when 'string' then (p #>> '{}') <> ''
           when 'object' then true
           when 'array' then true
           else false end
$function$;

CREATE OR REPLACE FUNCTION public.career_w(p jsonb, OUT n numeric, OUT u text)
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text; m text[];
begin
  n := null; u := 'kg';
  if p is null or jsonb_typeof(p) not in ('string', 'number') then return; end if;
  if not public.career_truthy(p) then return; end if;               -- String(v || ''): 0 and '' read as nothing
  t := regexp_replace(public.career_digits(p #>> '{}'), ',', '.');   -- the first comma only, as String.replace does
  m := regexp_match(t, '^\s*([1-4])\s*[×xX*]\s*([0-9]+(?:\.[0-9]+)?)');
  if m is not null then
    n := m[2]::numeric;
  else
    m := regexp_match(t, '[0-9]+(?:\.[0-9]+)?');
    if m is null then return; end if;
    n := m[1]::numeric;
  end if;
  if not (n > 0) then n := null; return; end if;
  if t ~* '[0-9]\s*(lbs?|pounds?)([^a-z]|$)' then u := 'lb';
  elsif t ~* '[0-9]\s*plates?([^a-z]|$)' then u := 'plates';
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.career_weeks(p_athlete text)
 RETURNS TABLE(cycle_index integer, cycle_num integer, week integer, weeks integer, wfrom date, wto date, cstart date, cend date, plan text[], is_current boolean, is_last boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with p as (select pr.data from public.programs pr where pr.athlete_id = p_athlete),
  cur as (
    select p.data,
           case when jsonb_typeof(p.data -> 'currentCycleIndex') = 'number'
                     and public.career_num(p.data -> 'currentCycleIndex') = trunc(public.career_num(p.data -> 'currentCycleIndex'))
                then public.career_num(p.data -> 'currentCycleIndex')::int else 0 end as cci,
           case when jsonb_typeof(p.data -> 'cycles') = 'array' then p.data -> 'cycles' else '[]'::jsonb end as cycles,
           case when jsonb_typeof(p.data -> 'programHistory') = 'array' then p.data -> 'programHistory' else '[]'::jsonb end as hist
      from p
  ),
  c as (
    select (x.o - 1)::int as idx,
           coalesce(case when public.career_num(x.c -> 'num') = trunc(public.career_num(x.c -> 'num'))
                         then public.career_num(x.c -> 'num')::int end, x.o::int) as num,
           public.career_day(x.c ->> 'startDate') as s, public.career_day(x.c ->> 'endDate') as e,
           cur.cci, jsonb_array_length(cur.cycles) as ncyc, cur.data, cur.hist
      from cur, jsonb_array_elements(cur.cycles) with ordinality x(c, o)
  ),
  planned as (
    select c.*,
           case when c.idx = c.cci then
             (select array_agg(coalesce(y.d ->> 'id', y.o::text) order by y.o)
                from jsonb_array_elements(case when jsonb_typeof(c.data -> 'workouts' -> 'days') = 'array'
                                               then c.data -> 'workouts' -> 'days' else '[]'::jsonb end) with ordinality y(d, o))
           else coalesce(
             (select array_agg(coalesce(y.d ->> 'id', y.o::text) order by y.o)
                from (select v.data from public.program_versions v
                       where v.athlete_id = p_athlete and jsonb_typeof(v.data -> 'currentCycleIndex') = 'number'
                         and public.career_num(v.data -> 'currentCycleIndex') = c.idx
                       order by v.saved_at desc limit 1) lv,
                     jsonb_array_elements(case when jsonb_typeof(lv.data -> 'workouts' -> 'days') = 'array'
                                               then lv.data -> 'workouts' -> 'days' else '[]'::jsonb end) with ordinality y(d, o)),
             (select array_agg(g::text order by g)
                from (select h.v as h from jsonb_array_elements(c.hist) as h(v)
                       where h.v ->> 'id' = 'prog' || c.num limit 1) hp,
                     generate_series(1, case when jsonb_typeof(hp.h -> 'days') = 'array' then jsonb_array_length(hp.h -> 'days') else 0 end) g),
             (select array_agg(g::text order by g)
                from (select c.hist -> (c.cci - 1 - c.idx) as h where jsonb_array_length(c.hist) = c.cci) hp,
                     generate_series(1, case when jsonb_typeof(hp.h -> 'days') = 'array' then jsonb_array_length(hp.h -> 'days') else 0 end) g))
           end as plan
      from c
     where c.idx <= c.cci
  )
  select pl.idx, pl.num, k::int, t.tot, pl.s + 7 * (k - 1), least(pl.s + 7 * k - 1, pl.e), pl.s, pl.e, pl.plan,
         pl.idx = pl.cci, pl.idx = pl.ncyc - 1
    from planned pl
   cross join lateral (select greatest(1, round((pl.e - pl.s) / 7.0)::int) as tot) t
   cross join lateral generate_series(1, t.tot) k
   where pl.s is not null and pl.e is not null and pl.e >= pl.s and cardinality(pl.plan) > 0
$function$;

CREATE OR REPLACE FUNCTION public.career_win_gain(a_w numeric, a_n numeric, a_ng boolean, a_idx numeric, b_w numeric, b_n numeric, b_ng boolean, b_idx numeric, p_min numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_g numeric; v_dw numeric := 0; v_dn numeric;
begin
  if not a_ng or not b_ng then return null; end if;            -- a hold: only its RPE can move
  v_g := case when coalesce(a_idx, 0) <> 0 and coalesce(b_idx, 0) <> 0 then b_idx / a_idx - 1 else 0 end;
  if v_g < p_min then return null; end if;
  if not (a_w is not null and b_w is not null) and (a_w is not null or b_w is not null) then return null; end if;
  if a_w is not null and b_w is not null then v_dw := round((b_w - a_w) * 2) / 2; end if;   -- winText(): to the half kilo
  v_dn := coalesce(b_n, 0) - coalesce(a_n, 0);
  if not (v_dw > 0 or v_dn > 0) then return null; end if;
  return v_g;
end $function$;

CREATE OR REPLACE FUNCTION public.career_wn(p jsonb)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ select (public.career_w(p)).n $function$;

CREATE OR REPLACE FUNCTION public.career_wu(p jsonb)
 RETURNS text
