CREATE OR REPLACE FUNCTION public.claim_titles(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(title text, earned_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return;   -- stage78: titles are gone (round 5, L5): no rows
end; $function$;

CREATE OR REPLACE FUNCTION public.clear_quests(p_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text; v_runs jsonb; v_kept jsonb := '[]'::jsonb; r jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  v_key := to_char(p_start, 'YYYY-MM-DD');
  select coalesce(rules -> 'questRuns', '[]'::jsonb) into v_runs from public.xp_rules where id = 1;
  for r in select value from jsonb_array_elements(v_runs) loop
    if r ->> 'start' is distinct from v_key then v_kept := v_kept || jsonb_build_array(r); end if;
  end loop;
  update public.xp_rules
     set rules = jsonb_set(rules, '{questRuns}', v_kept), updated_at = now()
   where id = 1;
  return v_kept;
end; $function$;

CREATE OR REPLACE FUNCTION public.clear_used_first_passwords()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  begin
    update public.athlete_identities
       set initial_password = null, sent_at = coalesce(sent_at, new.last_sign_in_at)
     where user_id = new.id and initial_password is not null
       and password_set_at is not null and new.last_sign_in_at > password_set_at;
    update public.tps_accounts
       set initial_password = null, sent_at = coalesce(sent_at, new.last_sign_in_at)
     where user_id = new.id and initial_password is not null
       and password_set_at is not null and new.last_sign_in_at > password_set_at;
    update public.assess_accounts
       set initial_password = null, sent_at = coalesce(sent_at, new.last_sign_in_at)
     where user_id = new.id and initial_password is not null
       and password_set_at is not null and new.last_sign_in_at > password_set_at;
  exception when others then
    null;   -- never block a sign-in over bookkeeping
  end;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_cheer(p_athlete text, p_word text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_to text; v_word text; v_day date := (now() at time zone 'UTC')::date;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  select m.athlete_id into v_to from public.crew_members() m where m.athlete_id = nullif(btrim(coalesce(p_athlete, '')), '');
  if v_to is null then raise exception 'crew:gone'; end if;
  v_word := nullif(regexp_replace(public.crew_clean(p_word), '\s+', ' ', 'g'), '');
  if v_word is not null and char_length(v_word) > 100 then raise exception 'crew:word_long'; end if;
  perform pg_advisory_xact_lock(hashtext('crew_cheer:' || public.coach_note_id()));
  if exists (select 1 from public.crew_cheers x where x.athlete_id = public.coach_note_id() and x.to_athlete = v_to and x.day = v_day) then raise exception 'crew:cheer_today'; end if;
  insert into public.crew_cheers (athlete_id, to_athlete, day, word) values (public.coach_note_id(), v_to, v_day, v_word);
  return jsonb_build_object('ok', true, 'season', public.crew_cheer_count(v_to));
end $function$;

CREATE OR REPLACE FUNCTION public.coach_cheer_word_clear(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  update public.crew_cheers set word = null where id = p_id and word is not null;
  return jsonb_build_object('ok', true);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_courtside_mark(p_athlete_id text, p_award_ids text[], p_what text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if p_what not in ('saw', 'sent', 'undo') then raise exception 'coach_courtside_mark: % is not saw, sent or undo', p_what; end if;
  if p_what = 'undo' then
    delete from public.courtside_marks m where m.athlete_id = p_athlete_id and m.award_id = any (p_award_ids);
    select count(*)::int into v_n from public.career_awards a where a.athlete_id = p_athlete_id and a.award_id = any (p_award_ids);
    return v_n;
  end if;
  insert into public.courtside_marks as m (athlete_id, award_id, saw_at, sent_at)
    select a.athlete_id, a.award_id, now(), case when p_what = 'sent' then now() end
      from public.career_awards a where a.athlete_id = p_athlete_id and a.award_id = any (p_award_ids) and a.how = 'live'
  on conflict (athlete_id, award_id) do update
     set saw_at = coalesce(m.saw_at, excluded.saw_at), sent_at = coalesce(m.sent_at, excluded.sent_at), updated_at = now();
  get diagnostics v_n = row_count;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  perform public.crew_sweep();
  return jsonb_build_object(
    'posts', (select coalesce(jsonb_agg(jsonb_build_object(
                'id', p.id, 'athlete_id', p.athlete_id, 'amir', p.athlete_id = public.coach_note_id(),
                'who', case when p.athlete_id = public.coach_note_id() then 'Amir'
                            else coalesce((select m.name from public.crew_members() m where m.athlete_id = p.athlete_id), public.crew_default_name(p.athlete_id), p.athlete_id) end,
                'seen', p.athlete_id = public.coach_note_id() or exists (select 1 from public.crew_members() m where m.athlete_id = p.athlete_id),
                'kind', p.kind, 'body', p.body, 'photo', p.has_photo, 'at', p.created_at, 'ask', p.session -> 'ask',   -- stage103: a Mailbag answer's question
                'kudos', (select count(*) from public.crew_kudos k where k.post_id = p.id)) order by p.created_at desc), '[]'::jsonb)
                from public.crew_posts p),
    'people', (select coalesce(jsonb_agg(jsonb_build_object(
                 'athlete_id', c.athlete_id, 'answer', c.answer, 'under13', c.under13, 'answered_at', c.answered_at,
                 'kinds_off', (select coalesce(jsonb_agg(k.key), '[]'::jsonb) from jsonb_each(c.kinds) k where k.value = 'false'::jsonb)) order by c.athlete_id), '[]'::jsonb)
                 from public.crew_consent c),
    'rings_week', (select count(*) from public.crew_rings r where r.created_at >= now() - interval '7 days'));
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_cheers()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', c.id, 'from_athlete', c.athlete_id,
             'from_who', case when c.athlete_id = public.coach_note_id() then 'Coach' else coalesce(gm.name, public.crew_default_name(c.athlete_id), c.athlete_id) end,
             'to_athlete', c.to_athlete, 'to_who', coalesce(tm.name, public.crew_default_name(c.to_athlete), c.to_athlete),
             'word', c.word, 'day', c.day) order by c.day desc, c.id desc)
      from public.crew_cheers c
      left join public.crew_members() gm on gm.athlete_id = c.athlete_id
      left join public.crew_members() tm on tm.athlete_id = c.to_athlete
     where c.day >= current_date - 7), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_face_clear(p_athlete text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  delete from public.crew_faces where athlete_id = p_athlete;
  return jsonb_build_object('ok', true);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_faces()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('athlete_id', f.athlete_id, 'fv', extract(epoch from f.updated_at)::bigint,
                                                       'b64', replace(encode(f.bytes, 'base64'), E'\n', '')) order by f.athlete_id)
                     from public.crew_faces f), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_post(p_body text, p_photo text DEFAULT NULL::text, p_w integer DEFAULT NULL::integer, p_h integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  perform public.crew_sweep();
  return public.crew_write_post(public.coach_note_id(), p_body, p_photo, p_w, p_h, 'post', null, false);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_remove(p_post uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  delete from public.crew_posts p where p.id = p_post;
  return found;
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_remove_reply(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  delete from public.crew_replies where id = p_id;
  return found;
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_under13(p_athlete text, p_on boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if nullif(btrim(coalesce(p_athlete, '')), '') is null or p_on is null then raise exception 'crew:who'; end if;
  if not exists (select 1 from public.programs p where p.athlete_id = p_athlete) then raise exception 'crew:who'; end if;
  insert into public.crew_consent as c (athlete_id, under13) values (p_athlete, p_on)
  on conflict (athlete_id) do update set under13 = excluded.under13, updated_at = now();
  if p_on then
    delete from public.crew_posts where athlete_id = p_athlete;
    delete from public.crew_kudos where athlete_id = p_athlete;
    delete from public.crew_rings where athlete_id = p_athlete;
    perform public.crew_forget(p_athlete);   -- stage96: the face, the cheers, the signatures and the mentions, both ways
  end if;
  return p_on;
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_week_close(p_week date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: Close early. The card shows the result and takes no more votes.
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  update public.crew_weeks set closed_at = coalesce(closed_at, now()), updated_at = now() where week_start = date_trunc('week', p_week)::date;
  return public.coach_crew_weekly();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_week_set(p_week date, p_q text, p_a text, p_b text, p_theme text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: write or change one week of the bank. Empty fields clear it (a week with nothing is skipped). A changed question keeps no
-- votes: the votes were for the old one.
declare w date := date_trunc('week', p_week)::date;
  v_q text := nullif(btrim(coalesce(p_q, '')), ''); v_a text := nullif(btrim(coalesce(p_a, '')), '');
  v_b text := nullif(btrim(coalesce(p_b, '')), ''); v_t text := nullif(btrim(coalesce(p_theme, '')), '');
  old public.crew_weeks;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if (v_q is null) <> (v_a is null) or (v_q is null) <> (v_b is null) then
    raise exception 'A question needs both sides, or leave all three empty.';
  end if;
  select * into old from public.crew_weeks where week_start = w;
  insert into public.crew_weeks (week_start, toss_q, toss_a, toss_b, theme) values (w, v_q, v_a, v_b, v_t)
    on conflict (week_start) do update set toss_q = excluded.toss_q, toss_a = excluded.toss_a, toss_b = excluded.toss_b,
                                           theme = excluded.theme, updated_at = now();
  if old.week_start is not null and (old.toss_q, old.toss_a, old.toss_b) is distinct from (v_q, v_a, v_b) then
    delete from public.crew_toss_votes where week_start = w;
  end if;
  return public.coach_crew_weekly();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_crew_weekly()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: coach.html's Crew desk: the bank (this week back 2, ahead 20), this week's votes, the Mailbag (open, and answered in 30 days).
declare v_now date := date_trunc('week', current_date)::date;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  return jsonb_build_object(
    'week', v_now,
    'weeks', coalesce((select jsonb_agg(jsonb_build_object('week', w.week_start, 'q', w.toss_q, 'a', w.toss_a, 'b', w.toss_b, 'theme', w.theme,
                                                           'closed', w.closed_at is not null,
                                                           'va', (select count(*) from public.crew_toss_votes t where t.week_start = w.week_start and t.side = 'a'),
                                                           'vb', (select count(*) from public.crew_toss_votes t where t.week_start = w.week_start and t.side = 'b'))
                                        order by w.week_start)
                         from public.crew_weeks w where w.week_start between v_now - 14 and v_now + 140), '[]'::jsonb),
    'members', (select count(*) from public.crew_members()),
    'questions', coalesce((select jsonb_agg(jsonb_build_object('id', q.id, 'athlete_id', q.athlete_id, 'body', q.body, 'ok_name', q.ok_name,
                                                               'at', q.created_at, 'answer', q.answer, 'answered_at', q.answered_at)
                                            order by (q.answered_at is null) desc, coalesce(q.answered_at, q.created_at) desc)
                             from public.crew_questions q where q.answered_at is null or q.answered_at > now() - interval '30 days'), '[]'::jsonb),
    'answered_month', (select count(*) from public.crew_questions q where q.answered_at >= date_trunc('month', now())));
end $function$;

CREATE OR REPLACE FUNCTION public.coach_delete_training_history(p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sessions integer; v_progress integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' then
    raise exception 'which athlete?';
  end if;
  with d as (delete from public.session_history where athlete_id = p_athlete_id returning 1)
    select count(*) into v_sessions from d;
  with d as (delete from public.athlete_progress where athlete_id = p_athlete_id returning 1)
    select count(*) into v_progress from d;
  return jsonb_build_object('sessions', v_sessions, 'progress', v_progress);
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_erase_person(p_kind text, p_key text, p_confirm text DEFAULT NULL::text, p_intake_ids uuid[] DEFAULT '{}'::uuid[], p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  -- Every table that holds a row under an athlete id, in the order they are emptied. A table that is missing here but has an
  -- athlete_id column is caught by the check near the end, which undoes everything and names it.
  -- The first four are in the order publish_cycle() and the dashboard's editor lock them (programs, its versions, the coaching log,
  -- its versions): the same order means the two can wait for each other but never deadlock, and an erasure that starts while a
  -- cycle is being published waits at programs, so the publish's new version rows are committed before they are deleted.
  c_athlete_tables constant text[] := array[
    'programs', 'program_versions', 'coaching_logs', 'coaching_log_versions',
    'session_history', 'athlete_progress', 'hab_notes', 'hab_titles', 'hab_season_results', 'leaderboard_optin',
    'library_sessions', 'messages', 'call_logs', 'cycle_reports', 'athlete_keys', 'hab_contacts', 'athlete_identities', 'athlete_status', 'career_facts', 'career_scores', 'career_awards', 'career_recognition', 'courtside_marks', 'career_honours', 'career_goals', 'career_notes', 'athlete_profile', 'crew_mentions', 'crew_replies', 'crew_award_likes', 'crew_cheers', 'crew_faces', 'crew_cheer_tally', 'crew_kudos', 'crew_photos', 'crew_posts', 'crew_open_results', 'crew_rings', 'crew_consent', 'push_sent', 'push_subs', 'crew_push_q', 'crew_push_seen', 'push_cycle_seen', 'referral_credits', 'crew_toss_votes', 'crew_questions'];
  -- Not clients: the public demo, and the identity coach.html reads the board through (AMIR_ATHLETE_ID there).
  c_protected constant text[] := array['demo', 'amir_ardekani'];
  -- Arabic-Indic (U+0660-0669) and Persian (U+06F0-06F9) digits, and what they fold to.
  c_digits_from constant text := U&'\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9';
  c_digits_to   constant text := '01234567890123456789';
  v_kind      text    := lower(btrim(coalesce(p_kind, '')));
  v_key       text    := btrim(coalesce(p_key, ''));
  v_word      text;                         -- what the coach must type to confirm
  v_shown     text;                         -- a name for the confirmation text
  v_user      uuid;
  v_users     uuid[]  := '{}';              -- the logins that go with the person
  v_counts    jsonb   := '{}'::jsonb;
  v_total     bigint  := 0;
  v_n         bigint;
  v_emails    text[]  := '{}';
  v_phones    text[]  := '{}';              -- the last 9 digits of each WhatsApp number on their contact record
  v_fullname  text;
  v_cands     jsonb   := '[]'::jsonb;       -- intake forms that look like theirs
  v_unlinked  jsonb   := '[]'::jsonb;       -- affiliate codes whose link to this athlete was cleared
  v_ids       uuid[]  := coalesce(p_intake_ids, '{}');
  v_log_id    bigint;
  v_result    jsonb;
  v_other     text;
  t           text;
  sch         text;
  v_col       text;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  -- NULL is neither a dry run nor a real run: "not null" is null, so every test of the flag below would be skipped while the deletes
  -- still ran and committed (found in review, 2026-10-11). Only an explicit true or false is accepted.
  if p_dry_run is null then
    raise exception 'p_dry_run must be true or false, not null. Nothing was erased.';
  end if;
  if v_kind not in ('athlete', 'course', 'testing') then
    raise exception 'Unknown kind of person "%": use athlete, course or testing.', v_kind;
  end if;
  if v_key = '' then
    raise exception 'Who? The id or username is empty.';
  end if;
  -- One erasure at a time (a double tap, two tabs): the second one waits, then finds nothing.
  perform pg_advisory_xact_lock(hashtext('coach_erase_person'));

  begin   -- everything that changes data is in this block; a dry run ends by raising ZZ100, which undoes all of it
    -- ── who is this, and which logins go with them ──────────────────────────────────────────────────────────────────────
    if v_kind = 'athlete' then
      if lower(v_key) = any (c_protected) then
        raise exception '"%" is not a client (the public demo, or the identity this dashboard reads the board through). It is never erased.', v_key;
      end if;
      v_word := v_key;
      -- The identity row for exactly this id, plus a sign-in on the internal address that NO identity row claims (the row was lost
      -- earlier). Ids are case-sensitive but GoTrue lower-cases the address, so a sign-in whose identity row names another id (a key
      -- typed in another case) is never taken: before this, typing ZZ_Case_A for zz_case_a deleted the login and left the data.
      select coalesce(array_agg(distinct x.id), '{}'::uuid[]) into v_users
        from (select i.user_id as id from public.athlete_identities i where i.athlete_id = v_key
              union
              select u.id from auth.users u
               where lower(u.email) = lower('athlete.' || v_key || '@amirardekani.com')
                 and not exists (select 1 from public.athlete_identities i2 where i2.user_id = u.id)) x;
      select nullif(btrim(concat_ws(' ', p.data -> 'athlete' ->> 'firstName', p.data -> 'athlete' ->> 'lastName')), '')
        into v_shown from public.programs p where p.athlete_id = v_key;
      if v_shown is null then
        select nullif(btrim(c.display_name), '') into v_shown from public.hab_contacts c where c.athlete_id = v_key;
      end if;
      if v_shown is null then
        select nullif(btrim(a.athlete_name), '') into v_shown from public.athlete_progress a where a.athlete_id = v_key;
      end if;
      v_shown := coalesce(v_shown, v_key);
      if exists (select 1 from public.tps_accounts a where a.user_id = any (v_users))
         or exists (select 1 from public.assess_accounts a where a.user_id = any (v_users)) then
        raise exception 'This athlete''s login is also a course or testing-app login. Nothing was erased: sort that out by hand first.';
      end if;
    elsif v_kind = 'course' then
      select a.user_id, a.username into v_user, v_word from public.tps_accounts a where lower(a.username) = lower(v_key);
      if v_user is null then
        raise exception 'There is no course login called "%". Nothing was erased.', v_key;
      end if;
      v_users := array[v_user];
      select nullif(btrim(n.note), '') into v_shown from public.buyer_notes n where n.user_id = v_user;
      v_shown := coalesce(v_shown, v_word);
      if exists (select 1 from public.athlete_identities i where i.user_id = v_user)
         or exists (select 1 from public.assess_accounts a where a.user_id = v_user) then
        raise exception 'This course login is also an athlete or testing-app login. Nothing was erased: sort that out by hand first.';
      end if;
    else
      select a.user_id, a.username into v_user, v_word from public.assess_accounts a where lower(a.username) = lower(v_key);
      if v_user is null then
        raise exception 'There is no testing-app login called "%". Nothing was erased.', v_key;
      end if;
      v_users := array[v_user];
      select nullif(btrim(n.note), '') into v_shown from public.buyer_notes n where n.user_id = v_user;
      v_shown := coalesce(v_shown, v_word);
      if exists (select 1 from public.athlete_identities i where i.user_id = v_user)
         or exists (select 1 from public.tps_accounts a where a.user_id = v_user) then
        raise exception 'This testing-app login is also an athlete or course login. Nothing was erased: sort that out by hand first.';
      end if;
    end if;

    if exists (select 1 from auth.users u
                where u.id = any (v_users)
                  and (lower(coalesce(u.email, '')) = 'amirardekanian@gmail.com' or u.id = auth.uid())) then
      raise exception 'That login is yours, the coach''s. Nothing was erased.';
    end if;

    -- ── the typed confirmation: a real run only ─────────────────────────────────────────────────────────────────────────
    if not p_dry_run and lower(btrim(coalesce(p_confirm, ''))) <> lower(v_word) then
      raise exception 'The confirmation does not match. Type exactly "%" to erase. Nothing was erased.', v_word;
    end if;

    -- ── athlete: the intake forms that look like theirs, then everything under the id ───────────────────────────────────
    if v_kind = 'athlete' then
      -- What identifies them: the emails and WhatsApp numbers on their contact record, and their full name as the programme spells it.
      -- A number is compared by its last 9 digits with Persian and Arabic-Indic digits folded to 0-9, so 0912…, +98912… and ۰۹۱۲… are one.
      select coalesce(array_agg(distinct lower(btrim(c.email))) filter (where nullif(btrim(c.email), '') is not null), '{}'::text[]),
             coalesce(array_agg(distinct right(d.digits, 9)) filter (where length(d.digits) >= 9), '{}'::text[])
        into v_emails, v_phones
        from public.hab_contacts c
        cross join lateral (select regexp_replace(translate(coalesce(c.whatsapp, ''), c_digits_from, c_digits_to), '\D', '', 'g') as digits) d
       where c.athlete_id = v_key;
      select lower(regexp_replace(btrim(concat_ws(' ', p.data -> 'athlete' ->> 'firstName', p.data -> 'athlete' ->> 'lastName')), '\s+', ' ', 'g'))
        into v_fullname from public.programs p
       where p.athlete_id = v_key
         and nullif(btrim(p.data -> 'athlete' ->> 'firstName'), '') is not null
         and nullif(btrim(p.data -> 'athlete' ->> 'lastName'), '') is not null;
      -- 'shared' = the same email or number is also on ANOTHER athlete's contact record (a parent's address for two children): the
      -- dashboard never ticks such a form for you.
      with f as (
        select i.id, i.created_at, i.name, i.programme, i.lang, (i.athlete_id is not distinct from v_key) as linked,
               lower(btrim(coalesce(i.email, ''))) as em,
               case when length(q.digits) >= 9 then right(q.digits, 9) end as ph,
               lower(regexp_replace(btrim(coalesce(i.name, '')), '\s+', ' ', 'g')) as nm
          from public.hab_intake i
          cross join lateral (select regexp_replace(translate(coalesce(i.contact, ''), c_digits_from, c_digits_to), '\D', '', 'g') as digits) q),
      m as (
        select f.*, case when f.linked then 'linked' when f.em <> '' and f.em = any (v_emails) then 'email'
                         when f.ph is not null and f.ph = any (v_phones) then 'whatsapp'
                         when v_fullname is not null and f.nm = v_fullname then 'name' end as how
          from f)
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', m.id, 'created_at', m.created_at, 'name', m.name, 'programme', m.programme, 'lang', m.lang,
               'matched_on', m.how,
               'shared', (m.how = 'email' and exists (select 1 from public.hab_contacts c2
                                                       where c2.athlete_id <> v_key and lower(btrim(coalesce(c2.email, ''))) = m.em))
                      or (m.how = 'whatsapp' and exists (select 1 from public.hab_contacts c2
                                                          cross join lateral (select regexp_replace(translate(coalesce(c2.whatsapp, ''), c_digits_from, c_digits_to), '\D', '', 'g') as digits) q2
                                                         where c2.athlete_id <> v_key and length(q2.digits) >= 9 and right(q2.digits, 9) = m.ph)))
               order by m.created_at), '[]'::jsonb)
        into v_cands from m where m.how is not null;
      -- The forms to erase are the coach's pick (Amir, 2026-10-11): the matches above are only offered, and a form filled in under
      -- another name or number (most Farsi forms: the programme is in Latin letters) is found by hand in the dashboard. So any
      -- form that exists may be named, but not a runaway list, and a form that is already gone stops the erasure.
      if (select count(distinct s.id) from unnest(v_ids) s(id)) > 10 then
        raise exception 'More than 10 intake forms in one erasure is almost certainly a mistake. Nothing was erased.';
      end if;
      if exists (select 1 from unnest(v_ids) s(id)
                  where s.id is null or not exists (select 1 from public.hab_intake i where i.id = s.id)) then
        raise exception 'One of the intake forms does not exist (it may already be gone). Nothing was erased.';
      end if;

      foreach t in array c_athlete_tables loop
        execute format('delete from public.%I where athlete_id = $1', t) using v_key;
        get diagnostics v_n = row_count;
        v_counts := v_counts || jsonb_build_object(t, v_n);
        v_total := v_total + v_n;
      end loop;

      -- stage81: the kudos others gave to this person's Bell lines (crew_kudos.to_athlete; the loop above deleted the ones they gave).
      delete from public.crew_kudos where to_athlete = v_key;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('crew_kudos (to them)', v_n);
      v_total := v_total + v_n;

      -- stage96: what others did TO this person (the loop above deleted what they did): cheers to them, names signed on their achievements, mentions of them.
      delete from public.crew_cheers where to_athlete = v_key;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('crew_cheers (to them)', v_n);
      v_total := v_total + v_n;
      delete from public.crew_award_likes where to_athlete = v_key;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('crew_award_likes (to them)', v_n);
      v_total := v_total + v_n;
      delete from public.crew_mentions where to_athlete = v_key;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('crew_mentions (to them)', v_n);
      v_total := v_total + v_n;

      -- stage97: a friend whose application is erased below leaves no name on the member's credit (the credit stays the member's own until THEY are erased).
      update public.referral_credits set friend_name = null, intake_id = null where intake_id = any (v_ids);

      -- The rollback copies the pipeline keeps before a one-off change to live programmes sit in the "backup" schema, outside the list
      -- above (backup.onename_2026_10_09 holds 17 athletes' old progress and session logs from the rename of 2026-10-09). Whatever table
      -- there has an athlete_id column is emptied for this person too, so a table added later is covered without anyone remembering it.
      for t in
        select c.relname::text
          from pg_catalog.pg_attribute a
          join pg_catalog.pg_class c on c.oid = a.attrelid
          join pg_catalog.pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'backup' and a.attname = 'athlete_id' and a.attnum > 0 and not a.attisdropped
           and c.relkind in ('r', 'p')
         order by 1
      loop
        execute format('delete from backup.%I where athlete_id::text = $1', t) using v_key;
        get diagnostics v_n = row_count;
        v_counts := v_counts || jsonb_build_object('backup.' || t, v_n);
        v_total := v_total + v_n;
      end loop;

      -- The forms are counted in v_total only AFTER the "nothing is stored" check below: a mistyped id with forms ticked must raise
      -- that error, not erase the forms and write a receipt.
      delete from public.hab_intake where id = any (v_ids);
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('hab_intake', v_n);

      -- A partner record is a business record and stays; only its link to the erased athlete id goes.
      with u as (update public.affiliates set athlete_id = null where athlete_id = v_key returning code)
        select coalesce(jsonb_agg(code order by code), '[]'::jsonb) into v_unlinked from u;
      -- An application linked to this athlete (stage61) keeps its answers unless the coach ticked it above; only the link goes.
      update public.hab_intake set athlete_id = null, linked_at = null where athlete_id = v_key;

    elsif v_kind = 'course' then
      delete from public.buyer_notes where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('buyer_notes', v_n);
      v_total := v_total + v_n;
      delete from public.tps_accounts where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('tps_accounts', v_n);
      v_total := v_total + v_n;

    else
      -- children first, so each count is the real number (a cascade would delete them uncounted)
      delete from public.assess_notes where account_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_notes', v_n);
      v_total := v_total + v_n;
      delete from public.assess_results where account_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_results', v_n);
      v_total := v_total + v_n;
      delete from public.assess_players where account_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_players', v_n);
      v_total := v_total + v_n;
      delete from public.buyer_notes where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('buyer_notes', v_n);
      v_total := v_total + v_n;
      delete from public.assess_accounts where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_accounts', v_n);
      v_total := v_total + v_n;
    end if;

    -- ── the sign-in account itself; its sessions, tokens and identities go with it ───────────────────────────────────────
    delete from auth.users where id = any (v_users);
    get diagnostics v_n = row_count;
    v_counts := v_counts || jsonb_build_object('auth_users', v_n);
    v_total := v_total + v_n;

    -- ── nothing may be left ────────────────────────────────────────────────────────────────────────────────────────────
    if exists (select 1 from public.athlete_identities x where x.user_id = any (v_users))
       or exists (select 1 from public.tps_accounts x where x.user_id = any (v_users))
       or exists (select 1 from public.assess_accounts x where x.user_id = any (v_users))
       or exists (select 1 from public.buyer_notes x where x.user_id = any (v_users)) then
      raise exception 'Stopped, nothing was erased: a login row was still there after its sign-in account was deleted.';
    end if;
    -- A table added later that keys its rows on a sign-in (a uuid column called user_id or account_id) and is not emptied by the
    -- cascade from the deleted sign-in: for a buyer this is the only check that such a table was never forgotten.
    for sch, t, v_col in
      select n.nspname::text, c.relname::text, a.attname::text
        from pg_catalog.pg_attribute a
        join pg_catalog.pg_class c on c.oid = a.attrelid
        join pg_catalog.pg_namespace n on n.oid = c.relnamespace
       where n.nspname = 'public' and a.attname in ('user_id', 'account_id') and a.atttypid = 'uuid'::regtype
         and a.attnum > 0 and not a.attisdropped and c.relkind in ('r', 'p')
       order by 1, 2, 3
    loop
      execute format('select count(*) from %I.%I where %I = any ($1)', sch, t, v_col) into v_n using v_users;
      if v_n > 0 then
        raise exception 'Stopped, nothing was erased: the table %.% still holds % row(s) for their sign-in (column %). coach_erase_person does not know that table yet.', sch, t, v_n, v_col;
      end if;
    end loop;
    if v_kind = 'athlete' then
      for sch, t in
        select n.nspname::text, c.relname::text
          from pg_catalog.pg_attribute a
          join pg_catalog.pg_class c on c.oid = a.attrelid
          join pg_catalog.pg_namespace n on n.oid = c.relnamespace
         where n.nspname in ('public', 'backup') and a.attname = 'athlete_id' and a.attnum > 0 and not a.attisdropped
           and c.relkind in ('r', 'p')
         order by 1, 2
      loop
        execute format('select count(*) from %I.%I where athlete_id::text = $1', sch, t) into v_n using v_key;
        if v_n > 0 then
          raise exception 'Stopped, nothing was erased: the table %.% still holds % row(s) for "%". coach_erase_person does not know that table yet.', sch, t, v_n, v_key;
        end if;
      end loop;
    end if;
    -- "Nothing is stored" looks at DATA only: a sign-in account on its own (the identity row was lost earlier) does not count, or a key
    -- typed in another case would take that login and leave the data under the real id.
    if v_total - coalesce((v_counts ->> 'auth_users')::bigint, 0) = 0 then
      if v_kind = 'athlete' then   -- ids are case-sensitive: say so when only the case differs
        select p.athlete_id into v_other from public.programs p where lower(p.athlete_id) = lower(v_key) and p.athlete_id <> v_key limit 1;
        if v_other is null then
          select a.athlete_id into v_other from public.athlete_progress a where lower(a.athlete_id) = lower(v_key) and a.athlete_id <> v_key limit 1;
        end if;
      end if;
      raise exception 'Nothing is stored for "%". Nothing was erased.%', v_key,
        case when v_other is not null then ' (There is an athlete "' || v_other || '": ids are case-sensitive.)' else '' end;
    end if;
    v_total := v_total + coalesce((v_counts ->> 'hab_intake')::bigint, 0);

    -- ── the receipt (a real run only) and the answer ───────────────────────────────────────────────────────────────────
    if not p_dry_run then
      insert into public.erasure_log (erased_by, kind, subject_hash, counts)
      values (auth.jwt() ->> 'email', v_kind,
              encode(sha256(convert_to(v_kind || ':' || lower(v_word), 'UTF8')), 'hex'),
              v_counts || jsonb_build_object('affiliates_unlinked', jsonb_array_length(v_unlinked)))
      returning id into v_log_id;
    end if;
    v_result := jsonb_build_object(
      'ok', true, 'dry_run', p_dry_run, 'kind', v_kind, 'key', v_key, 'shown_as', v_shown, 'confirm_word', v_word,
      'counts', v_counts, 'total', v_total, 'intake_candidates', v_cands, 'intake_erased', (v_counts ->> 'hab_intake')::bigint,
      'affiliates_unlinked', v_unlinked, 'log_id', v_log_id);
    if p_dry_run then
      raise exception using errcode = 'ZZ100', message = v_result::text;
    end if;
  exception when sqlstate 'ZZ100' then
    return sqlerrm::jsonb;       -- the dry run: every change above has been undone, only the counts come back
  end;
  return v_result;
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_from_amir(p_athlete_id text, p_day date, p_line text, p_award_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_line text := btrim(regexp_replace(coalesce(p_line, ''), '\s+', ' ', 'g'));
  r public.career_notes;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if p_day is null or p_day not between current_date - 1 and current_date + 1 then raise exception 'from_amir: % is not today', p_day; end if;
  if not exists (select 1 from public.programs where athlete_id = p_athlete_id) then raise exception 'no such athlete: %', p_athlete_id; end if;
  if v_line = '' then
    delete from public.career_notes where athlete_id = p_athlete_id and day = p_day and read_at is null;
    if not found and exists (select 1 from public.career_notes where athlete_id = p_athlete_id and day = p_day) then
      raise exception 'they have read it already: it stays';
    end if;
    return null;
  end if;
  if not public.career_is_client(p_athlete_id) then raise exception 'not a client: the demo and a former athlete get no line'; end if;
  if v_line ~ '[[:cntrl:]]' then raise exception 'the line has a control character'; end if;
  if char_length(v_line) > 90 then raise exception 'one line is at most 90 characters (this one is %)', char_length(v_line); end if;
  if p_award_id is not null and not exists (select 1 from public.career_awards a where a.athlete_id = p_athlete_id and a.award_id = p_award_id) then
    raise exception 'that moment is not %''s', p_athlete_id;
  end if;
  insert into public.career_notes (athlete_id, day, line, award_id) values (p_athlete_id, p_day, v_line, p_award_id)
  on conflict (athlete_id, day) do nothing
  returning * into r;
  if r.athlete_id is null then raise exception 'one line a day: % already has one today (take it back first to change it)', p_athlete_id; end if;
  return to_jsonb(r);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_goal_done(p_athlete_id text, p_month date, p_done boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.career_goals;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  update public.career_goals set done_at = case when p_done then coalesce(done_at, now()) end, updated_at = now()
   where athlete_id = p_athlete_id and month = date_trunc('month', p_month)::date
  returning * into r;
  if r.athlete_id is null then raise exception 'no goal for % in %', p_athlete_id, to_char(p_month, 'FMMonth YYYY'); end if;
  return to_jsonb(r);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_hide_session(p_athlete_id text, p_day integer, p_completed_on date, p_hide boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_hide boolean := coalesce(p_hide, true); v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' or p_day is null or p_completed_on is null then
    raise exception 'which session?';
  end if;
  with u as (
    update public.session_history s
       set hidden_at = case when v_hide then now() end,
           hidden_by = case when v_hide then auth.jwt() ->> 'email' end
     where s.athlete_id = p_athlete_id and s.day = p_day and s.completed_on = p_completed_on
       and (s.hidden_at is null) = v_hide
    returning 1)
  select count(*) into v_n from u;
  return jsonb_build_object('changed', v_n, 'hidden', v_hide);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_honour_confirm(p_month date, p_honour text, p_athlete_ids text[], p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  v_ids text[]; v_have text[]; v_id text; v_fig jsonb; v_done jsonb;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if p_honour not in ('sessions', 'improved', 'full_month') then
    raise exception 'coach_honour_confirm: % is not sessions, improved or full_month (your Pick is chosen with coach_honours_pick)', p_honour;
  end if;
  if not public.career_honours_open(m0) then raise exception 'coach_honour_confirm: % has not ended yet', to_char(m0, 'FMMonth YYYY'); end if;
  if current_date >= (m0 + interval '2 months')::date then raise exception '% can no longer be confirmed', to_char(m0, 'FMMonth YYYY'); end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v_ids from unnest(coalesce(p_athlete_ids, '{}')) x where x is not null and btrim(x) <> '';
  perform public.coach_honours_freeze(m0, p_not_clients);
  perform pg_advisory_xact_lock(hashtext('career:honours:' || m0));
  select coalesce(array_agg(h.athlete_id order by h.athlete_id), '{}') into v_have from public.career_honours h where h.month = m0 and h.honour = p_honour;
  if (select jsonb_exists(confirmed, p_honour) from public.career_honour_months where month = m0) then
    if v_have = v_ids then return public.coach_honours(m0, p_not_clients); end if;
    raise exception 'Your % % is already confirmed', to_char(m0, 'FMMonth YYYY'), p_honour;
  end if;
  foreach v_id in array v_ids loop
    if not exists (select 1 from public.programs where athlete_id = v_id) then raise exception 'no such athlete: %', v_id; end if;
    if not public.career_is_client(v_id, p_not_clients) then
      raise exception 'not a client: the demo, a former athlete and your own login are never honoured';
    end if;
    v_fig := public.career_honour_figure(m0, p_honour, v_id);
    if v_fig is null then
      raise exception 'that athlete has no % in %, so it cannot be honoured', case p_honour when 'sessions' then 'plan session' when 'improved' then 'main-lift win' else 'training week' end, to_char(m0, 'FMMonth YYYY');
    end if;
    insert into public.career_honours as h (month, honour, athlete_id, value, confirmed_at) values (m0, p_honour, v_id, v_fig, now())
    on conflict (month, honour, athlete_id) do update set value = excluded.value, confirmed_at = coalesce(h.confirmed_at, excluded.confirmed_at);
  end loop;
  delete from public.career_honours where month = m0 and honour = p_honour and not (athlete_id = any (v_ids));
  v_done := jsonb_build_object(p_honour, now());
  update public.career_honour_months set confirmed = confirmed || v_done where month = m0;
  return public.coach_honours(m0, p_not_clients);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_honours(p_month date, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  v_m public.career_honour_months;
  v_live jsonb;
  v_rows jsonb;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if not public.career_honours_open(m0) then raise exception 'coach_honours: % has not ended yet', to_char(m0, 'FMMonth YYYY'); end if;
  select * into v_m from public.career_honour_months where month = m0;
  select coalesce(jsonb_agg(jsonb_build_object('honour', h.honour, 'athlete_id', h.athlete_id, 'value', h.value, 'sent_at', h.sent_at, 'confirmed_at', h.confirmed_at)
                            order by h.honour, h.athlete_id), '[]'::jsonb)
    into v_rows from public.career_honours h where h.month = m0;
  if v_m.month is null or v_m.pick is null or not (coalesce(v_m.confirmed, '{}'::jsonb) ?& array['sessions', 'improved', 'full_month']) then v_live := public.career_honours_live(m0, p_not_clients); end if;
  return jsonb_build_object(
    'month', m0, 'frozen', v_m.month is not null, 'frozen_at', v_m.frozen_at, 'pick', v_m.pick, 'pick_at', v_m.pick_at,
    'pick_open', current_date < (m0 + interval '2 months')::date,
    'rows', v_rows, 'confirmed', coalesce(v_m.confirmed, '{}'::jsonb), 'ended', current_date >= (m0 + interval '1 month')::date,
    'live', v_live,
    'shortlist', case when v_m.pick is null then v_live -> 'shortlist' end);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_honours_freeze(p_month date, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  v jsonb;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if not public.career_honours_open(m0) then raise exception 'coach_honours_freeze: % has not ended yet', to_char(m0, 'FMMonth YYYY'); end if;
  perform pg_advisory_xact_lock(hashtext('career:honours:' || m0));
  if exists (select 1 from public.career_honour_months where month = m0) then return public.coach_honours(m0, p_not_clients); end if;
  v := public.career_honours_live(m0, p_not_clients);
  insert into public.career_honour_months (month) values (m0);
  insert into public.career_honours (month, honour, athlete_id, value)
    select m0, 'sessions', x, jsonb_build_object('n', (v -> 'sessions' ->> 'n')::int) from jsonb_array_elements_text(v -> 'sessions' -> 'who') x
    union all
    select m0, 'improved', e ->> 'athlete_id', jsonb_build_object('lift', e ->> 'lift', 'pct', (e ->> 'pct')::numeric) from jsonb_array_elements(v -> 'improved' -> 'who') e
    union all
    select m0, 'full_month', e ->> 'athlete_id', jsonb_build_object('weeks', (e ->> 'weeks')::int) from jsonb_array_elements(v -> 'full_month' -> 'who') e
    union all
    select m0, 'near', e ->> 'athlete_id', jsonb_build_object('held', (e ->> 'held')::int, 'weeks', (e ->> 'weeks')::int) from jsonb_array_elements(v -> 'full_month' -> 'near') e;
  return public.coach_honours(m0, p_not_clients);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_honours_pick(p_month date, p_athlete_id text, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  v_live jsonb; v_slot jsonb;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if current_date >= (m0 + interval '2 months')::date then raise exception '% can no longer be picked', to_char(m0, 'FMMonth YYYY'); end if;
  perform public.coach_honours_freeze(m0, p_not_clients);
  perform pg_advisory_xact_lock(hashtext('career:honours:' || m0));
  if (select pick from public.career_honour_months where month = m0) is not null then
    raise exception 'Your % pick is already decided', to_char(m0, 'FMMonth YYYY');
  end if;
  if p_athlete_id is null then
    update public.career_honour_months set pick = 'nobody', pick_at = now() where month = m0;
    return public.coach_honours(m0, p_not_clients);
  end if;
  if not exists (select 1 from public.programs where athlete_id = p_athlete_id) then raise exception 'no such athlete: %', p_athlete_id; end if;
  if not public.career_is_client(p_athlete_id, p_not_clients) then
    raise exception 'not a client: the demo, a former athlete and your own login are never picked';
  end if;
  v_live := public.career_honours_live(m0, p_not_clients);
  select e into v_slot from jsonb_array_elements(coalesce(v_live -> 'shortlist', '[]'::jsonb)) e where e ->> 'athlete_id' = p_athlete_id limit 1;
  insert into public.career_honours (month, honour, athlete_id, value, confirmed_at) values (m0, 'pick', p_athlete_id, coalesce(v_slot, '{}'::jsonb), now());
  update public.career_honour_months set pick = 'picked', pick_at = now() where month = m0;
  return public.coach_honours(m0, p_not_clients);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_honours_sent(p_month date, p_honour text, p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  update public.career_honours set sent_at = coalesce(sent_at, now())
   where month = date_trunc('month', p_month)::date and honour = p_honour and athlete_id = p_athlete_id;
  get diagnostics v_n = row_count;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.coach_honours_why(p_month date, p_why text, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage100: Amir's reason for his pick of the month, in his words, read by the crew on the Pick card and kept on the athlete's page.
-- Empty clears it. 140 characters at most (the card is small: Amir, 2026-10-25, "make the card a bit smaller").
declare
  m0 date := date_trunc('month', p_month)::date;
  v_why text := nullif(btrim(coalesce(p_why, '')), '');
  v_n int;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if v_why is not null and char_length(v_why) > 140 then
    raise exception 'The reason is % characters. Keep it to 140.', char_length(v_why);
  end if;
  update public.career_honours
     set value = case when v_why is null then coalesce(value, '{}'::jsonb) - 'why'
                      else coalesce(value, '{}'::jsonb) || jsonb_build_object('why', v_why) end
   where month = m0 and honour = 'pick';
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'There is no pick for % yet. Pick first, then write why.', to_char(m0, 'FMMonth YYYY'); end if;
  return public.coach_honours(m0, p_not_clients);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_login_use()
 RETURNS TABLE(app text, key text, signed_in_since boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
    select 'athlete'::text, ai.athlete_id, coalesce(u.last_sign_in_at > ai.password_set_at, false)
      from public.athlete_identities ai join auth.users u on u.id = ai.user_id
     where ai.initial_password is not null
    union all
    select 'course'::text, t.username, coalesce(u.last_sign_in_at > t.password_set_at, false)
      from public.tps_accounts t join auth.users u on u.id = t.user_id
     where t.initial_password is not null
    union all
    select 'testing'::text, a.username, coalesce(u.last_sign_in_at > a.password_set_at, false)
      from public.assess_accounts a join auth.users u on u.id = a.user_id
     where a.initial_password is not null;
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_note_id()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select '__coach__'::text $function$;

CREATE OR REPLACE FUNCTION public.coach_open()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o record; v_rows jsonb; v_past jsonb; v_crew jsonb;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  select * into o from public.crew_open where closed_at is null order by created_at desc limit 1;

  if found then
    with mem as (select * from public.crew_members())
    select coalesce(jsonb_agg(jsonb_build_object('athlete_id', res.athlete_id, 'who', coalesce(m.name, res.athlete_id),
                                                 'in_crew', m.athlete_id is not null, 'value', res.value, 'day', res.day)
                              order by case when o.better = 'low' then res.value else -res.value end, res.athlete_id), '[]'::jsonb)
      into v_rows
      from public.crew_open_results res left join mem m on m.athlete_id = res.athlete_id
     where res.open_id = o.id;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'title', p.title, 'unit', p.unit, 'opened_on', p.opened_on,
                                               'closed_at', p.closed_at, 'n', (select count(*) from public.crew_open_results x where x.open_id = p.id))
                            order by p.closed_at desc), '[]'::jsonb)
    into v_past
    from (select * from public.crew_open where closed_at is not null order by closed_at desc limit 5) p;

  select coalesce(jsonb_agg(jsonb_build_object('athlete_id', m.athlete_id, 'who', m.name) order by m.name), '[]'::jsonb)
    into v_crew from public.crew_members() m;

  return jsonb_build_object(
    'open', case when o.id is null then null else
      jsonb_build_object('id', o.id, 'title', o.title, 'how', o.how, 'unit', o.unit, 'better', o.better, 'opened_on', o.opened_on) end,
    'results', coalesce(v_rows, '[]'::jsonb), 'past', v_past, 'crew', v_crew, 'at', now());
end $function$;

CREATE OR REPLACE FUNCTION public.coach_open_close()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  update public.crew_open set closed_at = now() where closed_at is null;
  return public.coach_open();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_open_remove(p_athlete text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o record;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  select * into o from public.crew_open where closed_at is null order by created_at desc limit 1;
  if not found then raise exception 'no challenge is open'; end if;
  delete from public.crew_open_results where open_id = o.id and athlete_id = btrim(coalesce(p_athlete, ''));
  delete from public.crew_rings where kind = 'open' and ref = o.id::text and athlete_id = btrim(coalesce(p_athlete, ''));
  return public.coach_open();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_open_result(p_athlete text, p_value numeric, p_day date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o record; v_text text; v_rings boolean;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if nullif(btrim(coalesce(p_athlete, '')), '') is null then raise exception 'which athlete?'; end if;
  if p_value is null then raise exception 'what result?'; end if;
  if not exists (select 1 from public.programs p where p.athlete_id = btrim(p_athlete)) then
    raise exception 'no athlete "%"', btrim(p_athlete);
  end if;
  select * into o from public.crew_open where closed_at is null order by created_at desc limit 1;
  if not found then raise exception 'no challenge is open'; end if;

  insert into public.crew_open_results (open_id, athlete_id, value, day)
       values (o.id, btrim(p_athlete), p_value, coalesce(p_day, current_date))
  on conflict (open_id, athlete_id) do update set value = excluded.value, day = excluded.day, updated_at = now();

  v_text := 'posted ' || rtrim(btrim(to_char(p_value, 'FM999999990.99')), '.')
            || case when o.unit <> '' then ' ' || o.unit else '' end || ' in ' || o.title;
  select coalesce((m.kinds ->> 'open')::boolean, true)
    into v_rings from public.crew_members() m where m.athlete_id = btrim(p_athlete);
  if coalesce(v_rings, false) then
    insert into public.crew_rings (athlete_id, kind, ref, day, value)
         values (btrim(p_athlete), 'open', o.id::text, current_date, jsonb_build_object('text', v_text))
    on conflict (athlete_id, kind, ref) do update
      set value = excluded.value, day = excluded.day, created_at = now()
    where public.crew_rings.value is distinct from excluded.value;
  end if;
  return public.coach_open();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_open_set(p_title text, p_how text DEFAULT ''::text, p_unit text DEFAULT ''::text, p_better text DEFAULT 'high'::text, p_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_title text := btrim(coalesce(p_title, '')); v_better text := lower(btrim(coalesce(p_better, 'high')));
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if char_length(v_title) < 1 or char_length(v_title) > 60 then raise exception 'the challenge needs a name, up to 60 characters'; end if;
  if v_better not in ('high', 'low') then raise exception 'better is high or low, not %', v_better; end if;

  if p_id is not null then
    update public.crew_open set title = v_title, how = left(coalesce(p_how, ''), 400), unit = left(btrim(coalesce(p_unit, '')), 16), better = v_better
     where id = p_id and closed_at is null returning id into v_id;
    if v_id is null then raise exception 'no such challenge is open'; end if;
  else
    update public.crew_open set closed_at = now() where closed_at is null;
    insert into public.crew_open (title, how, unit, better)
         values (v_title, left(coalesce(p_how, ''), 400), left(btrim(coalesce(p_unit, '')), 16), v_better)
      returning id into v_id;
  end if;
  return public.coach_open();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_partner_code_make(p_athlete text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_a text := nullif(btrim(coalesce(p_athlete, '')), '');
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if v_a is null or v_a in ('demo', public.coach_note_id()) or not exists (select 1 from public.programs p where p.athlete_id = v_a) then raise exception 'partner:no_programme'; end if;
  if exists (select 1 from public.crew_consent c where c.athlete_id = v_a and c.under13) then raise exception 'partner:under13'; end if;
  if exists (select 1 from public.affiliates a where a.athlete_id = v_a and a.kind = 'athlete') then raise exception 'partner:has_code'; end if;
  return jsonb_build_object('code', public.partner_code_make(v_a));
end $function$;

CREATE OR REPLACE FUNCTION public.coach_partner_codes()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'code', a.code, 'athlete_id', a.athlete_id,
             'who', coalesce(nullif(btrim(concat_ws(' ', p.data -> 'athlete' ->> 'firstName', p.data -> 'athlete' ->> 'lastName')), ''), a.coach_name, a.athlete_id),
             'active', a.active,
             'uses', (select count(*) from public.hab_intake h
                       where h.status <> 'archived'
                         and (upper(regexp_replace(translate(coalesce(h.payload ->> 'Discount Code', ''), U&'\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9', '01234567890123456789'), '\s', '', 'g')) = a.code
                              or upper(regexp_replace(translate(split_part(btrim(coalesce(h.payload ->> 'Discount Applied', '')), ' ', 1), U&'\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9', '01234567890123456789'), '\s', '', 'g')) = a.code)),
             'credits', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'intake_id', r.intake_id, 'friend_name', r.friend_name, 'earned_on', r.earned_on, 'used_on', r.used_on, 'percent', r.percent)
                                                    order by r.earned_on desc, r.created_at desc)
                                    from public.referral_credits r where r.code = a.code), '[]'::jsonb)) order by a.code)
      from public.affiliates a left join public.programs p on p.athlete_id = a.athlete_id
     where a.kind = 'athlete'), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_partner_credit_add(p_code text, p_intake uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a record; i record; v_id uuid; v_name text;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  select x.* into a from public.affiliates x where x.code = upper(btrim(coalesce(p_code, ''))) and x.kind = 'athlete';
  if not found then raise exception 'partner:code'; end if;
  if a.athlete_id is null then raise exception 'partner:orphan'; end if;
  select h.* into i from public.hab_intake h where h.id = p_intake;
  if not found then raise exception 'partner:intake'; end if;
  if i.athlete_id is not null and i.athlete_id = a.athlete_id then raise exception 'partner:self'; end if;
  if exists (select 1 from public.referral_credits r where r.code = a.code and r.intake_id = p_intake) then raise exception 'partner:again'; end if;
  v_name := left(coalesce(nullif(btrim(i.name), ''), nullif(btrim(concat_ws(' ', i.payload ->> 'First Name', i.payload ->> 'Last Name')), '')), 80);
  insert into public.referral_credits (code, athlete_id, intake_id, friend_name, percent, note)
  values (a.code, a.athlete_id, p_intake, v_name, coalesce(a.reward_percent, 10), nullif(left(btrim(coalesce(p_note, '')), 200), ''))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'code', a.code, 'friend_name', v_name, 'percent', coalesce(a.reward_percent, 10), 'earned_on', current_date);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_partner_credit_used(p_id uuid, p_used boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if p_used is null then raise exception 'partner:used'; end if;
  update public.referral_credits set used_on = case when p_used then current_date end where id = p_id;
  return found;
end $function$;

CREATE OR REPLACE FUNCTION public.coach_question_answer(p_id bigint, p_answer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: Amir answers a Mailbag question for the crew: his pinned post (24 hours, 7 days on the Bell) with the question quoted, and the
-- answer kept on the question for the Answer Book. The asker is named by first name only if they said yes.
declare q public.crew_questions; v_a text := btrim(coalesce(p_answer, '')); v_by text; v_post uuid;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  select * into q from public.crew_questions where id = p_id for update;
  if q.id is null then raise exception 'That question is gone.'; end if;
  if q.answered_at is not null then raise exception 'That question is already answered.'; end if;
  if char_length(v_a) < 1 then raise exception 'Write the answer first.'; end if;
  if char_length(v_a) > 280 then raise exception 'The answer is % characters. Keep it to 280.', char_length(v_a); end if;
  if q.ok_name then
    v_by := nullif(split_part(btrim(coalesce((select c.name from public.crew_consent c where c.athlete_id = q.athlete_id),
                                             (select p.data -> 'athlete' ->> 'name' from public.programs p where p.athlete_id = q.athlete_id), '')), ' ', 1), '');
  end if;
  insert into public.crew_posts (athlete_id, kind, body, session, has_photo)
       values (public.coach_note_id(), 'post', v_a, jsonb_build_object('ask', jsonb_build_object('q', q.body, 'by', v_by)), false)
    returning id into v_post;
  update public.crew_questions set answer = v_a, answered_at = now(), answer_post = v_post where id = p_id;
  return public.coach_crew_weekly();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_question_drop(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: take a question off the Mailbag without answering it (the asker is not told).
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  delete from public.crew_questions where id = p_id and answered_at is null;
  return public.coach_crew_weekly();
end $function$;

CREATE OR REPLACE FUNCTION public.coach_save_spine(p_id text, p_entry jsonb, p_entry_snap jsonb, p_coach jsonb, p_coach_snap jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- The columns the editor owns. Anything else (id, updated_at, Claude's bookkeeping columns) is refused.
  -- stage64: steps (How to do it), and suggested_changes, so a Save that approves or discards Claude's drafts
  -- takes them off the list in the same transaction.
  c_entry text[] := array['name','aliases','pattern','qualities','purpose','tennis','cues','equipment','loads',
                          'easier','harder','alts','video','status','impact','muscles','steps','steps_fa','cues_fa','purpose_fa','tennis_fa'];
  c_coach text[] := array['sfr','flags','notes','credits','cost','suggested_changes'];
  -- SQL NULL and JSON null both mean "nothing for that half"; anything else that is not an object is refused below.
  v_entry   jsonb := coalesce(nullif(p_entry, 'null'::jsonb), '{}'::jsonb);
  v_coach   jsonb := coalesce(nullif(p_coach, 'null'::jsonb), '{}'::jsonb);
  v_esnap   jsonb := coalesce(nullif(p_entry_snap, 'null'::jsonb), '{}'::jsonb);
  v_csnap   jsonb := coalesce(nullif(p_coach_snap, 'null'::jsonb), '{}'::jsonb);
  v_live_e  jsonb;
  v_live_c  jsonb;
  v_clash_e text[];
  v_clash_c text[];
  v_k       text;
  v_set     text;
  v_cols    text;
  v_out_e   jsonb;
  v_out_c   jsonb;
  v_res     jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  -- A double-encoded or otherwise malformed payload must fail loudly: read as "{}" it came back ok:true having
  -- written nothing, and the page would have said Saved.
  if jsonb_typeof(v_entry) <> 'object' or jsonb_typeof(v_coach) <> 'object'
     or jsonb_typeof(v_esnap) <> 'object' or jsonb_typeof(v_csnap) <> 'object' then
    raise exception 'the entry, the coach-only part and their two snapshots must each be a JSON object';
  end if;

  for v_k in select jsonb_object_keys(v_entry) loop
    if not (v_k = any (c_entry)) then raise exception 'exercises.% cannot be written from the editor', v_k; end if;
  end loop;
  for v_k in select jsonb_object_keys(v_coach) loop
    if not (v_k = any (c_coach)) then raise exception 'exercise_coach.% cannot be written from the editor', v_k; end if;
  end loop;

  -- Lock the entry, then its coach-only row (always in this order). A concurrent writer is waited for,
  -- and READ COMMITTED hands back the row as it was committed.
  select to_jsonb(e) into v_live_e from public.exercises e where e.id = p_id for update;
  if v_live_e is null then
    raise exception 'this entry is no longer on the server (%). Refresh.', p_id;
  end if;
  select to_jsonb(c) into v_live_c from public.exercise_coach c where c.id = p_id for update;

  -- A column clashes when it differs from what the page read AND from what the coach is writing.
  select coalesce(array_agg(k order by k), '{}') into v_clash_e
    from jsonb_object_keys(v_entry) k
   where (v_live_e -> k) is distinct from coalesce(v_esnap -> k, 'null'::jsonb)
     and (v_live_e -> k) is distinct from (v_entry -> k);
  if v_live_c is null then
    -- No coach-only row yet. One that appeared since the page read is a clash on every column that
    -- differs from what is being written; a row that is still absent has nothing to clash with.
    v_clash_c := '{}';
  else
    select coalesce(array_agg(k order by k), '{}') into v_clash_c
      from jsonb_object_keys(v_coach) k
     where (v_live_c -> k) is distinct from coalesce(v_csnap -> k, 'null'::jsonb)
       and (v_live_c -> k) is distinct from (v_coach -> k);
  end if;
  if cardinality(v_clash_e) > 0 or cardinality(v_clash_c) > 0 then
    -- Nothing is written. Built key by key: jsonb_strip_nulls is recursive and would drop the live
    -- rows' own null columns, which the page needs to see.
    v_res := jsonb_build_object('ok', false);
    if cardinality(v_clash_e) > 0 then
      v_res := v_res || jsonb_build_object('entry', jsonb_build_object('cols', to_jsonb(v_clash_e), 'live', v_live_e));
    end if;
    if cardinality(v_clash_c) > 0 then
      v_res := v_res || jsonb_build_object('coach', jsonb_build_object('cols', to_jsonb(v_clash_c), 'live', v_live_c));
    end if;
    return v_res;
  end if;

  -- The entry half: only the columns sent, typed from the JSON by the table's own row type.
  if v_entry <> '{}'::jsonb then
    select string_agg(format('%I = r.%I', k, k), ', ') into v_set from jsonb_object_keys(v_entry) k;
    execute format('update public.exercises e set %s, updated_by = %L from jsonb_populate_record(null::public.exercises, $1) r where e.id = $2',
                   v_set, 'coach') using v_entry, p_id;
  end if;

  -- The coach-only half: update the row, or create it with only the columns sent (the rest take their defaults).
  if v_coach <> '{}'::jsonb then
    if v_live_c is null then
      select string_agg(format('%I', k), ', '), string_agg(format('r.%I', k), ', ')
        into v_cols, v_set from jsonb_object_keys(v_coach) k;
      execute format('insert into public.exercise_coach (id, %s) select $2, %s from jsonb_populate_record(null::public.exercise_coach, $1) r',
                     v_cols, v_set) using v_coach, p_id;
    else
      select string_agg(format('%I = r.%I', k, k), ', ') into v_set from jsonb_object_keys(v_coach) k;
      execute format('update public.exercise_coach c set %s from jsonb_populate_record(null::public.exercise_coach, $1) r where c.id = $2',
                     v_set) using v_coach, p_id;
    end if;
  end if;

  select to_jsonb(e) into v_out_e from public.exercises e where e.id = p_id;
  select to_jsonb(c) into v_out_c from public.exercise_coach c where c.id = p_id;
  return jsonb_build_object('ok', true,
    'entry', case when v_entry <> '{}'::jsonb then v_out_e end,
    'coach', case when v_coach <> '{}'::jsonb then v_out_c end);
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_season_levels(p_ids text[])
 RETURNS TABLE(athlete_id text, level integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if public.career_xp_on() then
    return query
      select x.id, coalesce((s.score #>> '{career,level}')::int, 1)
        from unnest(p_ids) as x(id)
        left join public.career_scores_for(p_ids, interval '3 seconds') s on s.athlete_id = x.id;
    return;
  end if;
  return query select x.id, public.hab_proof_level(x.id) from unnest(p_ids) as x(id);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_set_goal(p_athlete_id text, p_month date, p_line text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m0 date := date_trunc('month', p_month)::date;
  v_line text := btrim(regexp_replace(coalesce(p_line, ''), '\s+', ' ', 'g'));
  r public.career_goals;
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if not exists (select 1 from public.programs where athlete_id = p_athlete_id) then raise exception 'no such athlete: %', p_athlete_id; end if;
  if m0 < (date_trunc('month', current_date) - interval '1 month')::date or m0 > (date_trunc('month', current_date) + interval '1 month')::date then
    raise exception 'a goal is for last month, this month or next month (not %)', to_char(m0, 'FMMonth YYYY');
  end if;
  if v_line ~ '[[:cntrl:]]' then raise exception 'the goal has a control character'; end if;
  if v_line = '' then
    delete from public.career_goals where athlete_id = p_athlete_id and month = m0 and done_at is null;
    if found then return null; end if;
    if exists (select 1 from public.career_goals where athlete_id = p_athlete_id and month = m0) then
      raise exception 'that goal is ticked done: untick it first to clear it';
    end if;
    return null;
  end if;
  if char_length(v_line) > 140 then raise exception 'a goal is at most 140 characters (this one is %)', char_length(v_line); end if;
  insert into public.career_goals as g (athlete_id, month, line) values (p_athlete_id, m0, v_line)
  on conflict (athlete_id, month) do update set line = excluded.line, updated_at = now()
  returning * into r;
  return to_jsonb(r);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_set_status(p_athlete_id text, p_status text, p_since date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_note text := nullif(btrim(coalesce(p_note, '')), ''); v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' then
    raise exception 'which athlete?';
  end if;
  if p_status is null or p_status not in ('active', 'paused', 'former') then
    raise exception 'bad status: %', p_status;
  end if;
  if lower(p_athlete_id) in ('demo', 'amir_ardekani') then
    raise exception '"%" is the public demo or your own identity: it has no status', p_athlete_id;
  end if;
  if not exists (select 1 from public.programs p where p.athlete_id = p_athlete_id)
     and not exists (select 1 from public.hab_contacts c where c.athlete_id = p_athlete_id)
     and not exists (select 1 from public.athlete_progress a where a.athlete_id = p_athlete_id) then
    raise exception 'there is no athlete called "%"', p_athlete_id;
  end if;
  if p_status = 'active' then
    with d as (delete from public.athlete_status where athlete_id = p_athlete_id returning 1)
      select count(*) into v_n from d;
  else
    insert into public.athlete_status as s (athlete_id, status, since, note)
    values (p_athlete_id, p_status, coalesce(p_since, current_date), v_note)
    on conflict (athlete_id) do update
      set status     = excluded.status,
          since      = coalesce(p_since, case when s.status = excluded.status then s.since else current_date end),
          note       = excluded.note,
          updated_at = now();
  end if;
  return jsonb_build_object('athlete_id', p_athlete_id, 'status', p_status);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_set_whatsapp(p_athlete_id text, p_whatsapp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_wa text := nullif(btrim(coalesce(p_whatsapp, '')), ''); v_tier text; v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' then
    raise exception 'which athlete?';
  end if;
  if v_wa is not null and length(v_wa) > 40 then
    raise exception 'that is too long for a phone number';
  end if;
  if not exists (select 1 from public.programs p where p.athlete_id = p_athlete_id)
     and not exists (select 1 from public.hab_contacts c where c.athlete_id = p_athlete_id) then
    raise exception 'there is no athlete called "%"', p_athlete_id;
  end if;
  update public.hab_contacts c set whatsapp = v_wa, updated_at = now() where c.athlete_id = p_athlete_id;
  get diagnostics v_n = row_count;
  if v_n = 0 and v_wa is not null then
    select case when p.data -> 'athlete' ->> 'tier' = 'free' then 'free' else 'coached' end
      into v_tier from public.programs p where p.athlete_id = p_athlete_id;
    insert into public.hab_contacts (athlete_id, whatsapp, source, tier)
    values (p_athlete_id, v_wa, 'coach', coalesce(v_tier, 'coached'));
  end if;
  return jsonb_build_object('athlete_id', p_athlete_id, 'whatsapp', v_wa);
end $function$;

CREATE OR REPLACE FUNCTION public.coaching_logs_keep_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.body is distinct from new.body then
    insert into public.coaching_log_versions (athlete_id, body, was_updated_at)
    values (old.athlete_id, old.body, old.updated_at);
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.coaching_logs_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.contact_list()
 RETURNS TABLE(athlete_id text, email text, whatsapp text, source text, tier text, shown_as text, on_board boolean, days_logged integer, signed_up timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
  select c.athlete_id, c.email, c.whatsapp, c.source, c.tier,
         coalesce(o.display_name, c.display_name),
         (o.athlete_id is not null),
         coalesce((
           select count(*)::int
           from jsonb_each(public.hab_log_of(ap.data, c.athlete_id)) d
           where jsonb_typeof(d.value) = 'object' and d.value <> '{}'::jsonb
         ), 0),
         c.created_at
  from public.hab_contacts c
  left join public.leaderboard_optin o on o.athlete_id = c.athlete_id
  left join public.athlete_progress  ap on ap.athlete_id = c.athlete_id
  order by c.created_at desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.crew_answer(p_answer text, p_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who(); v_ans text := lower(btrim(coalesce(p_answer, ''))); v_name text := left(public.crew_clean(p_name), 24);
begin
  if v_ans not in ('yes', 'no') then raise exception 'crew:answer'; end if;
  insert into public.crew_consent as c (athlete_id, answer, name, answered_at, first_yes_at, yes_since, updated_at)
  values (v_me, v_ans, nullif(v_name, ''), now(), case when v_ans = 'yes' then now() end, case when v_ans = 'yes' then now() end, now())
  on conflict (athlete_id) do update
     set answer = excluded.answer,
         name = coalesce(excluded.name, c.name),
         answered_at = now(),
         first_yes_at = coalesce(c.first_yes_at, excluded.first_yes_at),
         yes_since = case when excluded.answer = 'yes' then case when c.answer = 'yes' then c.yes_since else now() end else null end,
         updated_at = now();
  if v_ans = 'no' then
    delete from public.crew_posts where athlete_id = v_me;
    delete from public.crew_kudos where athlete_id = v_me;
    delete from public.crew_rings where athlete_id = v_me;
    perform public.crew_forget(v_me);   -- stage96: the face, the cheers, the signatures and the mentions, both ways
  end if;
  return public.crew_me(v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_ask(p_body text, p_ok_name boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: a question to Amir for the Mailbag. Private: only Amir reads it, and the crew sees it only if he answers it, with the first name
-- only when ok_name. Any athlete with a programme can ask (crew member or not); three a day.
declare v_me text := public.current_athlete_id(); v_body text := btrim(coalesce(p_body, '')); v_id bigint;
begin
  if v_me is null then raise exception 'crew:who'; end if;
  if not exists (select 1 from public.programs p where p.athlete_id = v_me) then raise exception 'crew:who'; end if;
  if char_length(v_body) < 1 then raise exception 'crew:empty'; end if;
  if char_length(v_body) > 200 then raise exception 'crew:too_long'; end if;
  if (select count(*) from public.crew_questions q where q.athlete_id = v_me and q.created_at > now() - interval '1 day') >= 3 then
    raise exception 'crew:enough';
  end if;
  insert into public.crew_questions (athlete_id, body, ok_name) values (v_me, v_body, coalesce(p_ok_name, false)) returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_board(p_limit integer DEFAULT 25)
 RETURNS TABLE(pos integer, who text, points bigint, level integer, is_me boolean, ck uuid, fv bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage96: ck and fv
declare
  v_me text := public.current_athlete_id();
  v_coach boolean := public.is_coach();
  v_report boolean := coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role');
begin
  if v_me is null and not (v_coach or v_report) then
    raise exception 'not signed in';
  end if;
  return query
  with mem as (select * from public.crew_members()),
  sc as (
    select s.athlete_id as aid, s.score
      from public.career_scores_for((select array_agg(m.athlete_id) from mem m), interval '2.5 seconds') s
  ),
  scored as (
    select m.athlete_id as aid, m.name, m.crew_key as ckey,
           coalesce((sc.score #>> '{season,points}')::bigint, 0) as x,
           coalesce((sc.score #>> '{career,level}')::int, 1) as lv
      from mem m left join sc on sc.aid = m.athlete_id
  ),
  ranked as (
    select row_number() over (order by s.x desc, lower(s.name) asc) as rn, s.*
      from scored s
  )
  select r.rn::int, r.name, r.x, r.lv, (r.aid is not distinct from v_me), r.ckey, public.crew_face_v(r.aid)
    from ranked r
   where r.rn <= greatest(1, p_limit) or r.aid is not distinct from v_me
   order by r.rn;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_cheer(p_subject uuid, p_word text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.crew_who(); v_to text; v_word text; v_day date := (now() at time zone 'UTC')::date;
begin
  if exists (select 1 from public.crew_consent c where c.athlete_id = v_me and c.under13) then raise exception 'crew:under13'; end if;
  if not exists (select 1 from public.crew_members() m where m.athlete_id = v_me) then raise exception 'crew:not_yes'; end if;
  select m.athlete_id into v_to from public.crew_members() m where m.crew_key = p_subject;
  if v_to is null then raise exception 'crew:gone'; end if;
  if v_to = v_me then raise exception 'crew:own'; end if;
  v_word := nullif(regexp_replace(public.crew_clean(p_word), '\s+', ' ', 'g'), '');
  if v_word is not null and char_length(v_word) > 100 then raise exception 'crew:word_long'; end if;
  -- the caps under one lock, so two taps cannot both pass
  perform pg_advisory_xact_lock(hashtext('crew_cheer:' || v_me));
  if exists (select 1 from public.crew_cheers x where x.athlete_id = v_me and x.to_athlete = v_to and x.day = v_day) then raise exception 'crew:cheer_today'; end if;
  if (select count(*) from public.crew_cheers x where x.athlete_id = v_me and x.day = v_day) >= 30 then raise exception 'crew:cheers_today'; end if;
  insert into public.crew_cheers (athlete_id, to_athlete, day, word) values (v_me, v_to, v_day, v_word);
  return jsonb_build_object('ok', true, 'season', public.crew_cheer_count(v_to));
end $function$;

CREATE OR REPLACE FUNCTION public.crew_cheer_count(p_athlete text)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select count(*)::int from public.crew_cheers c
   where c.to_athlete = p_athlete and c.day >= public.crew_season_start(p_athlete)
     and (c.athlete_id = public.coach_note_id() or exists (select 1 from public.crew_members() m where m.athlete_id = c.athlete_id))
$function$;

CREATE OR REPLACE FUNCTION public.crew_clean(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select btrim(regexp_replace(
           regexp_replace(replace(coalesce(p, ''), chr(9), ' '), E'[\\x01-\\x08\\x0b-\\x1f\\x7f\\u200b\\u200e\\u200f\\u202a-\\u202e\\u2066-\\u2069\\ufeff]', '', 'g'),
           E'\\n{3,}', E'\n\n', 'g'))
$function$;

CREATE OR REPLACE FUNCTION public.crew_default_name(p_athlete text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select left(coalesce(nullif(btrim(concat_ws(' ', nullif(btrim(p.data -> 'athlete' ->> 'firstName'), ''),
                                              upper(left(nullif(btrim(p.data -> 'athlete' ->> 'lastName'), ''), 1)) || '.')), ''), 'Athlete'), 24)
    from public.programs p where p.athlete_id = p_athlete
$function$;

CREATE OR REPLACE FUNCTION public.crew_delete_post(p_post uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.current_athlete_id();
begin
  if v_me is null and not public.is_coach() then raise exception 'crew:signin'; end if;
  delete from public.crew_posts p where p.id = p_post and (p.athlete_id = v_me or public.is_coach());
  return found;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_emoji_list()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array['🔥', '💪', '👏', '😍']::text[]
$function$;

CREATE OR REPLACE FUNCTION public.crew_extra(p_athlete text, p_kinds jsonb, p_yes timestamp with time zone, p_first timestamp with time zone, p_viewer text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_strip_nulls(jsonb_build_object(
           'lv', case when p_athlete is not distinct from p_viewer or coalesce((p_kinds ->> 'level')::boolean, true) then public.crew_lv(p_athlete) end,
           'held', case when p_athlete is not distinct from p_viewer then (case when public.crew_held_now(p_athlete, null) then true end)
                        when coalesce((p_kinds ->> 'week')::boolean, true) then (case when public.crew_held_now(p_athlete, (p_yes at time zone 'UTC')::date) then true end) end,
           'new', case when p_first >= now() - interval '7 days' then true end)), '{}'::jsonb)
$function$;

CREATE OR REPLACE FUNCTION public.crew_face_clear()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who();
begin
  delete from public.crew_faces where athlete_id = v_me;
  return jsonb_build_object('fv', null);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_face_set(p_photo text, p_w integer, p_h integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who(); v_bytes bytea; v_t timestamptz;
begin
  if exists (select 1 from public.crew_consent c where c.athlete_id = v_me and c.under13) then raise exception 'crew:under13'; end if;
  if not exists (select 1 from public.crew_members() m where m.athlete_id = v_me) then raise exception 'crew:not_yes'; end if;
  if nullif(btrim(coalesce(p_photo, '')), '') is null then raise exception 'crew:photo_bad'; end if;
  begin
    v_bytes := decode(regexp_replace(regexp_replace(p_photo, '^data:[^,]*,', ''), '\s', '', 'g'), 'base64');
  exception when others then
    raise exception 'crew:photo_bad';
  end;
  if octet_length(v_bytes) > 60000 then raise exception 'crew:photo_big'; end if;
  if octet_length(v_bytes) < 100 or substring(v_bytes from 1 for 3) <> '\xffd8ff'::bytea then raise exception 'crew:photo_bad'; end if;
  if p_w is null or p_h is null or p_w not between 64 and 512 or p_h not between 64 and 512 then raise exception 'crew:photo_bad'; end if;
  -- a new picture always gets a new version (at least a second after the old one), because the version is the phone's cache key
  insert into public.crew_faces as f (athlete_id, w, h, bytes) values (v_me, p_w, p_h, v_bytes)
  on conflict (athlete_id) do update
     set w = excluded.w, h = excluded.h, bytes = excluded.bytes, updated_at = greatest(now(), f.updated_at + interval '1 second')
  returning f.updated_at into v_t;
  return jsonb_build_object('fv', extract(epoch from v_t)::bigint);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_face_v(p_athlete text)
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select extract(epoch from f.updated_at)::bigint from public.crew_faces f where f.athlete_id = p_athlete
$function$;

CREATE OR REPLACE FUNCTION public.crew_faces_get(p_keys uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.current_athlete_id();
begin
  if v_me is null and not public.is_coach() then raise exception 'not signed in'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('ck', k.ck, 'fv', extract(epoch from f.updated_at)::bigint, 'b64', replace(encode(f.bytes, 'base64'), E'\n', '')))
      from (select distinct x.ck from unnest((coalesce(p_keys, '{}'::uuid[]))[1:12]) x(ck)) k
      join public.crew_consent cc on cc.crew_key = k.ck
      join public.crew_faces f on f.athlete_id = cc.athlete_id
     where cc.athlete_id = v_me or exists (select 1 from public.crew_members() m where m.athlete_id = cc.athlete_id)), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_forget(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.crew_faces where athlete_id = p_athlete;
  delete from public.crew_cheers where athlete_id = p_athlete or to_athlete = p_athlete;
  delete from public.crew_award_likes where athlete_id = p_athlete or to_athlete = p_athlete;
  delete from public.crew_mentions where athlete_id = p_athlete or to_athlete = p_athlete;
  delete from public.crew_cheer_tally where athlete_id = p_athlete;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_game_of(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_strip_nulls(jsonb_build_object(
           'sports', to_jsonb(g.sports), 'hand', g.hand, 'backhand', g.backhand, 'side', g.side, 'plays_at', g.plays_at,
           'club', g.club, 'training_for', to_jsonb(g.training_for), 'working_on', g.working_on, 'ig', g.ig))
    from public.athlete_profile g where g.athlete_id = p_athlete
$function$;

CREATE OR REPLACE FUNCTION public.crew_held_now(p_athlete text, p_since date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.crew_now_week(p_athlete) w
      join public.career_facts f on f.athlete_id = p_athlete and f.kind = 'week_held' and f.void_at is null
                                and f.ref = 'c' || w.cycle_num || '|w' || w.week
                                and f.day >= coalesce(p_since, f.day))
$function$;

CREATE OR REPLACE FUNCTION public.crew_kind_list()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array['session', 'level', 'week', 'mark', 'achievement', 'best', 'cycle', 'honour', 'open']::text[]
$function$;

CREATE OR REPLACE FUNCTION public.crew_kinds(p_kinds jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who(); v_k jsonb;
begin
  if p_kinds is null or jsonb_typeof(p_kinds) <> 'object' then raise exception 'crew:kinds'; end if;
  select coalesce(jsonb_object_agg(k.key, k.value), '{}'::jsonb) into v_k
    from jsonb_each(p_kinds) k where k.key = any (public.crew_kind_list()) and jsonb_typeof(k.value) = 'boolean';
  update public.crew_consent c set kinds = c.kinds || v_k, updated_at = now() where c.athlete_id = v_me;
  if not found then raise exception 'crew:not_asked'; end if;
  return public.crew_me(v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_kudos(p_target text, p_on boolean DEFAULT true, p_emoji text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.crew_who(); v_t text := btrim(coalesce(p_target, '')); v_post uuid; v_to text; v_day date; v_author text;
  v_em text := nullif(btrim(coalesce(p_emoji, '')), '');
begin
  if not exists (select 1 from public.crew_members() m where m.athlete_id = v_me) then raise exception 'crew:not_yes'; end if;
  if v_em is not null and not (v_em = any (public.crew_emoji_list())) then raise exception 'crew:emoji'; end if;
  if v_t ~ '^[0-9a-f-]{36}$' then
    v_post := v_t::uuid;
    select p.athlete_id into v_author from public.crew_posts p
     where p.id = v_post and p.created_at >= now() - interval '7 days'
       and (p.athlete_id = public.coach_note_id() or exists (select 1 from public.crew_members() m where m.athlete_id = p.athlete_id));
    if v_author is null then raise exception 'crew:gone'; end if;
    if v_author = v_me then raise exception 'crew:own'; end if;
    if p_on then
      insert into public.crew_kudos (athlete_id, post_id, emoji) values (v_me, v_post, v_em)
      on conflict (athlete_id, post_id) where post_id is not null
      do update set emoji = excluded.emoji, created_at = now();
    else
      delete from public.crew_kudos k where k.athlete_id = v_me and k.post_id = v_post;
      -- stage98: a like is not a cheer. Taking one back leaves the cheer tally alone (stage96 took one off it here).
    end if;
    return public.crew_kudos_of(v_post, null, null, v_me);
  end if;
  if v_t !~ '^[0-9a-f-]{36}:\d{4}-\d{2}-\d{2}$' then raise exception 'crew:target'; end if;
  begin
    v_day := split_part(v_t, ':', 2)::date;
  exception when others then raise exception 'crew:target';
  end;
  select m.athlete_id into v_to from public.crew_members() m where m.crew_key = split_part(v_t, ':', 1)::uuid;
  if v_to is null or v_day < current_date - 7 or v_day > current_date + 1 then raise exception 'crew:gone'; end if;
  if v_to = v_me then raise exception 'crew:own'; end if;
  if p_on then
    insert into public.crew_kudos (athlete_id, to_athlete, line_day, emoji) values (v_me, v_to, v_day, v_em)
    on conflict (athlete_id, to_athlete, line_day) where to_athlete is not null
    do update set emoji = excluded.emoji, created_at = now();
    -- stage96: the like signs the live achievements of that person's day (Signed Ball). Kept past the 7-day sweep, removed when the like is taken back.
    insert into public.crew_award_likes (athlete_id, to_athlete, award_id)
    select v_me, v_to, a.award_id from public.career_awards a
     where a.athlete_id = v_to and a.kind = 'achievement' and a.how = 'live' and (a.created_at at time zone 'UTC')::date = v_day
    on conflict do nothing;
  else
    delete from public.crew_kudos k where k.athlete_id = v_me and k.to_athlete = v_to and k.line_day = v_day;
    delete from public.crew_award_likes l
     where l.athlete_id = v_me and l.to_athlete = v_to
       and l.award_id in (select a.award_id from public.career_awards a
                           where a.athlete_id = v_to and a.kind = 'achievement' and a.how = 'live' and (a.created_at at time zone 'UTC')::date = v_day);
  end if;
  return public.crew_kudos_of(null, v_to, v_day, v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_kudos_of(p_post uuid, p_to text, p_day date, p_viewer text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with k as (
    select k.athlete_id, m.name, k.created_at, k.emoji
      from public.crew_kudos k join public.crew_members() m on m.athlete_id = k.athlete_id
     where (p_post is not null and k.post_id = p_post) or (p_post is null and k.to_athlete = p_to and k.line_day = p_day)
  )
  select jsonb_build_object(
    'n', (select count(*) from k),
    'mine', exists (select 1 from k where k.athlete_id is not distinct from p_viewer),
    'emoji', (select k.emoji from k where k.athlete_id is not distinct from p_viewer and p_viewer is not null limit 1),
    'like', (select count(*) from k where k.emoji is null),
    'by', coalesce((select jsonb_object_agg(x.emoji, x.c) from (select k.emoji, count(*) as c from k where k.emoji is not null group by k.emoji) x), '{}'::jsonb),
    'names', coalesce((select jsonb_agg(x.name order by x.created_at desc)
                         from (select k.name, k.created_at from k where k.athlete_id is distinct from p_viewer order by k.created_at desc limit 3) x), '[]'::jsonb))
$function$;

CREATE OR REPLACE FUNCTION public.crew_level_ring()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old integer; v_new integer;
begin
  begin
    if coalesce(current_setting('crew.quiet', true), '') = 'on' then return null; end if;
    v_old := nullif(old.score #>> '{career,level}', '')::integer;
    v_new := nullif(new.score #>> '{career,level}', '')::integer;
    if v_new is not null and v_old is not null and v_new > v_old
       and exists (select 1 from public.crew_consent c where c.athlete_id = new.athlete_id and c.answer = 'yes' and not c.under13) then
      insert into public.crew_rings (athlete_id, kind, ref, value)
      values (new.athlete_id, 'level', v_new::text, jsonb_build_object('n', v_new))
      on conflict do nothing;
    end if;
  exception when others then
    raise warning 'crew: the level ring of % was not written: % (%)', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_lv(p_athlete text)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when (s.score #>> '{career,level}') ~ '^\d{1,4}$' then (s.score #>> '{career,level}')::int end
    from public.career_scores s where s.athlete_id = p_athlete
$function$;

CREATE OR REPLACE FUNCTION public.crew_me(p_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- stage96: ck and fv
  select case when p_id is null then null else jsonb_build_object(
    'answer', c.answer,
    'kinds', (select jsonb_object_agg(k.kind, coalesce((c.kinds ->> k.kind)::boolean, true)) from unnest(public.crew_kind_list()) k(kind)),
    'name', coalesce((select nullif(btrim(o.display_name), '') from public.leaderboard_optin o where o.athlete_id = p_id), c.name, public.crew_default_name(p_id)),
    'on_board', exists (select 1 from public.leaderboard_optin o where o.athlete_id = p_id),
    'under13', coalesce(c.under13, false),
    'can_post', coalesce(c.answer = 'yes' and not c.under13, false) and p_id <> 'demo'
                and not exists (select 1 from public.athlete_status s where s.athlete_id = p_id and s.status = 'former'),
    'photos_left', greatest(0, 3 - (select count(*) from public.crew_photos ph where ph.athlete_id = p_id and ph.created_at >= date_trunc('day', now()))),
    'posts_left', greatest(0, 10 - (select count(*) from public.crew_posts cp where cp.athlete_id = p_id and cp.created_at >= date_trunc('day', now()))),
    'ck', c.crew_key,
    'fv', public.crew_face_v(p_id))
  end
  from (select 1) one left join public.crew_consent c on c.athlete_id = p_id
$function$;

CREATE OR REPLACE FUNCTION public.crew_members()
 RETURNS TABLE(athlete_id text, name text, crew_key uuid, kinds jsonb, yes_since timestamp with time zone, first_yes_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select c.athlete_id,
         coalesce(nullif(btrim(o.display_name), ''), c.name, public.crew_default_name(c.athlete_id), 'Athlete'),
         c.crew_key, c.kinds, c.yes_since, c.first_yes_at
    from public.crew_consent c
    left join public.leaderboard_optin o on o.athlete_id = c.athlete_id
   where c.answer = 'yes' and not c.under13 and c.athlete_id not in ('demo', public.coach_note_id())
     and not exists (select 1 from public.athlete_status s where s.athlete_id = c.athlete_id and s.status = 'former')
$function$;

CREATE OR REPLACE FUNCTION public.crew_now_week(p_athlete text)
 RETURNS TABLE(cycle_num integer, week integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with p as (select pr.data from public.programs pr where pr.athlete_id = p_athlete),
  cur as (
    select p.data,
           case when jsonb_typeof(p.data -> 'currentCycleIndex') = 'number'
                     and public.career_num(p.data -> 'currentCycleIndex') = trunc(public.career_num(p.data -> 'currentCycleIndex'))
                then public.career_num(p.data -> 'currentCycleIndex')::int else 0 end as cci
      from p),
  c as (
    select coalesce(case when public.career_num(x.c -> 'num') = trunc(public.career_num(x.c -> 'num')) then public.career_num(x.c -> 'num')::int end, x.o::int) as num,
           public.career_day(x.c ->> 'startDate') as s, public.career_day(x.c ->> 'endDate') as e, cur.data
      from cur, jsonb_array_elements(case when jsonb_typeof(cur.data -> 'cycles') = 'array' then cur.data -> 'cycles' else '[]'::jsonb end) with ordinality x(c, o)
     where x.o - 1 = cur.cci)
  select c.num, k::int
    from c
   cross join lateral (select greatest(1, round((c.e - c.s) / 7.0)::int) as tot) t
   cross join lateral generate_series(1, t.tot) k
   where c.s is not null and c.e is not null and c.e >= c.s
     and jsonb_typeof(c.data -> 'workouts' -> 'days') = 'array' and jsonb_array_length(c.data -> 'workouts' -> 'days') > 0
     and current_date between c.s + 7 * (k - 1) and least(c.s + 7 * k - 1, c.e)
$function$;

CREATE OR REPLACE FUNCTION public.crew_open_now(p_viewer text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage96: ck and fv on each board row
declare o record; v_rows jsonb; v_me jsonb;
begin
  select * into o from public.crew_open where closed_at is null order by created_at desc limit 1;
  if not found then return null; end if;

  with mem as (select * from public.crew_members()),
  r as (
    select res.athlete_id, res.value, res.day, m.name, m.crew_key
      from public.crew_open_results res join mem m on m.athlete_id = res.athlete_id
     where res.open_id = o.id),
  ranked as (
    select r.*, rank() over (order by case when o.better = 'low' then r.value else -r.value end) as place from r)
  select coalesce(jsonb_agg(jsonb_build_object('who', ranked.name, 'value', ranked.value, 'place', ranked.place,
                                               'me', ranked.athlete_id is not distinct from p_viewer,
                                               'ck', ranked.crew_key, 'fv', public.crew_face_v(ranked.athlete_id))
                            order by ranked.place, ranked.name), '[]'::jsonb)
    into v_rows from ranked;

  select jsonb_build_object('value', res.value, 'day', res.day) into v_me
    from public.crew_open_results res where res.open_id = o.id and res.athlete_id is not distinct from p_viewer;

  return jsonb_build_object('id', o.id, 'title', o.title, 'how', o.how, 'unit', o.unit, 'better', o.better,
                            'opened_on', o.opened_on, 'board', v_rows, 'mine', v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_page(p_subject uuid DEFAULT NULL::uuid, p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage96
declare
  v_me text := public.current_athlete_id();
  v_coach boolean := public.is_coach();
  v_report boolean := coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role');
  v_view text := nullif(btrim(coalesce(p_athlete_id, '')), '');
  v_id text;                -- whose eyes the page is read with
  v_judge boolean;          -- must that person be in the crew? (not the coach reading as himself, not a report)
  v_ownkey uuid; v_subj text; v_own boolean;
  s record; c record;       -- the subject among crew_members(), and their consent row
  v_member boolean; v_kinds jsonb; v_joined date;
  v_s_session boolean; v_s_week boolean; v_s_best boolean; v_s_level boolean; v_s_ach boolean; v_s_hon boolean;
  v_who text; v_since date; v_art text; v_four jsonb; v_num jsonb := '{}'::jsonb; v_free boolean := false;
  v_giver text; v_cheers jsonb; v_ach jsonb; v_hon jsonb; v_best jsonb; v_cycle jsonb; v_ref jsonb; v_lv integer; v_out jsonb;
begin
  -- who is asking, and for whose eyes
  if v_view is not null and v_view is distinct from v_me and not (v_coach or v_report) then
    raise exception 'not your page';
  end if;
  v_id := coalesce(v_view, v_me);
  if v_id is null and not (v_coach or v_report) then
    raise exception 'not signed in';
  end if;
  v_judge := (not (v_coach or v_report)) or (v_coach and v_view is not null);
  if v_id is not null then
    select cc.crew_key into v_ownkey from public.crew_consent cc where cc.athlete_id = v_id;
  end if;

  -- whose page
  if p_subject is null or p_subject is not distinct from v_ownkey then
    v_own := true; v_subj := v_id;
    if v_subj is null then raise exception 'crew:who'; end if;
  else
    v_own := false;
    if v_judge and not exists (select 1 from public.crew_members() m where m.athlete_id = v_id) then
      raise exception 'crew:not_yes';
    end if;
    select m.athlete_id into v_subj from public.crew_members() m where m.crew_key = p_subject;
    if v_subj is null then raise exception 'crew:gone'; end if;
  end if;
  select m.* into s from public.crew_members() m where m.athlete_id = v_subj;
  v_member := found;
  select cc.* into c from public.crew_consent cc where cc.athlete_id = v_subj;

  -- their switches (a kind not named is on); your own page shows you everything
  v_kinds := case when v_member then coalesce(s.kinds, '{}'::jsonb) else '{}'::jsonb end;
  v_s_session := v_own or coalesce((v_kinds ->> 'session')::boolean, true);
  v_s_week := v_own or coalesce((v_kinds ->> 'week')::boolean, true);
  v_s_best := v_own or coalesce((v_kinds ->> 'best')::boolean, true);
  v_s_level := v_own or coalesce((v_kinds ->> 'level')::boolean, true);
  v_s_ach := v_own or coalesce((v_kinds ->> 'achievement')::boolean, true);
  v_s_hon := v_own or coalesce((v_kinds ->> 'honour')::boolean, true);
  if v_member then v_joined := (s.yes_since at time zone 'UTC')::date; end if;

  v_who := case when v_member then s.name
                else coalesce((select nullif(btrim(o.display_name), '') from public.leaderboard_optin o where o.athlete_id = v_subj),
                              c.name, public.crew_default_name(v_subj), 'Athlete') end;
  if v_s_session then
    select min(f.day) into v_since from public.career_facts f
     where f.athlete_id = v_subj and f.void_at is null and f.kind in ('session_finished', 'session_finished_early', 'library_session');
  end if;
  select p.data -> 'cycles' -> (case when jsonb_typeof(p.data -> 'currentCycleIndex') = 'number' then public.career_num(p.data -> 'currentCycleIndex')::int else 0 end) ->> 'art'
    into v_art from public.programs p where p.athlete_id = v_subj and jsonb_typeof(p.data -> 'cycles') = 'array';
  if v_s_level then v_lv := public.crew_lv(v_subj); end if;

  -- the four numbers: exactly the Scorecard's (career_rewards_profile is what get_profile() takes numbers.four from). A free athlete's four are
  -- other things (a day streak, perfect days), so they get no numbers here and `free: true`.
  v_four := public.career_rewards_profile(v_subj, null) -> 'numbers' -> 'four';
  if v_four is not null then
    if (v_four -> 'consistency' ->> 'key') = 'weeks_held' then
      if v_s_week then
        v_num := v_num || jsonb_build_object('weeks', jsonb_build_object('now', coalesce((v_four -> 'consistency' ->> 'value')::int, 0),
                                                                           'best', coalesce((v_four -> 'consistency' ->> 'best')::int, 0)));
      end if;
      if v_s_session then v_num := v_num || jsonb_build_object('sessions', coalesce((v_four -> 'commitment' ->> 'value')::int, 0)); end if;
      if v_s_best then v_num := v_num || jsonb_build_object('bests', coalesce((v_four -> 'progress' ->> 'value')::int, 0)); end if;
      if v_own then v_num := v_num || jsonb_build_object('comebacks', coalesce((v_four -> 'resilience' ->> 'value')::int, 0)); end if;
    else
      v_free := true;
    end if;
  end if;

  -- cheers: members only. The season's count, the all-time total (cheers and likes got), the last 7 days (the word goes after 7), and whether YOU cheered them today (not on your own page).
  if v_member then
    v_giver := case when v_coach and v_view is null then public.coach_note_id() else v_id end;
    v_cheers := jsonb_build_object(
      'season', public.crew_cheer_count(v_subj),
      'total', coalesce((select t.n from public.crew_cheer_tally t where t.athlete_id = v_subj), 0),   -- all time: cheers and likes received since joining
      'recent', coalesce((select jsonb_agg(x.j order by x.day desc, x.id desc) from (
                    select c2.id, c2.day,
                           jsonb_build_object('ck', gm.crew_key, 'who', case when c2.athlete_id = public.coach_note_id() then 'Coach' else gm.name end,
                                              'fv', public.crew_face_v(c2.athlete_id), 'coach', c2.athlete_id = public.coach_note_id(),
                                              'word', c2.word, 'day', c2.day) as j
                      from public.crew_cheers c2
                      left join public.crew_members() gm on gm.athlete_id = c2.athlete_id
                     where c2.to_athlete = v_subj and c2.day >= current_date - 7
                       and (gm.athlete_id is not null or c2.athlete_id = public.coach_note_id())
                     order by c2.day desc, c2.id desc limit 20) x), '[]'::jsonb));
    if not v_own then
      v_cheers := v_cheers || jsonb_build_object('mine_today', exists (
        select 1 from public.crew_cheers c3
         where c3.athlete_id = v_giver and c3.to_athlete = v_subj and c3.day = (now() at time zone 'UTC')::date));
    end if;
  end if;

  -- achievements, newest first, with the faces that signed each (Signed Ball): the members among the likers, newest first, five shown
  if v_s_ach then
    select coalesce(jsonb_agg(x.j order by x.day desc, x.award_id), '[]'::jsonb) into v_ach from (
      select a.award_id, a.day,
             jsonb_build_object(
               'id', a.award_id,
               'name', coalesce((select ct.body ->> 'name' from public.career_catalogue ct where ct.kind = 'achievement' and ct.id = a.item), a.item),
               'day', a.day, 'size', a.size,
               'signed', coalesce((select jsonb_agg(z.j order by z.ts desc) from (
                                     select l.created_at as ts,
                                            jsonb_build_object('ck', sm.crew_key, 'who', case when l.athlete_id = public.coach_note_id() then 'Coach' else sm.name end,
                                                               'fv', public.crew_face_v(l.athlete_id)) as j
                                       from public.crew_award_likes l
                                       left join public.crew_members() sm on sm.athlete_id = l.athlete_id
                                      where l.to_athlete = v_subj and l.award_id = a.award_id
                                        and (sm.athlete_id is not null or l.athlete_id = public.coach_note_id())
                                      order by l.created_at desc limit 5) z), '[]'::jsonb),
               'signed_n', (select count(*) from public.crew_award_likes l
                              left join public.crew_members() sm on sm.athlete_id = l.athlete_id
                             where l.to_athlete = v_subj and l.award_id = a.award_id
                               and (sm.athlete_id is not null or l.athlete_id = public.coach_note_id()))) as j
        from public.career_awards a
       where a.athlete_id = v_subj and a.kind = 'achievement'
       order by a.day desc, a.award_id limit 40) x;
  end if;

  -- the month's honours, once frozen (never "one week short")
  if v_s_hon then
    select coalesce(jsonb_agg(jsonb_build_object('month', z.month, 'honour', z.honour, 'value', z.value - 'slot') order by z.month desc, z.honour), '[]'::jsonb) into v_hon
      from (select h.month, h.honour, h.value from public.career_honours h
             where h.athlete_id = v_subj and h.honour <> 'near' and h.confirmed_at is not null   /* stage101: confirmed only */
               and exists (select 1 from public.career_honour_months hm where hm.month = h.month)
             order by h.month desc, h.honour limit 24) z;
  end if;

  -- the last five personal bests: the lift and the day, NEVER the weight
  if v_s_best then
    select coalesce(jsonb_agg(jsonb_build_object('lift', z.lift, 'day', z.day) order by z.day desc, z.lift), '[]'::jsonb) into v_best
      from (select f.value ->> 'lift' as lift, f.day from public.career_facts f
             where f.athlete_id = v_subj and f.void_at is null and f.kind = 'personal_best' and nullif(btrim(f.value ->> 'lift'), '') is not null
             order by f.day desc, f.created_at desc limit 5) z;
  end if;

  -- the current cycle, week by week. A plan day counts once in `done`; a plan day done again, a Library session and anything past the plan is
  -- `extra` ("they can do extra, it needs to show that as well"). ANOTHER person gets only the CURRENT week (`weeks` holds one entry, now: true) and the
  -- cycle's `done` and `extra` totals; no past weeks and no plan total for the cycle, because a row of past weeks with gaps would show a broken week, which the Bell's
  -- never list keeps for you alone. Their sessions before the day they joined are not counted anywhere. Your OWN page keeps every week of the cycle, the dates, the
  -- titles and the minutes (a Library session or a rehab day's name can hint at pain, which is on the never list), and carries the same two totals; never an RPE, a note or a check-in.
  if v_s_session then
    with w as (select * from public.career_weeks(v_subj) cw where cw.is_current),
    pdays as (select p.data -> 'workouts' -> 'days' as days from public.programs p where p.athlete_id = v_subj),
    f as (
      select cf.day as d, cf.ref,
             case when cf.kind in ('session_finished', 'session_finished_early') then nullif(btrim(cf.value ->> 'plan_day'), '') end as pday,
             case when (cf.value ->> 'minutes') ~ '^\d{1,4}$' then (cf.value ->> 'minutes')::int end as mins,
             cf.value ->> 'slug' as slug
        from public.career_facts cf
       where cf.athlete_id = v_subj and cf.void_at is null and cf.kind in ('session_finished', 'session_finished_early', 'library_session')
         and cf.day between (select min(w1.wfrom) from w w1) and (select max(w2.wto) from w w2)
         and (v_own or cf.day >= v_joined)),
    fw as (
      select w.week, f.d, f.ref, f.pday, f.mins, f.slug,
             (f.pday is not null and f.pday = any (w.plan) and row_number() over (partition by w.week, f.pday order by f.d, f.ref) = 1) as in_plan
        from f join w on f.d between w.wfrom and w.wto),
    fd as (
      select fw.week, fw.d, fw.ref, fw.in_plan, fw.mins,
             left(btrim(regexp_replace(public.crew_clean(
               case when fw.pday is not null
                    then coalesce((select coalesce(nullif(btrim(e ->> 'title'), ''), nullif(btrim(e ->> 'focusTag'), ''))
                                     from pdays pd, jsonb_array_elements(case when jsonb_typeof(pd.days) = 'array' then pd.days else '[]'::jsonb end) e
                                    where e ->> 'id' = fw.pday limit 1), 'Day ' || fw.pday)
                    else coalesce((select ls.title from public.library_sessions ls
                                    where ls.athlete_id = v_subj and ls.slug = fw.slug and ls.completed_on = fw.d limit 1), 'Library session') end),
               '\s+', ' ', 'g')), 40) as title
        from fw),
    wk as (
      select w.week, count(*) filter (where fd.in_plan) as done, count(*) filter (where not fd.in_plan) as extra,
             jsonb_agg(jsonb_build_object('day', fd.d, 'extra', not fd.in_plan)
                       || case when v_own then jsonb_build_object('title', fd.title) else '{}'::jsonb end
                       || case when v_own and fd.mins is not null then jsonb_build_object('mins', fd.mins) else '{}'::jsonb end
                       order by fd.d, fd.ref) filter (where fd.week is not null) as days
        from w left join fd on fd.week = w.week group by w.week)
    select jsonb_build_object(
             'n', max(w.cycle_num), 'per_week', max(cardinality(w.plan)),
             'done', coalesce(sum(wk.done), 0)::int, 'extra', coalesce(sum(wk.extra), 0)::int)
           || case when v_own then jsonb_build_object('from', max(w.cstart), 'to', max(w.cend)) else '{}'::jsonb end
           || jsonb_build_object('weeks', coalesce(jsonb_agg(jsonb_build_object(
                         'w', w.week, 'from', w.wfrom, 'to', w.wto, 'plan', cardinality(w.plan),
                         'done', coalesce(wk.done, 0),
                         'held', exists (select 1 from public.career_facts h
                                          where h.athlete_id = v_subj and h.kind = 'week_held' and h.void_at is null
                                            and h.ref = 'c' || w.cycle_num || '|w' || w.week and (v_own or h.day >= v_joined)),
                         'extra', coalesce(wk.extra, 0),
                         'now', current_date between w.wfrom and w.wto,
                         'days', coalesce(wk.days, '[]'::jsonb))
                       order by w.week) filter (where v_own or current_date between w.wfrom and w.wto), '[]'::jsonb))
      into v_cycle
      from w left join wk on wk.week = w.week
    having count(*) > 0;
  end if;

  v_out := jsonb_build_object(
    'ck', case when v_member then s.crew_key else c.crew_key end,
    'me', v_own, 'who', v_who, 'first', split_part(btrim(v_who), ' ', 1),
    'joined', v_joined, 'member', v_member, 'under13', coalesce(c.under13, false),
    'fv', public.crew_face_v(v_subj), 'art', v_art,
    'game', public.crew_game_of(v_subj), 'numbers', v_num);
  -- your own page also says which of your switches are on, so the app can mark the blocks the crew cannot see as "Only you"
  if v_own then
    v_out := v_out || jsonb_build_object('kinds', (select jsonb_object_agg(k.kind, coalesce((c.kinds ->> k.kind)::boolean, true)) from unnest(public.crew_kind_list()) k(kind)));
  end if;
  if v_since is not null then v_out := v_out || jsonb_build_object('since', v_since); end if;
  if v_member and s.first_yes_at >= now() - interval '7 days' then v_out := v_out || jsonb_build_object('new', true); end if;
  if v_lv is not null then v_out := v_out || jsonb_build_object('lv', v_lv); end if;
  if v_free then v_out := v_out || jsonb_build_object('free', true); end if;
  if v_cheers is not null then v_out := v_out || jsonb_build_object('cheers', v_cheers); end if;
  if v_ach is not null then v_out := v_out || jsonb_build_object('achievements', v_ach); end if;
  if v_hon is not null then v_out := v_out || jsonb_build_object('honours', v_hon); end if;
  if v_best is not null then v_out := v_out || jsonb_build_object('best_lifts', v_best); end if;
  if v_cycle is not null then v_out := v_out || jsonb_build_object('cycle', v_cycle); end if;
  -- stage97 (partner codes) adds crew_referral(); the page carries it on your own page once that function exists, and not before. An under-13 has none.
  if v_own and not coalesce(c.under13, false) and to_regprocedure('public.crew_referral(text)') is not null then
    execute 'select public.crew_referral($1)' into v_ref using v_subj;
    if v_ref is not null then v_out := v_out || jsonb_build_object('referral', v_ref); end if;
  end if;
  return v_out || jsonb_build_object('at', now());
end $function$;

CREATE OR REPLACE FUNCTION public.crew_photo(p_post uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.current_athlete_id(); r record;
begin
  if v_me is null and not public.is_coach() then
    raise exception 'not signed in';
  end if;
  select ph.mime, ph.w, ph.h, encode(ph.bytes, 'base64') as b64 into r
    from public.crew_photos ph join public.crew_posts p on p.id = ph.post_id
   where ph.post_id = p_post and p.created_at >= now() - interval '7 days'
     and (p.athlete_id = public.coach_note_id() or public.is_coach() or p.athlete_id = v_me
          or exists (select 1 from public.crew_members() m where m.athlete_id = p.athlete_id));
  if not found then
    return null;
  end if;
  return jsonb_build_object('id', p_post, 'mime', r.mime, 'w', r.w, 'h', r.h, 'b64', replace(r.b64, E'\n', ''));
end $function$;

CREATE OR REPLACE FUNCTION public.crew_post(p_body text, p_photo text DEFAULT NULL::text, p_w integer DEFAULT NULL::integer, p_h integer DEFAULT NULL::integer, p_kind text DEFAULT 'post'::text, p_session jsonb DEFAULT NULL::jsonb, p_key uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who(); v_out jsonb;
begin
  if not exists (select 1 from public.crew_members() m where m.athlete_id = v_me) then
    raise exception 'crew:not_yes';
  end if;
  perform public.crew_sweep();
  v_out := public.crew_write_post(v_me, p_body, p_photo, p_w, p_h, p_kind, p_session, true, p_key);
  return v_out || jsonb_build_object('me', public.crew_me(v_me));
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_add(p_who text, p_kind text, p_target_key uuid DEFAULT NULL::uuid, p_value jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- A quiet back-pay never rings: the same switch stage81's level ring reads (GAME-6, D20).
  if coalesce(current_setting('crew.quiet', true), '') = 'on' then return; end if;
  if nullif(btrim(coalesce(p_who, '')), '') is null then return; end if;
  -- Nobody is subscribed: there is nothing to queue for. Keeps the cost of this stage at zero until
  -- the first athlete taps the permission.
  if not exists (select 1 from public.push_subs limit 1) then return; end if;
  -- The cheap half of the crew test, on the primary key. The full one (a former athlete, the demo,
  -- the board) is done at sending time by crew_members(), so a "no" tomorrow silences what was
  -- queued today, and this trigger stays off the hot path of a session save.
  if p_who <> public.coach_note_id()
     and not exists (select 1 from public.crew_consent c
                      where c.athlete_id = p_who and c.answer = 'yes' and not c.under13) then
    return;
  end if;
  insert into public.crew_push_q (athlete_id, kind, target_key, value)
  values (p_who, p_kind, p_target_key, coalesce(p_value, '{}'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_done(p_athlete_id text, p_ok boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.crew_push_seen
     set upto = case when p_ok then greatest(coalesce(upto, pending), pending) else upto end,
         pending = null,
         at = now()
   where athlete_id = p_athlete_id;
  -- The same bookkeeping push_done() does, so a handset that has stopped answering runs out of
  -- patience (fails = 5) on this path too instead of being tried for ever.
  update public.push_subs
     set last_sent_at = now(),
         last_ok_at = case when p_ok then now() else last_ok_at end,
         fails = case when p_ok then 0 else least(32767, fails + 1) end
   where athlete_id = p_athlete_id;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_due(p_now timestamp with time zone DEFAULT now(), p_mark boolean DEFAULT true)
 RETURNS TABLE(endpoint text, p256dh text, auth text, athlete_id text, kind text, title text, body text, tag text, ttl integer, day date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- ⚠️ This function RETURNS a column called athlete_id, so inside it a bare `athlete_id` is both an
-- output parameter and a column of crew_push_seen, and the insert below (its column list and its
-- `on conflict`) is refused as ambiguous. The column is what is meant everywhere here. (The rehearsal
-- found this: it is an error on every call, not a wrong answer, so nothing could have shipped — but
-- the names have to stay as they are, because they are the shape push_due() already answers in and
-- the sender reads.)
#variable_conflict use_column
begin
  perform public.crew_push_sweep();

  -- The cutoff this send is covering. Written before a single push leaves, so an event that arrives
  -- while the sender is working is kept for the next tick rather than stepped over.
  if coalesce(p_mark, true) then
    insert into public.crew_push_seen (athlete_id, pending, at)
    -- stage96: DISTINCT. An athlete with two subscribed phones is two rows of the fold, and one INSERT cannot touch the same watermark twice
    -- (ON CONFLICT DO UPDATE command cannot affect row a second time), which stopped every crew notification the day somebody added a second phone.
    select distinct f.athlete_id, p_now, now() from public.crew_push_fold(p_now) f
    on conflict (athlete_id) do update set pending = p_now, at = now();
  end if;

  return query
    select f.endpoint, f.p256dh, f.auth, f.athlete_id, 'crew'::text,
           w.title, w.body, 'crew'::text, 3600, f.day
      from public.crew_push_fold(p_now) f
      cross join lateral public.crew_push_words(f.n, f.one_kind, f.one_who, f.one_mine, f.lang) w;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_fire()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; req bigint;
begin
  select * into c from public.push_config where id;
  if c.url is null or c.secret is null then
    return jsonb_build_object('ok', false, 'why', 'push_config is not filled in yet');
  end if;
  if to_regproc('net.http_post') is null then
    return jsonb_build_object('ok', false, 'why', 'pg_net is not installed');
  end if;
  execute format('select %s($1, $2::jsonb, ''{}''::jsonb, $3::jsonb, 20000)', 'net.http_post')
    into req
    using c.url || case when position('?' in c.url) > 0 then '&' else '?' end || 'only=crew',
          '{}'::jsonb,
          jsonb_build_object('Content-Type', 'application/json', 'x-push-key', c.secret);
  return jsonb_build_object('ok', true, 'request', req);
exception when others then
  -- A sender that is down must never take the job with it.
  raise warning 'crew_push_fire: %', sqlerrm;
  return jsonb_build_object('ok', false, 'why', sqlerrm);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_fold(p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(athlete_id text, endpoint text, p256dh text, auth text, lang text, day date, n integer, one_kind text, one_who text, one_mine boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with phone as (
    select s.endpoint, s.p256dh, s.auth, s.athlete_id, s.lang, s.kinds,
           public.push_local(p_now, s.tz_offset)::date as local_day,
           extract(hour from public.push_local(p_now, s.tz_offset))::int as local_hour
      from public.push_subs s
     where s.fails < 5
  ),
  -- Awake where they are: 08:00 to 21:59 local, so nothing lands after ten at night or before eight
  -- in the morning. What happened overnight waits in the queue and arrives at eight.
  awake as (
    select p.* from phone p
     where p.local_hour between 8 and 21 and public.push_on(p.kinds, 'crew')
  ),
  -- Only a crew member is sent the crew. A no, an under-13, a former athlete and the demo are not
  -- crew_members(), and nothing of theirs is in the Bell either.
  mine as (
    select a.*, m.crew_key
      from awake a join public.crew_members() m on m.athlete_id = a.athlete_id
  ),
  mark as (
    select mi.*, coalesce(sn.upto, (select min(s2.created_at) from public.push_subs s2 where s2.athlete_id = mi.athlete_id)) as upto
      from mine mi left join public.crew_push_seen sn on sn.athlete_id = mi.athlete_id
  ),
  -- What each of them has not been told about: never their own doing, never older than the Bell's own
  -- seven days, never a kind the subject switched off, and only while the subject is still in the crew
  -- (so a no today takes yesterday's queued moments with it, exactly as it takes them off the Bell).
  ev as (
    select mk.athlete_id as to_id, mk.endpoint, mk.p256dh, mk.auth, mk.lang, mk.local_day,
           q.created_at, q.kind,
           case when q.athlete_id = public.coach_note_id() then 'Amir' else d.name end as by_name,
           (q.target_key is not null and q.target_key = mk.crew_key) as to_me,
           (q.kind in ('cheer', 'reply', 'mention')) as aimed   -- stage96: goes to its target's phones only, never counted in a fold
      from mark mk
      join public.crew_push_q q
        on q.created_at > coalesce(mk.upto, q.created_at - interval '1 second')
       and q.athlete_id <> mk.athlete_id
      left join public.crew_members() d on d.athlete_id = q.athlete_id
     where q.created_at >= p_now - interval '7 days'
       and (d.athlete_id is not null or q.athlete_id = public.coach_note_id())
       and (q.kind not in ('level', 'week', 'mark', 'achievement', 'best', 'cycle', 'honour', 'open')
            or coalesce((d.kinds ->> q.kind)::boolean, true))
       -- stage96: an aimed event is owed to its target alone
       and (q.kind not in ('cheer', 'reply', 'mention') or (q.target_key is not null and q.target_key = mk.crew_key))
  ),
  -- Folded: one notification per athlete. When it is the only thing, it is named; when it is six, it
  -- is counted. The newest one is the one that gets named — which no answer depends on today, because
  -- a folded notification names nobody; it is here so that changing the folded words later needs no
  -- new thinking about which event they would be about.
  fold as (
    select e.to_id, e.endpoint, e.p256dh, e.auth, e.lang, e.local_day, count(*)::int as n,
           (array_agg(e.kind order by e.created_at desc))[1] as one_kind,
           (array_agg(coalesce(e.by_name, 'Someone') order by e.created_at desc))[1] as one_who,
           (array_agg(e.to_me order by e.created_at desc))[1] as one_mine
      from ev e
     where not e.aimed
     group by e.to_id, e.endpoint, e.p256dh, e.auth, e.lang, e.local_day
  ),
  -- stage96: a phone owed an aimed event is told THAT, naming its sender: the newest one, as one notification, never as a count. (push-send sends
  -- the first row's words to every row it groups under one athlete, kind and day, so there is one row per phone.)
  named as (
    select distinct on (e.to_id, e.endpoint)
           e.to_id, e.endpoint, e.p256dh, e.auth, e.lang, e.local_day, 1 as n, e.kind as one_kind,
           coalesce(e.by_name, 'Someone') as one_who, true as one_mine
      from ev e
     where e.aimed
     order by e.to_id, e.endpoint, e.created_at desc
  )
  select n.to_id, n.endpoint, n.p256dh, n.auth, n.lang, n.local_day, n.n, n.one_kind, n.one_who, n.one_mine
    from named n
  union all
  select f.to_id, f.endpoint, f.p256dh, f.auth, f.lang, f.local_day, f.n, f.one_kind, f.one_who, f.one_mine
    from fold f
   where not exists (select 1 from named n where n.to_id = f.to_id and n.endpoint = f.endpoint)
$function$;

CREATE OR REPLACE FUNCTION public.crew_push_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer := 0; k integer;
begin
  delete from public.crew_push_q where created_at < now() - interval '7 days';
  get diagnostics k = row_count; v_n := v_n + k;
  delete from public.crew_push_seen s
   where not exists (select 1 from public.push_subs p where p.athlete_id = s.athlete_id);
  get diagnostics k = row_count; v_n := v_n + k;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_t_award()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    perform public.crew_push_add(new.athlete_id, case when new.kind = 'badge' then 'mark' else 'achievement' end);
  exception when others then
    raise warning 'crew_push: an award of % did not queue: % (%)', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_t_cheer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key uuid;
begin
  begin
    select c.crew_key into v_key from public.crew_consent c where c.athlete_id = new.to_athlete;
    if v_key is not null then
      perform public.crew_push_add(new.athlete_id, 'cheer', v_key);
    end if;
  exception when others then
    raise warning 'crew_push: a cheer from % did not queue: % (%)', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_push_t_fact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    perform public.crew_push_add(new.athlete_id,
      case new.kind when 'week_held' then 'week' when 'personal_best' then 'best' else 'cycle' end);
  exception when others then
    raise warning 'crew_push: a fact of % did not queue: % (%)', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

