CREATE OR REPLACE FUNCTION public.crew_push_words(p_n integer, p_kind text, p_who text, p_mine boolean, p_lang text)
 RETURNS TABLE(title text, body text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  with l as (select case when p_lang = 'fa' then 'fa' else 'en' end as lang),
  -- more than one thing to tell them: the count, and nothing about who or what
  many as (
    select case when l.lang = 'fa' then 'تو تیم خبر هست' else 'The crew has been busy' end as title,
           case when l.lang = 'fa' then translate(p_n::text, '0123456789', '۰۱۲۳۴۵۶۷۸۹') || ' چیز تازه.'
                else p_n::text || ' new things to see.' end as body
      from l),
  -- exactly one: who, and which kind of thing
  one as (
    select case when l.lang = 'fa' then coalesce(w.fa, 'یه خبر تو تیم') else coalesce(w.en, 'Something in the crew') end as title,
           case when l.lang = 'fa' then 'یه سر بزن.' else 'Have a look.' end as body
      from l
      left join (values
        ('post',        p_who || ' posted',                 p_who || ' پست گذاشت'),
        ('kudos_you',   p_who || ' cheered you',            p_who || ' برات دست زد'),
        ('kudos',       p_who || ' gave a cheer',           p_who || ' یه دست زد'),
        ('level',       p_who || ' reached a new level',    p_who || ' سطحش رفت بالا'),
        ('week',        p_who || ' held their week',        p_who || ' هفته‌شو کامل کرد'),
        ('mark',        p_who || ' hit a new mark',         p_who || ' یه دستاورد گرفت'),
        ('achievement', p_who || ' earned an achievement',  p_who || ' یه دستاورد گرفت'),
        ('best',        p_who || ' set a personal best',    p_who || ' رکورد زد'),
        ('cycle',       p_who || ' finished a cycle',       p_who || ' یه دوره تموم کرد'),
        ('honour',      p_who || ' took an honour',         p_who || ' یه افتخار برد'),
        ('open',        p_who || ' played the Monthly Open', p_who || ' تو مسابقهٔ ماه بازی کرد'),
        ('joined',      p_who || ' joined the crew',        p_who || ' اومد تو تیم'),
        -- stage96: the aimed kinds. A name and a kind, never what was written.
        ('cheer',       p_who || ' sent you a cheer',       p_who || ' برات یه تشویق فرستاد'),   -- FA DRAFT for Amir
        ('reply',       p_who || ' replied to your post',   p_who || ' به پستت جواب داد'),        -- FA DRAFT for Amir
        ('mention',     p_who || ' mentioned you',          p_who || ' تو رو منشن کرد')           -- FA DRAFT for Amir
      ) as w(k, en, fa)
        on w.k = case when p_kind = 'kudos' and coalesce(p_mine, false) then 'kudos_you' else p_kind end)
  select title, body from many where p_n > 1
  union all
  select title, body from one where p_n <= 1
$function$;

CREATE OR REPLACE FUNCTION public.crew_referral(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select jsonb_build_object(
              'code', a.code, 'percent', a.percent, 'reward', coalesce(a.reward_percent, 10),
              'friends', (select count(*) from public.referral_credits r where r.code = a.code),
              'waiting', (select count(*) from public.referral_credits r where r.code = a.code and r.used_on is null),
              'used', (select count(*) from public.referral_credits r where r.code = a.code and r.used_on is not null))
            || case when a.active then '{}'::jsonb else jsonb_build_object('active', false) end
       from public.affiliates a where a.athlete_id = p_athlete and a.kind = 'athlete' limit 1),
    jsonb_build_object('code', null))
$function$;

CREATE OR REPLACE FUNCTION public.crew_reply(p_post uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who(); v_body text := public.crew_clean(p_body); v_author text;
  -- stage96: mentions. A token is @[<crew_key>|<name>]; v_seen is the reply as it will be READ (a token is "@name").
  v_rest text; v_out text := ''; v_seen text := ''; v_m text[]; v_pos integer; v_nm text; v_to text; v_cnt integer := 0; v_tos text[] := '{}'; v_id uuid;
  c_tok constant text := '(@\[([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\|([^]|\n]{1,40})\])';
begin
  if not exists (select 1 from public.crew_members() m where m.athlete_id = v_me) then raise exception 'crew:not_yes'; end if;
  if v_body = '' then raise exception 'crew:empty'; end if;
  -- stage96: check each mention token. Valid: a member, not the author, the first five. Anything else becomes plain "@name".
  v_rest := v_body;
  loop
    v_m := regexp_match(v_rest, c_tok);
    exit when v_m is null;
    v_pos := strpos(v_rest, v_m[1]);
    v_nm := left(btrim(v_m[3]), 24);
    v_out := v_out || left(v_rest, v_pos - 1);
    v_seen := v_seen || left(v_rest, v_pos - 1);
    v_to := null;
    if v_cnt < 5 and v_nm <> '' then
      select m.athlete_id into v_to from public.crew_members() m where m.crew_key = lower(v_m[2])::uuid and m.athlete_id <> v_me;
    end if;
    if v_to is not null then
      v_out := v_out || '@[' || lower(v_m[2]) || '|' || v_nm || ']';
      v_cnt := v_cnt + 1;
      if not (v_to = any (v_tos)) then v_tos := v_tos || v_to; end if;
    else
      v_out := v_out || '@' || v_nm;
    end if;
    v_seen := v_seen || '@' || v_nm;
    v_rest := substr(v_rest, v_pos + length(v_m[1]));
  end loop;
  v_body := v_out || v_rest;
  v_seen := v_seen || v_rest;
  if char_length(v_seen) > 140 or char_length(v_body) > 700 then raise exception 'crew:reply_long'; end if;
  perform public.crew_sweep();
  select p.athlete_id into v_author from public.crew_posts p
   where p.id = p_post and p.created_at >= now() - interval '7 days'
     and (p.athlete_id = public.coach_note_id() or exists (select 1 from public.crew_members() m where m.athlete_id = p.athlete_id));
  if v_author is null then raise exception 'crew:gone'; end if;
  -- Two caps under one lock, so two taps cannot both pass: what one athlete may say in a day, and how long one post's
  -- thread may get (everybody's, so a thread cannot be driven past reading length).
  perform pg_advisory_xact_lock(hashtext('crew_reply:' || v_me));
  if (select count(*) from public.crew_replies r where r.athlete_id = v_me and r.created_at >= date_trunc('day', now())) >= 30 then
    raise exception 'crew:replies_today';
  end if;
  if (select count(*) from public.crew_replies r where r.post_id = p_post) >= 50 then
    raise exception 'crew:replies_full';
  end if;
  insert into public.crew_replies (post_id, athlete_id, body) values (p_post, v_me, v_body) returning id into v_id;
  -- stage96: the valid mentions are what rings
  insert into public.crew_mentions (reply_id, athlete_id, to_athlete) select v_id, v_me, x from unnest(v_tos) x on conflict do nothing;
  return jsonb_build_object('post', p_post, 'replies', public.crew_reply_rows(p_post, v_me));
end $function$;

CREATE OR REPLACE FUNCTION public.crew_reply_delete(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who(); v_post uuid;
begin
  select r.post_id into v_post from public.crew_replies r where r.id = p_id and r.athlete_id = v_me;
  if v_post is null then raise exception 'crew:gone'; end if;
  delete from public.crew_replies where id = p_id and athlete_id = v_me;
  return jsonb_build_object('post', v_post, 'replies', public.crew_reply_rows(v_post, v_me));
end $function$;

CREATE OR REPLACE FUNCTION public.crew_reply_rows(p_post uuid, p_viewer text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- stage96: ck, fv and mentions
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', r.id,
           'who', case when r.athlete_id = public.coach_note_id() then 'Amir' else m.name end,
           'me', r.athlete_id is not distinct from p_viewer,
           'amir', r.athlete_id = public.coach_note_id(),
           'body', r.body,
           'at', r.created_at)
           || case when m.athlete_id is not null then jsonb_build_object('ck', m.crew_key, 'fv', public.crew_face_v(m.athlete_id)) else '{}'::jsonb end
           || coalesce((select jsonb_build_object('mentions', jsonb_agg(jsonb_build_object('ck', mm.crew_key, 'who', mm.name, 'fv', public.crew_face_v(mm.athlete_id)) order by mm.name))
                          from public.crew_mentions cm join public.crew_members() mm on mm.athlete_id = cm.to_athlete
                         where cm.reply_id = r.id having count(*) > 0), '{}'::jsonb)
           order by r.created_at), '[]'::jsonb)
    from public.crew_replies r
    left join public.crew_members() m on m.athlete_id = r.athlete_id
   where r.post_id = p_post
     and (r.athlete_id = public.coach_note_id() or m.athlete_id is not null)
$function$;

CREATE OR REPLACE FUNCTION public.crew_season_start(p_athlete text)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce((select case when (s.score #>> '{season,starts_on}') ~ '^\d{4}-\d{2}-\d{2}$' then (s.score #>> '{season,starts_on}')::date end
                     from public.career_scores s where s.athlete_id = p_athlete),
                  date_trunc('month', current_date)::date)
$function$;

CREATE OR REPLACE FUNCTION public.crew_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer := 0; k integer;
begin
  delete from public.crew_posts where created_at < now() - interval '7 days';
  get diagnostics k = row_count; v_n := v_n + k;
  delete from public.crew_kudos where to_athlete is not null and line_day < current_date - 7;
  get diagnostics k = row_count; v_n := v_n + k;
  delete from public.crew_rings where created_at < now() - interval '8 days';
  get diagnostics k = row_count; v_n := v_n + k;
  -- stage96: a cheer's word lives 7 days; the row (it is the season's count) lives 400
  update public.crew_cheers set word = null where word is not null and day < current_date - 7;
  get diagnostics k = row_count; v_n := v_n + k;
  delete from public.crew_cheers where day < current_date - 400;
  get diagnostics k = row_count; v_n := v_n + k;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_t_forget_former()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    perform public.crew_forget(new.athlete_id);
  exception when others then
    raise warning 'crew: the face and cheers of % were not cleared: % (%)', new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_t_tally_cheer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if new.to_athlete is distinct from new.athlete_id then perform public.crew_tally_up(new.to_athlete); end if;
  exception when others then
    raise warning 'crew: a cheer for % was not counted: % (%)', new.to_athlete, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_tally_up(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_athlete is null or p_athlete = public.coach_note_id() then return; end if;
  insert into public.crew_cheer_tally as t (athlete_id, n) values (p_athlete, 1)
  on conflict (athlete_id) do update set n = t.n + 1, updated_at = now();
end $function$;

CREATE OR REPLACE FUNCTION public.crew_vote(p_side text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: one vote a week for the signed-in crew member; tapping the other side changes it.
declare v_me text := public.current_athlete_id(); w public.crew_weeks; v_side text := lower(btrim(coalesce(p_side, '')));
begin
  if v_me is null then raise exception 'crew:who'; end if;
  if not exists (select 1 from public.crew_members() m where m.athlete_id = v_me) then raise exception 'crew:join'; end if;
  if v_side not in ('a', 'b') then raise exception 'crew:side'; end if;
  select * into w from public.crew_weeks where week_start = date_trunc('week', current_date)::date;
  if w.week_start is null or w.toss_q is null or w.closed_at is not null then raise exception 'crew:closed'; end if;
  insert into public.crew_toss_votes (week_start, athlete_id, side) values (w.week_start, v_me, v_side)
    on conflict (week_start, athlete_id) do update set side = excluded.side, created_at = now();
  return public.crew_weekly(v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_weekly(p_viewer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage102: this week's Toss and photo theme, with the faces of who chose each side (crew members only) and the viewer's own vote.
declare w public.crew_weeks; v jsonb;
begin
  select * into w from public.crew_weeks where week_start = date_trunc('week', current_date)::date;
  if w.week_start is null or (w.toss_q is null and w.theme is null) then return null; end if;
  with votes as (
    select t.side, t.created_at, m.athlete_id, m.name, m.crew_key
      from public.crew_toss_votes t join public.crew_members() m on m.athlete_id = t.athlete_id
     where t.week_start = w.week_start)
  select jsonb_build_object(
           'a', (select count(*) from votes where side = 'a'), 'b', (select count(*) from votes where side = 'b'),
           'fa', (select coalesce(jsonb_agg(jsonb_build_object('ck', crew_key, 'fv', public.crew_face_v(athlete_id), 'who', name,
                                                                'me', athlete_id is not distinct from p_viewer) order by created_at desc), '[]'::jsonb)
                    from votes where side = 'a'),
           'fb', (select coalesce(jsonb_agg(jsonb_build_object('ck', crew_key, 'fv', public.crew_face_v(athlete_id), 'who', name,
                                                                'me', athlete_id is not distinct from p_viewer) order by created_at desc), '[]'::jsonb)
                    from votes where side = 'b'))
    into v;
  return jsonb_build_object('week', w.week_start, 'q', w.toss_q, 'a', w.toss_a, 'b', w.toss_b, 'theme', w.theme,
                            'open', w.toss_q is not null and w.closed_at is null, 'closes', w.week_start + 6,
                            'mine', (select t.side from public.crew_toss_votes t where t.week_start = w.week_start and t.athlete_id = p_viewer),
                            'votes', v);
end $function$;

CREATE OR REPLACE FUNCTION public.crew_who()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.current_athlete_id();
begin
  if v_me is null then raise exception 'crew:signin'; end if;
  if v_me = 'demo' then raise exception 'crew:demo'; end if;
  return v_me;
end $function$;

CREATE OR REPLACE FUNCTION public.crew_write_post(p_who text, p_body text, p_photo text, p_w integer, p_h integer, p_kind text, p_session jsonb, p_capped boolean, p_key uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_body text := public.crew_clean(p_body); v_kind text := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), 'post');
  v_bytes bytea; v_id uuid; v_ses jsonb := null; v_seen uuid;
begin
  -- The same key again is the same post: hand back what was written the first time and write nothing.
  if p_key is not null then
    select cp.id into v_seen from public.crew_posts cp where cp.athlete_id = p_who and cp.client_key = p_key;
    if v_seen is not null then return jsonb_build_object('id', v_seen, 'again', true); end if;
  end if;
  if char_length(v_body) > 280 then raise exception 'crew:too_long'; end if;
  if v_kind not in ('post', 'session') then raise exception 'crew:kind'; end if;
  if nullif(btrim(coalesce(p_photo, '')), '') is not null then
    begin
      v_bytes := decode(regexp_replace(regexp_replace(p_photo, '^data:[^,]*,', ''), '\s', '', 'g'), 'base64');
    exception when others then
      raise exception 'crew:photo_bad';
    end;
    if octet_length(v_bytes) > 450000 then raise exception 'crew:photo_big'; end if;
    if octet_length(v_bytes) < 100 or substring(v_bytes from 1 for 3) <> '\xffd8ff'::bytea then raise exception 'crew:photo_bad'; end if;
  end if;
  if v_bytes is null and v_body = '' then raise exception 'crew:empty'; end if;
  if v_kind = 'session' and v_bytes is null then raise exception 'crew:session_photo'; end if;
  if v_kind = 'session' and p_session is not null and jsonb_typeof(p_session) = 'object' then
    v_ses := jsonb_strip_nulls(jsonb_build_object(
      'day', case when (p_session ->> 'day') ~ '^\d{1,2}$' then (p_session ->> 'day')::int end,
      'n', case when (p_session ->> 'n') ~ '^\d{1,4}$' then (p_session ->> 'n')::int end,
      -- stage96: the proof stamp. title (a name, at most 40 characters), mins (1 to 300) and held (did this session hold the week). Other keys are dropped.
      'title', nullif(left(btrim(regexp_replace(public.crew_clean(p_session ->> 'title'), '\s+', ' ', 'g')), 40), ''),
      'mins', case when (p_session ->> 'mins') ~ '^\d{1,3}$' and (p_session ->> 'mins')::int between 1 and 300 then (p_session ->> 'mins')::int end,
      'held', case when jsonb_typeof(p_session -> 'held') = 'boolean' then (p_session -> 'held')::boolean end));
  end if;
  if p_capped then
    perform pg_advisory_xact_lock(hashtext('crew_post:' || p_who));
    -- the key again, now under the lock: the race this is here to stop is two taps a second apart
    if p_key is not null then
      select cp.id into v_seen from public.crew_posts cp where cp.athlete_id = p_who and cp.client_key = p_key;
      if v_seen is not null then return jsonb_build_object('id', v_seen, 'again', true); end if;
    end if;
    if (select count(*) from public.crew_posts cp where cp.athlete_id = p_who and cp.created_at >= date_trunc('day', now())) >= 10 then
      raise exception 'crew:posts_today';
    end if;
    if v_bytes is not null and (select count(*) from public.crew_photos ph where ph.athlete_id = p_who and ph.created_at >= date_trunc('day', now())) >= 3 then
      raise exception 'crew:photos_today';
    end if;
  end if;
  insert into public.crew_posts (athlete_id, kind, body, session, has_photo, client_key)
  values (p_who, v_kind, v_body, v_ses, v_bytes is not null, p_key) returning id into v_id;
  if v_bytes is not null then
    insert into public.crew_photos (post_id, athlete_id, w, h, bytes)
    values (v_id, p_who, case when p_w between 1 and 4000 then p_w end, case when p_h between 1 and 4000 then p_h end, v_bytes);
  end if;
  return jsonb_build_object('id', v_id);
end $function$;

CREATE OR REPLACE FUNCTION public.current_athlete_id()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select athlete_id from public.athlete_identities where user_id = auth.uid() $function$;

CREATE OR REPLACE FUNCTION public.current_season()
 RETURNS TABLE(name text, starts_on date)
 LANGUAGE sql
 STABLE
AS $function$
  select s.name, s.starts_on
  from public.seasons s
  where s.starts_on <= current_date
  order by s.starts_on desc, s.id desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.cycle_push_done(p_athlete_id text, p_ok boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.push_cycle_seen
     set cycle_index = case when p_ok then greatest(coalesce(cycle_index, pending), pending) else cycle_index end,
         pending = null,
         at = now()
   where athlete_id = p_athlete_id;
  -- The same bookkeeping push_done() does, so a handset that has stopped answering runs out of
  -- patience (fails = 5) on this path too.
  update public.push_subs
     set last_sent_at = now(),
         last_ok_at = case when p_ok then now() else last_ok_at end,
         fails = case when p_ok then 0 else least(32767, fails + 1) end
   where athlete_id = p_athlete_id;
end $function$;

CREATE OR REPLACE FUNCTION public.cycle_push_due(p_now timestamp with time zone DEFAULT now(), p_mark boolean DEFAULT true)
 RETURNS TABLE(endpoint text, p256dh text, auth text, athlete_id text, kind text, title text, body text, tag text, ttl integer, day date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- ⚠️ The returned column athlete_id is also a column of push_cycle_seen, so a bare name inside the
-- writes below is ambiguous; the column is what is meant. (stage86 hit this and says more about it.)
#variable_conflict use_column
begin
  -- First sight: write down where they are and tell them nothing. An athlete who subscribes today is
  -- not news-flashed about the cycle they are already training.
  if coalesce(p_mark, true) then
    insert into public.push_cycle_seen (athlete_id, cycle_index, at)
    select f.athlete_id, f.cci, now() from public.cycle_push_fold(p_now) f where f.seen is null
    on conflict (athlete_id) do nothing;
  end if;

  -- The cutoff this send covers, written before a single push leaves.
  if coalesce(p_mark, true) then
    update public.push_cycle_seen s
       set pending = f.cci, at = now()
      from public.cycle_push_fold(p_now) f
     where s.athlete_id = f.athlete_id and f.seen is not null and f.cci > f.seen;
  end if;

  return query
    select f.endpoint, f.p256dh, f.auth, f.athlete_id, 'cycle'::text,
           w.title, w.body, 'cycle'::text, 7200, f.day
      from public.cycle_push_fold(p_now) f
      cross join lateral public.cycle_push_words(f.lang) w
     where f.seen is not null and f.cci > f.seen;
end $function$;

CREATE OR REPLACE FUNCTION public.cycle_push_fold(p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(athlete_id text, endpoint text, p256dh text, auth text, lang text, day date, cci integer, seen integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with phone as (
    select s.endpoint, s.p256dh, s.auth, s.athlete_id, s.lang, s.kinds,
           public.push_local(p_now, s.tz_offset)::date as local_day,
           extract(hour from public.push_local(p_now, s.tz_offset))::int as local_hour
      from public.push_subs s
     where s.fails < 5
  ),
  -- Awake where they are, and the switch left on.
  awake as (
    select p.* from phone p
     where p.local_hour between 8 and 21 and public.push_on(p.kinds, 'cycle')
  ),
  -- A coached athlete with a roadmap. A free Proof athlete has no cycles to be told about, and a
  -- programme with no roadmap yet (an athlete mid-intake) has nothing to announce either.
  prog as (
    select a.*, (pr.data ->> 'currentCycleIndex')::int as cci
      from awake a
      join public.programs pr on pr.athlete_id = a.athlete_id
     where coalesce(pr.data -> 'athlete' ->> 'tier', 'coached') <> 'free'
       and jsonb_typeof(pr.data -> 'cycles') = 'array'
       and jsonb_array_length(pr.data -> 'cycles') > 0
       and (pr.data ->> 'currentCycleIndex') ~ '^\d{1,3}$'
  )
  select g.athlete_id, g.endpoint, g.p256dh, g.auth, g.lang, g.local_day, g.cci, sn.cycle_index
    from prog g left join public.push_cycle_seen sn on sn.athlete_id = g.athlete_id
$function$;

CREATE OR REPLACE FUNCTION public.cycle_push_on_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Only a cycle ADVANCE is news. Every other write to programs — the dashboard's inline editor, a
  -- mid-cycle correction, a Spine rename moving history — leaves currentCycleIndex alone and must stay
  -- silent. A first programme arrives as an INSERT, which this trigger does not watch: a new athlete is
  -- onboarded by hand, and cycle_push_due()'s first-sight rule would hold its tongue anyway.
  if coalesce(new.data ->> 'currentCycleIndex', '') = coalesce(old.data ->> 'currentCycleIndex', '') then
    return new;
  end if;

  begin
    perform public.push_fire();
  exception when others then
    -- A sender that is down must never cost the athlete their new cycle. The hourly job will carry it.
    raise warning 'cycle_push_on_publish: %', sqlerrm;
  end;

  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.cycle_push_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  delete from public.push_cycle_seen s
   where not exists (select 1 from public.push_subs p where p.athlete_id = s.athlete_id);
  get diagnostics n = row_count;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.cycle_push_words(p_lang text)
 RETURNS TABLE(title text, body text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select t.title, t.body from (values
    ('en', 'Your next cycle is ready', 'Open the app and have a look.'),
    ('fa', 'دوره‌ی بعدیت آماده‌ست',     'برنامه رو باز کن و یه نگاه بنداز.')
  ) as t(lang, title, body)
  where t.lang = (case when p_lang = 'fa' then 'fa' else 'en' end)
$function$;

CREATE OR REPLACE FUNCTION public.delete_intake(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  delete from public.hab_intake where id = p_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.end_quests(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key   text;
  v_runs  jsonb;
  v_out   jsonb := '[]'::jsonb;
  v_found boolean := false;
  r       jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_start is null or p_end is null then
    raise exception 'give the run''s start day and the day it ends';
  end if;
  v_key := to_char(p_start, 'YYYY-MM-DD');
  select coalesce(rules -> 'questRuns', '[]'::jsonb) into v_runs from public.xp_rules where id = 1 for update;
  for r in select value from jsonb_array_elements(v_runs) loop
    if r ->> 'start' is not distinct from v_key then
      v_found := true;
      if p_end >= p_start then   -- a run that had not begun (end before start) is dropped: nothing was earned in it
        v_out := v_out || jsonb_build_array(r || jsonb_build_object('end', to_char(least(p_end, p_start + 6), 'YYYY-MM-DD')));
      end if;
    else
      v_out := v_out || jsonb_build_array(r);
    end if;
  end loop;
  if not v_found then
    raise exception 'no quest run starts on %', v_key;
  end if;
  update public.xp_rules set rules = jsonb_set(rules, '{questRuns}', v_out), updated_at = now() where id = 1;
  return v_out;
end; $function$;

CREATE OR REPLACE FUNCTION public.forget_contact(p_athlete_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if exists (
    select 1 from public.programs p
     where p.athlete_id = p_athlete_id
       and coalesce(p.data->'athlete'->>'tier', p.data->>'tier', '') <> 'free'
  ) then
    raise exception 'coached athlete: forget would delete their training app data (records, body weight, check-ins). Nothing was deleted.';
  end if;
  delete from public.hab_notes         where athlete_id = p_athlete_id;
  delete from public.leaderboard_optin where athlete_id = p_athlete_id;
  delete from public.athlete_progress  where athlete_id = p_athlete_id;
  delete from public.hab_contacts      where athlete_id = p_athlete_id;
  delete from public.athlete_keys      where athlete_id = p_athlete_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_achievements(p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.current_athlete_id();
  v_id text := coalesce(nullif(btrim(coalesce(p_athlete_id, '')), ''), v_me);
  v_rules jsonb; v_S date; v_hr jsonb; v_ctx jsonb; v_owned jsonb; v_free boolean;
  v_keys text[] := '{}'::text[]; v_m jsonb := '{}'::jsonb; c record; g jsonb; v_items jsonb := '[]'::jsonb; v_next jsonb;
  v_test text; v_k text; v_have numeric; v_need numeric; v_day date; v_met integer; v_n integer;
  v_mw integer; v_mh integer; v_spoilt boolean; v_done jsonb; v_xpw jsonb; v_times integer; v_sy jsonb;   /* stage99 */
begin
  if v_id is null then
    raise exception 'not signed in';
  end if;
  if not (public.is_coach() or v_id is not distinct from v_me or coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role')) then
    raise exception 'not your profile';
  end if;
  v_rules := public.career_rules_now();
  v_S := case when v_rules is not null then public.career_switch_day(v_rules, 'catalogue') end;
  if v_S is null then
    return jsonb_build_object('athlete_id', v_id, 'ready', false, 'items', '[]'::jsonb, 'next', null);
  end if;
  v_hr := public.career_habit_rules();
  v_ctx := jsonb_build_object(        -- as career_evaluate() builds it, for the measures a Proof goal reads
    'S', v_S, 'hr', v_hr, 'targets', coalesce(v_hr -> 'targets', '{}'::jsonb),
    'custom', coalesce((select f.value -> 'custom' from public.career_facts f
                         where f.athlete_id = v_id and f.kind = 'habit_day' and f.void_at is null and jsonb_typeof(f.value -> 'custom') = 'array'
                         order by f.day desc limit 1), '[]'::jsonb));
  select coalesce(jsonb_object_agg(a.item, a.day), '{}'::jsonb) into v_owned
    from public.career_awards a where a.athlete_id = v_id and a.kind = 'achievement';
  -- stage99: the day the work was done (earned_on) and the XP the award was minted with (0 for a D21 back-fill), by achievement
  select coalesce(jsonb_object_agg(a.item, a.earned_on), '{}'::jsonb), coalesce(jsonb_object_agg(a.item, case when a.pays then a.xp else 0 end), '{}'::jsonb)
    into v_done, v_xpw from public.career_awards a where a.athlete_id = v_id and a.kind = 'achievement';
  v_free := coalesce((select p.data #>> '{athlete,tier}' = 'free' from public.programs p where p.athlete_id = v_id), false);

  -- the measures the unearned ones read, in one pass
  for c in select cc.id, cc.body from public.career_catalogue cc where cc.kind = 'achievement' loop
    if not (v_owned ? c.id) and public.career_achievement_test(c.body) in ('total', 'best_run', 'proof', 'goals', 'best_value') then
      v_keys := v_keys || public.career_entry_keys('achievement', c.body, v_ctx);
    end if;
  end loop;
  if cardinality(v_keys) > 0 then
    v_m := public.career_measures(v_id, v_ctx, v_keys);
  end if;

  -- this calendar month's training weeks (Full Month, stage79's rule): those ending in it; spoilt once one has ended unheld
  select count(*)::int, count(*) filter (where h.held)::int, coalesce(bool_or(not h.held and h.wto < current_date), false)
    into v_mw, v_mh, v_spoilt
    from (select w.wto,
                 exists (select 1 from public.career_facts f where f.athlete_id = v_id and f.kind = 'week_held' and f.void_at is null
                           and f.ref = 'c' || w.cycle_num || '|w' || w.week) as held
            from public.career_weeks(v_id) w
           where w.wto is not null and coalesce(array_length(w.plan, 1), 0) > 0
             and date_trunc('month', w.wto) = date_trunc('month', current_date::timestamp)) h;

  for c in select cc.id, cc.body from public.career_catalogue cc where cc.kind = 'achievement' order by cc.id loop
    v_day := (v_owned ->> c.id)::date;
    if v_day is null and (c.body ? 'retire_at' or c.body ->> 'reads' = 'mission_sweep' or c.body ->> 'meaning' = 'chosen') then
      continue;                                       -- nothing left to earn it by
    end if;
    if v_day is null and v_free and coalesce(c.body ->> 'free', 'false') <> 'true' then continue; end if;
    v_test := public.career_achievement_test(c.body);
    v_have := null; v_need := null; v_times := null;
    if v_day is not null and c.body ->> 'repeats' is not null then      -- stage99: how many times it came ("Won 11 times"), display only
      select count(*)::int into v_times from public.career_facts f
       where f.athlete_id = v_id and f.kind = c.body ->> 'repeats' and f.void_at is null;
    end if;
    if v_day is null then
      if v_test in ('total', 'proof', 'best_value') then
        v_k := (public.career_entry_keys('achievement', c.body, v_ctx))[1];
        v_have := coalesce(public.career_num(v_m -> v_k -> 'have'), 0);
        v_need := public.career_num(case when v_test = 'proof' then c.body -> 'proof_need' else c.body -> 'at' end);
      elsif v_test = 'best_run' then
        v_have := coalesce(public.career_num(v_m -> 'weeks' -> 'now'), 0);
        v_need := public.career_num(c.body -> 'at');
      elsif v_test = 'goals' then
        v_met := 0; v_n := 0;
        for g in select e from jsonb_array_elements(case when jsonb_typeof(c.body -> 'goals') = 'array' then c.body -> 'goals' else '[]'::jsonb end) e loop
          v_n := v_n + 1;
          if coalesce(public.career_num(v_m -> public.career_proof_key(g ->> 'kind') -> 'have'), 0) >= coalesce(public.career_num(g -> 'need'), 1) then
            v_met := v_met + 1;
          end if;
        end loop;
        v_have := v_met; v_need := v_n;
      elsif v_test = 'month_held' then
        v_need := greatest(coalesce(public.career_num(c.body -> 'weeks'), 4), v_mw);
        v_have := case when v_spoilt then 0 else v_mh end;
      elsif v_test = 'slam_year' then      -- stage99: windows hit in the best calendar year, of all the windows there are
        v_sy := public.career_slam_year(v_id, c.body -> 'of');
        v_have := coalesce((v_sy ->> 'have')::numeric, 0); v_need := (v_sy ->> 'need')::numeric;
      else
        v_have := 0; v_need := 1;
      end if;
      if v_need is null or v_need <= 0 then v_need := 1; end if;
      v_have := least(greatest(v_have, 0), v_need);
    end if;
    v_items := v_items || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'id', c.id, 'name', coalesce(c.body ->> 'name', c.id), 'meaning', c.body ->> 'meaning', 'test', v_test, 'reads', c.body -> 'reads',
      'caption', c.body ->> 'caption', 'rule', c.body ->> 'rule', 'size', c.body ->> 'size', 'xp', c.body -> 'xp', 'origin', c.body ->> 'origin',
      'day', v_day, 'done_on', case when v_day is not null then (v_done ->> c.id)::date end,
      'xp_won', case when v_day is not null then (v_xpw ->> c.id)::int end, 'times', case when v_times >= 2 then v_times end,
      'have', v_have, 'need', v_need,
      'spoilt', case when v_day is null and v_test = 'month_held' and v_spoilt then true end)));
  end loop;

  -- Next up: with some progress, the furthest along, then the nearest to done; with none, never a resilience one (nobody aims to miss a week),
  -- then consistency, commitment, progress, the smallest size, the least XP (the easiest first step: Held, Back to Back, Every Rep Counted)
  select z.e into v_next from (
    select e, (e ->> 'have')::numeric as h, (e ->> 'need')::numeric as n from jsonb_array_elements(v_items) e
     where e ->> 'day' is null and not coalesce((e ->> 'spoilt')::boolean, false)
        and coalesce(e ->> 'test', '') not in ('on_dates', 'slam_year', 'clock')) z   /* stage99: nobody can work on a date or a time of day */
   where z.h > 0 or z.e ->> 'meaning' is distinct from 'resilience'
   order by case when z.h > 0 then 0 else 1 end,
            case when z.h > 0 then z.h / z.n end desc nulls last,
            case when z.h > 0 then z.n - z.h end,
            array_position(array['consistency', 'commitment', 'progress', 'resilience'], z.e ->> 'meaning'),
            array_position(array['tick', 'win', 'highlight', 'milestone', 'legend'], z.e ->> 'size'),
            coalesce(public.career_num(z.e -> 'xp'), 0), z.e ->> 'id'
   limit 1;

  return jsonb_build_object('athlete_id', v_id, 'ready', true, 'items', v_items, 'next', v_next,
                            'month', jsonb_build_object('weeks', v_mw, 'held', v_mh, 'spoilt', v_spoilt));
end $function$;

CREATE OR REPLACE FUNCTION public.get_answer_book()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- stage102 (#91 The Answer Book): every Mailbag answer, newest first, for anyone signed in. The asker is named by first name only when they
  -- said yes, else "Someone".
  select case when public.current_athlete_id() is null and not public.is_coach() then null else
    coalesce((select jsonb_agg(jsonb_build_object('q', q.body, 'a', q.answer, 'at', q.answered_at,
                                                  'by', case when q.ok_name then nullif(split_part(btrim(coalesce(c.name,
                                                             (select p.data -> 'athlete' ->> 'name' from public.programs p where p.athlete_id = q.athlete_id), '')), ' ', 1), '') end)
                               order by q.answered_at desc)
                from public.crew_questions q left join public.crew_consent c on c.athlete_id = q.athlete_id
               where q.answer is not null), '[]'::jsonb) end
$function$;

CREATE OR REPLACE FUNCTION public.get_awards(p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.current_athlete_id();
  v_id text := coalesce(nullif(btrim(coalesce(p_athlete_id, '')), ''), v_me);
  v_rules jsonb; v_S date; v_hr jsonb;
begin
  if v_id is null then
    raise exception 'not signed in';
  end if;
  if not (public.is_coach() or v_id is not distinct from v_me or coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role')) then
    raise exception 'not your profile';
  end if;
  v_rules := public.career_rules_now();
  v_S := case when v_rules is not null then public.career_switch_day(v_rules, 'catalogue') end;
  if v_S is null then
    return jsonb_build_object('athlete_id', v_id, 'catalogue', null, 'badges', '[]'::jsonb, 'achievements', '[]'::jsonb,
                              'titles', '[]'::jsonb, 'recent', '[]'::jsonb);
  end if;
  v_hr := public.career_habit_rules();
  return jsonb_build_object(
    'athlete_id', v_id,
    'catalogue', v_S,
    'catalogue_version', (select r.version::text || '@' || extract(epoch from r.loaded_at)::bigint::text
                            from public.career_rules r order by r.version desc limit 1),
    'badges', coalesce((
      -- Every badge the athlete holds, one row per badge (per habit for habit_tiers' ladders), newest first. A live badge: id, subject (only
      -- when there is one), name, meaning, tier, metal, day, caption, and `days`: the day each tier was earned, tier 1 first (null for a tier
      -- skipped). A retired badge is only ever the line "Earned before: HUMAN SPRINKLER II" under the badge that replaced it, so its row is
      -- id, subject, name, meaning, tier, of, retired, superseded_by and days, and a per-habit one (habit_tiers, with a subject) is id, subject,
      -- meaning, tier, retired and days: its successor is the subject's own badge (habitSucc() and earnedBeforeLines() in habits.html).
      select jsonb_agg(b.j order by b.day desc, b.id, b.subject)
        from (select bt.item as id, bt.subject, bt.day,
                     jsonb_strip_nulls(jsonb_build_object(
                       'id', bt.item, 'subject', nullif(bt.subject, ''), 'meaning', bt.meaning, 'tier', bt.tier))
                     || case when rt.retired and bt.subject <> '' then '{}'::jsonb
                             else jsonb_build_object('name', coalesce(c.body ->> 'name', bt.item)) end
                     || case when rt.retired
                             then jsonb_build_object('retired', true)
                                  || case when bt.subject = '' then jsonb_strip_nulls(jsonb_build_object(
                                            'of', case when jsonb_typeof(c.body -> 'tiers') = 'array' then jsonb_array_length(c.body -> 'tiers') end,
                                            'superseded_by', c.body -> 'superseded_by')) else '{}'::jsonb end
                             else jsonb_strip_nulls(jsonb_build_object(
                                    'metal', c.body -> 'tiers' -> (bt.tier - 1) ->> 'metal', 'day', bt.day,
                                    'caption', (public.career_award_spec('badge', bt.item, bt.tier, bt.day, bt.evidence, c.body)) ->> 'caption')) end
                     || jsonb_build_object('days', (select jsonb_agg(to_jsonb(d.day) order by g.t)
                                                      from generate_series(1, bt.tier) g(t)
                                                      left join public.career_awards d on d.athlete_id = bt.athlete_id and d.kind = 'badge'
                                                       and d.item = bt.item and d.subject = bt.subject and d.tier = g.t)) as j
                from (select distinct on (a.item, a.subject) a.* from public.career_awards a
                       where a.athlete_id = v_id and a.kind = 'badge' order by a.item, a.subject, a.tier desc) bt
                left join public.career_catalogue c on c.kind = 'badge' and c.id = bt.item
                cross join lateral (select coalesce(c.body ? 'retire_at', false) as retired) rt
               order by bt.day desc, bt.item, bt.subject) b), '[]'::jsonb),
    'achievements', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'id', a.item, 'name', coalesce(c.body ->> 'name', a.item), 'meaning', a.meaning, 'day', a.day, 'size', a.size,
               'caption', (public.career_award_spec('achievement', a.item, null, a.day, a.evidence, c.body)) ->> 'caption',
               'retired', case when c.body ? 'retire_at' then true end, 'superseded_by', c.body -> 'superseded_by')) order by a.day desc, a.item)
        from public.career_awards a left join public.career_catalogue c on c.kind = 'achievement' and c.id = a.item
       where a.athlete_id = v_id and a.kind = 'achievement'), '[]'::jsonb),
    'titles', coalesce((
      with ht as (
        select t.title as hab_id, t.earned_on as day,
               (select c0.id from public.career_catalogue c0 where c0.kind = 'title' and (c0.body ->> 'proof_id' = t.title or c0.id = t.title)
                 order by (c0.body ->> 'proof_id' = t.title) desc nulls last, c0.id limit 1) as cid
          from public.hab_titles t where t.athlete_id = v_id
        union all
        select coalesce(c1.body ->> 'proof_id', a.item), a.day, a.item
          from public.career_awards a left join public.career_catalogue c1 on c1.kind = 'title' and c1.id = a.item
         where a.athlete_id = v_id and a.kind = 'title'
           and not exists (select 1 from public.hab_titles t2 where t2.athlete_id = v_id and t2.title = coalesce(c1.body ->> 'proof_id', a.item))
      ),
      tt as (
        select ht.*, case when ht.hab_id like 't\_sn\_%' then 'season' end as season,
               coalesce(c.body, case when ht.hab_id like 't\_sn\_%' then (select s.body from public.career_catalogue s where s.kind = 'title' and s.id = 'season') end) as body
          from ht left join public.career_catalogue c on c.kind = 'title' and c.id = ht.cid
      )
      -- hab_id only when it differs from id (both apps read `hab_id || id`); empty keys left out (the size budget)
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'id', coalesce(tt.cid, case when tt.season is not null then 'season' end, tt.hab_id),
               'hab_id', nullif(tt.hab_id, coalesce(tt.cid, case when tt.season is not null then 'season' end, tt.hab_id)),
               'name', case when tt.season is not null
                            then coalesce((select r.season_name from public.hab_season_results r
                                            where r.athlete_id = v_id and to_char(r.starts_on, 'YYYYMMDD') = substr(tt.hab_id, 6) limit 1),
                                          tt.body ->> 'name', tt.hab_id)
                            else coalesce(tt.body ->> 'name', tt.hab_id) end,
               'meaning', case when tt.season is not null then 'season' else tt.body ->> 'meaning' end,
               'metal', tt.body ->> 'metal', 'from', tt.body ->> 'from', 'day', tt.day,
               -- source: 'award' or 'event' only, the two both apps read (syncCatalogueTitles(), catalogueTitles()); a road title
               -- (meaning 'level', or no catalogue row) and a season title (meaning 'season') say it by their meaning (the size budget)
               'source', case when tt.season is not null then null
                              when tt.body ->> 'meaning' = 'level' or tt.body is null then null
                              when tt.body ->> 'origin' = 'proof' then 'event'
                              else 'award' end)) order by tt.day, tt.hab_id)
        from tt), '[]'::jsonb),
    -- recent: the awards of the last 7 days (not the go-day's baseline), newest first, at most 10, each with its share spec; no created_at
    -- (the order is the server's)
    'recent', coalesce((
      select jsonb_agg(z.j order by z.created_at desc, z.award_id)
        from (select a.award_id, a.created_at,
                     jsonb_build_object('award_id', a.award_id, 'kind', a.kind, 'item', a.item, 'tier', a.tier, 'size', a.size, 'day', a.day,
                       'xp', case when not a.pays then 0 else a.xp /* stage76: minted XP */ end)
                     || jsonb_build_object('spec', public.career_award_spec(a.kind, a.item, a.tier, a.day, a.evidence, c.body)) as j
                from public.career_awards a left join public.career_catalogue c on c.kind = a.kind and c.id = a.item
               where a.athlete_id = v_id and a.how <> 'baseline' and a.created_at >= now() - interval '7 days'
               order by a.created_at desc, a.award_id limit 10) z), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.get_bell(p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.current_athlete_id();
  v_coach boolean := public.is_coach();
  v_report boolean := coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role');
  v_id text := coalesce(nullif(btrim(coalesce(p_athlete_id, '')), ''), v_me);
  v_from timestamptz := now() - interval '7 days';
  v_items jsonb; v_hon jsonb := null; v_m0 date := (date_trunc('month', current_date) - interval '1 month')::date;
  v_week jsonb; v_crew jsonb;
  v_pick jsonb := null;   -- stage100: Amir's Pick, the card on Crew for 7 days. stage102: the answer also carries 'weekly' (crew_weekly())
begin
  if v_id is null and not (v_coach or v_report) then
    raise exception 'not signed in';
  end if;
  if v_id is distinct from v_me and not (v_coach or v_report) then
    raise exception 'not your bell';
  end if;
  perform public.crew_sweep();

  with mem as (select * from public.crew_members()),
  on_kind as (select m.athlete_id, k.kind from mem m cross join unnest(public.crew_kind_list()) k(kind)
               where coalesce((m.kinds ->> k.kind)::boolean, true)),
  wk as (
    select f.athlete_id, f.kind, f.ref, f.day, f.created_at,
           count(*) filter (where f.kind = 'week_broken') over (partition by f.athlete_id order by f.day, f.ref rows unbounded preceding) as grp
      from public.career_facts f
     where f.athlete_id in (select athlete_id from mem) and f.void_at is null and f.kind in ('week_held', 'week_broken')),
  runs as (
    select wk.*, count(*) filter (where wk.kind = 'week_held') over (partition by wk.athlete_id, wk.grp order by wk.day, wk.ref rows unbounded preceding) as run
      from wk),
  parts as (
    select r.athlete_id, r.created_at as at, 'level' as kind, jsonb_build_object('k', 'level', 'n', (r.value ->> 'n')::int) as p
      from public.crew_rings r where r.kind = 'level' and r.created_at >= v_from
    union all
    select r.athlete_id, r.created_at, 'open', r.value || jsonb_build_object('k', 'open')
      from public.crew_rings r where r.kind = 'open' and r.created_at >= v_from
    union all
    select ru.athlete_id, ru.created_at, 'week', jsonb_build_object('k', 'week', 'run', ru.run)
      from runs ru where ru.kind = 'week_held' and ru.created_at >= v_from and ru.day >= current_date - 14
    union all
    select f.athlete_id, f.created_at, 'best', jsonb_build_object('k', 'best', 'lift', f.value ->> 'lift')
      from public.career_facts f
     where f.athlete_id in (select athlete_id from mem) and f.void_at is null and f.kind = 'personal_best'
       and f.day >= current_date - 14 and f.created_at >= v_from and nullif(btrim(f.value ->> 'lift'), '') is not null
    union all
    select f.athlete_id, f.created_at, 'cycle', jsonb_build_object('k', 'cycle', 'n', (f.value ->> 'cycle')::int)
      from public.career_facts f
     where f.athlete_id in (select athlete_id from mem) and f.void_at is null and f.kind = 'cycle_finished'
       and f.day >= current_date - 14 and f.created_at >= v_from
    union all
    select a.athlete_id, a.created_at,
           case when a.kind = 'badge' then 'mark' else 'achievement' end,
           case when a.kind = 'badge'
                then jsonb_build_object('k', 'mark', 'item', a.item,
                                        'at', (select (t.v ->> 'at')::int from public.career_catalogue c
                                                cross join lateral jsonb_array_elements(c.body -> 'tiers') with ordinality t(v, i)
                                                where c.kind = 'badge' and c.id = a.item and t.i = a.tier))
                else jsonb_build_object('k', 'achievement', 'id', a.item,
                                        'name', coalesce((select c.body ->> 'name' from public.career_catalogue c where c.kind = 'achievement' and c.id = a.item), a.item))
           end
      from public.career_awards a
     where a.athlete_id in (select athlete_id from mem) and a.how = 'live' and a.created_at >= v_from
       and (a.kind = 'achievement' or (a.kind = 'badge' and a.item in ('held_weeks', 'century', 'bests', 'comebacks')))
    union all
    select h.athlete_id, h.confirmed_at, 'honour', jsonb_build_object('k', 'honour', 'honour', h.honour, 'month', h.month)
      from public.career_honours h
     where h.athlete_id in (select athlete_id from mem) and h.honour not in ('near', 'pick') and h.confirmed_at >= v_from   -- stage100: a pick is its card, not a line
    union all
    select m.athlete_id, m.first_yes_at, 'joined', jsonb_build_object('k', 'joined')
      from mem m where m.first_yes_at >= v_from
  ),
  kept0 as (
    select p.*, (p.at at time zone 'UTC')::date as d
      from parts p join mem m on m.athlete_id = p.athlete_id
     where p.at >= coalesce(m.yes_since, p.at)
       and (p.kind = 'joined' or exists (select 1 from on_kind o where o.athlete_id = p.athlete_id and o.kind = p.kind))),
  kept as (
    select k.*, bool_or(k.kind = 'mark' and k.p ->> 'item' = 'held_weeks') over (partition by k.athlete_id, k.d) as hw_mark
      from kept0 k),
  lines as (
    select k.athlete_id, k.d, max(k.at) as at,
           max((k.p ->> 'n')::int) filter (where k.kind = 'level') as lvl,
           jsonb_agg(k.p order by k.at) filter (where k.kind in ('joined', 'mark', 'achievement', 'honour', 'open')) as rest,
           array_agg(distinct k.p ->> 'lift') filter (where k.kind = 'best') as lifts,
           max((k.p ->> 'run')::int) filter (where k.kind = 'week' and not k.hw_mark) as run,
           max((k.p ->> 'n')::int) filter (where k.kind = 'cycle') as cyc
      from kept k group by k.athlete_id, k.d),
  line_items as (
    select l.at, jsonb_build_object(
             't', 'line', 'key', m.crew_key::text || ':' || l.d::text, 'who', m.name, 'me', l.athlete_id is not distinct from v_id,
             'at', l.at,
             'parts', case when l.lvl is not null then jsonb_build_array(jsonb_build_object('k', 'level', 'n', l.lvl)) else '[]'::jsonb end
                      || coalesce(l.rest, '[]'::jsonb)
                      || case when l.lifts is not null then jsonb_build_array(jsonb_build_object('k', 'best', 'lifts', to_jsonb(l.lifts[1:3]),
                                                                                                  'more', greatest(0, cardinality(l.lifts) - 3))) else '[]'::jsonb end
                      || case when l.run is not null then jsonb_build_array(jsonb_build_object('k', 'week', 'run', l.run)) else '[]'::jsonb end
                      || case when l.cyc is not null then jsonb_build_array(jsonb_build_object('k', 'cycle', 'n', l.cyc)) else '[]'::jsonb end,
             'kudos', public.crew_kudos_of(null, l.athlete_id, l.d, v_id), 'fv', public.crew_face_v(l.athlete_id)) as j
      from lines l join mem m on m.athlete_id = l.athlete_id),
  -- the week's attendance, ONE item a day for the whole crew, never one line each. Grouped on the session's own `day`, from
  -- the day the athlete joined, so the 17 October back-pay cannot announce 39 sessions in an afternoon.
  sess as (
    select f.day as d, m.athlete_id, m.name, count(*) as n
      from public.career_facts f
      join mem m on m.athlete_id = f.athlete_id
     where f.void_at is null
       and f.kind in ('session_finished', 'session_finished_early', 'library_session')
       and f.day >= (current_date - 7) and f.day <= current_date
       and f.day >= coalesce((m.yes_since at time zone 'UTC')::date, f.day)
       and exists (select 1 from on_kind o where o.athlete_id = m.athlete_id and o.kind = 'session')
     group by f.day, m.athlete_id, m.name),
  sess_items as (
    select least(now(), ((s.d + 1)::timestamptz)) as at,
           jsonb_build_object(
             't', 'sess', 'key', 'sess:' || s.d::text, 'day', s.d,
             'n', sum(s.n),
             'names', coalesce(jsonb_agg(s.name order by lower(s.name)) filter (where s.athlete_id is distinct from v_id), '[]'::jsonb),
             'me', bool_or(s.athlete_id is not distinct from v_id)) as j
      from sess s group by s.d),
  post_items as (
    select p.created_at as at, (p.athlete_id = public.coach_note_id() and p.created_at >= now() - interval '24 hours') as pinned,
           jsonb_build_object(
             't', 'post', 'id', p.id, 'who', case when p.athlete_id = public.coach_note_id() then 'Amir' else m.name end,
             'me', p.athlete_id is not distinct from v_id, 'amir', p.athlete_id = public.coach_note_id(),
             'kind', p.kind, 'body', p.body, 'session', p.session, 'photo', p.has_photo,
             'w', ph.w, 'h', ph.h, 'at', p.created_at,
             'pinned', (p.athlete_id = public.coach_note_id() and p.created_at >= now() - interval '24 hours'),
             'left', greatest(0, ceil(extract(epoch from (p.created_at + interval '7 days' - now())) / 86400.0))::int,
             'kudos', public.crew_kudos_of(p.id, null, null, v_id), 'replies', public.crew_reply_rows(p.id, v_id)) || case when m.athlete_id is not null then jsonb_build_object('ck', m.crew_key, 'fv', public.crew_face_v(m.athlete_id)) else '{}'::jsonb end as j
      from public.crew_posts p
      left join mem m on m.athlete_id = p.athlete_id
      left join public.crew_photos ph on ph.post_id = p.id
     where p.created_at >= v_from and (p.athlete_id = public.coach_note_id() or m.athlete_id is not null)
     order by (p.athlete_id = public.coach_note_id() and p.created_at >= now() - interval '24 hours') desc, p.created_at desc
     limit 80)
  select coalesce(jsonb_agg(x.j order by x.pinned desc, x.at desc), '[]'::jsonb) into v_items
    from (select at, pinned, j from post_items
          union all select at, false, j from line_items
          union all select at, false, j from sess_items) x;

  -- the band's three numbers: the same 7 days as the Bell, the same switches, and nobody named.
  with mem as (select * from public.crew_members())
  select jsonb_build_object(
           'members', (select count(*) from mem),
           'sessions', (select count(*) from public.career_facts f join mem m on m.athlete_id = f.athlete_id
                         where f.void_at is null and f.kind in ('session_finished', 'session_finished_early', 'library_session')
                           and f.day >= (current_date - 7) and f.day <= current_date
                           and f.day >= coalesce((m.yes_since at time zone 'UTC')::date, f.day)
                           and coalesce((m.kinds ->> 'session')::boolean, true)),
           'held', (select count(*) from public.career_facts f join mem m on m.athlete_id = f.athlete_id
                     where f.void_at is null and f.kind = 'week_held'
                       and f.day >= (current_date - 7) and f.day <= current_date
                       and f.day >= coalesce((m.yes_since at time zone 'UTC')::date, f.day)
                       and coalesce((m.kinds ->> 'week')::boolean, true)))
    into v_week;

  -- who is in the room: names only. The level sits on the board, which the app keeps on the phone.
  with mem as (select * from public.crew_members())
  select coalesce(jsonb_agg(jsonb_build_object('who', m.name, 'me', m.athlete_id is not distinct from v_id,
                                               'since', (m.first_yes_at at time zone 'UTC')::date, 'ck', m.crew_key, 'fv', public.crew_face_v(m.athlete_id)) || public.crew_extra(m.athlete_id, m.kinds, m.yes_since, m.first_yes_at, v_id)
                            order by lower(m.name)), '[]'::jsonb)
    into v_crew from mem m;

  if extract(day from current_date) <= 14 and exists (select 1 from public.career_honour_months hm where hm.month = v_m0) then
    select jsonb_build_object('month', v_m0, 'rows', coalesce(jsonb_agg(jsonb_build_object('honour', h.honour, 'who', m.name, 'me', h.athlete_id is not distinct from v_id,
                                                                                         'value', h.value - 'slot', 'ck', m.crew_key) order by h.honour, m.name), '[]'::jsonb))
      into v_hon
      from public.career_honours h join public.crew_members() m on m.athlete_id = h.athlete_id
     where h.month = v_m0 and h.honour <> 'near' and h.confirmed_at is not null and coalesce((m.kinds ->> 'honour')::boolean, true);   -- stage101
  end if;

  -- stage100: Amir's Pick is a card on Crew for 7 days from the moment he picks (Amir, 2026-10-25: "make the card a bit smaller, and it should
  -- only stay for a week"), with his reason (`why`, written in Courtside). Only a crew member whose honours switch is on: anybody else's pick
  -- is on their own page alone. The newest pick wins if two months were picked inside one week.
  select jsonb_build_object('month', h.month, 'who', m.name, 'ck', m.crew_key, 'fv', public.crew_face_v(m.athlete_id),
                            'me', h.athlete_id is not distinct from v_id, 'why', nullif(btrim(coalesce(h.value ->> 'why', '')), ''),
                            'at', h.created_at, 'until', h.created_at + interval '7 days')
    into v_pick
    from public.career_honours h join public.crew_members() m on m.athlete_id = h.athlete_id
   where h.honour = 'pick' and h.confirmed_at is not null and h.created_at >= now() - interval '7 days' and coalesce((m.kinds ->> 'honour')::boolean, true)
   order by h.created_at desc
   limit 1;

  return jsonb_build_object('athlete_id', v_id, 'me', public.crew_me(v_id), 'items', v_items, 'honours', v_hon, 'pick', v_pick, 'weekly', public.crew_weekly(v_id), 'kinds', to_jsonb(public.crew_kind_list()),
                            'days', 7, 'emoji', to_jsonb(public.crew_emoji_list()), 'open', public.crew_open_now(v_id),
                            'week', v_week, 'crew', v_crew, 'lounge', 1, 'at', now());
end $function$;

CREATE OR REPLACE FUNCTION public.get_bell_if_new(p_athlete_id text DEFAULT NULL::text, p_etag text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb; v_tag text;
begin
  v := public.get_bell(p_athlete_id) - 'at';   -- the clock is not part of what the phone is holding
  v_tag := md5(v::text);
  if p_etag is not null and p_etag = v_tag then
    return jsonb_build_object('same', true, 'etag', v_tag, 'at', now());
  end if;
  return v || jsonb_build_object('etag', v_tag, 'at', now());
end $function$;

CREATE OR REPLACE FUNCTION public.get_course()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id   text;
  v_full boolean := false;
  v_open_lessons text[] := array['read-your-card', 'rpe-weights', 'tennis-demands'];
  v_open_tests   text[] := array['broad-jump'];
begin
  if public.is_coach() then
    v_full := true;
  else
    v_id := public.current_athlete_id();
    if v_id is not null then
      select coalesce(p.data->'athlete'->>'tier', '') <> 'free' into v_full
      from public.programs p where p.athlete_id = v_id;
      v_full := coalesce(v_full, false);
    end if;
  end if;

  return jsonb_build_object(
    'full', v_full,
    'lessons', coalesce((
      select jsonb_agg(
        case when v_full or c.id = any(v_open_lessons) then c.body
             else jsonb_strip_nulls(jsonb_build_object('id', c.body->'id', 'order', c.body->'order', 'group', c.body->'group',
               'icon', c.body->'icon', 'title', c.body->'title', 'summary', c.body->'summary',
               'audience', c.body->'audience', 'locked', true)) end
        order by c.sort, c.id)
      from public.course_en c where c.kind = 'lesson'), '[]'::jsonb),
    'tests', coalesce((
      select jsonb_agg(
        case when v_full or c.id = any(v_open_tests) then c.body
             else jsonb_strip_nulls(jsonb_build_object('id', c.body->'id', 'order', c.body->'order', 'icon', c.body->'icon',
               'title', c.body->'title', 'badge', c.body->'badge', 'why', c.body->'why', 'optional', c.body->'optional',
               'player', c.body->'player', 'calc', c.body->'calc', 'locked', true)) end
        order by c.sort, c.id)
      from public.course_en c where c.kind = 'test'), '[]'::jsonb),
    'day', (select c.body from public.course_en c where c.kind = 'testday' limit 1)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_courtside(p_from timestamp with time zone, p_to timestamp with time zone, p_not_clients text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then raise exception 'coach only'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '35 days' then
    raise exception 'get_courtside: give a window of at most 35 days (from %, to %)', p_from, p_to;
  end if;
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(jsonb_build_object(
             'athlete_id', a.athlete_id, 'award_id', a.award_id, 'kind', a.kind, 'item', a.item, 'tier', a.tier, 'day', a.day,
             'size', a.size, 'at', a.created_at,
             'spec', public.career_award_spec(a.kind, a.item, a.tier, a.day, a.evidence, c.body),
             'evidence', a.evidence,
             'facts', (select coalesce(jsonb_agg(jsonb_build_object('kind', f.kind, 'ref', f.ref, 'day', f.day, 'value', f.value)), '[]'::jsonb)
                         from jsonb_array_elements(coalesce(a.evidence -> 'facts', '[]'::jsonb)) e(x)
                         join public.career_facts f on f.athlete_id = a.athlete_id and f.kind = e.x ->> 'kind' and f.ref = e.x ->> 'ref'),
             'saw_at', m.saw_at, 'sent_at', m.sent_at)
           order by a.created_at desc, a.award_id)
      from public.career_awards a
      left join public.career_catalogue c on c.kind = a.kind and c.id = a.item
      left join public.courtside_marks m on m.athlete_id = a.athlete_id and m.award_id = a.award_id
     where a.how = 'live' and a.created_at >= p_from and a.created_at < p_to
       and a.size in ('highlight', 'milestone', 'legend')
       and (a.kind = 'achievement' or (a.kind = 'badge' and a.item in ('held_weeks', 'century', 'bests', 'comebacks')))
       and public.career_is_client(a.athlete_id, p_not_clients)), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.get_exercises()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id, 'name', e.name, 'aliases', e.aliases, 'pattern', e.pattern,
           'qualities', e.qualities, 'purpose', e.purpose, 'tennis', e.tennis,
           'cues', e.cues, 'equipment', e.equipment, 'loads', e.loads, 'impact', e.impact,
           'easier', e.easier, 'harder', e.harder, 'alts', e.alts, 'video', e.video,
           -- stage64: How to do it, [] when none
           'steps', to_jsonb(coalesce(e.steps, '{}'::text[])),
           -- stage42: muscle names and 1/0.5 only. Never cost, sfr or flags.
           'muscles', coalesce(nullif(c.credits, '{}'::jsonb), e.muscles)
         ) order by e.name), '[]'::jsonb)
  from public.exercises e
  left join public.exercise_coach c on c.id = e.id
  where e.status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.get_exercises_fa()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id, 'name', e.name, 'video', e.video,
           'steps', to_jsonb(coalesce(e.steps_fa, '{}'::text[])), 'cues', e.cues_fa,
           'purpose', e.purpose_fa, 'tennis', e.tennis_fa) order by e.id), '[]'::jsonb)
  from public.exercises e
  where e.status = 'approved'
    and (cardinality(e.steps_fa) > 0 or e.cues_fa is not null or e.purpose_fa is not null or e.tennis_fa is not null);
$function$;

CREATE OR REPLACE FUNCTION public.get_inbox(p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- stage101 (idea #90): the signed-in athlete's own Inbox. Never anybody else's: there is no athlete argument.
declare
  v_me text := public.current_athlete_id();
  v_floor timestamptz := now() - interval '7 days';
  v_since timestamptz := greatest(coalesce(p_since, now() - interval '7 days'), now() - interval '7 days');
  v_coach text := public.coach_note_id();
  v_rows jsonb;
  v_q boolean := to_regclass('public.crew_questions') is not null;
  v_ans jsonb := '[]'::jsonb;
begin
  if v_me is null then raise exception 'not signed in'; end if;

  if v_q then
    execute $q$
      select coalesce(jsonb_agg(jsonb_build_object('k', 'answer', 'at', q.answered_at, 'who', 'Amir', 'amir', true,
                                                   'q', left(q.body, 120), 'post', q.answer_post) order by q.answered_at desc), '[]'::jsonb)
        from public.crew_questions q
       where q.athlete_id = $1 and q.answered_at is not null and q.answered_at >= $2 $q$
      into v_ans using v_me, v_floor;
  end if;

  with mem as (select * from public.crew_members()),
  who as (
    select m.athlete_id, m.name, m.crew_key, public.crew_face_v(m.athlete_id) as fv from mem m
  ),
  cheers as (
    select c.created_at as at, jsonb_build_object('k', 'cheer', 'at', c.created_at,
             'who', case when c.athlete_id = v_coach then 'Amir' else w.name end, 'amir', c.athlete_id = v_coach,
             'ck', w.crew_key, 'fv', w.fv, 'word', c.word,
             -- once a day each: whether a cheer back can still go today
             'back', c.athlete_id <> v_coach and w.crew_key is not null
                     and not exists (select 1 from public.crew_cheers b where b.athlete_id = v_me and b.to_athlete = c.athlete_id and b.day = current_date)) as j
      from public.crew_cheers c left join who w on w.athlete_id = c.athlete_id
     where c.to_athlete = v_me and c.athlete_id <> v_me and c.created_at >= v_floor
       and (c.athlete_id = v_coach or w.athlete_id is not null)),
  replies as (
    select r.created_at as at, jsonb_build_object('k', 'reply', 'at', r.created_at,
             'who', case when r.athlete_id = v_coach then 'Amir' else w.name end, 'amir', r.athlete_id = v_coach,
             'ck', w.crew_key, 'fv', w.fv, 'body', left(r.body, 90), 'post', r.post_id, 'reply', r.id) as j
      from public.crew_replies r join public.crew_posts p on p.id = r.post_id
      left join who w on w.athlete_id = r.athlete_id
     where p.athlete_id = v_me and r.athlete_id <> v_me and r.created_at >= v_floor
       and (r.athlete_id = v_coach or w.athlete_id is not null)),
  mentions as (
    select m.created_at as at, jsonb_build_object('k', 'mention', 'at', m.created_at,
             'who', case when m.athlete_id = v_coach then 'Amir' else w.name end, 'amir', m.athlete_id = v_coach,
             'ck', w.crew_key, 'fv', w.fv, 'body', left(r.body, 90), 'post', r.post_id, 'reply', r.id) as j
      from public.crew_mentions m join public.crew_replies r on r.id = m.reply_id
      join public.crew_posts p on p.id = r.post_id
      left join who w on w.athlete_id = m.athlete_id
     where m.to_athlete = v_me and m.athlete_id <> v_me and m.created_at >= v_floor
       and p.athlete_id <> v_me                         -- a reply on MY post that names me is already its reply row
       and (m.athlete_id = v_coach or w.athlete_id is not null)),
  likes as (
    select max(k.created_at) as at, jsonb_build_object('k', 'like', 'at', max(k.created_at), 'n', count(*),
             'who', to_jsonb((array_agg(case when k.athlete_id = v_coach then 'Amir' else w.name end order by k.created_at desc))[1:2]),
             'faces', coalesce(jsonb_agg(jsonb_build_object('ck', w.crew_key, 'fv', w.fv, 'who', w.name) order by k.created_at desc) filter (where w.crew_key is not null), '[]'::jsonb),
             'post', k.post_id, 'day', k.line_day,
             'body', (select left(p.body, 60) from public.crew_posts p where p.id = k.post_id)) as j
      from public.crew_kudos k left join who w on w.athlete_id = k.athlete_id
     where k.to_athlete = v_me and k.athlete_id <> v_me and k.created_at >= v_floor
       and (k.athlete_id = v_coach or w.athlete_id is not null)
     group by k.post_id, k.line_day),
  award_likes as (
    select max(a.created_at) as at, jsonb_build_object('k', 'award_like', 'at', max(a.created_at), 'n', count(*),
             'who', to_jsonb((array_agg(w.name order by a.created_at desc))[1:2]), 'award', a.award_id,
             -- an award_id is "<kind>:<catalogue id>", e.g. achievement:lights_out
             'name', (select c.body ->> 'name' from public.career_catalogue c
                       where c.kind = split_part(a.award_id, ':', 1) and c.id = split_part(a.award_id, ':', 2) limit 1)) as j
      from public.crew_award_likes a join who w on w.athlete_id = a.athlete_id
     where a.to_athlete = v_me and a.athlete_id <> v_me and a.created_at >= v_floor
     group by a.award_id),
  joins as (
    select m.first_yes_at as at, jsonb_build_object('k', 'join', 'at', m.first_yes_at, 'who', w.name, 'ck', w.crew_key, 'fv', w.fv) as j
      from mem m join who w on w.athlete_id = m.athlete_id
     where m.athlete_id <> v_me and m.first_yes_at >= v_floor)
  select coalesce(jsonb_agg(x.j order by x.at desc), '[]'::jsonb) into v_rows
    from (select at, j from cheers union all select at, j from replies union all select at, j from mentions
          union all select at, j from likes union all select at, j from award_likes union all select at, j from joins
          union all select (e ->> 'at')::timestamptz, e from jsonb_array_elements(v_ans) e
          order by 1 desc limit 60) x;

  return jsonb_build_object('since', v_since, 'rows', v_rows,
                            'new', (select count(*) from jsonb_array_elements(v_rows) r where (r ->> 'at')::timestamptz > v_since),
                            'at', now());
end $function$;

CREATE OR REPLACE FUNCTION public.get_library(p_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(kind, cats), '{}'::jsonb)
  from (
    select c.kind,
           jsonb_agg(
             jsonb_build_object(
               'id', c.id, 'title', c.title, 'banner', c.banner, 'icon', c.icon,
               'items', coalesce((
                 select jsonb_agg(l.data order by coalesce(l.sort_order, 2147483647), l.slug)
                 from public.library l
                 where l.kind = c.kind and l.category_id = c.id and l.published
               ), '[]'::jsonb)
             )
             order by coalesce(c.sort_order, 2147483647), c.id
           ) as cats
    from public.library_categories c
    where p_kind is null or c.kind = p_kind
    group by c.kind
  ) t;
$function$;

CREATE OR REPLACE FUNCTION public.get_library_days(p_athlete_id text, p_since date DEFAULT NULL::date)
 RETURNS TABLE(completed_on date, counts_as text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() then
    raise exception 'not your athlete record';
  end if;

  return query
    select distinct s.completed_on, s.counts_as
    from public.library_sessions s
    where s.athlete_id = p_athlete_id
      and s.counts_as is not null
      and (p_since is null or s.completed_on >= p_since)
    order by 1, 2;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_messages(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS SETOF messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return query
    select * from public.messages where athlete_id = p_athlete_id order by created_at asc;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_my_history(p_athlete_id text, p_days integer DEFAULT 180)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if p_athlete_id = 'demo' then
    return '[]'::jsonb;
  end if;
  -- coalesce: a NULL id must be refused, not slip through a NULL comparison.
  if not coalesce(public.is_coach() or p_athlete_id = public.current_athlete_id(), false) then
    raise exception 'not allowed';
  end if;
  select coalesce(jsonb_agg(r order by r.completed_on desc, r.day desc), '[]'::jsonb) into v
  from (
    select s.completed_on, s.day, s.focus, s.session_rpe,
           s.readiness->'composite' as readiness,
           s.readiness as ready,
           s.log,
           case when s.log is null then s.summary end as summary
    from public.session_history s
    where s.athlete_id = p_athlete_id
      and s.hidden_at is null
      and s.completed_on >= current_date - greatest(1, least(coalesce(p_days, 180), 400))
    order by s.completed_on desc, s.day desc
    limit 120
  ) r;
  return v;
end $function$;

CREATE OR REPLACE FUNCTION public.get_my_moments(p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.current_athlete_id();
  v_id text := coalesce(nullif(btrim(coalesce(p_athlete_id, '')), ''), v_me);
  m0 date := date_trunc('month', current_date)::date;
begin
  if v_id is null then
    raise exception 'not signed in';
  end if;
  if not (public.is_coach() or v_id is not distinct from v_me or coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role')) then
    raise exception 'not your profile';
  end if;
  return jsonb_build_object(
    'athlete_id', v_id,
    'goal', (select jsonb_build_object('month', g.month, 'line', g.line, 'done_at', g.done_at)
               from public.career_goals g where g.athlete_id = v_id and g.month = m0),
    'goals', (select coalesce(jsonb_agg(jsonb_build_object('month', g.month, 'line', g.line, 'done_at', g.done_at) order by g.month desc), '[]'::jsonb)
                from public.career_goals g where g.athlete_id = v_id),
    'notes', (select coalesce(jsonb_agg(jsonb_build_object('day', n.day, 'line', n.line, 'award_id', n.award_id, 'read', n.read_at is not null)
                                        order by n.day desc), '[]'::jsonb)
                from public.career_notes n where n.athlete_id = v_id),
    'saw', (select coalesce(jsonb_agg(m.award_id order by m.award_id), '[]'::jsonb)
              from public.courtside_marks m where m.athlete_id = v_id and m.saw_at is not null),
    'honours', (select coalesce(jsonb_agg(jsonb_build_object('month', h.month, 'honour', h.honour, 'value', h.value) order by h.month desc, h.honour), '[]'::jsonb)
                  from public.career_honours h where h.athlete_id = v_id and h.honour <> 'near' and h.confirmed_at is not null))   /* stage101: confirmed only */;
end $function$;

CREATE OR REPLACE FUNCTION public.get_profile(p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.current_athlete_id();
  v_id text := coalesce(nullif(btrim(coalesce(p_athlete_id, '')), ''), v_me);
  v_rules jsonb; v_score jsonb; v_now integer := 0; v_best integer := 0; f record; v_xp date; v_rw jsonb; v_rp jsonb; v_out jsonb;
begin
  if v_id is null then
    raise exception 'not signed in';
  end if;
  -- the athlete reads their own, the coach anyone's, and so does the SQL editor or the service role (no sign-in claims: a report)
  if not (public.is_coach() or v_id is not distinct from v_me or coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role')) then
    raise exception 'not your profile';
  end if;
  v_rules := public.career_rules_now();
  if v_rules is null then
    return jsonb_build_object('athlete_id', v_id, 'ready', false);
  end if;
  perform public.career_derive(v_id);
  begin
    v_rw := public.career_evaluate(v_id, null, 'live');
  exception when others then
    raise warning 'Career Mode could not work out the awards of %: % (%). The profile is answered from the stored cache.', v_id, sqlerrm, sqlstate;
    v_rw := null;
  end;
  v_score := coalesce(public.career_scored(v_id), '{}'::jsonb);
  v_xp := public.career_switch_day(v_rules, 'xp');
  -- weeks held in a row: only a broken week ends a run (a week between cycles, or one Amir paused, is no week at all)
  for f in select cf.kind from public.career_facts cf
            where cf.athlete_id = v_id and cf.void_at is null and cf.kind in ('week_held', 'week_broken')
            order by cf.day, cf.ref loop
    if f.kind = 'week_held' then v_now := v_now + 1; v_best := greatest(v_best, v_now); else v_now := 0; end if;
  end loop;
  v_out := jsonb_build_object(
    'athlete_id', v_id,
    'ready', true,
    'shadow', v_xp is null,
    'switch', jsonb_build_object('xp', v_xp, 'catalogue', public.career_switch_day(v_rules, 'catalogue')),
    'rules_version', (select max(r.version) from public.career_rules r),
    'career', (v_score -> 'career') - 'rank',   -- stage78: no rank name
    'season', v_score -> 'season',
    'week', v_score -> 'week',
    'since', (select min(cf.day) from public.career_facts cf
               where cf.athlete_id = v_id and cf.void_at is null
                 and cf.kind in ('habit_day', 'session_finished', 'session_finished_early', 'library_session')),
    'kept', (select cf.value from public.career_facts cf
              where cf.athlete_id = v_id and cf.kind = 'level_kept' and cf.ref = 'xp-switch' and cf.void_at is null),
    'numbers', (select jsonb_build_object(
                  'weeks_held', jsonb_build_object('now', v_now, 'best', v_best),
                  'sessions_with_amir', count(*) filter (where cf.kind in ('session_finished', 'session_finished_early')),
                  'personal_bests', count(*) filter (where cf.kind = 'personal_best'),
                  'comebacks', count(*) filter (where cf.kind = 'comeback'),
                  'days_on_target', count(*) filter (where cf.kind = 'day_on_target'),
                  'perfect_days', count(*) filter (where cf.kind = 'perfect_day'))
                  from public.career_facts cf where cf.athlete_id = v_id and cf.void_at is null),
    'rules', jsonb_build_object(
      'version', (select max(r.version) from public.career_rules r),
      'level', jsonb_build_object('base', v_rules #> '{level,base}', 'growth', v_rules #> '{level,growth}',
                                  'levels_per_rank', v_rules #> '{level,levels_per_rank}', 'prestige_after', v_rules #> '{level,prestige_after}'),   -- stage78: no rank names
      'season', '{}'::jsonb,   -- stage78: no season title
      'prices', coalesce((select jsonb_object_agg(k.key, public.career_num(v_rules #> array['fact', k.key, 'xp']))
                            from unnest(array['session_finished', 'session_finished_early', 'full_log', 'checkin_done', 'week_held',
                                              'bounce_back', 'training_return', 'library_session', 'retest_done', 'day_on_target', 'perfect_day']) as k(key)
                           where public.career_num(v_rules #> array['fact', k.key, 'xp']) is not null), '{}'::jsonb)),
    'badges', '[]'::jsonb, 'achievements', '[]'::jsonb, 'missions', '[]'::jsonb, 'quest', null, 'moments', '[]'::jsonb
  );
  v_rp := public.career_rewards_profile(v_id, v_rw);
  return v_out || (v_rp - 'numbers' - 'slam' - 'title_worn' - 'titles_owned')   -- stage78
         || case when v_rp ? 'numbers' then jsonb_build_object('numbers', (v_out -> 'numbers') || (v_rp -> 'numbers')) else '{}'::jsonb end;
end $function$;

CREATE OR REPLACE FUNCTION public.get_program(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_data jsonb;
begin
  -- 'demo' is the public showcase (synthetic athlete), linked openly from the site
  -- and opened by people who have no key and never will.
  if p_athlete_id = 'demo'
     or public.is_coach()
     or p_athlete_id = public.current_athlete_id() then
    select data into v_data from public.programs where athlete_id = p_athlete_id;
    return v_data;
  end if;

  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if v_expected is null or p_key is null or p_key is distinct from v_expected then
    raise exception 'invalid athlete key';
  end if;

  select data into v_data from public.programs where athlete_id = p_athlete_id;
  return v_data;
end $function$;

CREATE OR REPLACE FUNCTION public.get_progress(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_data jsonb;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  select data into v_data from public.athlete_progress where athlete_id = p_athlete_id;
  return coalesce(v_data, '{}'::jsonb);
end; $function$;

CREATE OR REPLACE FUNCTION public.get_qualities()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', q.id, 'name', q.name, 'family', q.family, 'line', q.line,
           'tennis', q.tennis, 'tests', q.tests, 'sort', q.sort
         ) order by q.sort), '[]'::jsonb)
  from public.qualities q
  where q.status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.get_quests(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(pool jsonb, runs jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_rules jsonb;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return; end if;
  return query select coalesce(v_rules -> 'quests', '[]'::jsonb),
                      coalesce(v_rules -> 'questRuns', '[]'::jsonb);
end; $function$;

CREATE OR REPLACE FUNCTION public.get_season(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(name text, starts_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return query select * from public.current_season();
end; $function$;

CREATE OR REPLACE FUNCTION public.get_workout_days(p_athlete_id text, p_key text DEFAULT NULL::text, p_since date DEFAULT NULL::date)
 RETURNS SETOF date
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  -- A row exists here only because the athlete pressed "Finish Session", so
  -- every row counts — a partly-finished session still means they showed up.
  -- A row the coach has hidden does not count (stage60).
  return query
    select distinct s.completed_on
    from public.session_history s
    where s.athlete_id = p_athlete_id
      and s.completed_on is not null
      and s.hidden_at is null
      and (p_since is null or s.completed_on >= p_since)
    order by 1;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_bonus_xp(p_log jsonb, p_cfg jsonb, p_season_start date, p_from date, p_to date, p_rules jsonb)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
AS $function$
with
  bonusmult as (
    select coalesce((p_rules ->> 'completionBonus')::numeric, 1.2) as cb,
           coalesce((p_rules ->> 'customXp')::numeric, 25) as cx,
           coalesce((p_rules ->> 'streakQualifyPct')::numeric, 80) as qpct,
           coalesce((p_rules ->> 'gateV2')::boolean, false) as gate2,
           coalesce((p_rules ->> 'lapseDays')::int, 3) as lapse,
           coalesce((p_rules ->> 'comebackXp')::numeric, 0) as cbxp,
           coalesce((p_rules ->> 'comebackStick')::int, 7) as stick
  ),
  dl as (
    select (e.key)::date as d, e.value as vals
    from jsonb_each(coalesce(p_log, '{}'::jsonb)) e
    where e.key ~ '^\d{4}-\d{2}-\d{2}$'
      and jsonb_typeof(e.value) = 'object'
      and (p_season_start is null or (e.key)::date >= p_season_start)
  ),
  habits as (
    select t.key as hid, t.value::numeric as tgt, b.cx as fallback
    from jsonb_each_text(coalesce(p_rules -> 'targets', '{}'::jsonb)) t, bonusmult b
    union all
    select c.value ->> 'id', 1::numeric, b.cx
    from jsonb_array_elements(coalesce(p_cfg -> 'custom', '[]'::jsonb)) c, bonusmult b
    where c.value ->> 'id' is not null
  ),
  weighted as (
    select h.hid, h.tgt,
           coalesce((p_rules -> 'weights' ->> h.hid)::numeric, h.fallback) as w
    from habits h
  ),
  dayroster as (
    select dl.d,
           (select r.value -> 'ids'
              from jsonb_array_elements(coalesce(p_cfg -> 'roster', '[]'::jsonb)) r(value)
             where (r.value ->> 'from')::date <= dl.d
             order by (r.value ->> 'from')::date desc limit 1) as ids
    from dl
  ),
  daylive as (
    select dr.d, w.hid, w.tgt, w.w,
           jsonb_exists(coalesce(p_rules -> 'unearnable', '[]'::jsonb), w.hid) as lockd
    from dayroster dr cross join weighted w
    where case when dr.ids is null
               then coalesce(p_cfg -> 'on' ->> w.hid, 'true') <> 'false'
               else jsonb_exists(dr.ids, w.hid) end
  ),
  done as (
    select w.hid, dl.d from dl cross join weighted w
    where jsonb_typeof(dl.vals -> w.hid) = 'number' and (dl.vals ->> w.hid)::numeric >= w.tgt
  ),
  islands as (
    select hid, d, d - (row_number() over (partition by hid order by d))::int as grp from done
  ),
  runlen as (
    select hid, d, (row_number() over (partition by hid, grp order by d))::int as run from islands
  ),
  hitno as (
    select hid, d, (row_number() over (partition by hid order by d))::int as n from done
  ),
  perday as (
    select dl.d, dl.vals,
           count(dv.hid) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt)::int as ndone,
           count(dv.hid)::int as nlive,
           coalesce(sum(dv.w) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt), 0) as wdone,
           coalesce(sum(dv.w) filter (
             where (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                    and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
                or not dv.lockd), 0) as glive,
           coalesce(sum(
             case when jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt
                  then dv.w
                  when dv.lockd then 0
                  when dv.tgt > 0 and jsonb_typeof(dl.vals -> dv.hid) = 'number'
                       and (dl.vals ->> dv.hid)::numeric > 0
                  then dv.w * least((dl.vals ->> dv.hid)::numeric / dv.tgt, 1)
                  else 0 end), 0) as gpart,
           count(dv.hid) filter (
             where not (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
               and not dv.lockd)::int as gmiss
    from dl left join daylive dv on dv.d = dl.d
    group by dl.d, dl.vals
  ),
  qualday as (
    select p.d
    from perday p, bonusmult b
    where case when b.gate2
               then (p.glive > 0 and round(p.gpart / p.glive * 100) >= b.qpct)
                     or (p.gmiss <= 1 and p.gpart > 0)
               else p.glive > 0 and round(p.wdone / p.glive * 100) >= b.qpct
          end
  ),
  qgap as (
    select d, (d - lag(d) over (order by d) - 1) as gone from qualday
  ),
  qisl as (
    select d, d - (row_number() over (order by d))::int as grp from qualday
  ),
  qrun as (
    select grp, min(d) as startd, count(*)::int as runlen from qisl group by grp
  ),
  comeback as (
    select g.d, g.gone, r.runlen
    from qgap g join qrun r on r.startd = g.d, bonusmult b
    where b.lapse > 0 and g.gone >= b.lapse
  ),
  comeback_paid as (
    select sum(b.cbxp) as xp
    from comeback c, bonusmult b
    where (p_from is null or c.d >= p_from) and (p_to is null or c.d <= p_to)
  ),
  cb_run_at as (
    select c.d + i as d, i + 1 as run
    from comeback c, generate_series(0, c.runlen - 1) as i
  ),
  cb_run_no as (
    select d, max(run) over (order by d) as n from cb_run_at
  ),
  cb_stuck_no as (
    select c.d + (b.stick - 1) as d,
           (row_number() over (order by c.d))::int as n
    from comeback c, bonusmult b
    where c.runlen >= b.stick
  ),
  with3 as (select d, (row_number() over (order by d))::int as n from perday where ndone >= 3),
  perfect as (
    select p.d, (row_number() over (order by p.d))::int as n
    from perday p where p.nlive > 0 and p.ndone >= p.nlive
  ),
  tiers as (
    select (t.ord - 1)::int as idx, (t.val ->> 'days')::int as days, (t.val ->> 'mult')::numeric as mult
    from jsonb_array_elements(coalesce(p_rules -> 'tiers', '[]'::jsonb)) with ordinality t(val, ord)
  ),
  tier_cross as (
    select rl.hid, tr.idx, tr.mult, min(rl.d) as crossed
    from runlen rl join tiers tr on rl.run >= tr.days group by rl.hid, tr.idx, tr.mult
  ),
  tier_paid as (
    select sum(greatest(10, round(w.w * b.cb * tc.mult / 10) * 10)) as xp
    from tier_cross tc join weighted w on w.hid = tc.hid cross join bonusmult b
    where (p_from is null or tc.crossed >= p_from) and (p_to is null or tc.crossed <= p_to)
  ),
  ms as (
    select m.val ->> 'code' as code, (m.val ->> 'need')::int as need,
           (m.val ->> 'xp')::numeric as xp, m.val ->> 'measure' as measure
    from jsonb_array_elements(coalesce(p_rules -> 'milestones', '[]'::jsonb)) m(val)
  ),
  ms_cross as (
    select m.code, m.xp, min(rl.d) as crossed
    from ms m join runlen rl on m.measure = 'streak:' || rl.hid and rl.run >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(hn.d) from ms m join hitno hn on m.measure = 'daysHit:' || hn.hid and hn.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(w3.d) from ms m join with3 w3 on m.measure = 'daysWith3' and w3.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(pf.d) from ms m join perfect pf on m.measure = 'perfectDays' and pf.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(cr.d) from ms m join cb_run_no cr on m.measure = 'comebackRun' and cr.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(cs.d) from ms m join cb_stuck_no cs on m.measure = 'comebacksStuck' and cs.n >= m.need group by m.code, m.xp
  ),
  ms_paid as (
    select sum(xp) as xp from ms_cross
    where (p_from is null or crossed >= p_from) and (p_to is null or crossed <= p_to)
  ),
  qruns as (
    select rstart,
           least(rstart + 6, coalesce(next_start - 1, rstart + 6), coalesce(own_end, rstart + 6)) as rend,
           ids
    from (
      select (r.val ->> 'start')::date as rstart,
             r.val -> 'ids' as ids,
             case when r.val ->> 'end' ~ '^\d{4}-\d{2}-\d{2}$' then (r.val ->> 'end')::date end as own_end,
             lead((r.val ->> 'start')::date) over (order by (r.val ->> 'start')::date) as next_start
      from jsonb_array_elements(coalesce(p_rules -> 'questRuns', '[]'::jsonb)) r(val)
      where r.val ->> 'start' ~ '^\d{4}-\d{2}-\d{2}$'
    ) q
  ),
  rq as (
    select qr.rstart, qr.rend, pq.val as quest
    from qruns qr
    join jsonb_array_elements(coalesce(p_rules -> 'quests', '[]'::jsonb)) pq(val)
      on jsonb_exists(qr.ids, pq.val ->> 'id')
  ),
  dh as (
    select qr.rstart, w.hid, dl.d,
           (row_number() over (partition by qr.rstart, w.hid order by dl.d))::int as n
    from qruns qr join dl on dl.d between qr.rstart and qr.rend cross join weighted w
    where jsonb_typeof(dl.vals -> w.hid) = 'number' and (dl.vals ->> w.hid)::numeric >= w.tgt
  ),
  tot as (
    select qr.rstart, w.hid, dl.d,
           sum(case when jsonb_typeof(dl.vals -> w.hid) = 'number'
                    then (dl.vals ->> w.hid)::numeric else 0 end)
             over (partition by qr.rstart, w.hid order by dl.d) as acc
    from qruns qr join dl on dl.d between qr.rstart and qr.rend cross join weighted w
  ),
  qd as (
    select qr.rstart, q.d,
           (row_number() over (partition by qr.rstart order by q.d))::int as n
    from qruns qr join qualday q on q.d between qr.rstart and qr.rend
  ),
  pfw as (
    select qr.rstart, p.d,
           (row_number() over (partition by qr.rstart order by p.d))::int as n
    from qruns qr join perday p on p.d between qr.rstart and qr.rend
    where p.nlive > 0 and p.ndone >= p.nlive
  ),
  quest_cross as (
    select rq.rstart, rq.quest ->> 'id' as qid, (rq.quest ->> 'xp')::numeric as xp, min(dh.d) as crossed
    from rq join dh on dh.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'daysHit:' || dh.hid and dh.n >= (rq.quest ->> 'need')::int
    group by 1,2,3
    union all
    select rq.rstart, rq.quest ->> 'id', (rq.quest ->> 'xp')::numeric, min(tot.d)
    from rq join tot on tot.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'total:' || tot.hid and tot.acc >= (rq.quest ->> 'need')::numeric
    group by 1,2,3
    union all
    select rq.rstart, rq.quest ->> 'id', (rq.quest ->> 'xp')::numeric, min(qd.d)
    from rq join qd on qd.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'qualify' and qd.n >= (rq.quest ->> 'need')::int
    group by 1,2,3
    union all
    select rq.rstart, rq.quest ->> 'id', (rq.quest ->> 'xp')::numeric, min(pfw.d)
    from rq join pfw on pfw.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'perfect' and pfw.n >= (rq.quest ->> 'need')::int
    group by 1,2,3
  ),
  quest_paid as (
    select sum(xp) as xp from quest_cross
    where (p_from is null or crossed >= p_from) and (p_to is null or crossed <= p_to)
  )
select (coalesce((select xp from tier_paid), 0)
      + coalesce((select xp from ms_paid), 0)
      + coalesce((select xp from quest_paid), 0)
      + coalesce((select xp from comeback_paid), 0))::bigint;
$function$;

CREATE OR REPLACE FUNCTION public.hab_career_level(p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb; v_data jsonb; v_xp bigint;
begin
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return 1; end if;
  select data into v_data from public.athlete_progress where athlete_id = p_athlete_id;
  if v_data is null then return 1; end if;
  v_xp := public.hab_xp(public.hab_log_of(v_data, p_athlete_id),
                        '1970-01-01'::date, current_date, v_rules)
        + public.hab_bonus_xp(public.hab_log_of(v_data, p_athlete_id),
                              public.hab_cfg_of(v_data, p_athlete_id),
                              '1970-01-01'::date, '1970-01-01'::date, current_date, v_rules);
  return public.hab_level(v_xp, v_rules);
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_cfg_of(p_data jsonb, p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare t text;
begin
  if p_data is null then return null; end if;
  t := p_data ->> (p_athlete_id || '_hab_cfg');
  if t is null or btrim(t) = '' then return null; end if;
  begin
    return t::jsonb;
  exception when others then
    return null;
  end;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_clean_note(p_body text, p_max integer DEFAULT 200)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare t text;
begin
  t := coalesce(p_body, '');
  t := regexp_replace(t, '[<>"''\\]', '', 'g');
  t := regexp_replace(t, '\s+', ' ', 'g');
  t := btrim(t);
  return left(t, greatest(1, p_max));
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_close_season(p_ended_on date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_start date; v_rules jsonb; v_n integer := 0;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;

  select name, starts_on into v_name, v_start from public.current_season();
  if v_start is null then return 0; end if;
  if p_ended_on < v_start then
    raise exception 'a season cannot end (%) before it started (%)', p_ended_on, v_start;
  end if;
  if p_ended_on > current_date then
    raise exception 'cannot archive a season that has not finished yet (ends %, today is %)',
                    p_ended_on, current_date;
  end if;
  -- stage78: the season is archived with no title (titles are gone, round 5, L5)

  if public.career_xp_on() then
    v_rules := public.career_rules_now();
    with who as (
      select distinct f.athlete_id as id from public.career_facts f where f.void_at is null
    ),
    scored as (
      select w.id,
             (public.career_score(w.id, v_start, v_start, p_ended_on) ->> 'xp')::bigint as pts,
             (public.career_score(w.id, null, null, p_ended_on) ->> 'xp')::bigint as cxp
        from who w
    )
    insert into public.hab_season_results (athlete_id, starts_on, season_name, ended_on, level, xp)
    select s.id, v_start, v_name, p_ended_on, (public.career_level(s.cxp, v_rules) ->> 'level')::int, s.pts
      from scored s
     where s.pts > 0
    on conflict (athlete_id, starts_on) do nothing;
    get diagnostics v_n = row_count;
    return v_n;
  end if;

  select rules into v_rules from public.xp_rules where id = 1;

  with scored as (
    select a.athlete_id,
           public.hab_xp(public.hab_log_of(a.data, a.athlete_id), v_start, p_ended_on, v_rules)
         + public.hab_bonus_xp(public.hab_log_of(a.data, a.athlete_id),
                               public.hab_cfg_of(a.data, a.athlete_id),
                               v_start, v_start, p_ended_on, v_rules) as xp
    from public.athlete_progress a
    where a.data ? (a.athlete_id || '_hab_log')
  )
  insert into public.hab_season_results (athlete_id, starts_on, season_name, ended_on, level, xp)
  select s.athlete_id, v_start, v_name, p_ended_on,
         public.hab_level(s.xp::bigint, v_rules), s.xp
  from scored s
  where s.xp > 0
  on conflict (athlete_id, starts_on) do nothing;
  get diagnostics v_n = row_count;

  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.hab_hash(p_s text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare h bigint := 0; i int;
begin
  for i in 1 .. length(p_s) loop
    h := (h * 31 + ascii(substr(p_s, i, 1))) % 2147483647;
  end loop;
  return h;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_level(p_xp bigint, p_rules jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  base numeric := coalesce((p_rules ->> 'base')::numeric, 300);
  growth numeric := coalesce((p_rules ->> 'growth')::numeric, 0.55);
  lv int := 1; spent numeric := 0; cost numeric;
begin
  cost := greatest(10, round(base * power(1, growth) / 10) * 10);
  while lv < 5000 and coalesce(p_xp, 0) - spent >= cost loop
    spent := spent + cost;
    lv := lv + 1;
    cost := greatest(10, round(base * power(lv, growth) / 10) * 10);
  end loop;
  return lv;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_log_of(p_data jsonb, p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare t text;
begin
  if p_data is null then return null; end if;
  t := p_data ->> (p_athlete_id || '_hab_log');
  if t is null or btrim(t) = '' then return null; end if;
  begin
    return t::jsonb;
  exception when others then
    return null;
  end;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_mint_titles(p_athlete_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return;   -- stage78: titles are gone (Career Mode round 5, L5); nothing is minted
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_notes_floor()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select current_date - 8;
$function$;

CREATE OR REPLACE FUNCTION public.hab_notes_prune()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.hab_notes where day < public.hab_notes_floor();
  return null;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_proof_level(p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb; v_data jsonb; v_start date; v_xp bigint;
begin
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return 1; end if;
  select data into v_data from public.athlete_progress where athlete_id = p_athlete_id;
  if v_data is null then return 1; end if;
  select s.starts_on into v_start from public.current_season() s;
  v_start := coalesce(v_start, '1970-01-01'::date);
  v_xp := public.hab_xp(public.hab_log_of(v_data, p_athlete_id), v_start, current_date, v_rules)
        + public.hab_bonus_xp(public.hab_log_of(v_data, p_athlete_id), public.hab_cfg_of(v_data, p_athlete_id),
                              v_start, v_start, current_date, v_rules);
  return public.hab_level(v_xp, v_rules);
end $function$;

CREATE OR REPLACE FUNCTION public.hab_rank_label(p_level integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  names text[] := array['ROOKIE','CONTENDER','GRINDER','OPERATOR','ENFORCER',
                        'PREDATOR','MACHINE','RELENTLESS','UNTOUCHABLE','IMMORTAL'];
  subs int := 5;
  per_cycle int := 50;
  i int := greatest(0, coalesce(p_level, 1) - 1);
  star int; within int; nm text; sub int;
begin
  star := i / per_cycle;
  within := i % per_cycle;
  nm := names[(within / subs) + 1];
  sub := (within % subs) + 1;
  return case when star > 0 then '★' || star || ' ' else '' end || nm || ' ' || sub;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_season_level(p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.career_xp_on() then
    return coalesce((public.career_scored(p_athlete_id) #>> '{career,level}')::int, 1);
  end if;
  return public.hab_proof_level(p_athlete_id);
end $function$;

CREATE OR REPLACE FUNCTION public.hab_xp(p_log jsonb, p_from date, p_to date, p_rules jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  r record; r2 record;
  d date; v numeric; tgt numeric; w numeric;
  bonus numeric := coalesce((p_rules ->> 'completionBonus')::numeric, 1.2);
  custom numeric := coalesce((p_rules ->> 'customXp')::numeric, 25);
  maxcustom int := coalesce((p_rules ->> 'maxCustom')::int, 2147483647);
  ncustom int;
  total numeric := 0;
begin
  if p_log is null or jsonb_typeof(p_log) <> 'object' then return 0; end if;
  for r in select key, value from jsonb_each(p_log) loop
    if jsonb_typeof(r.value) <> 'object' then continue; end if;
    begin
      d := r.key::date;
    exception when others then
      continue;
    end;
    if p_from is not null and d < p_from then continue; end if;
    if p_to   is not null and d > p_to   then continue; end if;
    ncustom := 0;
    for r2 in select key, value from jsonb_each(r.value) loop
      if jsonb_typeof(r2.value) <> 'number' then continue; end if;
      v := (r2.value #>> '{}')::numeric;
      if v <= 0 then continue; end if;
      tgt := coalesce((p_rules -> 'targets' ->> r2.key)::numeric, 1);
      if tgt <= 0 then tgt := 1; end if;
      if (p_rules -> 'weights' ->> r2.key) is null then
        ncustom := ncustom + 1;
        if ncustom > maxcustom then continue; end if;
        w := custom;
      else
        w := (p_rules -> 'weights' ->> r2.key)::numeric;
      end if;
      if v >= tgt then
        total := total + round(w * bonus);
      else
        total := total + round(w * (v / tgt));
      end if;
    end loop;
  end loop;
  return total::bigint;
end; $function$;

CREATE OR REPLACE FUNCTION public.hide_note(p_athlete_id text, p_day date, p_hidden boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  update public.hab_notes n set hidden = p_hidden, updated_at = now()
   where n.athlete_id = p_athlete_id and n.day = p_day;
end; $function$;

CREATE OR REPLACE FUNCTION public.history_detail(e jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when jsonb_typeof(e->'rx') = 'object' then nullif(concat_ws(' · ',
        case when coalesce(e->'rx'->>'rounds', '') <> '' then '×' || (e->'rx'->>'rounds') || ' Rounds' end,
        nullif(concat_ws(' × ', nullif(e->'rx'->>'sets', ''),
               nullif(coalesce(e->'rx'->>'reps', e->'rx'->>'time', e->'rx'->>'distance', e->'rx'->>'work', '')
                      || case when e->'rx'->'side' = 'true'::jsonb then '/side' else '' end, '')), ''),
        case when coalesce(e->'rx'->>'rpe', '') <> '' then 'RPE ' || (e->'rx'->>'rpe') end,
        case when jsonb_typeof(e->'items') = 'array' then
          (select string_agg(i->>'name', ', ' order by n) from jsonb_array_elements(e->'items') with ordinality x(i, n)) end
      ), '')
    else nullif(concat_ws(' · ',
        nullif(e->>'rounds', ''),
        case when jsonb_typeof(e->'chips') = 'array' then
          (select string_agg(coalesce(ch->>'label', ch #>> '{}'), ' · ' order by n)
             from jsonb_array_elements(e->'chips') with ordinality x(ch, n)) end,
        nullif(e->>'detail', ''),
        case when jsonb_typeof(e->'items') = 'array' then
          (select string_agg(i->>'name', ', ' order by n) from jsonb_array_elements(e->'items') with ordinality x(i, n)) end
      ), '')
  end
$function$;

CREATE OR REPLACE FUNCTION public.intake_list()
 RETURNS TABLE(id uuid, created_at timestamp with time zone, lang text, name text, email text, contact text, programme text, status text, handled_at timestamp with time zone, payload jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
  select i.id, i.created_at, i.lang, i.name, i.email, i.contact,
         i.programme, i.status, i.handled_at, i.payload
  from public.hab_intake i
  order by i.created_at desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.is_coach()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select coalesce(auth.jwt() ->> 'email', '') = 'amirardekanian@gmail.com' $function$;

CREATE OR REPLACE FUNCTION public.leaderboard_top(p_athlete_id text, p_key text DEFAULT NULL::text, p_scope text DEFAULT 'season'::text, p_limit integer DEFAULT 10)
 RETURNS TABLE(pos integer, display_name text, title text, xp bigint, level integer, rank_label text, is_me boolean, joined boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected text; v_rules jsonb; v_from date; v_to date; v_joined boolean;
  v_season_start date;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  select exists (select 1 from public.leaderboard_optin o where o.athlete_id = p_athlete_id)
    into v_joined;

  -- stage78: no title and no rank name on the board (round 5, L5, L8: the board keeps its order, only the names go)
  if public.career_xp_on() then
    return query
    with board as (
      select o.athlete_id as aid, o.display_name as dname from public.leaderboard_optin o
    ),
    sc as (
      select s.athlete_id as aid, s.score
        from public.career_scores_for((select array_agg(b.aid) from board b), interval '2.5 seconds') s
    ),
    scored as (
      select b.aid, b.dname,
             coalesce(case when p_scope = 'week' then (sc.score #>> '{week,points}')::bigint
                           else (sc.score #>> '{season,points}')::bigint end, 0) as x,
             coalesce((sc.score #>> '{career,level}')::int, 1) as lv
        from board b left join sc on sc.aid = b.aid
    ),
    ranked as (
      select row_number() over (order by s.x desc, lower(s.dname) asc) as rn, s.*
        from scored s
    )
    select r.rn::int, r.dname, null::text, r.x, r.lv, null::text, (r.aid = p_athlete_id), v_joined
      from ranked r
     where r.rn <= greatest(1, p_limit) or r.aid = p_athlete_id
     order by r.rn;
    return;
  end if;

  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return; end if;

  select s.starts_on into v_season_start from public.current_season() s;
  v_season_start := coalesce(v_season_start, '1970-01-01'::date);
  v_to := current_date;

  if p_scope = 'week' then
    v_from := greatest(current_date - 6, v_season_start);
  else
    v_from := v_season_start;
  end if;

  return query
  with scored as (
    select o.athlete_id as aid,
           o.display_name as dname,
           ( public.hab_xp(public.hab_log_of(ap.data, o.athlete_id), v_from, v_to, v_rules)
           + public.hab_bonus_xp(public.hab_log_of(ap.data, o.athlete_id),
                                 public.hab_cfg_of(ap.data, o.athlete_id),
                                 v_season_start, v_from, v_to, v_rules) ) as x
    from public.leaderboard_optin o
    left join public.athlete_progress ap on ap.athlete_id = o.athlete_id
  ),
  ranked as (
    select row_number() over (order by s.x desc, lower(s.dname) asc) as rn, s.*
    from scored s
  )
  select r.rn::int,
         r.dname,
         null::text,
         r.x,
         public.hab_level(r.x, v_rules),
         null::text,
         (r.aid = p_athlete_id),
         v_joined
  from ranked r
  where r.rn <= greatest(1, p_limit) or r.aid = p_athlete_id
  order by r.rn;
end $function$;

CREATE OR REPLACE FUNCTION public.library_sessions_for(p_athlete_id text, p_days integer DEFAULT 10)
 RETURNS TABLE(completed_on date, slug text, title text, category_id text, duration_min integer, counts_as text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
    select s.completed_on, s.slug, s.title, s.category_id, s.duration_min, s.counts_as
    from public.library_sessions s
    where s.athlete_id = p_athlete_id
      and s.completed_on >= current_date - greatest(coalesce(p_days, 10), 1)
    order by s.completed_on desc, s.title;
end;
$function$;

CREATE OR REPLACE FUNCTION public.library_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.log_library_session(p_athlete_id text, p_slug text, p_on date DEFAULT NULL::date)
 RETURNS TABLE(logged_on date, counted_as text, workout_title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item   jsonb;
  v_cat    text;
  v_when   date := coalesce(p_on, current_date);
  v_counts text;
  v_title  text;
  v_dur    int;
begin
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() then
    raise exception 'not your athlete record';
  end if;
  if p_slug is null or btrim(p_slug) = '' then
    raise exception 'slug required';
  end if;
  if v_when > current_date or v_when < current_date - 1 then
    raise exception 'completed_on must be today or yesterday';
  end if;

  select l.data, l.category_id into v_item, v_cat
  from public.library l
  where l.slug = p_slug and l.kind = 'workout' and l.published;

  if v_item is null then
    raise exception 'no published workout at that slug';
  end if;

  -- Whitelist, not a cast. One entry per habit a library workout may tick, and
  -- every id here must exist in HABITS in habits.html. 'breathe' joined the list
  -- with the Breath section (2026-09-12). Anything unrecognised counts for
  -- nothing: fail closed, so a new workout can never inflate a score by accident.
  v_counts := case v_item ->> 'countsAs'
                when 'strength' then 'strength'
                when 'mobility' then 'mobility'
                when 'breathe'  then 'breathe'
                else null
              end;
  v_title  := v_item ->> 'title';
  v_dur    := nullif(regexp_replace(coalesce(v_item ->> 'duration', ''), '\D', '', 'g'), '')::int;

  insert into public.library_sessions
    (athlete_id, slug, completed_on, counts_as, title, category_id, duration_min)
  values
    (p_athlete_id, p_slug, v_when, v_counts, v_title, v_cat, v_dur)
  on conflict (athlete_id, slug, completed_on) do update
    set counts_as    = excluded.counts_as,
        title        = excluded.title,
        category_id  = excluded.category_id,
        duration_min = excluded.duration_min;

  return query select v_when, v_counts, v_title;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_athlete_read(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  update public.messages set read_by_athlete = true
    where athlete_id = p_athlete_id and sender = 'coach' and read_by_athlete = false;
end; $function$;

CREATE OR REPLACE FUNCTION public.mark_moments_told(p_athlete_id text, p_award_ids text[], p_app text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  if p_app is null or p_app not in ('proof', 'training') then
    raise exception 'mark_moments_told: the app is proof or training, not %', coalesce(p_app, 'null');
  end if;
  if p_athlete_id is null or p_athlete_id is distinct from public.current_athlete_id() then
    return 0;
  end if;
  with u as (
    update public.career_recognition r set told_at = now(), told_by = p_app
     where r.athlete_id = p_athlete_id and r.audience = 'athlete' and r.told_at is null and r.award_id = any (coalesce(p_award_ids, '{}'::text[]))
    returning 1
  )
  select count(*) into v_n from u;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.mark_note_read(p_athlete_id text, p_day date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  if p_athlete_id is null or p_athlete_id is distinct from public.current_athlete_id() then return 0; end if;   -- the athlete themself, never a preview
  update public.career_notes set read_at = now() where athlete_id = p_athlete_id and day = p_day and read_at is null;
  get diagnostics v_n = row_count;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.move_buyer_label()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(new.label), '') is not null then
    insert into public.buyer_notes (user_id, app, note)
    values (new.user_id, tg_argv[0], left(btrim(new.label), 80))
    on conflict (user_id) do update set note = excluded.note, updated_at = now();
  end if;
  new.label := null;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.my_game_set(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.crew_who();
  c_sports constant text[] := array['tennis', 'padel', 'squash', 'badminton', 'pickleball', 'table_tennis', 'beach_tennis'];
  c_train constant text[] := array['competition', 'strength', 'fitness', 'physique', 'running', 'health'];
  r public.athlete_profile%rowtype; v text; arr text[];
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'game:shape'; end if;
  select g.* into r from public.athlete_profile g where g.athlete_id = v_me;
  if not found then
    r.sports := '{}'; r.training_for := '{}';
  end if;
  if p ? 'sports' then
    if jsonb_typeof(p -> 'sports') = 'null' then arr := '{}';
    elsif jsonb_typeof(p -> 'sports') <> 'array' then raise exception 'game:sports';
    else
      select coalesce(array_agg(z.s order by array_position(c_sports, z.s)), '{}') into arr
        from (select distinct lower(btrim(e)) as s from jsonb_array_elements_text(p -> 'sports') e where btrim(e) <> '') z;
      if not (arr <@ c_sports) then raise exception 'game:sports'; end if;
    end if;
    r.sports := arr;
  end if;
  if p ? 'training_for' then
    if jsonb_typeof(p -> 'training_for') = 'null' then arr := '{}';
    elsif jsonb_typeof(p -> 'training_for') <> 'array' then raise exception 'game:training_for';
    else
      select coalesce(array_agg(z.s order by array_position(c_train, z.s)), '{}') into arr
        from (select distinct lower(btrim(e)) as s from jsonb_array_elements_text(p -> 'training_for') e where btrim(e) <> '') z;
      if not (arr <@ c_train) then raise exception 'game:training_for'; end if;
    end if;
    r.training_for := arr;
  end if;
  if p ? 'hand' then
    v := lower(nullif(btrim(coalesce(p ->> 'hand', '')), ''));
    if v is not null and v not in ('right', 'left') then raise exception 'game:hand'; end if;
    r.hand := v;
  end if;
  if p ? 'backhand' then
    v := lower(nullif(btrim(coalesce(p ->> 'backhand', '')), ''));
    if v is not null and v not in ('one', 'two') then raise exception 'game:backhand'; end if;
    r.backhand := v;
  end if;
  if p ? 'side' then
    v := lower(nullif(btrim(coalesce(p ->> 'side', '')), ''));
    if v is not null and v not in ('right', 'left', 'both') then raise exception 'game:side'; end if;
    r.side := v;
  end if;
  if p ? 'plays_at' then
    v := lower(nullif(btrim(coalesce(p ->> 'plays_at', '')), ''));
    if v is not null and v not in ('fun', 'club', 'competition') then raise exception 'game:plays_at'; end if;
    r.plays_at := v;
  end if;
  if p ? 'club' then
    v := nullif(regexp_replace(public.crew_clean(p ->> 'club'), '\s+', ' ', 'g'), '');
    if v is not null and char_length(v) > 40 then raise exception 'game:club'; end if;
    r.club := v;
  end if;
  if p ? 'working_on' then
    v := nullif(regexp_replace(public.crew_clean(p ->> 'working_on'), '\s+', ' ', 'g'), '');
    if v is not null and char_length(v) > 60 then raise exception 'game:working_on'; end if;
    r.working_on := v;
  end if;
  if p ? 'ig' then
    v := ltrim(nullif(btrim(coalesce(p ->> 'ig', '')), ''), '@');
    v := nullif(v, '');
    if v is not null and v !~ '^[A-Za-z0-9._]{1,30}$' then raise exception 'game:ig'; end if;
    r.ig := v;
  end if;
  insert into public.athlete_profile as g (athlete_id, sports, hand, backhand, side, plays_at, club, training_for, working_on, ig, updated_at)
  values (v_me, r.sports, r.hand, r.backhand, r.side, r.plays_at, r.club, r.training_for, r.working_on, r.ig, now())
  on conflict (athlete_id) do update
     set sports = excluded.sports, hand = excluded.hand, backhand = excluded.backhand, side = excluded.side, plays_at = excluded.plays_at,
         club = excluded.club, training_for = excluded.training_for, working_on = excluded.working_on, ig = excluded.ig, updated_at = now();
  return public.crew_game_of(v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.my_partner_code(p_make boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := public.crew_who();
begin
  if exists (select 1 from public.crew_consent c where c.athlete_id = v_me and c.under13) then raise exception 'partner:under13'; end if;
  if coalesce(p_make, false) then
    perform public.partner_code_make(v_me);
  end if;
  return public.crew_referral(v_me);
end $function$;

CREATE OR REPLACE FUNCTION public.partner_code_make(p_athlete text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_have text; v_base text; v_name text; v_code text; v_try integer := 0;
begin
  perform pg_advisory_xact_lock(hashtext('partner_code'));
  select a.code into v_have from public.affiliates a where a.athlete_id = p_athlete and a.kind = 'athlete';
  if v_have is not null then return v_have; end if;
  select upper(left(regexp_replace(coalesce(p.data -> 'athlete' ->> 'firstName', ''), '[^A-Za-z]', '', 'g'), 10)),
         nullif(btrim(concat_ws(' ', nullif(btrim(p.data -> 'athlete' ->> 'firstName'), ''), nullif(btrim(p.data -> 'athlete' ->> 'lastName'), ''))), '')
    into v_base, v_name from public.programs p where p.athlete_id = p_athlete;
  if not found then raise exception 'partner:no_programme'; end if;
  v_base := coalesce(nullif(v_base, ''), 'FRIEND');
  loop
    v_try := v_try + 1;
    v_code := v_base || case when v_try <= 40 then lpad((10 + floor(random() * 90))::int::text, 2, '0')
                             else lpad(floor(random() * 10000)::int::text, 4, '0') end;
    exit when not exists (select 1 from public.affiliates a where a.code = v_code);
    if v_try > 400 then raise exception 'partner:full'; end if;
  end loop;
  insert into public.affiliates (code, percent, reward_percent, coach_name, kind, active, athlete_id, applied_on)
  values (v_code, 10, 10, left(coalesce(v_name, p_athlete), 80), 'athlete', true, p_athlete, current_date);
  return v_code;
end $function$;

CREATE OR REPLACE FUNCTION public.programme_fingerprint(p_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with recursive walk(path, val) as (
    select k, p.data->k from public.programs p,
           unnest(array['athlete','sport','currentCycleIndex','cycles','workouts','notes']) k
     where p.athlete_id = p_id
    union all
    select w.path || '/' || c.k, c.v from walk w cross join lateral (
      select e.key as k, e.value as v
        from jsonb_each(case when jsonb_typeof(w.val) = 'object' then w.val else '{}'::jsonb end) e
      union all
      select (a.idx - 1)::text, a.value
        from jsonb_array_elements(case when jsonb_typeof(w.val) = 'array' then w.val else '[]'::jsonb end)
             with ordinality a(value, idx)) c)
  select jsonb_build_object(
           'fp', md5(string_agg(path || '=' || (val #>> '{}'), E'\n' order by path collate "C")),
           'leaves', count(*), 'chars', coalesce(sum(length(val #>> '{}')), 0))
    from walk where jsonb_typeof(val) not in ('object', 'array', 'null');
$function$;

CREATE OR REPLACE FUNCTION public.programs_keep_versions_from(p_data jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  idx int := 0;
  s   text;
  d   date;
begin
  begin idx := coalesce((p_data ->> 'currentCycleIndex')::int, 0); exception when others then idx := 0; end;
  if idx < 0 then idx := 0; end if;
  -- the previous cycle's start first, then the current cycle's
  foreach s in array array[
      case when idx >= 1 then p_data -> 'cycles' -> (idx - 1) ->> 'startDate' end,
      p_data -> 'cycles' -> idx ->> 'startDate'] loop
    if s is not null then
      begin d := s::date; exception when others then d := null; end;
      if d is not null then return d::timestamptz; end if;
    end if;
  end loop;
  return now() - interval '70 days';
end; $function$;

CREATE OR REPLACE FUNCTION public.programs_version_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  keep_from timestamptz;
begin
  if old.data is distinct from new.data then
    insert into public.program_versions (athlete_id, data, saved_by)
    values (old.athlete_id, old.data, old.updated_by);

    begin
      keep_from := public.programs_keep_versions_from(new.data);
    exception when others then
      keep_from := now() - interval '70 days';
    end;

    delete from public.program_versions v
     where v.athlete_id = old.athlete_id
       and (
            v.id not in (
              select id from public.program_versions
               where athlete_id = old.athlete_id
               order by id desc
               limit 150)
         or (v.saved_at < keep_from
             and v.id not in (
               select id from public.program_versions
                where athlete_id = old.athlete_id
                order by id desc
                limit 20))
       );
  end if;
  new.updated_at := now();
  new.updated_by := coalesce(
    auth.jwt() ->> 'email',
    case when new.updated_by is not distinct from old.updated_by and old.updated_by like '%@%' then 'sql' else new.updated_by end);
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.publish_cycle(p_athlete_id text, p_workouts jsonb, p_notes jsonb, p_new_cycle boolean, p_cycle_patch jsonb DEFAULT NULL::jsonb, p_cycles jsonb DEFAULT NULL::jsonb, p_sport jsonb DEFAULT NULL::jsonb, p_log_section text DEFAULT NULL::text, p_log_profile text DEFAULT NULL::text, p_log_ledger text DEFAULT NULL::text, p_log_new text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_data jsonb; v_who jsonb; v_cci int; v_n int; v_cycle jsonb; v_entry jsonb; v_key text; v_i int;
  v_body text; v_had_log boolean; v_s int; v_e int; v_len int; v_m text[];
  v_prof boolean := false; v_ledger boolean := false; v_out jsonb;
  v_w jsonb; v_filled boolean := false;                -- stage74: the workouts object as stored, and whether its label had to be written
begin
  if jsonb_typeof(p_workouts->'days') is distinct from 'array' then
    raise exception 'publish_cycle: p_workouts must be the whole workouts object {"label": "Program 0N · <Cycle Name>", "days": [...]}';   -- stage74
  end if;
  if jsonb_typeof(p_notes) is distinct from 'object' then
    raise exception 'publish_cycle: p_notes must be an object, e.g. {"cards": [...]}';
  end if;

  select p.data into v_data from public.programs p where p.athlete_id = p_athlete_id for update;
  if not found then
    raise exception 'publish_cycle: no programme row for % (run /athlete-intake first)', p_athlete_id;
  end if;
  v_who := v_data->'athlete';
  v_cci := coalesce((v_data->>'currentCycleIndex')::int, 0);

  -- 1. The archive, built from the live row, newest FIRST, with an id (SCHEMA → programHistory).
  if p_new_cycle then
    if jsonb_typeof(v_data->'workouts'->'days') is distinct from 'array' then
      raise exception 'publish_cycle: % has no workouts to archive; a new athlete publishes with p_new_cycle = false', p_athlete_id;
    end if;
    v_cycle := v_data->'cycles'->v_cci;
    v_n := coalesce((v_cycle->>'num')::int, v_cci + 1);
    v_entry := jsonb_build_object(
      'id', 'prog' || v_n,
      'label', 'Program ' || lpad(v_n::text, 2, '0') || coalesce(' · ' || nullif(v_cycle->>'name', ''), ''),
      'subtitle', coalesce(nullif(concat_ws(' · ', nullif(v_cycle->>'name', ''), nullif(v_cycle->>'weeks', ''),
                    case when coalesce(v_cycle->>'startDate', '') <> ''
                         then (v_cycle->>'startDate') || coalesce(' → ' || nullif(v_cycle->>'endDate', ''), '') end), ''),
                    'Cycle ' || v_n),
      'days', (select coalesce(jsonb_agg(jsonb_build_object(
                  'label', 'Day ' || coalesce(dd->>'id', dn::text),
                  'focus', coalesce(dd->>'focusTag', ''),
                  'exercises', (select coalesce(jsonb_agg(jsonb_build_object(
                                    'name', ex->>'name', 'detail', coalesce(public.history_detail(ex), '')) order by bn, en), '[]'::jsonb)
                                  from jsonb_array_elements(case when jsonb_typeof(dd->'blocks') = 'array' then dd->'blocks' else '[]'::jsonb end)
                                       with ordinality bx(b, bn)
                                  cross join lateral jsonb_array_elements(case when jsonb_typeof(b->'exercises') = 'array' then b->'exercises' else '[]'::jsonb end)
                                       with ordinality exx(ex, en))
                ) order by dn), '[]'::jsonb)
               from jsonb_array_elements(v_data->'workouts'->'days') with ordinality dx(dd, dn)));
    v_data := jsonb_set(v_data, '{programHistory}', jsonb_build_array(v_entry)
              || case when jsonb_typeof(v_data->'programHistory') = 'array' then v_data->'programHistory' else '[]'::jsonb end);
    v_cci := v_cci + 1;
  end if;
  v_data := jsonb_set(v_data, '{currentCycleIndex}', to_jsonb(v_cci));

  -- 2. The roadmap: whole only when there is none; otherwise only the fields the spec names.
  if p_cycles is not null then
    if jsonb_typeof(v_data->'cycles') = 'array' and jsonb_array_length(v_data->'cycles') > 0 then
      raise exception 'publish_cycle: % already has a roadmap; change it through p_cycle_patch (a roadmap_amend: line, PRC-17)', p_athlete_id;
    end if;
    v_data := v_data || jsonb_build_object('cycles', p_cycles);
  end if;
  if p_cycle_patch is not null then
    for v_key in select jsonb_object_keys(p_cycle_patch) loop
      v_i := v_key::int;
      if jsonb_typeof(v_data->'cycles') is distinct from 'array' or v_i < 0 or v_i >= jsonb_array_length(v_data->'cycles') then
        raise exception 'publish_cycle: cycle index % is not in the roadmap', v_key;
      end if;
      if jsonb_typeof(p_cycle_patch->v_key) is distinct from 'object' then
        raise exception 'publish_cycle: the patch for cycle % must be an object of fields', v_key;
      end if;
      v_data := jsonb_set(v_data, array['cycles', v_key], (v_data->'cycles'->v_i) || (p_cycle_patch->v_key));
    end loop;
  end if;
  if jsonb_typeof(v_data->'cycles') is distinct from 'array' or v_cci >= jsonb_array_length(v_data->'cycles') then
    raise exception 'publish_cycle: currentCycleIndex % has no cycle in the roadmap', v_cci;
  end if;

  -- 3. The new cycle's days and notes, and the sport line if the spec gave one.
  v_w := p_workouts;                                                                       -- stage74 from here to the end of the if
  if jsonb_typeof(v_w->'label') is distinct from 'string' or btrim(v_w->>'label') = '' then
    v_cycle := v_data->'cycles'->v_cci;                                                    -- the NEW cycle (the archive's v_cycle was the old one)
    v_n := coalesce((v_cycle->>'num')::int, v_cci + 1);
    v_w := jsonb_set(v_w, '{label}',
             to_jsonb('Program ' || lpad(v_n::text, 2, '0') || coalesce(' · ' || nullif(v_cycle->>'name', ''), '')));
    v_filled := true;
  end if;
  v_data := v_data || jsonb_build_object('workouts', v_w, 'notes', p_notes);
  if p_sport is not null then v_data := v_data || jsonb_build_object('sport', p_sport); end if;
  if (v_data->'athlete') is distinct from v_who then
    raise exception 'publish_cycle: the athlete block would change';
  end if;
  update public.programs set data = v_data, updated_by = 'publish_cycle' where athlete_id = p_athlete_id;
  v_out := jsonb_build_object('athlete_id', p_athlete_id, 'currentCycleIndex', v_cci,
             'archived', case when p_new_cycle then v_entry->>'id' end,
             'label', v_w->>'label', 'label_filled', v_filled,                             -- stage74
             'fingerprint', public.programme_fingerprint(p_athlete_id));

  -- 4. The coaching log: spliced, never retyped.
  if coalesce(p_log_section, p_log_profile, p_log_ledger, p_log_new) is not null then
    select l.body into v_body from public.coaching_logs l where l.athlete_id = p_athlete_id for update;
    v_had_log := found;
    if not v_had_log then
      if p_log_new is null then
        raise exception 'publish_cycle: % has no coaching log yet; pass p_log_new', p_athlete_id;
      end if;
      v_body := p_log_new;
    elsif p_log_new is not null then
      raise exception 'publish_cycle: % already has a coaching log; p_log_new is for a first one only', p_athlete_id;
    end if;

    if p_log_profile is not null then
      v_s := strpos(v_body, '```profile');
      if v_s > 0 then                                  -- replace the block, fences included
        v_e := strpos(substr(v_body, v_s + 10), '```');
        if v_e = 0 then raise exception 'publish_cycle: the profile block in the log has no closing fence'; end if;
        v_body := substr(v_body, 1, v_s - 1) || p_log_profile || substr(v_body, v_s + v_e + 12);
      else                                             -- first profile: before the ledger, under its own heading
        v_s := coalesce(nullif(strpos(v_body, E'\n## Exercise Ledger'), 0) + 1,
                        nullif(regexp_instr(v_body, '\|\s*Exercise\s*\|\s*Status'), 0));
        if v_s is null then
          v_s := coalesce(nullif(strpos(v_body, E'\n## '), 0) + 1, length(v_body) + 1);
        end if;
        v_body := substr(v_body, 1, v_s - 1) || '## Athlete profile' || E'\n' || p_log_profile || E'\n\n' || substr(v_body, v_s);
      end if;
      v_prof := true;
    end if;

    if p_log_ledger is not null then
      v_s := regexp_instr(v_body, '\|\s*Exercise\s*\|\s*Status');
      if v_s > 0 then                                  -- replace every consecutive table line
        v_m := regexp_match(substr(v_body, v_s), '^((?:\|[^\n]*(?:\n|$))+)');
        v_len := length(v_m[1]);
        v_body := substr(v_body, 1, v_s - 1) || rtrim(p_log_ledger, E'\n') || E'\n' || substr(v_body, v_s + v_len);
      else                                             -- a log from before the ledger: before the first cycle
        v_s := coalesce(nullif(strpos(v_body, E'\n## Roadmap'), 0), nullif(strpos(v_body, E'\n## Cycle'), 0));
        if v_s is null then v_s := length(v_body) + 1; else v_s := v_s + 1; end if;
        v_body := substr(v_body, 1, v_s - 1) || '## Exercise Ledger' || E'\n\n' || rtrim(p_log_ledger, E'\n') || E'\n\n' || substr(v_body, v_s);
      end if;
      v_ledger := true;
    end if;

    if p_log_section is not null then
      v_body := rtrim(v_body, E'\n') || E'\n\n' || p_log_section;
    end if;

    if v_had_log then
      update public.coaching_logs set body = v_body where athlete_id = p_athlete_id;
    else
      insert into public.coaching_logs (athlete_id, body) values (p_athlete_id, v_body);
    end if;
    v_out := v_out || jsonb_build_object('log', jsonb_build_object(
               'md5', md5(v_body), 'length', length(v_body), 'first_log', not v_had_log,
               'profile_replaced', v_prof, 'ledger_replaced', v_ledger,
               'section_at_end', p_log_section is null or right(v_body, length(p_log_section)) = p_log_section));
  end if;
  return v_out;
end
$function$;

CREATE OR REPLACE FUNCTION public.purge_old_notes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  delete from public.hab_notes where day < public.hab_notes_floor();
  get diagnostics v_n = row_count;
  return v_n;
end; $function$;

CREATE OR REPLACE FUNCTION public.push_done(p_athlete_id text, p_kind text, p_day date, p_ok boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_ok then
    insert into public.push_sent (athlete_id, day, kind) values (p_athlete_id, p_day, p_kind)
    on conflict (athlete_id, day, kind) do nothing;
  end if;
  update public.push_subs
     set last_sent_at = now(),
         last_ok_at = case when p_ok then now() else last_ok_at end,
         fails = case when p_ok then 0 else least(32767, fails + 1) end
   where athlete_id = p_athlete_id;
end $function$;

CREATE OR REPLACE FUNCTION public.push_drop(p_endpoint text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.push_subs where endpoint = p_endpoint;
end $function$;

CREATE OR REPLACE FUNCTION public.push_due(p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(endpoint text, p256dh text, auth text, athlete_id text, kind text, title text, body text, tag text, ttl integer, day date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with phone as (
    select s.*,
           public.push_local(p_now, s.tz_offset) as local_at,
           public.push_local(p_now, s.tz_offset)::date as local_day,
           extract(hour from public.push_local(p_now, s.tz_offset))::int as local_hour
      from public.push_subs s
     where s.fails < 5
  ),
  ripe as (
    select p.* from phone p where p.local_hour = p.hour
  ),
  coached as (
    select r.*, (select coalesce(pr.data->'athlete'->>'tier', 'coached') <> 'free'
                   from public.programs pr where pr.athlete_id = r.athlete_id) as is_coached
      from ripe r
  ),
  judged as (
    select c.*,
      (c.is_coached and public.push_on(c.kinds, 'workout')
        and not exists (select 1 from public.career_facts f
                         where f.athlete_id = c.athlete_id and f.kind = 'session_finished'
                           and f.void_at is null and f.day > c.local_day - c.quiet_days)
        and not exists (select 1 from public.push_sent t
                         where t.athlete_id = c.athlete_id and t.day = c.local_day and t.kind = 'workout')
      ) as want_workout,
      (public.push_on(c.kinds, 'habits')
        and not exists (select 1 from public.career_facts f
                         where f.athlete_id = c.athlete_id and f.kind = 'habit_day'
                           and f.void_at is null and f.day = c.local_day)
        and not exists (select 1 from public.push_sent t
                         where t.athlete_id = c.athlete_id and t.day = c.local_day and t.kind = 'habits')
      ) as want_habits
      from coached c
  ),
  picked as (
    select j.*, case when j.want_workout then 'workout'
                     when j.want_habits then 'habits' end as kind
      from judged j
     where j.want_workout or j.want_habits
  )
  select p.endpoint, p.p256dh, p.auth, p.athlete_id, p.kind,
         l.title, l.body, p.kind as tag, 7200 as ttl, p.local_day
    from picked p
    cross join lateral public.push_lines(p.kind, p.lang) l
$function$;

CREATE OR REPLACE FUNCTION public.push_fire()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; req bigint;
begin
  select * into c from public.push_config where id;
  if c.url is null or c.secret is null then
    return jsonb_build_object('ok', false, 'why', 'push_config is not filled in yet');
  end if;
  if to_regproc('net.http_post') is null then
    return jsonb_build_object('ok', false, 'why', 'pg_net is not installed');
  end if;
  execute format('select %s($1, $2::jsonb, ''{}''::jsonb, $3::jsonb, 20000)', 'net.http_post')
    into req
    using c.url, '{}'::jsonb,
          jsonb_build_object('Content-Type', 'application/json', 'x-push-key', c.secret);
  return jsonb_build_object('ok', true, 'request', req);
exception when others then
  raise warning 'push_fire: %', sqlerrm;
  return jsonb_build_object('ok', false, 'why', sqlerrm);
end $function$;

CREATE OR REPLACE FUNCTION public.push_forget(p_endpoint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text := public.current_athlete_id();
begin
  if v_id is null then return null; end if;
  delete from public.push_subs
   where athlete_id = v_id and (p_endpoint is null or endpoint = p_endpoint);
  return public.push_me();
end $function$;

CREATE OR REPLACE FUNCTION public.push_kind_list()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array['habits', 'workout', 'crew', 'cycle']::text[]
$function$;

CREATE OR REPLACE FUNCTION public.push_lang_of(p_athlete_id text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when p.data -> 'athlete' ->> 'lang' in ('en', 'fa') then p.data -> 'athlete' ->> 'lang' end
    from public.programs p where p.athlete_id = p_athlete_id
$function$;

CREATE OR REPLACE FUNCTION public.push_lang_sync()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  update public.push_subs s
     set lang = l.lang, updated_at = now()
    from (select s2.endpoint, public.push_lang_of(s2.athlete_id) as lang
            from public.push_subs s2) l
   where l.endpoint = s.endpoint
     and l.lang is not null
     and l.lang <> s.lang;
  get diagnostics n = row_count;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.push_lines(p_kind text, p_lang text)
 RETURNS TABLE(title text, body text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select t.title, t.body from (values
    ('habits',  'en', 'Your day is still open',  'Tick what you did today.'),
    ('habits',  'fa', 'روزت هنوز بازه',            'بزن ببینم امروز چی کار کردی.'),
    ('workout', 'en', 'Time to train',            'It has been a couple of days.'),
    ('workout', 'fa', 'وقتِ تمرینه',               'دو روزی می‌شه خبری نیست.')
  ) as t(kind, lang, title, body)
  where t.kind = p_kind and t.lang = (case when p_lang = 'fa' then 'fa' else 'en' end)
$function$;

CREATE OR REPLACE FUNCTION public.push_local(p_now timestamp with time zone, p_tz_offset integer)
 RETURNS timestamp without time zone
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select (p_now at time zone 'utc') + make_interval(mins => p_tz_offset)
$function$;

CREATE OR REPLACE FUNCTION public.push_me()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text := public.current_athlete_id(); v jsonb;
begin
  if v_id is null then return null; end if;
  select jsonb_build_object(
           'on', count(*) > 0,
           'phones', count(*),
           'hour', coalesce(min(hour), 20),
           'quiet_days', coalesce(min(quiet_days), 2),
           'kinds', coalesce(min(kinds::text)::jsonb, '{}'::jsonb),
           'lang', coalesce(min(lang), 'en'),
           'list', public.push_kind_list())
    into v
    from public.push_subs where athlete_id = v_id;
  return v;
end $function$;

CREATE OR REPLACE FUNCTION public.push_on(p_kinds jsonb, p_kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce((p_kinds ->> p_kind)::boolean, true)
$function$;

CREATE OR REPLACE FUNCTION public.push_set(p_kinds jsonb DEFAULT NULL::jsonb, p_hour integer DEFAULT NULL::integer, p_quiet_days integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text := public.current_athlete_id();
begin
  if v_id is null then return null; end if;
  -- greatest() and least() IGNORE nulls in Postgres, so greatest(8, null) is 8, not null. The null
  -- check has to come first, or "change nothing" quietly resets the hour to 8 and quiet days to 1.
  update public.push_subs
     set kinds = case when p_kinds is null or jsonb_typeof(p_kinds) <> 'object' then kinds
                      else kinds || p_kinds end,
         hour = case when p_hour is null then hour else least(22, greatest(8, p_hour)) end,
         quiet_days = case when p_quiet_days is null then quiet_days else least(4, greatest(1, p_quiet_days)) end,
         updated_at = now()
   where athlete_id = v_id;
  return public.push_me();
end $function$;

CREATE OR REPLACE FUNCTION public.push_subscribe(p_endpoint text, p_p256dh text, p_auth text, p_app text DEFAULT 'proof'::text, p_hour integer DEFAULT 20, p_tz_offset integer DEFAULT 0, p_lang text DEFAULT 'en'::text, p_device text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text := public.current_athlete_id();
begin
  if v_id is null then return null; end if;
  if p_endpoint is null or char_length(p_endpoint) < 20 or p_p256dh is null or p_auth is null then
    raise exception 'push_subscribe: that is not a subscription';
  end if;
  insert into public.push_subs as s (endpoint, athlete_id, p256dh, auth, app, hour, tz_offset, lang, device)
  values (p_endpoint, v_id, p_p256dh, p_auth,
          case when p_app = 'training' then 'training' else 'proof' end,
          least(22, greatest(8, coalesce(p_hour, 20))),
          least(840, greatest(-840, coalesce(p_tz_offset, 0))),
          case when p_lang = 'fa' then 'fa' else 'en' end,
          left(nullif(btrim(coalesce(p_device, '')), ''), 120))
  on conflict (endpoint) do update
    set athlete_id = excluded.athlete_id, p256dh = excluded.p256dh, auth = excluded.auth,
        app = excluded.app, tz_offset = excluded.tz_offset, lang = excluded.lang,
        device = excluded.device, fails = 0, updated_at = now()
  where s.endpoint = excluded.endpoint;
  return public.push_me();
end $function$;

CREATE OR REPLACE FUNCTION public.push_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  delete from public.push_sent where day < (now() at time zone 'utc')::date - 30;
  get diagnostics n = row_count;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.roll_call(p_athlete_id text, p_key text DEFAULT NULL::text, p_days integer DEFAULT 7)
 RETURNS TABLE(day date, display_name text, title text, body text, pct smallint, rank_label text, is_me boolean, is_coach boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected text; v_from date;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  v_from := current_date - greatest(1, least(60, coalesce(p_days, 7)));

  -- stage78: no title and no rank name beside a line (round 5, L5)
  return query
  with visible as (
    select n.athlete_id as aid, n.day as d, o.display_name as dname,
           n.body as b, n.pct as p, n.updated_at as ua, false as coach
    from public.hab_notes n
    join public.leaderboard_optin o on o.athlete_id = n.athlete_id
    where not n.hidden and n.day >= v_from and n.day <= current_date + 1
    union all
    select n.athlete_id, n.day, 'AMIR'::text,
           n.body, n.pct, n.updated_at, true
    from public.hab_notes n
    where n.athlete_id = public.coach_note_id()
      and not n.hidden and n.day >= v_from and n.day <= current_date + 1
  )
  select vi.d, vi.dname, null::text, vi.b, vi.p,
         null::text, (vi.aid = p_athlete_id), vi.coach
  from visible vi
  order by vi.d desc, vi.coach desc, vi.ua desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.save_progress(p_athlete_id text, p_athlete_name text, p_data jsonb, p_key text DEFAULT NULL::text, p_drop text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected text;
  v_drop     text[];
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  select coalesce(array_agg(k), '{}'::text[])
    into v_drop
    from unnest(coalesce(p_drop, '{}'::text[])) as k
   where left(k, length(p_athlete_id) + 1) =  p_athlete_id || '_'
     and left(k, length(p_athlete_id) + 5) <> p_athlete_id || '_hab_';

  insert into public.athlete_progress (athlete_id, athlete_name, data, updated_at)
  values (p_athlete_id, p_athlete_name, p_data, now())
  on conflict (athlete_id) do update
    set athlete_name = excluded.athlete_name,
        data         = (athlete_progress.data - v_drop) || excluded.data,
        updated_at   = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_session(p_athlete_id text, p_athlete_name text, p_day integer, p_completed_on date, p_session jsonb, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
        v_replace boolean := public.is_coach() and coalesce((p_session->>'replace_log')::boolean, false);
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  insert into public.session_history
    (athlete_id, athlete_name, day, completed_on, status, session_rpe,
     duration_min, readiness, day_note, focus, summary, log, updated_at, fin)
  values (
    p_athlete_id, p_athlete_name, p_day, p_completed_on,
    p_session->>'status', round(nullif(p_session->>'session_rpe','')::numeric)::int,
    round(nullif(p_session->>'duration_min','')::numeric)::int, p_session->'readiness',
    p_session->>'day_note', p_session->>'focus', p_session->>'summary',
    case when jsonb_typeof(p_session->'log') = 'array' then p_session->'log' end,
    now(),
    /* stage99: the phone's local finish time, "H:MM" or "HH:MM"; anything else is dropped */ case when (p_session->>'fin') ~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' then lpad(p_session->>'fin', 5, '0') end)
  on conflict (athlete_id, day, completed_on) do update
    set athlete_name = excluded.athlete_name, status = excluded.status,
        session_rpe = excluded.session_rpe, duration_min = excluded.duration_min,
        readiness = excluded.readiness, day_note = excluded.day_note,
        focus = excluded.focus, summary = excluded.summary,
        log = case when v_replace then excluded.log else coalesce(excluded.log, session_history.log) end,
        coach_status = case
          when not public.is_coach()
           and ((coalesce(btrim(excluded.day_note), '') <> '' and excluded.day_note is distinct from session_history.day_note)
             or (public.session_ex_notes(excluded.log, excluded.summary) <> ''
             and public.session_ex_notes(excluded.log, excluded.summary)
                 is distinct from public.session_ex_notes(session_history.log, session_history.summary))) then 'new'
          else session_history.coach_status end,
        -- stage60: the phone re-sending a session the coach hid leaves it hidden; the coach saving over it brings it back.
        hidden_at = case when public.is_coach() then null else session_history.hidden_at end,
        hidden_by = case when public.is_coach() then null else session_history.hidden_by end,
        fin = coalesce(session_history.fin, excluded.fin),   /* stage99: the first finish time stays */
        updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.season_list()
 RETURNS TABLE(starts_on date, name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.starts_on, s.name from public.seasons s order by s.starts_on;
$function$;

CREATE OR REPLACE FUNCTION public.season_record(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(starts_on date, season_name text, ended_on date, level integer, xp bigint, title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return query
    select r.starts_on, r.season_name, r.ended_on, r.level, r.xp, t.title
    from public.hab_season_results r
    left join public.hab_titles t
      on t.athlete_id = r.athlete_id
     and t.title = 't_sn_' || to_char(r.starts_on, 'YYYYMMDD')
    where r.athlete_id = p_athlete_id
    order by r.starts_on desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.season_start_of(p_day date)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select s.starts_on from public.seasons s where s.starts_on <= p_day order by s.starts_on desc, s.id desc limit 1
$function$;

CREATE OR REPLACE FUNCTION public.send_athlete_message(p_athlete_id text, p_body text, p_context text DEFAULT NULL::text, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  if coalesce(btrim(p_body), '') = '' then return; end if;
  insert into public.messages (athlete_id, sender, body, context, read_by_athlete, read_by_coach)
  values (p_athlete_id, 'athlete', left(p_body, 2000), p_context, true, false);
end; $function$;

CREATE OR REPLACE FUNCTION public.session_ex_notes(p_log jsonb, p_summary text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(case
    when jsonb_typeof(p_log) = 'array' then
      (select string_agg(btrim(t.e ->> 'note'), E'\n' order by t.ord)
         from jsonb_array_elements(p_log) with ordinality as t(e, ord)
        where coalesce(btrim(t.e ->> 'note'), '') <> '')
    else
      (select string_agg(btrim(r.m[1]), E'\n')
         from regexp_matches(coalesce(p_summary, ''), '(?:^|\n)[ \t]+Note:[ \t]*([^\n]*)', 'g') as r(m)
        where btrim(r.m[1]) <> '')
  end, '');
$function$;

CREATE OR REPLACE FUNCTION public.set_coach_note(p_body text, p_day date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_body text;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  v_body := public.hab_clean_note(p_body);
  if v_body = '' then
    delete from public.hab_notes n
     where n.athlete_id = public.coach_note_id() and n.day = p_day;
    return;
  end if;
  insert into public.hab_notes (athlete_id, day, body)
  values (public.coach_note_id(), p_day, v_body)
  on conflict (athlete_id, day) do update
    set body = excluded.body, updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.set_day_note(p_athlete_id text, p_key text DEFAULT NULL::text, p_day date DEFAULT NULL::date, p_body text DEFAULT NULL::text, p_pct integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_body text; v_day date;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  if p_athlete_id = public.coach_note_id() then
    raise exception 'reserved id';
  end if;

  if not exists (select 1 from public.leaderboard_optin o where o.athlete_id = p_athlete_id) then
    raise exception 'join the leaderboard before posting';
  end if;

  -- TODAY ONLY, but "today" is the athlete's, not the server's. A one-day
  -- tolerance either side covers every timezone without allowing edits to history.
  v_day := coalesce(p_day, current_date);
  if v_day > current_date + 1 or v_day < current_date - 1 then
    raise exception 'you can only write today''s line';
  end if;

  v_body := public.hab_clean_note(p_body);

  if v_body = '' then
    delete from public.hab_notes n where n.athlete_id = p_athlete_id and n.day = v_day;
    return;
  end if;

  insert into public.hab_notes (athlete_id, day, body, pct)
  values (p_athlete_id, v_day, v_body,
          case when p_pct is null then null
               else greatest(0, least(100, p_pct))::smallint end)
  on conflict (athlete_id, day) do update
    set body = excluded.body, pct = excluded.pct, updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.set_intake_outcome(p_id uuid, p_outcome text, p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ath text := nullif(btrim(coalesce(p_athlete_id, '')), ''); v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_outcome is not null and p_outcome not in ('client', 'free', 'not_a_fit', 'no_reply', 'declined', 'other') then
    raise exception 'bad intake outcome: %', p_outcome;
  end if;
  if p_outcome is null or p_outcome not in ('client', 'free') then
    v_ath := null;      -- only an application that became someone keeps the link
  end if;
  if p_outcome = 'client' and v_ath is null then
    raise exception 'pick the athlete this application became';
  end if;
  if v_ath is not null
     and not exists (select 1 from public.programs p where p.athlete_id = v_ath)
     and not exists (select 1 from public.hab_contacts c where c.athlete_id = v_ath) then
    raise exception 'there is no athlete called "%"', v_ath;
  end if;
  update public.hab_intake i
     set outcome    = p_outcome,
         athlete_id = v_ath,
         linked_at  = case when v_ath is null then null
                           when i.athlete_id is not distinct from v_ath then i.linked_at
                           else now() end,
         status     = case when p_outcome is not null and i.status = 'new' then 'handled' else i.status end,
         handled_at = case when p_outcome is not null and i.status = 'new' then now() else i.handled_at end
   where i.id = p_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then
    raise exception 'no such application';
  end if;
  return jsonb_build_object('outcome', p_outcome, 'athlete_id', v_ath);
end $function$;

CREATE OR REPLACE FUNCTION public.set_intake_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_status not in ('new', 'handled', 'archived') then
    raise exception 'bad intake status: %', p_status;
  end if;
  update public.hab_intake
     set status     = p_status,
         handled_at = case when p_status = 'new' then null
                           else coalesce(handled_at, now()) end
   where id = p_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.set_leaderboard_optin(p_athlete_id text, p_display_name text, p_opt_in boolean, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_name text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  if not p_opt_in then
    delete from public.leaderboard_optin where athlete_id = p_athlete_id;
    return;
  end if;

  v_name := btrim(regexp_replace(coalesce(p_display_name, ''), '[<>"''\\]', '', 'g'));
  v_name := left(v_name, 24);
  if v_name = '' then v_name := 'ATHLETE'; end if;

  insert into public.leaderboard_optin (athlete_id, display_name)
  values (p_athlete_id, v_name)
  on conflict (athlete_id) do update
    set display_name = excluded.display_name, updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.set_quests(p_start date, p_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text; v_runs jsonb; v_kept jsonb := '[]'::jsonb; r jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_ids is null or array_length(p_ids, 1) is null then
    raise exception 'give at least one quest id, or use clear_quests()';
  end if;
  v_key := to_char(p_start, 'YYYY-MM-DD');
  select coalesce(rules -> 'questRuns', '[]'::jsonb) into v_runs from public.xp_rules where id = 1;
  for r in select value from jsonb_array_elements(v_runs) loop
    if r ->> 'start' is distinct from v_key then v_kept := v_kept || jsonb_build_array(r); end if;
  end loop;
  v_kept := v_kept || jsonb_build_array(jsonb_build_object('start', v_key, 'ids', to_jsonb(p_ids)));
  update public.xp_rules
     set rules = jsonb_set(rules, '{questRuns}', v_kept), updated_at = now()
   where id = 1;
  return v_kept;
end; $function$;

CREATE OR REPLACE FUNCTION public.set_title(p_athlete_id text, p_title text, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  -- stage78: titles are gone (round 5, L5). Whatever an old phone asks for, the board shows no title.
  update public.leaderboard_optin set title = null, updated_at = now() where athlete_id = p_athlete_id;
  if not found then raise exception 'join the board first'; end if;
end; $function$;

CREATE OR REPLACE FUNCTION public.spine_credits_ok(c jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select c is null or (jsonb_typeof(c) = 'object' and not exists (
    select 1 from jsonb_each(c) e(k, v)
    where e.k not in ('quads', 'hamstrings', 'glutes', 'adductors', 'calves', 'shins', 'peroneals', 'back',
                      'chest', 'shoulder', 'biceps', 'triceps', 'forearm', 'core', 'neck')
       or jsonb_typeof(e.v) <> 'number' or (e.v #>> '{}')::numeric not in (0.5, 1)))
$function$;

CREATE OR REPLACE FUNCTION public.spine_keep_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o   jsonb := to_jsonb(old);
  n   jsonb;
  ch  jsonb;
  who text := coalesce(auth.jwt() ->> 'email', 'sql');
begin
  if tg_op = 'DELETE' then
    insert into public.spine_versions (tbl, row_id, op, data, saved_by, was_updated_at)
    values (tg_table_name, old.id, 'delete', o, who, nullif(o ->> 'updated_at', '')::timestamptz);
    return old;
  end if;
  n := to_jsonb(new);
  select coalesce(jsonb_object_agg(e.key, n -> e.key), '{}'::jsonb) into ch
    from jsonb_each(o) e
   where e.key not in ('updated_at', 'updated_by')
     and (n -> e.key) is distinct from e.value;
  if ch = '{}'::jsonb then
    return new;
  end if;
  insert into public.spine_versions (tbl, row_id, op, data, changed, saved_by, was_updated_at)
  values (tg_table_name, old.id, 'update', o, ch, who, nullif(o ->> 'updated_at', '')::timestamptz);
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.spine_steps_ok(s text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  -- One list, 0 to 6 lines, none blank (only spaces, tabs or line breaks count as blank), none over 140 characters.
  select s is null or (coalesce(array_ndims(s), 1) = 1 and coalesce(cardinality(s), 0) <= 6 and not exists (
    select 1 from unnest(s) x where x is null or x !~ '\S' or char_length(x) > 140))
$function$;

CREATE OR REPLACE FUNCTION public.start_season(p_name text, p_starts_on date DEFAULT CURRENT_DATE)
 RETURNS TABLE(name text, starts_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_latest date; v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;

  if coalesce(btrim(p_name), '') = '' then
    raise exception 'a season needs a name';
  end if;

  if p_starts_on > current_date then
    raise exception 'a season cannot start in the future (%) — run this on the day it begins', p_starts_on;
  end if;

  select max(s.starts_on) into v_latest from public.seasons s;
  if v_latest is not null and p_starts_on <= v_latest then
    raise exception 'the new season (%) must start after the latest one (%)', p_starts_on, v_latest;
  end if;

  v_n := public.hab_close_season(p_starts_on - 1);
  raise notice 'archived % athlete season record(s)', v_n;

  insert into public.seasons (name, starts_on) values (btrim(p_name), p_starts_on);
  return query select * from public.current_season();
end; $function$;

CREATE OR REPLACE FUNCTION public.submit_intake(p_payload jsonb, p_lang text DEFAULT 'en'::text, p_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_contact text DEFAULT NULL::text, p_programme text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_payload is null or jsonb_typeof(p_payload) is distinct from 'object'
     or p_payload = '{}'::jsonb then
    raise exception 'intake payload must be a non-empty object';
  end if;
  if char_length(p_payload::text) > 60000 then
    raise exception 'intake payload too large';
  end if;

  insert into public.hab_intake (lang, name, email, contact, programme, payload)
  values (
    coalesce(nullif(lower(btrim(p_lang)), ''), 'en'),
    nullif(left(btrim(coalesce(p_name, '')),     200), ''),
    nullif(left(btrim(coalesce(p_email, '')),    200), ''),
    nullif(left(btrim(coalesce(p_contact, '')),  200), ''),
    nullif(left(btrim(coalesce(p_programme, '')),200), ''),
    p_payload)
  returning id into v_id;

  return v_id;
end; $function$;

