CREATE TRIGGER affiliates_touch BEFORE UPDATE ON public.affiliates FOR EACH ROW EXECUTE FUNCTION touch_affiliates_updated_at();
CREATE TRIGGER assess_accounts_label_trg BEFORE INSERT OR UPDATE OF label ON public.assess_accounts FOR EACH ROW EXECUTE FUNCTION move_buyer_label('testing');
CREATE TRIGGER assess_players_touch BEFORE UPDATE ON public.assess_players FOR EACH ROW EXECUTE FUNCTION assess_touch();
CREATE TRIGGER assess_results_touch BEFORE UPDATE ON public.assess_results FOR EACH ROW EXECUTE FUNCTION assess_touch();
CREATE TRIGGER career_progress_trg AFTER INSERT OR DELETE OR UPDATE ON public.athlete_progress FOR EACH ROW EXECUTE FUNCTION career_on_progress();
CREATE TRIGGER crew_forget_former AFTER INSERT OR UPDATE OF status ON public.athlete_status FOR EACH ROW WHEN ((new.status = 'former'::text)) EXECUTE FUNCTION crew_t_forget_former();
CREATE TRIGGER call_logs_touch BEFORE UPDATE ON public.call_logs FOR EACH ROW EXECUTE FUNCTION touch_call_logs_updated_at();
CREATE TRIGGER crew_push_award AFTER INSERT ON public.career_awards FOR EACH ROW WHEN (((new.how = 'live'::text) AND ((new.kind = 'achievement'::text) OR ((new.kind = 'badge'::text) AND (new.item = ANY (ARRAY['held_weeks'::text, 'century'::text, 'bests'::text, 'comebacks'::text])))))) EXECUTE FUNCTION crew_push_t_award();
CREATE TRIGGER crew_push_fact AFTER INSERT ON public.career_facts FOR EACH ROW WHEN (((new.void_at IS NULL) AND (new.kind = ANY (ARRAY['week_held'::text, 'personal_best'::text, 'cycle_finished'::text])) AND (new.day >= (CURRENT_DATE - 14)) AND ((new.kind <> 'personal_best'::text) OR (NULLIF(btrim((new.value ->> 'lift'::text)), ''::text) IS NOT NULL)))) EXECUTE FUNCTION crew_push_t_fact();
CREATE TRIGGER crew_push_honour AFTER INSERT ON public.career_honours FOR EACH ROW WHEN (((new.honour <> 'near'::text) AND (new.confirmed_at IS NOT NULL))) EXECUTE FUNCTION crew_push_t_honour();
CREATE TRIGGER crew_push_honour_ok AFTER UPDATE OF confirmed_at ON public.career_honours FOR EACH ROW WHEN (((new.honour <> 'near'::text) AND (old.confirmed_at IS NULL) AND (new.confirmed_at IS NOT NULL))) EXECUTE FUNCTION crew_push_t_honour();
CREATE TRIGGER crew_level_ring AFTER UPDATE OF score ON public.career_scores FOR EACH ROW EXECUTE FUNCTION crew_level_ring();
CREATE TRIGGER coaching_logs_touch_trg BEFORE UPDATE ON public.coaching_logs FOR EACH ROW EXECUTE FUNCTION coaching_logs_touch();
CREATE TRIGGER coaching_logs_version_trg BEFORE UPDATE ON public.coaching_logs FOR EACH ROW EXECUTE FUNCTION coaching_logs_keep_version();
CREATE TRIGGER crew_push_cheer AFTER INSERT ON public.crew_cheers FOR EACH ROW EXECUTE FUNCTION crew_push_t_cheer();
CREATE TRIGGER crew_tally_cheer AFTER INSERT ON public.crew_cheers FOR EACH ROW EXECUTE FUNCTION crew_t_tally_cheer();
CREATE TRIGGER crew_push_joined AFTER INSERT OR UPDATE OF first_yes_at ON public.crew_consent FOR EACH ROW EXECUTE FUNCTION crew_push_t_joined();
CREATE TRIGGER crew_push_kudos AFTER INSERT ON public.crew_kudos FOR EACH ROW EXECUTE FUNCTION crew_push_t_kudos();
CREATE TRIGGER crew_push_mention AFTER INSERT ON public.crew_mentions FOR EACH ROW EXECUTE FUNCTION crew_push_t_mention();
CREATE TRIGGER crew_push_post AFTER INSERT ON public.crew_posts FOR EACH ROW EXECUTE FUNCTION crew_push_t_post();
CREATE TRIGGER crew_push_reply AFTER INSERT ON public.crew_replies FOR EACH ROW EXECUTE FUNCTION crew_push_t_reply();
CREATE TRIGGER crew_push_ring AFTER INSERT ON public.crew_rings FOR EACH ROW EXECUTE FUNCTION crew_push_t_ring();
CREATE TRIGGER exercise_coach_version_trg BEFORE DELETE OR UPDATE ON public.exercise_coach FOR EACH ROW EXECUTE FUNCTION spine_keep_version();
CREATE TRIGGER exercises_touch_updated_at BEFORE UPDATE ON public.exercises FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER exercises_version_trg BEFORE DELETE OR UPDATE ON public.exercises FOR EACH ROW EXECUTE FUNCTION spine_keep_version();
CREATE TRIGGER hab_notes_prune_trg AFTER INSERT OR UPDATE ON public.hab_notes FOR EACH STATEMENT EXECUTE FUNCTION hab_notes_prune();
CREATE TRIGGER library_touch_trg BEFORE UPDATE ON public.library FOR EACH ROW EXECUTE FUNCTION library_touch();
CREATE TRIGGER career_library_trg AFTER INSERT OR DELETE OR UPDATE ON public.library_sessions FOR EACH ROW EXECUTE FUNCTION career_on_library();
CREATE TRIGGER career_programme_trg AFTER INSERT OR UPDATE OF data ON public.programs FOR EACH ROW EXECUTE FUNCTION career_on_programme();
CREATE TRIGGER programs_cycle_push_trg AFTER UPDATE OF data ON public.programs FOR EACH ROW EXECUTE FUNCTION cycle_push_on_publish();
CREATE TRIGGER programs_version_trg BEFORE UPDATE ON public.programs FOR EACH ROW EXECUTE FUNCTION programs_version_snapshot();
